window.GRAMMAR_PAGES = {"1":{"line":"Every noun is <b>masculine</b> (le, un) or <b>feminine</b> (la, une), even a table. Learn each noun with its article. Endings help: <b>-age, -ment, -eau</b> are usually masculine; <b>-tion, -té, -ure</b> usually feminine. Plural: add <b>-s</b> (not heard); -eau → -eaux, -al → -aux.","words":"Everyday nouns with pictures: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:17\">Vocab 17 · The « Survival 50 » Nouns</a>.","steps":[{"tool":"sort","title":"Masculine or feminine?","sub":"Tap the box for each noun. The ending is a clue, with a few traps.","boxes":[{"k":"m","label":"le / un","sub":"masculine"},{"k":"f","label":"la / une","sub":"feminine"}],"cards":[{"t":"fromage","box":"m","why":"-age: usually masculine, <b>le fromage</b>.","en":"cheese"},{"t":"nation","box":"f","why":"-tion: feminine, <b>la nation</b>.","en":"nation"},{"t":"gouvernement","box":"m","why":"-ment: masculine, <b>le gouvernement</b>.","en":"government"},{"t":"liberté","box":"f","why":"-té: feminine, <b>la liberté</b>.","en":"freedom"},{"t":"bateau","box":"m","why":"-eau: masculine, <b>le bateau</b>.","en":"boat"},{"t":"voiture","box":"f","why":"-ure: feminine, <b>la voiture</b>.","en":"car"},{"t":"plage","box":"f","why":"A trap: -age but feminine, <b>la plage</b>.","en":"beach"},{"t":"problème","box":"m","why":"A trap: -e but masculine, <b>le problème</b>.","en":"problem"},{"t":"maison","box":"f","why":"<b>la maison</b>: learn it with la.","en":"house"}]},{"tool":"agree","title":"One or more?","sub":"Switch to the plural: the letters that change light up. The -s is written, not heard.","cols":["one","more than one"],"rows":[{"forms":["le livre","les livres"],"en":["the book","the books"]},{"forms":["la table","les tables"],"en":["the table","the tables"]},{"forms":["le gâteau","les gâteaux"],"en":["the cake","the cakes · -eau → -eaux"]},{"forms":["le journal","les journaux"],"en":["the newspaper","the newspapers · -al → -aux"]},{"forms":["le prix","les prix"],"en":["the price","the prices · -x stays"]},{"forms":["le nez","les nez"],"en":["the nose","the noses · -z stays"]}]},{"tool":"flip","title":"A man, a woman","sub":"Tap a card: the job or the person turns feminine.","cards":[{"a":"un étudiant","b":"une étudiante","tag":"+ e"},{"a":"un acteur","b":"une actrice","tag":"-teur → -trice"},{"a":"un chanteur","b":"une chanteuse","tag":"-eur → -euse"},{"a":"un Italien","b":"une Italienne","tag":"-en → -enne"},{"a":"un boulanger","b":"une boulangère","tag":"-er → -ère"},{"a":"un journaliste","b":"une journaliste","tag":"-e: no change"}]}],"practice":{"choose":[{"q":"___ fromage","en":"cheese","opts":["le","la"],"a":"le","why":"What does -age usually take?","hint":"-age is usually masculine: <b>le fromage</b>."},{"q":"___ nation","en":"nation","opts":["la","le"],"a":"la","why":"What does -tion take?","hint":"-tion is feminine: <b>la nation</b>."},{"q":"___ problème","en":"problem","opts":["le","la"],"a":"le","why":"It ends in -e, but it is one of the traps.","hint":"<b>le problème</b>: masculine."},{"q":"___ plage","en":"beach","opts":["la","le"],"a":"la","why":"It ends in -age, but it is one of the traps.","hint":"<b>la plage</b>: feminine."},{"q":"le gâteau → les ___","en":"the cakes","opts":["gâteaux","gâteaus","gâteau"],"a":"gâteaux","why":"What does -eau take in the plural?","hint":"-eau → <b>-eaux</b>."},{"q":"le journal → les ___","en":"the newspapers","opts":["journaux","journals","journales"],"a":"journaux","why":"What does -al become?","hint":"-al → <b>-aux</b>."},{"q":"un acteur → une ___","en":"an actress","opts":["actrice","acteuse","acteure"],"a":"actrice","why":"-teur has its own feminine.","hint":"-teur → <b>-trice</b>."}],"build":[{"en":"The newspapers are on the table.","tiles":["Les","journaux","sont","sur","la","table."],"trap":"journals","why":"-al in the plural…","hint":"les <b>journaux</b>."},{"en":"She is a student.","tiles":["C'est","une","étudiante."],"trap":"un","why":"She: the feminine.","hint":"<b>une</b> étudiante."},{"en":"I like cakes.","tiles":["J'aime","les","gâteaux."],"trap":"gâteaus","why":"-eau in the plural…","hint":"les <b>gâteaux</b>."},{"en":"The problem is simple.","tiles":["Le","problème","est","simple."],"trap":"La","why":"problème is a trap.","hint":"<b>le</b> problème."},{"en":"The beach is beautiful.","tiles":["La","plage","est","belle."],"trap":"Le","why":"plage is a trap.","hint":"<b>la</b> plage."}],"spot":[{"words":["J'aime","la","fromage."],"bad":1,"fix":"le","hint":"<b>le</b> fromage (-age).","look":"Look at the article."},{"words":["Les","journals","sont là."],"bad":1,"fix":"journaux","hint":"-al → <b>-aux</b>.","look":"Look at the plural."},{"words":["C'est","un","actrice."],"bad":1,"fix":"une","hint":"actrice is a woman: <b>une</b>.","look":"Look at the article."},{"words":["Le","plage","est loin."],"bad":0,"fix":"La","hint":"<b>la</b> plage.","look":"Look at the article."},{"words":["Il y a","deux","gâteau."],"bad":2,"fix":"gâteaux.","hint":"Two cakes: <b>gâteaux</b>.","look":"Two of them…"}]},"drill":[["Which article? ___ plage","la plage","-age is usually masculine, but plage is feminine: <b>la plage</b>."],["Plural of le journal","les journaux","-al → <b>-aux</b>: les journaux."],["Plural of le prix","les prix","Nouns in -s, -x or -z do not change: les prix."],["Feminine of un acteur","une actrice","-teur → <b>-trice</b>."],["Plural of le gâteau","les gâteaux","-eau → <b>-eaux</b>."],["Which article? ___ problème","le problème","A trap: -e but masculine, <b>le problème</b>."]]},"4":{"line":"French verbs need a subject: <b>je</b> (j' before a vowel), <b>tu, il, elle, on, nous, vous, ils, elles</b>. <b>tu</b> = one person you know well; <b>vous</b> = polite, or more than one person. <b>ils</b> for a group with at least one man, <b>elles</b> only women. Things are il or elle too. <b>on</b> = we, in everyday French.","words":"","steps":[{"tool":"sort","title":"tu or vous?","sub":"Who are you talking to? Tap the box.","boxes":[{"k":"tu","label":"tu","sub":"one person you know well"},{"k":"vous","label":"vous","sub":"polite, or more than one"}],"cards":[{"t":"your best friend","box":"tu","why":"A friend: <b>tu</b>.","say":"Salut ! Tu vas bien ?"},{"t":"your boss","box":"vous","why":"Polite: <b>vous</b>.","say":"Bonjour Madame, vous allez bien ?"},{"t":"a child","box":"tu","why":"A child: <b>tu</b>.","say":"Tu as quel âge ?"},{"t":"a waiter in a café","box":"vous","why":"Someone you do not know: <b>vous</b>.","say":"Vous avez une table, s'il vous plaît ?"},{"t":"your mother","box":"tu","why":"Family: <b>tu</b>.","say":"Maman, tu viens ?"},{"t":"two friends together","box":"vous","why":"More than one person: <b>vous</b>, even friends.","say":"Salut ! Vous venez ?"},{"t":"a doctor","box":"vous","why":"Polite: <b>vous</b>.","say":"Bonjour docteur, vous allez bien ?"}]},{"tool":"sort","title":"il, elle, ils or elles?","sub":"Tap the pronoun for each one.","boxes":[{"k":"il","label":"il"},{"k":"elle","label":"elle"},{"k":"ils","label":"ils"},{"k":"elles","label":"elles"}],"cards":[{"t":"Paul","box":"il"},{"t":"Marie","box":"elle"},{"t":"Marie et Julie","box":"elles","why":"Only women: <b>elles</b>."},{"t":"Marie et Paul","box":"ils","why":"One man is enough: <b>ils</b>."},{"t":"le livre","box":"il","why":"Things too: le livre → <b>il</b>."},{"t":"la table","box":"elle","why":"la table → <b>elle</b>."},{"t":"les enfants (girls and boys)","box":"ils","why":"Mixed: <b>ils</b>."},{"t":"les filles","box":"elles"}]},{"tool":"flip","title":"je → j', and on","sub":"Tap a card. Before a vowel or a silent h, je becomes j'. In everyday French, on means we.","cards":[{"a":"je + aime","b":"j'aime","tag":"je → j'"},{"a":"je + habite","b":"j'habite","tag":"silent h: j'"},{"a":"je + écoute","b":"j'écoute","tag":"je → j'"},{"a":"je + parle","b":"je parle","tag":"no vowel: no change"},{"a":"Nous allons au cinéma.","b":"On va au cinéma.","tag":"nous → on (everyday)"}]}],"practice":{"choose":[{"q":"Marie et Julie → ___","en":"","opts":["elles","ils","elle","vous"],"a":"elles","why":"Two women…","hint":"Only women: <b>elles</b>."},{"q":"Marie et Paul → ___","en":"","opts":["ils","elles","il","on"],"a":"ils","why":"There is a man in the group.","hint":"One man is enough: <b>ils</b>."},{"q":"« ___ êtes prêt, monsieur ? »","en":"Are you ready, sir?","opts":["Vous","Tu","Il","Nous"],"a":"Vous","why":"Talking to « monsieur »…","hint":"Polite: <b>vous</b>."},{"q":"« ___ viens ce soir ? » (to a friend)","en":"Are you coming tonight?","opts":["Tu","Vous","Il","Je"],"a":"Tu","why":"A friend…","hint":"A friend: <b>tu</b>."},{"q":"___ aime le café. (I)","en":"I like coffee.","opts":["J'","Je","Tu","Il"],"a":"J'","why":"aime starts with a vowel.","hint":"Before a vowel: <b>j'</b>aime."},{"q":"Le livre ? ___ est sur la table.","en":"The book? It is on the table.","opts":["Il","Elle","Le","On"],"a":"Il","why":"le livre is masculine.","hint":"le livre → <b>il</b>."},{"q":"La voiture ? ___ est rouge.","en":"The car? It is red.","opts":["Elle","Il","La","On"],"a":"Elle","why":"la voiture is feminine.","hint":"la voiture → <b>elle</b>."}],"build":[{"en":"We're going to the cinema (everyday French).","tiles":["On","va","au","cinéma."],"trap":"allons","why":"on takes the il form.","hint":"<b>on va</b>."},{"en":"I live in Lyon.","tiles":["J'habite","à","Lyon."],"trap":"Je","why":"habite starts with a silent h.","hint":"<b>j'</b>habite."},{"en":"They (Marie and Paul) are here.","tiles":["Ils","sont","là."],"trap":"Elles","why":"There is a man in the group.","hint":"<b>ils</b> sont là."},{"en":"Are you ready, sir?","tiles":["Vous","êtes","prêt,","monsieur ?"],"trap":"Tu","why":"Polite…","hint":"<b>vous</b> êtes."},{"en":"She is tired.","tiles":["Elle","est","fatiguée."],"trap":"Il","why":"She…","hint":"<b>elle</b> est."}],"spot":[{"words":["Je aime","le chocolat."],"bad":0,"fix":"J'aime","hint":"Before a vowel: <b>j'</b>aime.","look":"aime starts with a vowel."},{"words":["Marie et Paul,","elles","sont là."],"bad":1,"fix":"ils","hint":"One man is enough: <b>ils</b>.","look":"Look at who is in the group."},{"words":["Monsieur,","tu","êtes","en retard."],"bad":1,"fix":"vous","hint":"Polite, and êtes is the vous form: <b>vous</b>.","look":"Look at the verb: which pronoun does it go with?"},{"words":["On","allons","au parc."],"bad":1,"fix":"va","hint":"on takes the il form: <b>on va</b>.","look":"Look at the verb after on."},{"words":["La table ?","Il","est","grande."],"bad":1,"fix":"Elle","hint":"la table → <b>elle</b>.","look":"Is table masculine or feminine?"}]},"drill":[["Speaking to your boss: tu or vous?","vous","Polite: <b>vous</b>."],["Marie and Julie","elles","Only women: <b>elles</b>."],["Marie and Paul","ils","One man is enough: <b>ils</b>."],["je + aime","J'aime","Before a vowel, je becomes <b>j'</b>."],["Le livre → pronoun","il","Things are il or elle too: le livre → <b>il</b>."],["je + habite","J'habite","A silent h counts as a vowel: <b>j'</b>habite."]]},"29":{"line":"<b>moi, toi, lui, elle, nous, vous, eux, elles</b> stand on their own. Use them after <b>c'est</b> (c'est moi), after a little word like <b>avec, chez, pour</b> (avec toi, chez lui), to stress (<b>Moi</b>, je préfère le thé), and in short answers (Moi aussi, Moi non plus).","words":"","steps":[{"tool":"swap","title":"Put the stress on it","sub":"Pick a sentence and tap « Stress it »: the stressed pronoun comes to the front.","button":["Stress it","Plain again"],"legend":[["p","the stressed pronoun"]],"items":[{"label":"Je préfère le thé.","en":["I prefer tea.","Me, I prefer tea."],"a":[["s","Je",""],["v","préfère",""],["o","le thé.",""]],"b":[["m","Moi,","p"],["s","je",""],["v","préfère",""],["o","le thé.",""]],"note":"<b>Moi</b> at the front puts the weight on « I »."},{"label":"Tu as raison.","en":["You are right.","You, you are right."],"a":[["s","Tu",""],["v","as",""],["o","raison.",""]],"b":[["m","Toi,","p"],["s","tu",""],["v","as",""],["o","raison.",""]],"note":"tu → <b>toi</b>."},{"label":"Il est grand.","en":["He is tall.","Him, he is tall."],"a":[["s","Il",""],["v","est",""],["o","grand.",""]],"b":[["m","Lui,","p"],["s","il",""],["v","est",""],["o","grand.",""]],"note":"il → <b>lui</b>."},{"label":"Ils sont partis.","en":["They left.","Them, they left."],"a":[["s","Ils",""],["v","sont",""],["o","partis.",""]],"b":[["m","Eux,","p"],["s","ils",""],["v","sont",""],["o","partis.",""]],"note":"ils → <b>eux</b> (men, or a mixed group)."}]},{"tool":"flip","title":"After c'est and little words","sub":"Tap a card: the subject pronoun turns into its stressed form.","cards":[{"a":"je","b":"C'est moi.","tag":"je → moi"},{"a":"tu","b":"avec toi","tag":"tu → toi"},{"a":"il","b":"chez lui","tag":"il → lui"},{"a":"elle","b":"pour elle","tag":"elle → elle"},{"a":"nous","b":"sans nous","tag":"nous → nous"},{"a":"ils","b":"avec eux","tag":"ils → eux"},{"a":"elles","b":"chez elles","tag":"elles → elles"}]},{"tool":"pairs","title":"Short answers","sub":"Agreeing with a yes, and with a no. Tap one to hear it.","cap":["Agreeing with a yes","Agreeing with a no"],"rows":[{"l":"J'aime le café. Moi aussi.","r":"Je n'aime pas le café. Moi non plus.","en":"me too / me neither"},{"l":"Il est content. Moi aussi.","r":"Il n'est pas content. Moi non plus."},{"l":"Nous partons. Nous aussi.","r":"Nous ne partons pas. Nous non plus."}]}],"practice":{"choose":[{"q":"C'est ___ ! (me)","en":"It's me!","opts":["moi","je","me","mon"],"a":"moi","why":"After c'est…","hint":"c'est <b>moi</b>."},{"q":"Je viens avec ___. (you, tu)","en":"I'm coming with you.","opts":["toi","tu","te","ton"],"a":"toi","why":"After avec…","hint":"avec <b>toi</b>."},{"q":"Elle habite chez ___. (him)","en":"She lives at his place.","opts":["lui","il","le","son"],"a":"lui","why":"After chez…","hint":"chez <b>lui</b>."},{"q":"Je travaille avec ___. (them, men)","en":"I work with them.","opts":["eux","ils","leur","les"],"a":"eux","why":"After avec, ils becomes…","hint":"avec <b>eux</b>."},{"q":"___, je préfère le thé.","en":"Me, I prefer tea.","opts":["Moi","Je","Me","Mon"],"a":"Moi","why":"Stress at the front…","hint":"<b>Moi</b>, je …"},{"q":"« J'aime ce film. » « ___ aussi. »","en":"« Me too. »","opts":["Moi","Je","Me","Mon"],"a":"Moi","why":"A short answer stands on its own.","hint":"<b>Moi</b> aussi."},{"q":"« Je n'ai pas faim. » « Moi ___. »","en":"« Me neither. »","opts":["non plus","aussi","pas","non"],"a":"non plus","why":"Agreeing with a no…","hint":"Moi <b>non plus</b>."}],"build":[{"en":"It's me.","tiles":["C'est","moi."],"trap":"je","why":"After c'est…","hint":"c'est <b>moi</b>."},{"en":"I'm coming with you.","tiles":["Je","viens","avec","toi."],"trap":"tu","why":"After avec…","hint":"avec <b>toi</b>."},{"en":"Paul is taller than him.","tiles":["Paul","est","plus","grand","que","lui."],"trap":"il","why":"After que…","hint":"que <b>lui</b>."},{"en":"Me too.","tiles":["Moi","aussi."],"trap":"Je","why":"A short answer…","hint":"<b>Moi</b> aussi."},{"en":"I'm going home.","tiles":["Je","rentre","chez","moi."],"trap":"je","why":"After chez…","hint":"chez <b>moi</b>."}],"spot":[{"words":["C'est","je."],"bad":1,"fix":"moi.","hint":"After c'est: <b>moi</b>.","look":"Look at the word after c'est."},{"words":["Je pars","avec","tu."],"bad":2,"fix":"toi.","hint":"After avec: <b>toi</b>.","look":"Look at the word after avec."},{"words":["Il dîne","chez","il."],"bad":2,"fix":"lui.","hint":"After chez: <b>lui</b>.","look":"Look at the word after chez."},{"words":["Je","aussi."],"bad":0,"fix":"Moi","hint":"A short answer: <b>Moi</b> aussi.","look":"Can je stand on its own?","say":"Moi aussi."},{"words":["Je travaille","avec","ils."],"bad":2,"fix":"eux.","hint":"After avec, ils becomes <b>eux</b>.","look":"Look at the word after avec."}]},"drill":[["It's me","C'est moi.","After c'est: <b>moi</b>."],["with you (tu)","avec toi","After avec: <b>toi</b>."],["taller than him","plus grand que lui","After que: <b>lui</b>."],["Me too","Moi aussi.","A short answer: <b>Moi</b> aussi."],["at their place (men)","chez eux","After chez, ils becomes <b>eux</b>."],["Me neither.","Moi non plus.","Agreeing with a no: moi <b>non plus</b>."]]},"v1":{"line":"<b>être</b> (to be): je suis, tu es, il est, nous sommes, vous êtes, ils sont. <b>avoir</b> (to have): j'ai, tu as, il a, nous avons, vous avez, ils ont. Learn them as whole words: they have no regular pattern. Listen: <b>ils ont</b> (a z sound) and <b>ils sont</b> (an s sound) are different verbs.<br><b>aller</b> (to go): je vais, tu vas, il va, nous allons, vous allez, ils vont. <b>faire</b> (to do, to make): je fais, tu fais, il fait, nous faisons (said « fesons »), vous faites, ils font. aller + a verb = the near future (je vais manger). faire is in the weather (il fait beau) and in sports (je fais du vélo).<br><b>vouloir</b> (want), <b>pouvoir</b> (can), <b>devoir</b> (must), <b>savoir</b> (know how to) + a second verb that stays as it is: je <b>veux</b> partir, tu <b>peux</b> venir, il <b>doit</b> travailler, je <b>sais</b> nager. Only the first verb changes. To be polite: je <b>voudrais</b>.<br>Learn one model and you know its family. <b>prendre</b>: je prends, nous prenons, ils prennent (→ comprendre, apprendre). <b>venir</b>: je viens, nous venons, ils viennent (→ devenir, revenir). <b>partir</b>: je pars, nous partons (→ sortir, dormir). <b>boire</b>: je bois, nous buvons, ils boivent.","words":"The weather with faire: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:8\">Vocab 8 · La Météo & Les Saisons</a>. Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"conj","title":"être and avoir","sub":"Pick the verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"être","en":"to be","forms":["suis","es","est","sommes","êtes","sont"],"tail":"à Paris"},{"inf":"avoir","en":"to have","forms":["ai","as","a","avons","avez","ont"],"tail":"un chat"}]},{"tool":"conj","title":"aller and faire","sub":"Pick the verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"aller","en":"to go","forms":["vais","vas","va","allons","allez","vont"],"tail":"au marché"},{"inf":"faire","en":"to do, to make","forms":["fais","fais","fait","faisons","faites","font"],"tail":"du sport"}]},{"tool":"conj","title":"The four modal verbs","sub":"Pick a verb, then tap a person. The second verb never changes.","neg":true,"verbs":[{"inf":"vouloir","en":"to want","forms":["veux","veux","veut","voulons","voulez","veulent"],"tail":"partir"},{"inf":"pouvoir","en":"can","forms":["peux","peux","peut","pouvons","pouvez","peuvent"],"tail":"venir"},{"inf":"devoir","en":"must","forms":["dois","dois","doit","devons","devez","doivent"],"tail":"travailler"},{"inf":"savoir","en":"to know how to","forms":["sais","sais","sait","savons","savez","savent"],"tail":"nager"}]},{"tool":"conj","title":"Four models","sub":"Pick a verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"prendre","en":"to take","forms":["prends","prends","prend","prenons","prenez","prennent"],"tail":"le train"},{"inf":"venir","en":"to come","forms":["viens","viens","vient","venons","venez","viennent"],"tail":"demain"},{"inf":"partir","en":"to leave","forms":["pars","pars","part","partons","partez","partent"],"tail":"à huit heures"},{"inf":"boire","en":"to drink","forms":["bois","bois","boit","buvons","buvez","boivent"],"tail":"de l'eau"}]},{"tool":"sort","title":"être or avoir?","sub":"Tap the verb each sentence needs.","boxes":[{"k":"etre","label":"être","sub":"who or what someone is"},{"k":"avoir","label":"avoir","sub":"having, age, hunger, fear…"}],"cards":[{"t":"Je … étudiant.","box":"etre","why":"Who you are: <b>je suis</b> étudiant.","say":"Je suis étudiant."},{"t":"J'… vingt ans.","box":"avoir","why":"Age: <b>j'ai</b> vingt ans.","say":"J'ai vingt ans."},{"t":"Elle … fatiguée.","box":"etre","why":"How she is: <b>elle est</b> fatiguée.","say":"Elle est fatiguée."},{"t":"Nous … faim.","box":"avoir","why":"Hunger: <b>nous avons</b> faim.","say":"Nous avons faim."},{"t":"Ils … de Lyon.","box":"etre","why":"Where from: <b>ils sont</b> de Lyon.","say":"Ils sont de Lyon."},{"t":"Tu … un chat ?","box":"avoir","why":"Having: <b>tu as</b> un chat ?","say":"Tu as un chat ?"},{"t":"Il … médecin.","box":"etre","why":"A job: <b>il est</b> médecin.","say":"Il est médecin."},{"t":"Vous … raison.","box":"avoir","why":"<b>vous avez</b> raison.","say":"Vous avez raison."}]}],"practice":{"choose":[{"q":"Nous ___ fatigués.","en":"We are tired.","opts":["sommes","avons","êtes","sont"],"a":"sommes","why":"How we are: être, and nous.","hint":"être: nous <b>sommes</b>."},{"q":"Ils ___ une grande maison.","en":"They have a big house.","opts":["ont","sont","avons","a"],"a":"ont","why":"Having: avoir, and ils.","hint":"avoir: ils <b>ont</b>."},{"q":"Vous ___ en retard.","en":"You are late.","opts":["êtes","avez","es","sont"],"a":"êtes","why":"être, and vous.","hint":"être: vous <b>êtes</b>."},{"q":"Je ___ au marché.","en":"I am going to the market.","opts":["vais","va","vas","allons"],"a":"vais","why":"aller with je.","hint":"je <b>vais</b>."},{"q":"Nous ___ du sport.","en":"We do sport.","opts":["faisons","faites","font","fais"],"a":"faisons","why":"faire with nous.","hint":"nous <b>faisons</b>."},{"q":"Vous ___ la cuisine ?","en":"Are you cooking?","opts":["faites","faisez","fait","font"],"a":"faites","why":"faire with vous: an irregular one.","hint":"vous <b>faites</b>."},{"q":"Je ___ partir. (want)","en":"I want to leave.","opts":["veux","voulez","veut","voulons"],"a":"veux","why":"vouloir with je.","hint":"je <b>veux</b>."},{"q":"Nous ___ venir demain. (can)","en":"We can come tomorrow.","opts":["pouvons","peuvons","pouvez","peux"],"a":"pouvons","why":"pouvoir with nous.","hint":"nous <b>pouvons</b>."},{"q":"Tu ___ travailler. (must)","en":"You must work.","opts":["dois","doit","devoir","devez"],"a":"dois","why":"devoir with tu.","hint":"tu <b>dois</b>."},{"q":"Je ___ le bus. (prendre)","en":"I take the bus.","opts":["prends","prend","prenons","prennent"],"a":"prends","why":"prendre with je.","hint":"je <b>prends</b>."},{"q":"Nous ___ du thé. (boire)","en":"We drink tea.","opts":["buvons","boivons","boisons","buvez"],"a":"buvons","why":"boire with nous has its own stem.","hint":"nous <b>buvons</b>."},{"q":"Ils ___ demain. (venir)","en":"They are coming tomorrow.","opts":["viennent","venent","vient","venons"],"a":"viennent","why":"venir with ils: double n.","hint":"ils <b>viennent</b>."},{"q":"J'___ faim.","en":"I'm hungry.","opts":["ai","suis","as","est"],"a":"ai","why":"Hunger takes avoir: <b>j'ai faim</b>.","hint":"Hunger is something you have."},{"q":"Elle ___ dix ans.","en":"She is ten.","opts":["a","est","as","es"],"a":"a","why":"Age takes avoir: elle <b>a</b> dix ans.","hint":"Age is something you have."},{"q":"Je ___ en retard.","en":"I'm late.","opts":["suis","ai","es","a"],"a":"suis","why":"être: je <b>suis</b> en retard.","hint":"Being late is a state: être."}],"build":[{"en":"We are from Lyon.","tiles":["Nous","sommes","de","Lyon."],"trap":"avons","why":"Where from: être.","hint":"nous <b>sommes</b>."},{"en":"They have a big house.","tiles":["Ils","ont","une","grande","maison."],"trap":"sont","why":"Having: avoir.","hint":"ils <b>ont</b>."},{"en":"We are going to the market.","tiles":["Nous","allons","au","marché."],"trap":"allez","why":"aller with nous.","hint":"nous <b>allons</b>."},{"en":"The weather is nice.","tiles":["Il","fait","beau."],"trap":"est","why":"The weather takes faire.","hint":"il <b>fait</b> beau."},{"en":"I want to leave.","tiles":["Je","veux","partir."],"trap":"pars","why":"The second verb stays as it is.","hint":"veux <b>partir</b>."},{"en":"Can you help me?","tiles":["Tu","peux","m'aider ?"],"trap":"aides","why":"The second verb stays as it is.","hint":"peux <b>m'aider</b>."},{"en":"I take the train.","tiles":["Je","prends","le","train."],"trap":"prend","why":"prendre with je.","hint":"je <b>prends</b>."},{"en":"They are coming tomorrow.","tiles":["Ils","viennent","demain."],"trap":"venent","why":"venir with ils.","hint":"ils <b>viennent</b>."}],"spot":[{"words":["Nous","avons","fatigués."],"bad":1,"fix":"sommes","hint":"How we are: <b>nous sommes</b>.","look":"Is fatigués something you have?"},{"words":["Ils","sont","une voiture."],"bad":1,"fix":"ont","hint":"Having: <b>ils ont</b>.","look":"Look at the verb."},{"words":["Vous","faisez","du vélo."],"bad":1,"fix":"faites","hint":"vous <b>faites</b>.","look":"Look at the verb with vous."},{"words":["Ils","allent","au cinéma."],"bad":1,"fix":"vont","hint":"ils <b>vont</b>.","look":"Look at the verb with ils."},{"words":["Je","veux","pars."],"bad":2,"fix":"partir.","hint":"The second verb stays as it is: <b>partir</b>.","look":"Look at the second verb."},{"words":["Ils","peuvent","venons."],"bad":2,"fix":"venir.","hint":"The second verb stays as it is: <b>venir</b>.","look":"Look at the second verb."},{"words":["Ils","prendent","le bus."],"bad":1,"fix":"prennent","hint":"prendre with ils: <b>prennent</b>.","look":"Look at the verb with ils."},{"words":["Nous","boivons","du café."],"bad":1,"fix":"buvons","hint":"boire with nous: <b>buvons</b>.","look":"Look at the verb with nous."}]},"drill":[["we are (être)","nous sommes","être: nous <b>sommes</b>."],["they have (avoir)","ils ont","avoir: ils <b>ont</b> (a z sound)."],["I go","je vais","aller: je <b>vais</b>."],["we do (faire)","nous faisons","faire: nous <b>faisons</b> (said « fesons »)."],["I want (vouloir)","je veux","vouloir: je <b>veux</b>."],["we can (pouvoir)","nous pouvons","pouvoir: nous <b>pouvons</b>."],["I take (prendre)","je prends","prendre: je <b>prends</b>."],["we drink (boire)","nous buvons","boire: nous <b>buvons</b>."],["I'm 20 years old.","J'ai vingt ans. / J'ai 20 ans.","Age takes <b>avoir</b>: j'ai vingt ans (never je suis 20)."],["I'm not hungry.","Je n'ai pas faim.","The no goes round avoir: je <b>n'ai pas</b> faim."],["I agree.","Je suis d'accord.","This one uses <b>être</b>: je suis d'accord."]]},"5":{"line":"Take off -er, -ir or -re, then add the endings. <b>-er</b> (parler): je parle, tu parles, il parle, nous parlons, vous parlez, ils parlent; -e, -es and -ent are not heard. <b>-ir</b> (finir): je finis, nous finissons, ils finissent. <b>-re</b> (vendre): je vends, il vend, nous vendons. Je parle = I speak, I am speaking and I do speak.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"conj","title":"The three families","sub":"Pick a verb, then tap a person: the ending lights up. Grey endings are written but not heard.","neg":true,"verbs":[{"inf":"parler","en":"to speak","stem":"parl","forms":["parle","parles","parle","parlons","parlez","parlent"],"silent":[true,true,true,false,false,true],"tail":"français"},{"inf":"aimer","en":"to like","stem":"aim","forms":["aime","aimes","aime","aimons","aimez","aiment"],"silent":[true,true,true,false,false,true],"tail":"le café"},{"inf":"finir","en":"to finish","stem":"fin","forms":["finis","finis","finit","finissons","finissez","finissent"],"tail":"à six heures"},{"inf":"vendre","en":"to sell","stem":"vend","forms":["vends","vends","vend","vendons","vendez","vendent"],"tail":"des livres"}]},{"tool":"sort","title":"Which family?","sub":"Tap the family for each verb.","boxes":[{"k":"er","label":"-er","sub":"like parler"},{"k":"ir","label":"-ir","sub":"like finir"},{"k":"re","label":"-re","sub":"like vendre"}],"cards":[{"t":"manger","box":"er","why":"to eat"},{"t":"choisir","box":"ir","why":"to choose: nous choisissons"},{"t":"attendre","box":"re","why":"to wait: j'attends"},{"t":"regarder","box":"er","why":"to watch"},{"t":"réussir","box":"ir","why":"to succeed: ils réussissent"},{"t":"répondre","box":"re","why":"to answer: il répond"},{"t":"habiter","box":"er","why":"to live"},{"t":"entendre","box":"re","why":"to hear"}]},{"tool":"flip","title":"Small spelling changes","sub":"Tap a card to see the right spelling.","cards":[{"a":"nous mangons","b":"nous mangeons","tag":"g + e before o"},{"a":"nous commencons","b":"nous commençons","tag":"c → ç before o"},{"a":"je aime","b":"j'aime","tag":"je → j' before a vowel"},{"a":"ils finent","b":"ils finissent","tag":"-ir: -issent"},{"a":"il vende","b":"il vend","tag":"-re: il vend"}]}],"practice":{"choose":[{"q":"Nous ___ (manger) à midi.","en":"We eat at noon.","opts":["mangeons","mangons","mangez","mangent"],"a":"mangeons","why":"g before o needs a little help.","hint":"nous <b>mangeons</b>."},{"q":"Tu ___ (finir) à cinq heures.","en":"You finish at five.","opts":["finis","finit","fini","finissez"],"a":"finis","why":"-ir with tu.","hint":"tu <b>finis</b>."},{"q":"Ils ___ (vendre) leur maison.","en":"They are selling their house.","opts":["vendent","vendont","vend","vendez"],"a":"vendent","why":"-re with ils.","hint":"ils <b>vendent</b>."},{"q":"Vous ___ (parler) anglais ?","en":"Do you speak English?","opts":["parlez","parlons","parles","parler"],"a":"parlez","why":"-er with vous.","hint":"vous <b>parlez</b>."},{"q":"Elle ___ (choisir) une robe.","en":"She chooses a dress.","opts":["choisit","choisis","choisi","choisissent"],"a":"choisit","why":"-ir with elle.","hint":"elle <b>choisit</b>."},{"q":"J'___ (aimer) le café.","en":"I like coffee.","opts":["aime","aimes","aiment","aimons"],"a":"aime","why":"-er with je.","hint":"j'<b>aime</b>."},{"q":"Ils ___ (finir) tard.","en":"They finish late.","opts":["finissent","finent","finissons","finis"],"a":"finissent","why":"-ir with ils.","hint":"ils <b>finissent</b>."}],"build":[{"en":"I speak French.","tiles":["Je","parle","français."],"trap":"parles","why":"-er with je.","hint":"je <b>parle</b>."},{"en":"We eat at noon.","tiles":["Nous","mangeons","à","midi."],"trap":"mangons","why":"g before o…","hint":"nous <b>mangeons</b>."},{"en":"They finish at six.","tiles":["Ils","finissent","à","six heures."],"trap":"finent","why":"-ir with ils.","hint":"ils <b>finissent</b>."},{"en":"You (tu) are waiting for the bus.","tiles":["Tu","attends","le","bus."],"trap":"attend","why":"-re with tu.","hint":"tu <b>attends</b>."},{"en":"She likes tea.","tiles":["Elle","aime","le","thé."],"trap":"aimes","why":"-er with elle.","hint":"elle <b>aime</b>."}],"spot":[{"words":["Nous","mangons","ensemble."],"bad":1,"fix":"mangeons","hint":"nous <b>mangeons</b>: keep the e.","look":"Look at the spelling with nous."},{"words":["Ils","finent","le travail."],"bad":1,"fix":"finissent","hint":"-ir with ils: <b>finissent</b>.","look":"Look at the verb with ils."},{"words":["Tu","parle","anglais ?"],"bad":1,"fix":"parles","hint":"-er with tu: <b>parles</b>.","look":"Look at the ending with tu."},{"words":["Il","vends","sa voiture."],"bad":1,"fix":"vend","hint":"-re with il: <b>vend</b>.","look":"Look at the ending with il."},{"words":["Je aime","le thé."],"bad":0,"fix":"J'aime","hint":"Before a vowel: <b>j'</b>aime.","look":"Look at the first word."}]},"drill":[["nous (manger)","nous mangeons","Keep the e before o: nous <b>mangeons</b>."],["tu (finir)","tu finis","-ir: tu <b>finis</b>."],["ils (vendre)","ils vendent","-re: ils <b>vendent</b>."],["I like coffee","J'aime le café.","j'<b>aime</b>, and likes take le."],["vous (parler)","vous parlez","-er: vous <b>-ez</b>."],["elle (choisir)","elle choisit","-ir: il / elle <b>-it</b>."]]},"7":{"line":"Three ways to ask the same yes/no question: <b>Tu viens ?</b> (your voice goes up: everyday), <b>Est-ce que tu viens ?</b> (everyday, very clear), <b>Viens-tu ?</b> (verb first with a hyphen: formal). With il or elle and a vowel, add <b>-t-</b>: A-t-il faim ? Question words go first or, in casual French, last: Où tu habites ? Tu habites où ?","words":"Où, quand, comment…: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:2\">Vocab 2 · Question Words</a>.","steps":[{"tool":"swap","title":"Make it a question","sub":"Pick a sentence and tap « Make it a question ».","button":["Make it a question","Back to the sentence"],"legend":[["x","added"],["v","the verb"]],"items":[{"label":"Tu viens. (voice up)","en":["You are coming.","Are you coming?"],"a":[["s","Tu",""],["v","viens.","v"]],"b":[["s","Tu",""],["v","viens ?","v"]],"note":"Same words: only your voice goes up. Everyday French."},{"label":"Vous habitez à Paris. (est-ce que)","en":["You live in Paris.","Do you live in Paris?"],"a":[["s","Vous",""],["v","habitez","v"],["o","à Paris.",""]],"b":[["q","Est-ce que","x"],["s","vous",""],["v","habitez","v"],["o","à Paris ?",""]],"note":"<b>Est-ce que</b> at the front: clear, and everyday."},{"label":"Tu as faim. (verb first)","en":["You are hungry.","Are you hungry?"],"a":[["s","Tu",""],["v","as","v"],["o","faim.",""]],"b":[["v","As-","v"],["s","tu",""],["o","faim ?",""]],"note":"The verb jumps first, with a hyphen: <b>As-tu</b> faim ? Formal."},{"label":"Il parle anglais. (-t-)","en":["He speaks English.","Does he speak English?"],"a":[["s","Il",""],["v","parle","v"],["o","anglais.",""]],"b":[["v","Parle-","v"],["t","t-","x"],["s","il",""],["o","anglais ?",""]],"note":"Two vowels meet (parle / il): add <b>-t-</b>."},{"label":"Tu habites à Lyon. (où)","en":["You live in Lyon.","Where do you live?"],"a":[["s","Tu",""],["v","habites","v"],["o","à Lyon.",""]],"b":[["s","Tu",""],["v","habites","v"],["w","où ?","x"]],"note":"Casual: the question word goes at the end. Also: <b>Où est-ce que</b> tu habites ?"}]},{"tool":"sort","title":"Casual, everyday or formal?","sub":"Tap the box for each question.","boxes":[{"k":"c","label":"Casual","sub":"only the voice goes up"},{"k":"e","label":"Everyday","sub":"est-ce que"},{"k":"f","label":"Formal","sub":"the verb first"}],"cards":[{"t":"Tu viens ce soir ?","box":"c"},{"t":"Est-ce que tu viens ?","box":"e"},{"t":"Viens-tu ce soir ?","box":"f"},{"t":"Vous parlez anglais ?","box":"c"},{"t":"Parlez-vous anglais ?","box":"f"},{"t":"Est-ce qu'il a faim ?","box":"e","why":"Before a vowel: est-ce <b>qu'</b>il."},{"t":"A-t-il faim ?","box":"f","why":"-t- between two vowels."},{"t":"Tu habites où ?","box":"c"}]}],"practice":{"choose":[{"q":"___ tu viens ?","en":"Are you coming?","opts":["Est-ce que","Est-ce","Que","Qu'est-ce"],"a":"Est-ce que","why":"The everyday question starter…","hint":"<b>Est-ce que</b> tu viens ?"},{"q":"___-tu faim ?","en":"Are you hungry?","opts":["As","A","Es","Ai"],"a":"As","why":"avoir with tu, verb first.","hint":"<b>As</b>-tu faim ?"},{"q":"Parle-___-il anglais ?","en":"Does he speak English?","opts":["t","s","l","il"],"a":"t","why":"Two vowels meet.","hint":"Parle-<b>t</b>-il ?"},{"q":"___ qu'elle est là ?","en":"Is she here?","opts":["Est-ce","Est-ce que","Est","Que"],"a":"Est-ce","why":"qu' is already there.","hint":"<b>Est-ce</b> qu'elle est là ?"},{"q":"Tu habites ___ ? (where)","en":"Where do you live?","opts":["où","ou","quand","qui"],"a":"où","why":"where, with its accent…","hint":"<b>où</b> (with an accent) = where; ou = or."},{"q":"___-vous français ?","en":"Are you French?","opts":["Êtes","Es","Est","Sont"],"a":"Êtes","why":"être with vous, verb first.","hint":"<b>Êtes</b>-vous français ?"},{"q":"Où ___ vous habitez ?","en":"Where do you live?","opts":["est-ce que","est-ce","que","qu'"],"a":"est-ce que","why":"After a question word…","hint":"Où <b>est-ce que</b> vous habitez ?"}],"build":[{"en":"Do you live in Paris? (est-ce que)","tiles":["Est-ce que","vous","habitez","à","Paris ?"],"trap":"Est-ce","why":"The whole starter…","hint":"<b>Est-ce que</b> vous …"},{"en":"Does he speak English? (verb first)","tiles":["Parle-t-il","anglais ?"],"trap":"Parle-il","why":"Two vowels meet.","hint":"<b>Parle-t-il</b> …"},{"en":"Where do you live? (casual)","tiles":["Tu","habites","où ?"],"trap":"ou","why":"where, with its accent.","hint":"… <b>où</b> ?"},{"en":"Is she here? (est-ce que)","tiles":["Est-ce","qu'elle","est","là ?"],"trap":"que elle","why":"Before a vowel…","hint":"Est-ce <b>qu'elle</b> …"},{"en":"Are you French? (verb first, vous)","tiles":["Êtes-vous","français ?"],"trap":"Es-vous","why":"être with vous.","hint":"<b>Êtes-vous</b> …"}],"spot":[{"words":["Parle-il","anglais ?"],"bad":0,"fix":"Parle-t-il","hint":"Two vowels meet: <b>-t-</b>.","look":"Look between the verb and il."},{"words":["Est-ce que","elle","vient ?"],"bad":0,"fix":"Est-ce qu'","hint":"Before a vowel: est-ce <b>qu'</b>elle.","look":"What happens to que before a vowel?","say":"Est-ce qu'elle vient ?"},{"words":["Tu","habites","ou ?"],"bad":2,"fix":"où ?","hint":"<b>où</b> = where (ou = or).","look":"Look at the question word."},{"words":["A-il","faim ?"],"bad":0,"fix":"A-t-il","hint":"Two vowels meet: <b>A-t-il</b>.","look":"Look between a and il."},{"words":["Est-ce","tu","viens ?"],"bad":0,"fix":"Est-ce que","hint":"The whole starter: <b>Est-ce que</b>.","look":"Something is missing at the start."}]},"drill":[["Est-ce que form: Vous habitez à Paris.","Est-ce que vous habitez à Paris ?","<b>Est-ce que</b> at the front."],["Invert: Tu as faim.","As-tu faim ?","Verb first, with a hyphen: <b>As-tu</b> …?"],["Invert: Il parle anglais.","Parle-t-il anglais ?","Two vowels meet: add <b>-t-</b>."],["Where do you live? (casual)","Tu habites où ?","Casual: the question word at the end."],["Est-ce que form: Elle est là.","Est-ce qu'elle est là ?","Before a vowel: est-ce <b>qu'</b>elle."],["Invert: Vous êtes français.","Êtes-vous français ?","Verb first: <b>Êtes-vous</b> …?"]]},"8":{"line":"An adjective matches its noun: <b>+e</b> for feminine, <b>+s</b> for plural (petit, petite, petits, petites). Most go <b>after</b> the noun: une voiture rouge. A few short ones go <b>before</b>: beauty, age, good, size (BAGS): une belle maison, un jeune homme, un bon ami, une petite ville. Watch: blanc → blanche, beau → bel before a vowel.","words":"Describing people: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:12\">Vocab 12 · Personality & Physical Description</a> · colours: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:14\">Vocab 14 · Les Couleurs</a>.","steps":[{"tool":"agree","title":"Switch the noun","sub":"Tap masculine, feminine or plural: what changes lights up.","cols":["masculine","feminine","masc. plural","fem. plural"],"rows":[{"forms":["un chat noir","une chatte noire","des chats noirs","des chattes noires"],"en":"a black cat"},{"forms":["un petit garçon","une petite fille","des petits garçons","des petites filles"],"en":"a little boy / girl"},{"forms":["un ami content","une amie contente","des amis contents","des amies contentes"],"en":"a happy friend"},{"forms":["un homme heureux","une femme heureuse","des hommes heureux","des femmes heureuses"],"en":"-eux → -euse"},{"forms":["un pull blanc","une robe blanche","des pulls blancs","des robes blanches"],"en":"blanc → blanche"},{"forms":["un livre rouge","une voiture rouge","des livres rouges","des voitures rouges"],"en":"-e already: no new e"}]},{"tool":"sort","title":"Before or after the noun?","sub":"Tap the box for each adjective.","boxes":[{"k":"b","label":"before","sub":"BAGS: beauty, age, good, size"},{"k":"a","label":"after","sub":"most: colour, nationality, shape, feelings"}],"cards":[{"t":"petit","box":"b","why":"Size: une <b>petite</b> ville."},{"t":"rouge","box":"a","why":"Colour: une voiture <b>rouge</b>."},{"t":"jeune","box":"b","why":"Age: un <b>jeune</b> homme."},{"t":"français","box":"a","why":"Nationality: un film <b>français</b>."},{"t":"bon","box":"b","why":"Good: un <b>bon</b> ami."},{"t":"intéressant","box":"a","why":"un livre <b>intéressant</b>."},{"t":"beau","box":"b","why":"Beauty: un <b>beau</b> jardin."},{"t":"rond","box":"a","why":"Shape: une table <b>ronde</b>."},{"t":"vieux","box":"b","why":"Age: un <b>vieux</b> livre."}]},{"tool":"flip","title":"Special forms","sub":"Tap a card.","cards":[{"a":"beau + homme","b":"un bel homme","tag":"beau → bel before a vowel"},{"a":"vieux + ami","b":"un vieil ami","tag":"vieux → vieil before a vowel"},{"a":"nouveau + hôtel","b":"un nouvel hôtel","tag":"nouveau → nouvel"},{"a":"blanc (feminine)","b":"blanche","tag":"-c → -che"},{"a":"long (feminine)","b":"longue","tag":"-g → -gue"},{"a":"beau (feminine)","b":"belle","tag":"beau → belle"}]}],"practice":{"choose":[{"q":"une voiture ___ (blanc)","en":"a white car","opts":["blanche","blance","blanc","blanches"],"a":"blanche","why":"blanc has a special feminine.","hint":"<b>blanche</b>."},{"q":"des chats ___ (noir)","en":"black cats","opts":["noirs","noir","noires","noire"],"a":"noirs","why":"Masculine, more than one.","hint":"<b>noirs</b>."},{"q":"un ___ homme (beau)","en":"a handsome man","opts":["bel","beau","belle","beaux"],"a":"bel","why":"homme starts with a silent h.","hint":"<b>bel</b> before a vowel."},{"q":"une ___ maison (petit)","en":"a small house","opts":["petite","petit","petites","petits"],"a":"petite","why":"One, feminine.","hint":"<b>petite</b>."},{"q":"une robe ___ (long)","en":"a long dress","opts":["longue","longe","long","longues"],"a":"longue","why":"long has a special feminine.","hint":"<b>longue</b>."},{"q":"des filles ___ (heureux)","en":"happy girls","opts":["heureuses","heureux","heureuse","heureuxes"],"a":"heureuses","why":"Feminine and more than one.","hint":"<b>heureuses</b>."},{"q":"un ___ ami (vieux)","en":"an old friend","opts":["vieil","vieux","vieille","vieilles"],"a":"vieil","why":"ami starts with a vowel.","hint":"<b>vieil</b> before a vowel."}],"build":[{"en":"I live in a small town.","tiles":["J'habite","dans","une","petite","ville."],"trap":"petit","why":"ville is feminine; petit goes before.","hint":"une <b>petite</b> ville."},{"en":"She has a red car.","tiles":["Elle","a","une","voiture","rouge."],"trap":"rouges","why":"One car; colours go after.","hint":"une voiture <b>rouge</b>."},{"en":"He is a young man.","tiles":["C'est","un","jeune","homme."],"trap":"jeunes","why":"Age goes before.","hint":"un <b>jeune</b> homme."},{"en":"Two happy girls.","tiles":["Deux","filles","heureuses."],"trap":"heureux","why":"Feminine and more than one.","hint":"filles <b>heureuses</b>."},{"en":"It's a beautiful house.","tiles":["C'est","une","belle","maison."],"trap":"beau","why":"maison is feminine.","hint":"une <b>belle</b> maison."}],"spot":[{"words":["une","voiture","blanc."],"bad":2,"fix":"blanche.","hint":"Feminine: <b>blanche</b>.","look":"Does the adjective match voiture?"},{"words":["un","beau","homme."],"bad":1,"fix":"bel","hint":"Before a vowel: <b>bel</b>.","look":"homme starts with a silent h."},{"words":["une","maison petite."],"bad":1,"fix":"petite maison.","hint":"Size goes before: une <b>petite maison</b>.","look":"Where does petit go?"},{"words":["des","chats","noir."],"bad":2,"fix":"noirs.","hint":"More than one: <b>noirs</b>.","look":"How many cats?"},{"words":["une","rouge voiture."],"bad":1,"fix":"voiture rouge.","hint":"Colours go after: une <b>voiture rouge</b>.","look":"Where do colours go?"}]},"drill":[["une voiture (blanc)","une voiture blanche","blanc → <b>blanche</b>."],["des chats (noir)","des chats noirs","Plural: <b>+s</b>."],["un (beau) homme","un bel homme","Before a vowel: <b>bel</b>."],["une maison (petit)","une petite maison","Size goes before, + e: une <b>petite</b> maison."],["une robe (long)","une robe longue","long → <b>longue</b>."],["des filles (heureux)","des filles heureuses","-eux → <b>-euse</b>, plural <b>-euses</b>."]]},"9":{"line":"my: <b>mon / ma / mes</b> · your: ton / ta / tes · his or her: <b>son / sa / ses</b> · our: notre / nos · your: votre / vos · their: leur / leurs. They agree with the <b>thing owned</b>: sa voiture = his car or her car. Before a vowel: <b>mon</b> amie. this: <b>ce / cet</b> (before a vowel) <b>/ cette / ces</b>.","words":"The family: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:9\">Vocab 9 · La Famille</a>.","steps":[{"tool":"agree","title":"Switch the thing owned","sub":"Tap masculine, feminine or plural: the little word follows the thing, not the owner.","cols":["masculine","feminine","plural"],"rows":[{"forms":["mon frère","ma sœur","mes frères"],"en":["my brother","my sister","my brothers"]},{"forms":["ton père","ta mère","tes parents"],"en":["your father","your mother","your parents"]},{"forms":["son livre","sa voiture","ses clés"],"en":["his / her book","his / her car","his / her keys"]},{"forms":["notre ami","notre amie","nos amis"],"en":["our friend","our friend","our friends"]},{"forms":["leur chat","leur maison","leurs enfants"],"en":["their cat","their house","their children"]},{"forms":["ce livre","cette table","ces livres"],"en":["this book","this table","these books"]}]},{"tool":"sort","title":"son, sa or ses?","sub":"Look at the thing, not at who owns it. Tap the box.","boxes":[{"k":"son","label":"son","sub":"masculine, or before a vowel"},{"k":"sa","label":"sa","sub":"feminine"},{"k":"ses","label":"ses","sub":"more than one"}],"cards":[{"t":"Paul: … voiture","box":"sa","why":"voiture is feminine: <b>sa</b> voiture, even for Paul.","say":"sa voiture"},{"t":"Marie: … vélo","box":"son","why":"vélo is masculine: <b>son</b> vélo, even for Marie.","say":"son vélo"},{"t":"Paul: … sœurs","box":"ses","why":"More than one: <b>ses</b> sœurs.","say":"ses sœurs"},{"t":"Marie: … père","box":"son","why":"<b>son</b> père.","say":"son père"},{"t":"Marie: … amie","box":"son","why":"amie starts with a vowel: <b>son</b> amie.","say":"son amie"},{"t":"Paul: … maison","box":"sa","why":"<b>sa</b> maison.","say":"sa maison"},{"t":"Marie: … livres","box":"ses","why":"<b>ses</b> livres.","say":"ses livres"}]},{"tool":"flip","title":"Before a vowel","sub":"Tap a card: ma, ta, sa and ce change before a vowel.","cards":[{"a":"ma + amie","b":"mon amie","tag":"ma → mon"},{"a":"ta + école","b":"ton école","tag":"ta → ton"},{"a":"sa + histoire","b":"son histoire","tag":"sa → son (silent h)"},{"a":"ce + hôtel","b":"cet hôtel","tag":"ce → cet"},{"a":"ce + arbre","b":"cet arbre","tag":"ce → cet"},{"a":"ce + garçon","b":"ce garçon","tag":"no vowel: no change"}]}],"practice":{"choose":[{"q":"___ sœur (my)","en":"my sister","opts":["ma","mon","mes","me"],"a":"ma","why":"sœur is feminine.","hint":"<b>ma</b> sœur."},{"q":"___ amie (my)","en":"my friend (a woman)","opts":["mon","ma","m'","mes"],"a":"mon","why":"amie starts with a vowel.","hint":"Before a vowel: <b>mon</b> amie."},{"q":"___ hôtel (this)","en":"this hotel","opts":["cet","ce","cette","ces"],"a":"cet","why":"hôtel starts with a silent h.","hint":"<b>cet</b> hôtel."},{"q":"___ maison (this)","en":"this house","opts":["cette","cet","ce","ces"],"a":"cette","why":"maison is feminine.","hint":"<b>cette</b> maison."},{"q":"Paul aime ___ voiture.","en":"Paul loves his car.","opts":["sa","son","ses","leur"],"a":"sa","why":"Look at voiture, not at Paul.","hint":"voiture is feminine: <b>sa</b>."},{"q":"Ils aiment ___ enfants.","en":"They love their children.","opts":["leurs","leur","ses","son"],"a":"leurs","why":"Their, and more than one child.","hint":"<b>leurs</b> enfants."},{"q":"___ livres (these)","en":"these books","opts":["ces","ses","cettes","cet"],"a":"ces","why":"these, not his…","hint":"<b>ces</b> livres (ses = his / her)."}],"build":[{"en":"This is my friend Julie.","tiles":["C'est","mon","amie","Julie."],"trap":"ma","why":"amie starts with a vowel.","hint":"<b>mon</b> amie."},{"en":"Paul washes his car.","tiles":["Paul","lave","sa","voiture."],"trap":"son","why":"voiture is feminine.","hint":"<b>sa</b> voiture."},{"en":"This hotel is big.","tiles":["Cet","hôtel","est","grand."],"trap":"Ce","why":"hôtel starts with a silent h.","hint":"<b>cet</b> hôtel."},{"en":"Their children are here.","tiles":["Leurs","enfants","sont","là."],"trap":"Ses","why":"Their, more than one.","hint":"<b>leurs</b> enfants."},{"en":"I like these shoes.","tiles":["J'aime","ces","chaussures."],"trap":"ses","why":"these…","hint":"<b>ces</b> chaussures."}],"spot":[{"words":["C'est","ma","amie."],"bad":1,"fix":"mon","hint":"Before a vowel: <b>mon</b> amie.","look":"amie starts with a vowel."},{"words":["Ce","hôtel","est loin."],"bad":0,"fix":"Cet","hint":"Before a vowel: <b>cet</b>.","look":"hôtel starts with a silent h."},{"words":["Marie aime","son","voiture."],"bad":1,"fix":"sa","hint":"voiture is feminine: <b>sa</b>.","look":"Look at the thing, not the owner."},{"words":["Ils voient","leur","enfants."],"bad":1,"fix":"leurs","hint":"More than one: <b>leurs</b>.","look":"How many children?"},{"words":["J'aime","cette","livre."],"bad":1,"fix":"ce","hint":"livre is masculine: <b>ce</b>.","look":"Is livre masculine or feminine?"}]},"drill":[["___ sœur (my)","ma sœur","Feminine: <b>ma</b>."],["___ amie (my)","mon amie","Before a vowel: <b>mon</b>, even feminine."],["___ hôtel (this)","cet hôtel","Before a vowel: <b>cet</b>."],["___ maison (this)","cette maison","Feminine: <b>cette</b>."],["___ voiture (his)","sa voiture","voiture is feminine: <b>sa</b>, whoever owns it."],["___ enfants (their)","leurs enfants","More than one: <b>leurs</b>."]]},"11":{"line":"<b>C'est</b> + a name, or + un / le / mon … + a noun: c'est Paul, c'est un médecin, c'est mon frère. <b>Il / elle est</b> + an adjective, or a job with <b>no article</b>: il est grand, elle est infirmière. About a thing or an idea: c'est beau, c'est facile.","words":"The jobs: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:11\">Vocab 11 · Professions & Occupations</a>.","steps":[{"tool":"sort","title":"c'est or il / elle est?","sub":"Tap the box for each ending.","boxes":[{"k":"c","label":"C'est","sub":"+ a name, or un / le / mon + a noun"},{"k":"i","label":"Il / elle est","sub":"+ an adjective, or a job alone"}],"cards":[{"t":"… Paul.","box":"c","why":"A name: <b>c'est</b> Paul.","say":"C'est Paul."},{"t":"… médecin.","box":"i","why":"A job alone: <b>il est</b> médecin.","say":"Il est médecin."},{"t":"… un bon médecin.","box":"c","why":"un + a noun: <b>c'est</b> un bon médecin.","say":"C'est un bon médecin."},{"t":"… très grand. (Paul)","box":"i","why":"An adjective: <b>il est</b> très grand.","say":"Il est très grand."},{"t":"… mon frère.","box":"c","why":"mon + a noun: <b>c'est</b> mon frère.","say":"C'est mon frère."},{"t":"… infirmière. (Marie)","box":"i","why":"A job alone: <b>elle est</b> infirmière.","say":"Elle est infirmière."},{"t":"… une amie.","box":"c","why":"une + a noun: <b>c'est</b> une amie.","say":"C'est une amie."},{"t":"… fatiguée. (Léa)","box":"i","why":"An adjective: <b>elle est</b> fatiguée.","say":"Elle est fatiguée."}]},{"tool":"swap","title":"Add un or une, change the start","sub":"Pick a sentence and tap « Add un / une »: il est becomes c'est.","button":["Add un / une","Take it away"],"legend":[["x","the start"],["p","un / une (+ adjective)"]],"items":[{"label":"Il est médecin.","en":["He is a doctor.","He is a good doctor."],"a":[["s","Il est","x"],["o","médecin.",""]],"b":[["s2","C'est","x"],["a","un","p"],["ad","bon","p"],["o","médecin.",""]],"note":"With un / une, <b>il est</b> becomes <b>c'est</b>."},{"label":"Elle est professeure.","en":["She is a teacher.","She is a nice teacher."],"a":[["s","Elle est","x"],["o","professeure.",""]],"b":[["s2","C'est","x"],["a","une","p"],["o","professeure",""],["ad","sympa.","p"]],"note":"<b>c'est une</b> professeure sympa."},{"label":"Il est français.","en":["He is French.","He is a French friend."],"a":[["s","Il est","x"],["o","français.",""]],"b":[["s2","C'est","x"],["a","un","p"],["n","ami","p"],["o","français.",""]],"note":"An adjective alone: il est. un + a noun: <b>c'est</b>."}]}],"practice":{"choose":[{"q":"___ un livre intéressant.","en":"It's an interesting book.","opts":["C'est","Il est","Elle est","Ce"],"a":"C'est","why":"un + a noun follows.","hint":"un + noun: <b>c'est</b>."},{"q":"Marie ? ___ infirmière.","en":"Marie? She is a nurse.","opts":["Elle est","C'est","Elle est une","C'est une"],"a":"Elle est","why":"A job with no article…","hint":"A job alone: <b>elle est</b> infirmière."},{"q":"___ mon frère.","en":"This is my brother.","opts":["C'est","Il est","Il","Ce sont"],"a":"C'est","why":"mon + a noun follows.","hint":"<b>c'est</b> mon frère."},{"q":"Paul ? ___ très grand.","en":"Paul? He is very tall.","opts":["Il est","C'est","Il a","Ce"],"a":"Il est","why":"An adjective follows, about a person.","hint":"<b>il est</b> très grand."},{"q":"Il est ___.","en":"He is a doctor.","opts":["médecin","un médecin","le médecin","une médecin"],"a":"médecin","why":"After il est, a job…","hint":"No article: il est <b>médecin</b>."},{"q":"C'est ___ bon médecin.","en":"He is a good doctor.","opts":["un","le","de","des"],"a":"un","why":"After c'est, a noun takes…","hint":"<b>c'est un</b> bon médecin."},{"q":"Le film ? ___ génial !","en":"The film? It is great!","opts":["C'est","Il est","Elle est","Ce sont"],"a":"C'est","why":"An opinion about a thing…","hint":"Your opinion of a thing: <b>c'est</b> génial."}],"build":[{"en":"She is a nurse.","tiles":["Elle","est","infirmière."],"trap":"une","why":"A job alone: no article.","hint":"elle est <b>infirmière</b>."},{"en":"This is my brother.","tiles":["C'est","mon","frère."],"trap":"Il est","why":"mon + a noun…","hint":"<b>c'est</b> mon frère."},{"en":"He is very tall.","tiles":["Il","est","très","grand."],"trap":"C'est","why":"An adjective about a person…","hint":"<b>il est</b> très grand."},{"en":"It's an interesting book.","tiles":["C'est","un","livre","intéressant."],"trap":"Il est","why":"un + a noun…","hint":"<b>c'est</b> un livre."},{"en":"He is a good doctor.","tiles":["C'est","un","bon","médecin."],"trap":"Il est","why":"un + a noun…","hint":"<b>c'est</b> un bon médecin."}],"spot":[{"words":["Il est","un bon","médecin."],"bad":0,"fix":"C'est","hint":"un + a noun: <b>c'est</b>.","look":"Look at the start."},{"words":["Paul ?","C'est","très grand."],"bad":1,"fix":"Il est","hint":"An adjective about a person: <b>il est</b>.","look":"Is it an adjective or a noun after it?"},{"words":["Il est","mon","frère."],"bad":0,"fix":"C'est","hint":"mon + a noun: <b>c'est</b>.","look":"Look at the start."},{"words":["Marie ?","Elle est","une infirmière."],"bad":2,"fix":"infirmière.","hint":"A job after elle est: no article.","look":"Look after elle est."},{"words":["Il est","Paul."],"bad":0,"fix":"C'est","hint":"A name: <b>c'est</b> Paul.","look":"Look at the start."}]},"drill":[["___ un livre intéressant","C'est un livre intéressant.","un + a noun: <b>c'est</b>."],["She is a nurse","Elle est infirmière.","A job alone: <b>elle est</b> infirmière, no article."],["This is my brother","C'est mon frère. / Voici mon frère.","mon + a noun: <b>c'est</b> mon frère."],["He is very tall","Il est très grand.","An adjective: <b>il est</b> grand."],["He is French.","Il est français.","An adjective: <b>il est</b> français."],["He is a French friend.","C'est un ami français.","un + a noun: <b>c'est</b> un ami."]]},"13":{"line":"What is going to happen: <b>aller</b> in the present + the verb as it is: je <b>vais</b> manger, tu vas partir, il va pleuvoir, nous allons voir. The no goes round aller: je <b>ne vais pas</b> partir. It is the usual way to talk about plans.","words":"","steps":[{"tool":"line","title":"On the time line","sub":"Tap a point: before now, now, or what is going to happen.","now":"","marks":[{"at":-0.8,"label":"hier","fr":"Hier, j'ai mangé chez moi.","en":"Yesterday I ate at home.","note":"Before now: the passé composé (in A2)."},{"at":0.0,"label":"maintenant","fr":"Je mange.","en":"I am eating.","note":"Now: the present."},{"at":0.3,"label":"ce soir","fr":"Ce soir, je vais manger au restaurant.","html":"Ce soir, je <span class=\"gt-end\">vais manger</span> au restaurant.","en":"Tonight I'm going to eat at the restaurant."},{"at":0.6,"label":"demain","fr":"Demain, il va pleuvoir.","html":"Demain, il <span class=\"gt-end\">va pleuvoir</span>.","en":"Tomorrow it's going to rain."},{"at":0.92,"label":"l'été prochain","fr":"L'été prochain, nous allons voyager.","html":"L'été prochain, nous <span class=\"gt-end\">allons voyager</span>.","en":"Next summer we're going to travel."}]},{"tool":"swap","title":"Now → soon","sub":"Pick a sentence and tap « Make it the future »: aller comes in, the verb goes back to its -er, -ir or -re form.","button":["Make it the future","Back to now"],"legend":[["x","aller"],["v","the verb"],["n","ne … pas"]],"items":[{"label":"Je mange.","en":["I am eating.","I am going to eat."],"a":[["s","Je",""],["v","mange.","v"]],"b":[["s","Je",""],["a","vais","x"],["v","manger.","v"]]},{"label":"Nous partons.","en":["We are leaving.","We are going to leave."],"a":[["s","Nous",""],["v","partons.","v"]],"b":[["s","Nous",""],["a","allons","x"],["v","partir.","v"]]},{"label":"Il pleut.","en":["It's raining.","It's going to rain."],"a":[["s","Il",""],["v","pleut.","v"]],"b":[["s","Il",""],["a","va","x"],["v","pleuvoir.","v"]]},{"label":"Elle ne part pas.","en":["She isn't leaving.","She isn't going to leave."],"a":[["s","Elle",""],["ne","ne","n"],["v","part","v"],["pas","pas.","n"]],"b":[["s","Elle",""],["ne","ne","n"],["a","va","x"],["pas","pas","n"],["v","partir.","v"]],"note":"The no goes round <b>va</b>: elle ne va pas partir."}]},{"tool":"conj","title":"aller + the verb","sub":"Tap a person: only aller changes.","neg":true,"verbs":[{"inf":"manger","en":"going to eat","forms":["vais","vas","va","allons","allez","vont"],"tail":"manger"},{"inf":"partir","en":"going to leave","forms":["vais","vas","va","allons","allez","vont"],"tail":"partir"}]}],"practice":{"choose":[{"q":"Nous ___ manger.","en":"We are going to eat.","opts":["allons","allez","vont","vais"],"a":"allons","why":"aller with nous.","hint":"nous <b>allons</b> manger."},{"q":"Je vais ___ demain.","en":"I'm going to leave tomorrow.","opts":["partir","pars","part","parti"],"a":"partir","why":"After vais, the verb…","hint":"It stays as it is: <b>partir</b>."},{"q":"Il ___ pleuvoir.","en":"It's going to rain.","opts":["va","vas","vais","est"],"a":"va","why":"aller with il.","hint":"il <b>va</b> pleuvoir."},{"q":"Elle ne ___ pas venir.","en":"She isn't going to come.","opts":["va","vas","vais","vont"],"a":"va","why":"aller with elle.","hint":"elle ne <b>va</b> pas venir."},{"q":"Ils ___ voyager.","en":"They are going to travel.","opts":["vont","allent","va","allons"],"a":"vont","why":"aller with ils.","hint":"ils <b>vont</b> voyager."},{"q":"Tu ___ voir.","en":"You're going to see.","opts":["vas","va","vais","allez"],"a":"vas","why":"aller with tu.","hint":"tu <b>vas</b> voir."},{"q":"Je ___ t'appeler.","en":"I'm going to call you.","opts":["vais","va","vas","suis"],"a":"vais","why":"aller with je.","hint":"je <b>vais</b> t'appeler."}],"build":[{"en":"We are going to eat.","tiles":["Nous","allons","manger."],"trap":"mangeons","why":"The second verb stays as it is.","hint":"allons <b>manger</b>."},{"en":"She isn't going to leave.","tiles":["Elle","ne","va","pas","partir."],"trap":"part","why":"The no goes round va.","hint":"ne <b>va</b> pas partir."},{"en":"It's going to rain.","tiles":["Il","va","pleuvoir."],"trap":"pleut","why":"The second verb stays as it is.","hint":"va <b>pleuvoir</b>."},{"en":"I'm going to call you.","tiles":["Je","vais","t'appeler."],"trap":"appelle","why":"The second verb stays as it is.","hint":"vais <b>t'appeler</b>."},{"en":"They are going to travel.","tiles":["Ils","vont","voyager."],"trap":"voyagent","why":"The second verb stays as it is.","hint":"vont <b>voyager</b>."}],"spot":[{"words":["Je","vais","mange."],"bad":2,"fix":"manger.","hint":"The second verb stays as it is: <b>manger</b>.","look":"Look at the second verb."},{"words":["Nous","allez","partir."],"bad":1,"fix":"allons","hint":"aller with nous: <b>allons</b>.","look":"Look at aller with nous."},{"words":["Elle","va pas","venir."],"bad":1,"fix":"ne va pas","hint":"The full no: <b>ne va pas</b>.","look":"Something is missing in the no."},{"words":["Il","va","pleut."],"bad":2,"fix":"pleuvoir.","hint":"The second verb stays as it is: <b>pleuvoir</b>.","look":"Look at the second verb."},{"words":["Ils","allent","voyager."],"bad":1,"fix":"vont","hint":"aller with ils: <b>vont</b>.","look":"Look at aller with ils."}]},"drill":[["We are going to eat","Nous allons manger. / On va manger.","aller + the verb as it is: nous <b>allons</b> manger."],["She isn't going to leave","Elle ne va pas partir.","The no goes round aller: elle <b>ne va pas</b> partir."],["I'm going to call you","Je vais t'appeler. / Je vais vous appeler. / Je vais te téléphoner.","je <b>vais</b> + the verb."],["It's going to rain","Il va pleuvoir.","il <b>va</b> pleuvoir."],["They are going to travel.","Ils vont voyager.","ils <b>vont</b> + the verb as it is."],["I'm going to eat.","Je vais manger.","je <b>vais</b> manger."]]},"14":{"line":"To tell someone to do something, take the <b>tu, nous</b> or <b>vous</b> form and drop the subject: Parle ! Parlons ! Parlez ! For -er verbs (and aller), the tu form loses its -s: tu manges → <b>Mange !</b> The no goes round the verb: <b>Ne</b> parle <b>pas</b> ! A few are special: sois, soyez (être), aie (avoir).","words":"","steps":[{"tool":"swap","title":"Drop the subject","sub":"Pick a sentence and tap « Make it an order ».","button":["Make it an order","Back to the sentence"],"legend":[["v","the verb"],["n","ne … pas"]],"items":[{"label":"Tu parles.","en":["You speak.","Speak!"],"a":[["s","Tu",""],["v","parles.","v"]],"b":[["v","Parle !","v"]],"note":"-er verbs: tu parles → <b>Parle !</b> (no -s)."},{"label":"Vous entrez.","en":["You come in.","Come in!"],"a":[["s","Vous",""],["v","entrez.","v"]],"b":[["v","Entrez !","v"]],"note":"Polite, or to several people: <b>Entrez !</b>"},{"label":"Nous partons.","en":["We are leaving.","Let's go!"],"a":[["s","Nous",""],["v","partons.","v"]],"b":[["v","Partons !","v"]],"note":"The nous form = « let's »: <b>Partons !</b>"},{"label":"Tu attends.","en":["You wait.","Wait!"],"a":[["s","Tu",""],["v","attends.","v"]],"b":[["v","Attends !","v"]],"note":"Not an -er verb: the -s stays: <b>Attends !</b>"},{"label":"Tu ne parles pas.","en":["You don't speak.","Don't speak!"],"a":[["s","Tu",""],["ne","ne","n"],["v","parles","v"],["pas","pas.","n"]],"b":[["ne","Ne","n"],["v","parle","v"],["pas","pas !","n"]],"note":"The no goes round the verb: <b>Ne parle pas !</b>"},{"label":"Tu vas au lit.","en":["You go to bed.","Go to bed!"],"a":[["s","Tu",""],["v","vas","v"],["o","au lit.",""]],"b":[["v","Va","v"],["o","au lit !",""]],"note":"aller loses its -s too: <b>Va !</b>"}]},{"tool":"sort","title":"tu, nous or vous?","sub":"Who is it for? Tap the box.","boxes":[{"k":"tu","label":"tu","sub":"one person you know well"},{"k":"nous","label":"nous","sub":"let's (you and me)"},{"k":"vous","label":"vous","sub":"polite, or several"}],"cards":[{"t":"Viens !","box":"tu"},{"t":"Venez !","box":"vous"},{"t":"Allons-y !","box":"nous","why":"<b>Allons-y</b> = let's go."},{"t":"Mange !","box":"tu"},{"t":"Écoutez !","box":"vous"},{"t":"Partons !","box":"nous"},{"t":"Attends !","box":"tu"}]},{"tool":"flip","title":"The special ones","sub":"Tap a card.","cards":[{"a":"être (tu)","b":"Sois sage !","tag":"être → sois","en":"be good"},{"a":"être (vous)","b":"Soyez à l'heure !","tag":"être → soyez","en":"be on time"},{"a":"avoir (tu)","b":"N'aie pas peur !","tag":"avoir → aie","en":"don't be afraid"},{"a":"aller (tu)","b":"Va !","tag":"tu vas → va","en":"go"},{"a":"faire (tu)","b":"Fais attention !","tag":"faire → fais","en":"be careful"}]}],"practice":{"choose":[{"q":"Tell a friend: ___ ! (wait)","en":"Wait!","opts":["Attends","Attend","Attendez","Tu attends"],"a":"Attends","why":"A friend: the tu form, no subject.","hint":"<b>Attends !</b>"},{"q":"Tell your boss: ___ ! (come in)","en":"Come in!","opts":["Entrez","Entre","Entrons","Vous entrez"],"a":"Entrez","why":"Polite: the vous form, no subject.","hint":"<b>Entrez !</b>"},{"q":"___ ! (Let's go)","en":"Let's go!","opts":["Allons-y","Allez-y","Va","Vont"],"a":"Allons-y","why":"Let's = the nous form.","hint":"<b>Allons-y !</b>"},{"q":"___ ! (eat, tu)","en":"Eat!","opts":["Mange","Manges","Mangez","Tu manges"],"a":"Mange","why":"-er verbs with tu lose something.","hint":"<b>Mange !</b> (no -s)."},{"q":"Ne ___ pas en retard ! (tu, être)","en":"Don't be late!","opts":["sois","es","être","soit"],"a":"sois","why":"être has a special form.","hint":"Ne <b>sois</b> pas en retard !"},{"q":"___ attention ! (tu, faire)","en":"Be careful!","opts":["Fais","Fait","Faire","Faites"],"a":"Fais","why":"faire with tu.","hint":"<b>Fais</b> attention !"},{"q":"Ne ___ pas ! (tu, parler)","en":"Don't speak!","opts":["parle","parles","parlez","parler"],"a":"parle","why":"-er verbs with tu…","hint":"Ne <b>parle</b> pas !"}],"build":[{"en":"Come in, please! (vous)","tiles":["Entrez,","s'il","vous","plaît !"],"trap":"Vous entrez","why":"No subject in an order.","hint":"<b>Entrez</b>, …"},{"en":"Don't be late! (tu)","tiles":["Ne","sois","pas","en retard !"],"trap":"es","why":"être has a special form.","hint":"Ne <b>sois</b> pas …"},{"en":"Let's go to the park!","tiles":["Allons","au","parc !"],"trap":"Nous","why":"No subject in an order.","hint":"<b>Allons</b> au parc !"},{"en":"Eat your soup! (tu)","tiles":["Mange","ta","soupe !"],"trap":"Manges","why":"-er verbs with tu lose the -s.","hint":"<b>Mange</b> ta soupe !"},{"en":"Don't talk! (vous)","tiles":["Ne","parlez","pas !"],"trap":"Vous","why":"No subject in an order.","hint":"Ne <b>parlez</b> pas !"}],"spot":[{"words":["Manges","ta soupe !"],"bad":0,"fix":"Mange","hint":"-er verbs lose the -s: <b>Mange !</b>","look":"Look at the end of the verb."},{"words":["Tu attends !"],"bad":0,"fix":"Attends !","hint":"No subject in an order: <b>Attends !</b>","look":"Is the subject needed?"},{"words":["Ne","es","pas en retard !"],"bad":1,"fix":"sois","hint":"être: <b>sois</b>.","look":"être has a special form."},{"words":["Parle","pas !"],"bad":0,"fix":"Ne parle","hint":"The full no: <b>Ne parle pas !</b>","look":"Something is missing in the no."},{"words":["Vas","au lit !"],"bad":0,"fix":"Va","hint":"aller loses its -s: <b>Va !</b>","look":"Look at the end of the verb."}]},"drill":[["Tell a friend: wait!","Attends !","The tu form, no subject: <b>Attends !</b>"],["Tell your boss: come in!","Entrez !","Polite: the vous form, <b>Entrez !</b>"],["Let's go!","Allons-y ! / On y va !","Let's = the nous form: <b>Allons-y !</b>"],["Don't be late (tu)","Ne sois pas en retard !","être → <b>sois</b>; the no goes round it."],["Tell a friend: eat!","Mange !","-er verbs drop the -s: <b>Mange !</b>"],["Tell two friends: listen!","Écoutez !","More than one person: the vous form, <b>Écoutez !</b>"]]},"2":{"line":"<b>le, la, l', les</b> = the · <b>un, une, des</b> = a, some · <b>du, de la, de l', des</b> = some of something. Only <b>le</b> and <b>les</b> stick to à and de: <b>au, aux, du, des</b>. A city takes <b>à</b> (à Paris); a country takes <b>au</b> (masculine), <b>en</b> (feminine) or <b>aux</b> (plural); a person takes <b>chez</b>. After a no or a quantity: <b>de</b>.","words":"The countries and nationalities: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:10\">Vocab 10 · Les Nationalités & Pays</a>. Food and ordering: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:18\">Vocab 18 · Café, Food & Ordering</a>.","steps":[{"tool":"join","title":"à and de + the article","sub":"Tap a pair: only le and les stick; la and l' stay apart.","pairs":[{"a":"à","b":"le marché","res":"au marché","ex":"Je vais au marché.","en":"I am going to the market."},{"a":"à","b":"la plage","res":"à la plage","stay":true,"ex":"Nous allons à la plage.","en":"We are going to the beach."},{"a":"à","b":"l'école","res":"à l'école","stay":true,"ex":"Il est à l'école.","en":"He is at school."},{"a":"à","b":"les enfants","res":"aux enfants","ex":"Elle parle aux enfants.","en":"She is talking to the children."},{"a":"de","b":"le cinéma","res":"du cinéma","ex":"Je reviens du cinéma.","en":"I am coming back from the cinema."},{"a":"de","b":"la gare","res":"de la gare","stay":true,"ex":"Je viens de la gare.","en":"I am coming from the station."},{"a":"de","b":"les voisins","res":"des voisins","ex":"C'est la porte des voisins.","en":"It is the neighbours' door."}]},{"tool":"sort","title":"Some of it, or all of it?","sub":"Tap the box: an amount (some) or the thing in general (likes and dislikes)?","boxes":[{"k":"some","label":"du / de la / des","sub":"some, an amount"},{"k":"all","label":"le / la / les","sub":"in general: aimer, adorer, détester"}],"cards":[{"t":"Je bois … café le matin.","box":"some","why":"An amount you drink: <b>du</b> café.","say":"Je bois du café le matin."},{"t":"J'adore … café.","box":"all","why":"Likes take le: <b>le</b> café.","say":"J'adore le café."},{"t":"Tu veux … pain ?","box":"some","why":"Some bread: <b>du</b> pain.","say":"Tu veux du pain ?"},{"t":"Je déteste … fromage.","box":"all","why":"Dislikes take le: <b>le</b> fromage.","say":"Je déteste le fromage."},{"t":"On achète … pommes.","box":"some","why":"Some apples: <b>des</b> pommes.","say":"On achète des pommes."},{"t":"Les enfants aiment … chocolat.","box":"all","why":"Likes take le: <b>le</b> chocolat.","say":"Les enfants aiment le chocolat."}]},{"tool":"flip","title":"After a no, after a quantity","sub":"Tap a card: du, de la, des become de.","cards":[{"a":"Je bois du café.","b":"Je ne bois pas de café.","tag":"du → pas de"},{"a":"Il y a de la soupe.","b":"Il n'y a pas de soupe.","tag":"de la → pas de"},{"a":"Elle mange des pommes.","b":"Elle mange beaucoup de pommes.","tag":"des → beaucoup de"},{"a":"J'achète du fromage.","b":"J'achète un kilo de fromage.","tag":"du → un kilo de"},{"a":"Il boit de l'eau.","b":"Il ne boit pas d'eau.","tag":"de l' → pas d'"}]},{"tool":"sort","title":"en, au, aux or à?","sub":"Tap the box for each place. Watch the masculine countries that end in -e.","boxes":[{"k":"en","label":"en","sub":"feminine, or starts with a vowel"},{"k":"au","label":"au","sub":"masculine"},{"k":"aux","label":"aux","sub":"plural"},{"k":"a","label":"à","sub":"a city"}],"cards":[{"t":"France","box":"en","why":"<b>en</b> France (la France)."},{"t":"Canada","box":"au","why":"<b>au</b> Canada (le Canada)."},{"t":"États-Unis","box":"aux","why":"<b>aux</b> États-Unis (les États-Unis)."},{"t":"Paris","box":"a","why":"A city: <b>à</b> Paris."},{"t":"Espagne","box":"en","why":"<b>en</b> Espagne (l'Espagne)."},{"t":"Japon","box":"au","why":"<b>au</b> Japon (le Japon)."},{"t":"Mexique","box":"au","why":"A trap: -e but masculine: <b>au</b> Mexique."},{"t":"Iran","box":"en","why":"A vowel: <b>en</b> Iran."},{"t":"Pays-Bas","box":"aux","why":"<b>aux</b> Pays-Bas."},{"t":"Londres","box":"a","why":"A city: <b>à</b> Londres."},{"t":"Portugal","box":"au","why":"<b>au</b> Portugal."},{"t":"Cambodge","box":"au","why":"A trap: -e but masculine: <b>au</b> Cambodge."}]},{"tool":"flip","title":"Going to → coming from","sub":"Tap a card: « to » turns into « from ».","cards":[{"a":"Je vais en France.","b":"Je viens de France.","tag":"en → de"},{"a":"Je vais au Canada.","b":"Je viens du Canada.","tag":"au → du"},{"a":"Je vais aux États-Unis.","b":"Je viens des États-Unis.","tag":"aux → des"},{"a":"Je vais à Paris.","b":"Je viens de Paris.","tag":"à → de"},{"a":"Je vais en Italie.","b":"Je viens d'Italie.","tag":"en → d'"},{"a":"Je vais au Japon.","b":"Je viens du Japon.","tag":"au → du"}]}],"practice":{"choose":[{"q":"Je voudrais ___ eau.","en":"I'd like some water.","opts":["de l'","du","de la","des"],"a":"de l'","why":"eau starts with a vowel.","hint":"<b>de l'</b>eau."},{"q":"Tu veux ___ pain ?","en":"Do you want some bread?","opts":["du","de la","le","des"],"a":"du","why":"le pain: some of it…","hint":"de + le = <b>du</b>."},{"q":"Elle mange ___ salade.","en":"She is eating (some) salad.","opts":["de la","du","la","des"],"a":"de la","why":"la salade: some of it…","hint":"<b>de la</b> salade."},{"q":"J'aime ___ fromage.","en":"I like cheese.","opts":["le","du","de","un"],"a":"le","why":"Liking something: some, or in general?","hint":"Likes take <b>le</b>."},{"q":"Il ne mange pas ___ viande.","en":"He doesn't eat meat.","opts":["de","de la","la","du"],"a":"de","why":"It is a no.","hint":"After a no: <b>pas de</b>."},{"q":"Il y a beaucoup ___ gens.","en":"There are a lot of people.","opts":["de","des","du","les"],"a":"de","why":"After beaucoup…","hint":"<b>beaucoup de</b>."},{"q":"On achète ___ tomates.","en":"We are buying (some) tomatoes.","opts":["des","de","les","du"],"a":"des","why":"Some tomatoes, more than one.","hint":"<b>des</b> tomates."},{"q":"J'habite ___ France.","en":"I live in France.","opts":["en","au","à","aux"],"a":"en","why":"la France is feminine.","hint":"Feminine country: <b>en</b>."},{"q":"Nous allons ___ Canada.","en":"We are going to Canada.","opts":["au","en","à","aux"],"a":"au","why":"le Canada is masculine.","hint":"à + le = <b>au</b>."},{"q":"Elle vit ___ États-Unis.","en":"She lives in the United States.","opts":["aux","au","en","à"],"a":"aux","why":"les États-Unis is plural.","hint":"à + les = <b>aux</b>."},{"q":"Il travaille ___ Paris.","en":"He works in Paris.","opts":["à","en","au","dans"],"a":"à","why":"Paris is a city.","hint":"A city: <b>à</b>."},{"q":"Je vais ___ Mexique.","en":"I am going to Mexico.","opts":["au","en","à","aux"],"a":"au","why":"It ends in -e, but le Mexique is masculine.","hint":"<b>au</b> Mexique."},{"q":"Il vient ___ Japon.","en":"He comes from Japan.","opts":["du","de","des","au"],"a":"du","why":"From + le Japon…","hint":"de + le = <b>du</b>."},{"q":"Elle revient ___ Italie.","en":"She is coming back from Italy.","opts":["d'","de","du","en"],"a":"d'","why":"Italie starts with a vowel.","hint":"<b>d'</b>Italie."}],"build":[{"en":"I drink water.","tiles":["Je","bois","de l'","eau."],"trap":"du","why":"eau starts with a vowel.","hint":"<b>de l'</b>eau."},{"en":"She doesn't eat meat.","tiles":["Elle","ne","mange","pas","de","viande."],"trap":"de la","why":"It is a no.","hint":"pas <b>de</b> viande."},{"en":"Do you want some bread?","tiles":["Tu","veux","du","pain ?"],"trap":"de le","why":"de + le join.","hint":"<b>du</b> pain."},{"en":"There are a lot of people.","tiles":["Il","y a","beaucoup","de","monde."],"trap":"du","why":"After beaucoup…","hint":"beaucoup <b>de</b>."},{"en":"I like chocolate.","tiles":["J'aime","le","chocolat."],"trap":"du","why":"Likes take le.","hint":"j'aime <b>le</b> chocolat."},{"en":"I live in Spain.","tiles":["J'habite","en","Espagne."],"trap":"au","why":"l'Espagne is feminine.","hint":"<b>en</b> Espagne."},{"en":"We are going to Portugal.","tiles":["Nous","allons","au","Portugal."],"trap":"en","why":"le Portugal is masculine.","hint":"<b>au</b> Portugal."},{"en":"She comes from the United States.","tiles":["Elle","vient","des","États-Unis."],"trap":"de les","why":"de + les join.","hint":"<b>des</b> États-Unis."},{"en":"He works in London.","tiles":["Il","travaille","à","Londres."],"trap":"en","why":"London is a city.","hint":"<b>à</b> Londres."},{"en":"I come from Canada.","tiles":["Je","viens","du","Canada."],"trap":"de le","why":"de + le join.","hint":"<b>du</b> Canada."}],"spot":[{"words":["Je","bois","de le","café."],"bad":2,"fix":"du","hint":"de + le = <b>du</b>.","look":"Two little words that should join."},{"words":["Elle","ne mange pas","de la","viande."],"bad":2,"fix":"de","hint":"After a no: <b>pas de</b>.","look":"Look at the word after pas."},{"words":["J'aime","du","chocolat."],"bad":1,"fix":"le","hint":"Likes take <b>le</b>.","look":"With aimer, which article?"},{"words":["Il y a","beaucoup","des","gens."],"bad":2,"fix":"de","hint":"<b>beaucoup de</b>, never beaucoup des.","look":"Look at the word after beaucoup."},{"words":["Je voudrais","du","eau."],"bad":1,"fix":"de l'","hint":"eau starts with a vowel: <b>de l'</b>eau.","look":"eau starts with a vowel.","say":"Je voudrais de l'eau."},{"words":["J'habite","au","France."],"bad":1,"fix":"en","hint":"Feminine country: <b>en</b> France.","look":"Look at the little word before France."},{"words":["Nous allons","en","Canada."],"bad":1,"fix":"au","hint":"Masculine country: <b>au</b> Canada.","look":"Look at the little word before Canada."},{"words":["Il vit","en","Paris."],"bad":1,"fix":"à","hint":"A city: <b>à</b> Paris.","look":"Is Paris a country or a city?"},{"words":["Elle vient","de les","États-Unis."],"bad":1,"fix":"des","hint":"de + les = <b>des</b>.","look":"Two little words that should join."},{"words":["Je vais","en","Mexique."],"bad":1,"fix":"au","hint":"<b>au</b> Mexique: masculine, although it ends in -e.","look":"Mexique is one of the traps."}]},"drill":[["I'd like some water","Je voudrais de l'eau. / J'aimerais de l'eau.","Before a vowel: <b>de l'</b>eau."],["She doesn't eat meat","Elle ne mange pas de viande.","After a no: <b>pas de</b>."],["a lot of people","beaucoup de monde / beaucoup de gens","After beaucoup: <b>de</b>."],["Do you want some bread?","Tu veux du pain ? / Vous voulez du pain ? / Veux-tu du pain ?","de + le = <b>du</b> pain."],["I live in France","J'habite en France. / Je vis en France.","Feminine country: <b>en</b> France."],["We are going to Canada","Nous allons au Canada.","Masculine country: à + le = <b>au</b> Canada."],["She comes from the United States","Elle vient des États-Unis.","From a plural country: de + les = <b>des</b>."],["He lives in Japan","Il habite au Japon. / Il vit au Japon.","le Japon: <b>au</b> Japon."]],"game":"articles"},"24":{"line":"Three phrases with a verb that stays as it is: <b>venir de</b> = has just (elle <b>vient d'</b>arriver), <b>être en train de</b> = is busy doing right now (il <b>est en train de</b> cuisiner), <b>aller</b> = is going to (je <b>vais</b> partir). Only the first verb changes.","words":"","steps":[{"tool":"line","title":"Just now, right now, soon","sub":"Tap a point on the line.","now":"","marks":[{"at":-0.55,"label":"just now","fr":"Elle vient d'arriver.","html":"Elle <span class=\"gt-end\">vient d'</span>arriver.","en":"She has just arrived.","note":"<b>venir de</b> + the verb: it has just happened."},{"at":0.0,"label":"right now","fr":"Il est en train de cuisiner.","html":"Il <span class=\"gt-end\">est en train de</span> cuisiner.","en":"He is busy cooking.","note":"<b>être en train de</b> + the verb: it is happening right now."},{"at":0.55,"label":"soon","fr":"Nous allons partir.","html":"Nous <span class=\"gt-end\">allons</span> partir.","en":"We are going to leave.","note":"<b>aller</b> + the verb: it is going to happen."}]},{"tool":"swap","title":"Add the phrase","sub":"Pick a sentence and tap « Add it »: the phrase comes in, the verb goes back to its -er, -ir or -re form.","button":["Add it","Take it away"],"legend":[["x","the phrase (it changes)"],["v","stays as it is"]],"items":[{"label":"Elle arrive. (venir de)","en":["She arrives.","She has just arrived."],"a":[["s","Elle",""],["v","arrive.","v"]],"b":[["s","Elle",""],["m","vient d'","x"],["v","arriver.","v"]],"note":"de before a vowel: vient <b>d'</b>arriver."},{"label":"Je mange. (venir de)","en":["I eat.","I have just eaten."],"a":[["s","Je",""],["v","mange.","v"]],"b":[["s","Je",""],["m","viens de","x"],["v","manger.","v"]]},{"label":"Il cuisine. (en train de)","en":["He cooks.","He is busy cooking."],"a":[["s","Il",""],["v","cuisine.","v"]],"b":[["s","Il",""],["m","est en train de","x"],["v","cuisiner.","v"]]},{"label":"Nous travaillons. (en train de)","en":["We work.","We are busy working."],"a":[["s","Nous",""],["v","travaillons.","v"]],"b":[["s","Nous",""],["m","sommes en train de","x"],["v","travailler.","v"]]},{"label":"Tu peux. (pouvoir + verb)","en":["You can.","Can you help me?"],"a":[["s","Tu",""],["m","peux.","x"]],"b":[["s","Tu",""],["m","peux","x"],["v","m'aider ?","v"]],"note":"A modal works the same way: <b>peux</b> + aider."}]},{"tool":"conj","title":"venir de, person by person","sub":"Tap a person: only venir changes.","neg":false,"verbs":[{"inf":"venir de","en":"has just","forms":["viens de","viens de","vient de","venons de","venez de","viennent de"],"tail":"manger"},{"inf":"être en train de","en":"is busy","forms":["suis en train de","es en train de","est en train de","sommes en train de","êtes en train de","sont en train de"],"tail":"lire"}]}],"practice":{"choose":[{"q":"Elle ___ d'arriver.","en":"She has just arrived.","opts":["vient","va","est","a"],"a":"vient","why":"has just = venir de.","hint":"elle <b>vient d'</b>arriver."},{"q":"Il est ___ de cuisiner.","en":"He is busy cooking.","opts":["en train","en cours","train","entrain"],"a":"en train","why":"busy doing = être en train de.","hint":"il est <b>en train de</b> cuisiner."},{"q":"Nous venons de ___.","en":"We have just eaten.","opts":["manger","mangé","mangeons","mange"],"a":"manger","why":"After venir de, the verb…","hint":"It stays as it is: <b>manger</b>."},{"q":"Ils ___ de partir.","en":"They have just left.","opts":["viennent","venent","vont","sont"],"a":"viennent","why":"venir with ils.","hint":"ils <b>viennent</b> de partir."},{"q":"Je suis en train ___ lire.","en":"I am busy reading.","opts":["de","à","du","pour"],"a":"de","why":"en train …","hint":"en train <b>de</b> lire."},{"q":"___-vous m'aider ?","en":"Can you help me?","opts":["Pouvez","Pouvons","Peux","Peut"],"a":"Pouvez","why":"pouvoir with vous, verb first.","hint":"<b>Pouvez</b>-vous …?"}],"build":[{"en":"She has just arrived.","tiles":["Elle","vient d'","arriver."],"trap":"arrivée","why":"The verb stays as it is.","hint":"vient d'<b>arriver</b>."},{"en":"He is busy cooking.","tiles":["Il","est","en train de","cuisiner."],"trap":"cuisine","why":"The verb stays as it is.","hint":"en train de <b>cuisiner</b>."},{"en":"We have just finished.","tiles":["Nous","venons de","finir."],"trap":"fini","why":"The verb stays as it is.","hint":"venons de <b>finir</b>."},{"en":"They are busy working.","tiles":["Ils","sont","en train de","travailler."],"trap":"ont","why":"être en train de…","hint":"ils <b>sont</b> en train de …"},{"en":"I want to leave.","tiles":["Je","veux","partir."],"trap":"pars","why":"The verb stays as it is.","hint":"veux <b>partir</b>."}],"spot":[{"words":["Elle","vient de","arrivée."],"bad":2,"fix":"arriver.","hint":"The verb stays as it is: <b>arriver</b>.","look":"Look at the second verb.","say":"Elle vient d'arriver."},{"words":["Il","a","en train de","manger."],"bad":1,"fix":"est","hint":"<b>être</b> en train de.","look":"Which verb goes with en train de?"},{"words":["Nous","venons","manger."],"bad":1,"fix":"venons de","hint":"<b>venir de</b> = has just.","look":"Something is missing after venons.","say":"Nous venons de manger."},{"words":["Ils","venent de","partir."],"bad":1,"fix":"viennent de","hint":"venir with ils: <b>viennent</b>.","look":"Look at venir with ils."},{"words":["Je","suis en train","lire."],"bad":1,"fix":"suis en train de","hint":"en train <b>de</b>.","look":"Something is missing after en train."}]},"drill":[["I want to leave","Je veux partir.","The second verb stays as it is: veux <b>partir</b>."],["Can you help me? (vous)","Pouvez-vous m'aider ?","Verb first: <b>Pouvez-vous</b> …?"],["She has just arrived","Elle vient d'arriver.","has just = <b>venir de</b>: elle vient d'arriver."],["He is busy cooking","Il est en train de cuisiner. / Il est en train de faire la cuisine.","busy doing = <b>être en train de</b>."],["We have just eaten.","Nous venons de manger.","nous <b>venons de</b> + manger."],["They are busy working.","Ils sont en train de travailler.","ils <b>sont en train de</b> + travailler."]]},"21":{"line":"Compare with <b>plus</b> (more), <b>moins</b> (less) or <b>aussi</b> (as) + the adjective + <b>que</b>: Paul est plus grand que Marie. The most: <b>le / la / les plus</b>: la plus grande ville. Special: bon → <b>meilleur</b> (better, an adjective), bien → <b>mieux</b> (better, an adverb).","words":"Opposites to compare with: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:16\">Vocab 16 · High-Frequency Opposites</a>.","steps":[{"tool":"swap","title":"Compare","sub":"Pick a sentence and tap « Compare ».","button":["Compare","Back"],"legend":[["x","plus / moins / aussi … que"],["p","the most"]],"items":[{"label":"Paul est grand.","en":["Paul is tall.","Paul is taller than Marie."],"a":[["s","Paul est",""],["a","grand.",""]],"b":[["s","Paul est",""],["p","plus","x"],["a","grand",""],["q","que","x"],["o","Marie.",""]]},{"label":"Ce film est intéressant.","en":["This film is interesting.","This film is less interesting than the book."],"a":[["s","Ce film est",""],["a","intéressant.",""]],"b":[["s","Ce film est",""],["p","moins","x"],["a","intéressant",""],["q","que","x"],["o","le livre.",""]]},{"label":"Elle est sympa.","en":["She is nice.","She is as nice as her sister."],"a":[["s","Elle est",""],["a","sympa.",""]],"b":[["s","Elle est",""],["p","aussi","x"],["a","sympa",""],["q","que","x"],["o","sa sœur.",""]]},{"label":"C'est une grande ville.","en":["It's a big city.","It's the biggest city in France."],"a":[["s","C'est une",""],["a","grande",""],["o","ville.",""]],"b":[["s","C'est",""],["l","la plus","p"],["a","grande",""],["o","ville",""],["d","de France.","p"]],"note":"The most: <b>la plus</b> grande ville <b>de</b> France (in = de)."},{"label":"Il court vite.","en":["He runs fast.","He runs faster than me."],"a":[["s","Il court",""],["a","vite.",""]],"b":[["s","Il court",""],["p","plus","x"],["a","vite",""],["q","que","x"],["o","moi.",""]],"note":"After que: <b>moi</b>, toi, lui (stressed pronouns)."}]},{"tool":"sort","title":"meilleur or mieux?","sub":"better + a noun or after être: meilleur. better + a verb: mieux. Tap the box.","boxes":[{"k":"m","label":"meilleur(e)(s)","sub":"an adjective: with a noun"},{"k":"x","label":"mieux","sub":"an adverb: with a verb"}],"cards":[{"t":"Ce gâteau est … que l'autre.","box":"m","why":"About the cake (a noun): <b>meilleur</b>.","say":"Ce gâteau est meilleur que l'autre."},{"t":"Elle chante … que moi.","box":"x","why":"About how she sings (a verb): <b>mieux</b>.","say":"Elle chante mieux que moi."},{"t":"C'est la … pizza de Rome.","box":"m","why":"With pizza: <b>meilleure</b>.","say":"C'est la meilleure pizza de Rome."},{"t":"Tu parles … français maintenant.","box":"x","why":"How you speak: <b>mieux</b>.","say":"Tu parles mieux français maintenant."},{"t":"Ses notes sont …","box":"m","why":"About the marks (a noun): <b>meilleures</b>.","say":"Ses notes sont meilleures."},{"t":"Je dors … ici.","box":"x","why":"How I sleep: <b>mieux</b>.","say":"Je dors mieux ici."}]},{"tool":"flip","title":"The special ones","sub":"Tap a card.","cards":[{"a":"plus bon","b":"meilleur","tag":"bon → meilleur"},{"a":"plus bien","b":"mieux","tag":"bien → mieux"},{"a":"le plus bon","b":"le meilleur","tag":"the best (adjective)"},{"a":"le plus bien","b":"le mieux","tag":"the best (adverb)"}]}],"practice":{"choose":[{"q":"Paul est ___ grand que Marie.","en":"Paul is taller than Marie.","opts":["plus","plus de","le plus","très"],"a":"plus","why":"more + an adjective…","hint":"<b>plus</b> grand <b>que</b>."},{"q":"Elle est aussi sympa ___ sa sœur.","en":"She is as nice as her sister.","opts":["que","comme","de","than"],"a":"que","why":"The second part starts with…","hint":"aussi … <b>que</b>."},{"q":"C'est la ville la plus belle ___ France.","en":"It's the most beautiful city in France.","opts":["de","en","dans","à"],"a":"de","why":"the most … in a place…","hint":"la plus belle <b>de</b> France."},{"q":"Ce vin est ___ que l'autre.","en":"This wine is better than the other.","opts":["meilleur","mieux","plus bon","bien"],"a":"meilleur","why":"About the wine (a noun).","hint":"<b>meilleur</b>."},{"q":"Elle chante ___ que moi.","en":"She sings better than me.","opts":["mieux","meilleur","plus bien","meilleure"],"a":"mieux","why":"About how she sings (a verb).","hint":"<b>mieux</b>."},{"q":"Il est plus grand que ___.","en":"He is taller than me.","opts":["moi","je","me","mon"],"a":"moi","why":"After que…","hint":"que <b>moi</b>."}],"build":[{"en":"Paul is taller than Marie.","tiles":["Paul","est","plus","grand","que","Marie."],"trap":"de","why":"than = que.","hint":"plus grand <b>que</b> Marie."},{"en":"She sings better than me.","tiles":["Elle","chante","mieux","que","moi."],"trap":"meilleur","why":"How she sings: an adverb.","hint":"chante <b>mieux</b>."},{"en":"the biggest city in France","tiles":["la","plus","grande","ville","de","France"],"trap":"en","why":"in = de after a superlative.","hint":"… <b>de</b> France."},{"en":"This film is less interesting.","tiles":["Ce","film","est","moins","intéressant."],"trap":"plus","why":"less = moins.","hint":"<b>moins</b> intéressant."},{"en":"It's the best cake.","tiles":["C'est","le","meilleur","gâteau."],"trap":"mieux","why":"With a noun…","hint":"le <b>meilleur</b> gâteau."}],"spot":[{"words":["Ce gâteau","est","plus bon."],"bad":2,"fix":"meilleur.","hint":"bon → <b>meilleur</b>.","look":"Look at plus bon."},{"words":["Elle chante","meilleur","que moi."],"bad":1,"fix":"mieux","hint":"How she sings: <b>mieux</b>.","look":"Is it about a noun or a verb?"},{"words":["Paul est","plus grand","de Marie."],"bad":2,"fix":"que Marie.","hint":"than = <b>que</b>.","look":"Look at « than »."},{"words":["C'est","la plus belle ville","en France."],"bad":2,"fix":"de France.","hint":"After a superlative: <b>de</b> France.","look":"How do you say « in » after the most?"},{"words":["Il est","plus grand que","je."],"bad":2,"fix":"moi.","hint":"After que: <b>moi</b>.","look":"Look at the last word."}]},"drill":[["Paul is taller than Marie","Paul est plus grand que Marie.","<b>plus</b> + adjective + <b>que</b>."],["This is better","C'est meilleur. / C'est mieux.","bon → <b>meilleur</b>, bien → <b>mieux</b>."],["She sings better than me","Elle chante mieux que moi.","How she sings: <b>mieux</b>; after que: moi."],["the biggest city in France","la plus grande ville de France","The most: <b>la plus</b> …, in = <b>de</b>."],["She is as nice as her sister.","Elle est aussi sympa que sa sœur.","as … as = <b>aussi … que</b>."],["It's the best cake.","C'est le meilleur gâteau.","the best + a noun: <b>le meilleur</b>."]]},"19":{"line":"A pronoun replaces a noun so you don't repeat it, and it goes <b>before the verb</b>. The thing or person itself (who? what?): <b>le, la, l', les</b>: je vois Paul → je <b>le</b> vois. After <b>à</b> + a person (to whom?): <b>lui, leur</b>: je parle à Marie → je <b>lui</b> parle. me, te, nous, vous work for both.","words":"","steps":[{"tool":"swap","title":"Replace the noun","sub":"Pick a sentence and tap « Use a pronoun »: the noun goes, the pronoun jumps before the verb.","button":["Use a pronoun","Back to the noun"],"legend":[["p","the pronoun"],["v","the verb"],["n","ne … pas"]],"items":[{"label":"Je vois Paul.","en":["I see Paul.","I see him."],"a":[["s","Je",""],["v","vois","v"],["o","Paul.","x"]],"b":[["s","Je",""],["p","le","p"],["v","vois.","v"]],"note":"Paul (who?) → <b>le</b>, before the verb."},{"label":"Je regarde les photos.","en":["I look at the photos.","I look at them."],"a":[["s","Je",""],["v","regarde","v"],["o","les photos.","x"]],"b":[["s","Je",""],["p","les","p"],["v","regarde.","v"]]},{"label":"Je parle à Marie.","en":["I speak to Marie.","I speak to her."],"a":[["s","Je",""],["v","parle","v"],["o","à Marie.","x"]],"b":[["s","Je",""],["p","lui","p"],["v","parle.","v"]],"note":"à + a person → <b>lui</b> (him or her)."},{"label":"Il téléphone à ses parents.","en":["He phones his parents.","He phones them."],"a":[["s","Il",""],["v","téléphone","v"],["o","à ses parents.","x"]],"b":[["s","Il",""],["p","leur","p"],["v","téléphone.","v"]],"note":"à + people → <b>leur</b>."},{"label":"Je ne connais pas Paul.","en":["I don't know Paul.","I don't know him."],"a":[["s","Je",""],["ne","ne","n"],["v","connais","v"],["pas","pas","n"],["o","Paul.","x"]],"b":[["s","Je",""],["ne","ne","n"],["p","le","p"],["v","connais","v"],["pas","pas.","n"]],"note":"ne goes before the pronoun: je <b>ne le</b> connais pas."},{"label":"Je veux voir le film.","en":["I want to see the film.","I want to see it."],"a":[["s","Je",""],["m","veux",""],["v","voir","v"],["o","le film.","x"]],"b":[["s","Je",""],["m","veux",""],["p","le","p"],["v","voir.","v"]],"note":"Two verbs: the pronoun goes before the one it belongs to: veux <b>le voir</b>."}]},{"tool":"sort","title":"le / la / les or lui / leur?","sub":"Is there an à before the person? Tap the box.","boxes":[{"k":"d","label":"le / la / les","sub":"who? what? (no à)"},{"k":"i","label":"lui / leur","sub":"à + a person"}],"cards":[{"t":"Je vois Marie.","box":"d","why":"voir quelqu'un (no à): je <b>la</b> vois."},{"t":"Je parle à Marie.","box":"i","why":"parler à: je <b>lui</b> parle."},{"t":"J'aide mes amis.","box":"d","why":"aider quelqu'un (no à): je <b>les</b> aide."},{"t":"J'écris à mes amis.","box":"i","why":"écrire à: je <b>leur</b> écris."},{"t":"J'écoute le professeur.","box":"d","why":"écouter quelqu'un (no à): je <b>l'</b>écoute."},{"t":"Je téléphone à Paul.","box":"i","why":"téléphoner à: je <b>lui</b> téléphone."},{"t":"Je donne le livre (à Paul).","box":"d","why":"the book: je <b>le</b> donne."},{"t":"Je donne un livre à Paul.","box":"i","why":"to Paul: je <b>lui</b> donne un livre."}]}],"practice":{"choose":[{"q":"Paul ? Je ___ vois demain.","en":"Paul? I see him tomorrow.","opts":["le","lui","la","les"],"a":"le","why":"voir quelqu'un: no à.","hint":"Paul → <b>le</b>."},{"q":"Marie ? Je ___ parle souvent.","en":"Marie? I often speak to her.","opts":["lui","la","le","leur"],"a":"lui","why":"parler à quelqu'un.","hint":"à Marie → <b>lui</b>."},{"q":"Mes parents ? Je ___ téléphone le dimanche.","en":"My parents? I phone them on Sundays.","opts":["leur","les","lui","leurs"],"a":"leur","why":"téléphoner à + several people.","hint":"à mes parents → <b>leur</b>."},{"q":"Les clés ? Je ne ___ trouve pas.","en":"The keys? I can't find them.","opts":["les","leur","la","le"],"a":"les","why":"trouver quelque chose: no à.","hint":"les clés → <b>les</b>."},{"q":"Le film ? Je veux ___ voir.","en":"The film? I want to see it.","opts":["le","lui","la","les"],"a":"le","why":"Two verbs: before which one?","hint":"veux <b>le</b> voir."},{"q":"L'histoire ? Je ___ aime.","en":"The story? I like it.","opts":["l'","la","le","lui"],"a":"l'","why":"aime starts with a vowel.","hint":"Before a vowel, le / la → <b>l'</b>: je l'aime."}],"build":[{"en":"I see him.","tiles":["Je","le","vois."],"trap":"lui","why":"voir quelqu'un: no à.","hint":"je <b>le</b> vois."},{"en":"I speak to her.","tiles":["Je","lui","parle."],"trap":"la","why":"parler à…","hint":"je <b>lui</b> parle."},{"en":"I don't know them.","tiles":["Je","ne","les","connais","pas."],"trap":"leur","why":"connaître quelqu'un: no à.","hint":"je ne <b>les</b> connais pas."},{"en":"I want to see it.","tiles":["Je","veux","le","voir."],"trap":"lui","why":"Before the verb it belongs to.","hint":"veux <b>le voir</b>."},{"en":"He phones them.","tiles":["Il","leur","téléphone."],"trap":"les","why":"téléphoner à…","hint":"il <b>leur</b> téléphone."}],"spot":[{"words":["Je","vois","le."],"bad":1,"fix":"le vois.","hint":"The pronoun goes before the verb: je <b>le vois</b>.","look":"Where does the pronoun go?","say":"Je le vois."},{"words":["Marie ?","Je","la","parle."],"bad":2,"fix":"lui","hint":"parler à: <b>lui</b>.","look":"Is there an à after parler?"},{"words":["Mes amis ?","Je","leur","aide."],"bad":2,"fix":"les","hint":"aider quelqu'un (no à): <b>les</b>.","look":"Is there an à after aider?"},{"words":["Je","ne","connais le","pas."],"bad":2,"fix":"le connais","hint":"ne + pronoun + verb + pas: je ne <b>le connais</b> pas.","look":"Where does the pronoun go in a no?","say":"Je ne le connais pas."},{"words":["Je","le veux","voir."],"bad":1,"fix":"veux le","hint":"Before the verb it belongs to: veux <b>le voir</b>.","look":"Which verb does the pronoun belong to?","say":"Je veux le voir."}]},"drill":[["I see him","Je le vois.","Who? <b>le</b>, before the verb."],["I speak to her","Je lui parle.","à + a person: <b>lui</b>."],["I don't know them","Je ne les connais pas.","ne goes before the pronoun: je <b>ne les</b> connais pas."],["Look at me! (tu)","Regarde-moi !","In an order, the pronoun goes after: <b>Regarde-moi !</b>"],["I want to see it. (le film)","Je veux le voir.","Before the verb it belongs to: veux <b>le voir</b>."],["He phones them. (his parents)","Il leur téléphone.","à + people: <b>leur</b>."]]},"20":{"line":"<b>y</b> replaces a place (à Paris, dans la cuisine, chez moi) or à + a thing: je vais à Paris → j'<b>y</b> vais. <b>en</b> replaces de + a thing, and « some » or an amount: je veux du café → j'<b>en</b> veux; j'ai deux sœurs → j'<b>en</b> ai deux. Both go before the verb.","words":"","steps":[{"tool":"swap","title":"Replace it with y or en","sub":"Pick a sentence and tap « Use y / en ».","button":["Use y / en","Back"],"legend":[["p","y / en"],["x","what it replaces"]],"items":[{"label":"Je vais à Paris.","en":["I'm going to Paris.","I'm going there."],"a":[["s","Je",""],["v","vais",""],["o","à Paris.","x"]],"b":[["s","J'",""],["p","y","p"],["v","vais.",""]],"note":"A place → <b>y</b> (there)."},{"label":"Je pense à mon examen.","en":["I'm thinking about my exam.","I'm thinking about it."],"a":[["s","Je",""],["v","pense",""],["o","à mon examen.","x"]],"b":[["s","J'",""],["p","y","p"],["v","pense.",""]],"note":"à + a thing → <b>y</b>."},{"label":"Je veux du café.","en":["I want some coffee.","I want some."],"a":[["s","Je",""],["v","veux",""],["o","du café.","x"]],"b":[["s","J'",""],["p","en","p"],["v","veux.",""]],"note":"du / de la / des + a thing → <b>en</b> (some)."},{"label":"J'ai deux sœurs.","en":["I have two sisters.","I have two (of them)."],"a":[["s","J'",""],["v","ai",""],["n","deux",""],["o","sœurs.","x"]],"b":[["s","J'",""],["p","en","p"],["v","ai",""],["n","deux.",""]],"note":"An amount: <b>en</b>, and the number stays at the end."},{"label":"Je ne bois pas de lait.","en":["I don't drink milk.","I don't drink any."],"a":[["s","Je",""],["ne","ne",""],["v","bois",""],["pas","pas",""],["o","de lait.","x"]],"b":[["s","Je",""],["ne","n'",""],["p","en","p"],["v","bois",""],["pas","pas.",""]],"note":"ne becomes n' before en: je <b>n'en</b> bois pas."}]},{"tool":"sort","title":"y or en?","sub":"Tap the box for what each one replaces.","boxes":[{"k":"y","label":"y","sub":"a place, or à + a thing"},{"k":"en","label":"en","sub":"de + a thing, some, an amount"}],"cards":[{"t":"à la plage","box":"y","why":"A place: <b>y</b>."},{"t":"du pain","box":"en","why":"Some: <b>en</b>."},{"t":"chez Paul","box":"y","why":"A place: <b>y</b>."},{"t":"trois enfants","box":"en","why":"An amount: <b>en</b> … trois."},{"t":"à ton problème (penser à)","box":"y","why":"à + a thing: <b>y</b>."},{"t":"de la musique (parler de)","box":"en","why":"de + a thing: <b>en</b>."},{"t":"dans la cuisine","box":"y","why":"A place: <b>y</b>."},{"t":"beaucoup d'amis","box":"en","why":"An amount: <b>en</b> … beaucoup."}]}],"practice":{"choose":[{"q":"Tu vas à Paris ? Oui, j'___ vais.","en":"Are you going to Paris? Yes, I'm going there.","opts":["y","en","le","la"],"a":"y","why":"A place…","hint":"<b>y</b> = there."},{"q":"Tu veux de l'eau ? Oui, j'___ veux.","en":"Do you want some water? Yes, I want some.","opts":["en","y","la","l'"],"a":"en","why":"some…","hint":"<b>en</b> = some."},{"q":"Tu as des frères ? J'___ ai deux.","en":"Do you have brothers? I have two.","opts":["en","y","les","leur"],"a":"en","why":"An amount…","hint":"<b>en</b> … deux."},{"q":"Tu penses à tes vacances ? Oui, j'___ pense.","en":"Are you thinking about your holidays? Yes.","opts":["y","en","les","lui"],"a":"y","why":"penser à + a thing.","hint":"à + a thing: <b>y</b>."},{"q":"Il ne ___ boit pas.","en":"He doesn't drink any.","opts":["n'en","ne en","n'y","en"],"a":"n'en","why":"ne before a vowel…","hint":"<b>n'en</b>."},{"q":"On ___ va ! ","en":"Let's go! (there)","opts":["y","en","le","là"],"a":"y","why":"aller somewhere…","hint":"<b>On y va !</b>"}],"build":[{"en":"Yes, I'm going there.","tiles":["Oui,","j'","y","vais."],"trap":"en","why":"A place…","hint":"j'<b>y</b> vais."},{"en":"I want some.","tiles":["J'","en","veux."],"trap":"y","why":"some…","hint":"j'<b>en</b> veux."},{"en":"I have two (of them).","tiles":["J'","en","ai","deux."],"trap":"les","why":"An amount…","hint":"j'<b>en</b> ai deux."},{"en":"I don't have any.","tiles":["Je","n'","en","ai","pas."],"trap":"ne","why":"ne before a vowel.","hint":"je <b>n'en</b> ai pas."},{"en":"I'm thinking about it.","tiles":["J'","y","pense."],"trap":"en","why":"penser à…","hint":"j'<b>y</b> pense."}],"spot":[{"words":["Paris ?","J'en","vais demain."],"bad":1,"fix":"J'y","hint":"A place: <b>y</b>.","look":"Is it a place or an amount?"},{"words":["Du café ?","J'y","veux bien."],"bad":1,"fix":"J'en","hint":"Some: <b>en</b>.","look":"Is it a place or « some »?"},{"words":["Des sœurs ?","J'ai","deux."],"bad":1,"fix":"J'en ai","hint":"Keep the amount with <b>en</b>: j'en ai deux.","look":"Something is missing before ai.","say":"J'en ai deux."},{"words":["Je","ne en","bois pas."],"bad":1,"fix":"n'en","hint":"<b>n'en</b>.","look":"ne before a vowel…","say":"Je n'en bois pas."},{"words":["Je","vais y."],"bad":1,"fix":"y vais.","hint":"y goes before the verb: <b>j'y vais</b>.","look":"Where does y go?","say":"J'y vais."}]},"drill":[["Are you going to Paris? Yes, I'm going there.","Oui, j'y vais. / J'y vais.","A place: <b>y</b>."],["Do you want some water? Yes, I want some.","Oui, j'en veux. / J'en veux.","some: <b>en</b>."],["I have two sisters (use en)","J'en ai deux.","An amount: <b>en</b> … deux."],["I don't have any","Je n'en ai pas.","ne before a vowel: <b>n'en</b>."],["I'm thinking about it. (penser à)","J'y pense.","à + a thing: <b>y</b>."],["Let's go! (there)","On y va ! / Allons-y !","<b>y</b> = there."]]},"30":{"line":"After a word of quantity, just <b>de</b> (d' before a vowel) + the noun, with no article: <b>beaucoup de</b> pain, <b>un peu d'</b>eau, <b>trop de</b> sucre, <b>assez de</b> temps, <b>combien de</b> frères ?, un kilo <b>de</b> tomates. It is the same de as after a no. With en: j'<b>en</b> ai beaucoup.","words":"Food and amounts: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:18\">Vocab 18 · Café, Food & Ordering</a> · <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:4\">Vocab 4 · Numbers & Scale Units</a>.","steps":[{"tool":"flip","title":"Add a quantity","sub":"Tap a card: du, de la, des become de after the quantity.","cards":[{"a":"des pommes","b":"beaucoup de pommes","tag":"des → beaucoup de"},{"a":"de l'eau","b":"un peu d'eau","tag":"de l' → un peu d'"},{"a":"du sucre","b":"trop de sucre","tag":"du → trop de"},{"a":"du temps","b":"assez de temps","tag":"du → assez de"},{"a":"des tomates","b":"un kilo de tomates","tag":"des → un kilo de"},{"a":"du lait","b":"une bouteille de lait","tag":"du → une bouteille de"},{"a":"des frères ?","b":"Combien de frères ?","tag":"des → combien de"}]},{"tool":"swap","title":"Replace it with en","sub":"Pick a sentence and tap « Use en »: the quantity stays at the end.","button":["Use en","Back"],"legend":[["p","en"],["x","what it replaces"]],"items":[{"label":"J'ai beaucoup de livres.","en":["I have a lot of books.","I have a lot (of them)."],"a":[["s","J'",""],["v","ai",""],["q","beaucoup",""],["o","de livres.","x"]],"b":[["s","J'",""],["p","en","p"],["v","ai",""],["q","beaucoup.",""]]},{"label":"Il boit un peu de lait.","en":["He drinks a little milk.","He drinks a little (of it)."],"a":[["s","Il",""],["v","boit",""],["q","un peu",""],["o","de lait.","x"]],"b":[["s","Il",""],["p","en","p"],["v","boit",""],["q","un peu.",""]]},{"label":"Tu as assez d'argent ?","en":["Do you have enough money?","Do you have enough (of it)?"],"a":[["s","Tu",""],["v","as",""],["q","assez",""],["o","d'argent ?","x"]],"b":[["s","Tu",""],["p","en","p"],["v","as",""],["q","assez ?",""]]}]}],"practice":{"choose":[{"q":"beaucoup ___ pain","en":"a lot of bread","opts":["de","du","des","le"],"a":"de","why":"After a quantity…","hint":"<b>beaucoup de</b>."},{"q":"un peu ___ eau","en":"a little water","opts":["d'","de","de l'","du"],"a":"d'","why":"eau starts with a vowel.","hint":"un peu <b>d'</b>eau."},{"q":"___ de frères as-tu ?","en":"How many brothers do you have?","opts":["Combien","Comment","Quel","Beaucoup"],"a":"Combien","why":"How many…","hint":"<b>Combien de</b>."},{"q":"Il y a trop ___ monde.","en":"There are too many people.","opts":["de","du","des","les"],"a":"de","why":"After trop…","hint":"<b>trop de</b>."},{"q":"un kilo ___ tomates","en":"a kilo of tomatoes","opts":["de","des","du","les"],"a":"de","why":"After un kilo…","hint":"un kilo <b>de</b>."},{"q":"Des livres ? J'___ ai beaucoup.","en":"Books? I have a lot.","opts":["en","y","les","leur"],"a":"en","why":"Replace « de livres ».","hint":"<b>en</b> … beaucoup."}],"build":[{"en":"a lot of bread","tiles":["beaucoup","de","pain"],"trap":"du","why":"After a quantity: just de.","hint":"beaucoup <b>de</b> pain."},{"en":"a little water","tiles":["un peu","d'","eau"],"trap":"de l'","why":"After a quantity: just de.","hint":"un peu <b>d'</b>eau."},{"en":"How many brothers do you have?","tiles":["Combien","de","frères","as-tu ?"],"trap":"des","why":"After combien: just de.","hint":"combien <b>de</b> frères."},{"en":"I have a lot (of them).","tiles":["J'","en","ai","beaucoup."],"trap":"les","why":"Replace « de livres » with en.","hint":"j'<b>en</b> ai beaucoup."},{"en":"We have enough time.","tiles":["Nous","avons","assez","de","temps."],"trap":"du","why":"After assez: just de.","hint":"assez <b>de</b> temps."}],"spot":[{"words":["beaucoup","des","amis"],"bad":1,"fix":"d'","hint":"After a quantity: <b>d'</b>amis.","look":"Look after beaucoup.","say":"beaucoup d'amis"},{"words":["un peu","du","sucre"],"bad":1,"fix":"de","hint":"After a quantity: <b>de</b>.","look":"Look after un peu."},{"words":["Combien","des","enfants ?"],"bad":1,"fix":"d'","hint":"After combien: <b>d'</b>enfants.","look":"Look after combien.","say":"Combien d'enfants ?"},{"words":["un litre","de le","lait"],"bad":1,"fix":"de","hint":"After a quantity: just <b>de</b>.","look":"Look after un litre."},{"words":["Des livres ?","J'ai","beaucoup."],"bad":1,"fix":"J'en ai","hint":"Keep the amount with <b>en</b>.","look":"Something is missing before ai.","say":"J'en ai beaucoup."}]},"drill":[["a lot of bread","beaucoup de pain","After a quantity: <b>de</b>, no article."],["a little water","un peu d'eau","Before a vowel: <b>d'</b>eau."],["How many brothers do you have?","Combien de frères as-tu ? / Tu as combien de frères ? / Combien de frères est-ce que tu as ? / Combien de frères avez-vous ?","<b>combien de</b> + the noun."],["I have a lot of books (use en)","J'en ai beaucoup.","<b>en</b> replaces « de livres »; beaucoup stays at the end."],["too much sugar","trop de sucre","<b>trop de</b>."],["a kilo of tomatoes","un kilo de tomates","un kilo <b>de</b>."]]},"31":{"line":"In an order, the pronoun goes <b>after</b> the verb with a hyphen: Regarde-<b>le</b> ! Donne-<b>moi</b> ça ! (me → <b>moi</b>, te → <b>toi</b>: Dépêche-toi !). In a no, it goes back <b>before</b> the verb: <b>Ne le</b> regarde <b>pas</b> !","words":"","steps":[{"tool":"swap","title":"Make it an order","sub":"Pick a sentence and tap « Make it an order »: the pronoun jumps after the verb.","button":["Make it an order","Back"],"legend":[["p","the pronoun"],["v","the verb"],["n","ne … pas"]],"items":[{"label":"Tu le regardes.","en":["You look at it.","Look at it!"],"a":[["s","Tu",""],["p","le","p"],["v","regardes.","v"]],"b":[["v","Regarde-","v"],["p","le !","p"]],"note":"After the verb, with a hyphen: <b>Regarde-le !</b>"},{"label":"Tu me donnes ça.","en":["You give me that.","Give me that!"],"a":[["s","Tu",""],["p","me","p"],["v","donnes","v"],["o","ça.",""]],"b":[["v","Donne-","v"],["p","moi","p"],["o","ça !",""]],"note":"me becomes <b>moi</b> after the verb."},{"label":"Tu te dépêches.","en":["You hurry up.","Hurry up!"],"a":[["s","Tu",""],["p","te","p"],["v","dépêches.","v"]],"b":[["v","Dépêche-","v"],["p","toi !","p"]],"note":"te becomes <b>toi</b>: Dépêche-toi !"},{"label":"Vous vous asseyez.","en":["You sit down.","Sit down!"],"a":[["s","Vous",""],["p","vous","p"],["v","asseyez.","v"]],"b":[["v","Asseyez-","v"],["p","vous !","p"]]},{"label":"Tu ne le regardes pas.","en":["You don't look at it.","Don't look at it!"],"a":[["s","Tu",""],["ne","ne","n"],["p","le","p"],["v","regardes","v"],["pas","pas.","n"]],"b":[["ne","Ne","n"],["p","le","p"],["v","regarde","v"],["pas","pas !","n"]],"note":"In a no, the pronoun stays <b>before</b> the verb."},{"label":"Tu lui parles.","en":["You speak to him.","Speak to him!"],"a":[["s","Tu",""],["p","lui","p"],["v","parles.","v"]],"b":[["v","Parle-","v"],["p","lui !","p"]]}]},{"tool":"flip","title":"me → moi, te → toi","sub":"Tap a card: after the verb, me and te change.","cards":[{"a":"Tu me regardes.","b":"Regarde-moi !","tag":"me → moi"},{"a":"Tu me le donnes.","b":"Donne-le-moi !","tag":"le before moi"},{"a":"Tu te lèves.","b":"Lève-toi !","tag":"te → toi"},{"a":"Tu ne te lèves pas.","b":"Ne te lève pas !","tag":"a no: te stays before"},{"a":"Tu y vas.","b":"Vas-y !","tag":"vas + y: the -s comes back"}]}],"practice":{"choose":[{"q":"Regarde-___ ! (it)","en":"Look at it!","opts":["le","lui","la","moi"],"a":"le","why":"it, after the verb…","hint":"Regarde-<b>le</b> !"},{"q":"Donne-___ ça ! (me)","en":"Give me that!","opts":["moi","me","je","toi"],"a":"moi","why":"me after the verb…","hint":"Donne-<b>moi</b> ça !"},{"q":"Dépêche-___ !","en":"Hurry up!","opts":["toi","te","tu","vous"],"a":"toi","why":"te after the verb…","hint":"Dépêche-<b>toi</b> !"},{"q":"Ne ___ regarde pas !","en":"Don't look at it!","opts":["le","moi","lui","toi"],"a":"le","why":"In a no, the pronoun goes…","hint":"<b>Ne le</b> regarde pas !"},{"q":"Asseyez-___ !","en":"Sit down! (vous)","opts":["vous","toi","nous","se"],"a":"vous","why":"vous after the verb…","hint":"Asseyez-<b>vous</b> !"},{"q":"Ne te ___ pas !","en":"Don't get up!","opts":["lève","lèves","lever","levez"],"a":"lève","why":"tu form of an -er verb in an order.","hint":"Ne te <b>lève</b> pas !"}],"build":[{"en":"Look at it! (tu)","tiles":["Regarde-le","!"],"trap":"Le regarde","why":"In an order, the pronoun goes after.","hint":"<b>Regarde-le !</b>"},{"en":"Don't look at it!","tiles":["Ne","le","regarde","pas !"],"trap":"Regarde-le","why":"In a no, the pronoun goes before.","hint":"<b>Ne le regarde pas !</b>"},{"en":"Hurry up! (vous)","tiles":["Dépêchez-vous","!"],"trap":"Vous dépêchez","why":"In an order, the pronoun goes after.","hint":"<b>Dépêchez-vous !</b>"},{"en":"Give it to me!","tiles":["Donne-le-moi","!"],"trap":"Donne-moi-le","why":"le before moi.","hint":"<b>Donne-le-moi !</b>"},{"en":"Get up! (tu)","tiles":["Lève-toi","!"],"trap":"Lève-te","why":"te after the verb…","hint":"<b>Lève-toi !</b>"}],"spot":[{"words":["Regarde-","me !"],"bad":1,"fix":"moi !","hint":"After the verb: <b>moi</b>.","look":"What does me become after the verb?","say":"Regarde-moi !"},{"words":["Ne","regarde-le","pas !"],"bad":1,"fix":"le regarde","hint":"In a no, before: <b>Ne le regarde pas !</b>","look":"Where does le go in a no?"},{"words":["Dépêche-","te !"],"bad":1,"fix":"toi !","hint":"After the verb: <b>toi</b>.","look":"What does te become after the verb?","say":"Dépêche-toi !"},{"words":["Le","regarde !"],"bad":0,"fix":"Regarde-le !","hint":"In an order, after the verb: <b>Regarde-le !</b>","look":"Where does le go in an order?","say":"Regarde-le !"},{"words":["Donne-moi-le !"],"bad":0,"fix":"Donne-le-moi !","hint":"le goes before moi: <b>Donne-le-moi !</b>","look":"Which pronoun comes first?"}]},"drill":[["Look at it! (tu)","Regarde-le !","After the verb, with a hyphen: <b>Regarde-le !</b>"],["Don't look at it!","Ne le regarde pas !","In a no, before the verb: <b>Ne le</b> regarde pas."],["Hurry up! (vous)","Dépêchez-vous !","<b>Dépêchez-vous !</b>"],["Give it to me!","Donne-le-moi !","le before moi: <b>Donne-le-moi !</b>"],["Look at me! (tu)","Regarde-moi !","me → <b>moi</b> after the verb."],["Get up! (tu)","Lève-toi !","te → <b>toi</b>: Lève-toi !"]]},"v10":{"line":"Every compound tense is a helper verb + the <b>past participle</b>, so learn the participle first. <b>-er → -é</b> (parler → parlé), <b>-ir → -i</b> (finir → fini), <b>-re → -u</b> (vendre → vendu). Many common verbs are irregular: pris, mis, fait, dit, écrit, ouvert, été, eu, vu, bu, pu, dû, su, venu, né, mort.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"sort","title":"How does it end?","sub":"Tap the ending of each past participle.","boxes":[{"k":"e","label":"-é","sub":"-er verbs"},{"k":"i","label":"-i / -is / -it","sub":"finir, prendre, dire…"},{"k":"u","label":"-u","sub":"-re and many others"},{"k":"x","label":"other","sub":"learn them"}],"cards":[{"t":"parler","box":"e","why":"<b>parlé</b>"},{"t":"finir","box":"i","why":"<b>fini</b>"},{"t":"vendre","box":"u","why":"<b>vendu</b>"},{"t":"prendre","box":"i","why":"<b>pris</b>"},{"t":"voir","box":"u","why":"<b>vu</b>"},{"t":"faire","box":"x","why":"<b>fait</b>"},{"t":"dire","box":"i","why":"<b>dit</b>"},{"t":"ouvrir","box":"x","why":"<b>ouvert</b>"},{"t":"avoir","box":"u","why":"<b>eu</b>"},{"t":"être","box":"x","why":"<b>été</b>"},{"t":"aller","box":"e","why":"<b>allé</b>"},{"t":"mettre","box":"i","why":"<b>mis</b>"}]},{"tool":"flip","title":"The irregular ones to know","sub":"Tap a card: the infinitive turns into its past participle.","cards":[{"a":"prendre","b":"pris","tag":"comprendre → compris"},{"a":"mettre","b":"mis","tag":"promettre → promis"},{"a":"écrire","b":"écrit","tag":"décrire → décrit"},{"a":"ouvrir","b":"ouvert","tag":"offrir → offert"},{"a":"devoir","b":"dû","tag":"with an accent"},{"a":"pouvoir","b":"pu"},{"a":"savoir","b":"su"},{"a":"vouloir","b":"voulu"},{"a":"boire","b":"bu"},{"a":"connaître","b":"connu"},{"a":"naître","b":"né"},{"a":"mourir","b":"mort"}]}],"practice":{"choose":[{"q":"prendre → ___","en":"taken","opts":["pris","prendu","prit","prené"],"a":"pris","why":"An irregular one.","hint":"<b>pris</b>."},{"q":"ouvrir → ___","en":"opened","opts":["ouvert","ouvri","ouvru","ouvré"],"a":"ouvert","why":"An irregular one.","hint":"<b>ouvert</b>."},{"q":"devoir → ___","en":"had to","opts":["dû","du","devu","doit"],"a":"dû","why":"With an accent.","hint":"<b>dû</b>."},{"q":"finir → ___","en":"finished","opts":["fini","finé","finu","finis"],"a":"fini","why":"Regular -ir.","hint":"<b>fini</b>."},{"q":"vendre → ___","en":"sold","opts":["vendu","vendi","vendé","vendit"],"a":"vendu","why":"Regular -re.","hint":"<b>vendu</b>."},{"q":"faire → ___","en":"done","opts":["fait","faisé","fairu","fai"],"a":"fait","why":"An irregular one.","hint":"<b>fait</b>."}],"build":[{"en":"I have taken the bus.","tiles":["J'ai","pris","le","bus."],"trap":"prendu","why":"prendre → ?","hint":"j'ai <b>pris</b>."},{"en":"She has opened the window.","tiles":["Elle","a","ouvert","la","fenêtre."],"trap":"ouvri","why":"ouvrir → ?","hint":"elle a <b>ouvert</b>."},{"en":"We have seen the film.","tiles":["Nous","avons","vu","le","film."],"trap":"voiré","why":"voir → ?","hint":"nous avons <b>vu</b>."},{"en":"They have done their homework.","tiles":["Ils","ont","fait","leurs","devoirs."],"trap":"faisé","why":"faire → ?","hint":"ils ont <b>fait</b>."},{"en":"I had to leave.","tiles":["J'ai","dû","partir."],"trap":"devu","why":"devoir → ?","hint":"j'ai <b>dû</b> partir."}],"spot":[{"words":["J'ai","prendu","le train."],"bad":1,"fix":"pris","hint":"prendre → <b>pris</b>.","look":"Look at the participle."},{"words":["Elle a","ouvri","la porte."],"bad":1,"fix":"ouvert","hint":"ouvrir → <b>ouvert</b>.","look":"Look at the participle."},{"words":["Nous avons","mettu","la table."],"bad":1,"fix":"mis","hint":"mettre → <b>mis</b>.","look":"Look at the participle."},{"words":["Il a","écrivé","une lettre."],"bad":1,"fix":"écrit","hint":"écrire → <b>écrit</b>.","look":"Look at the participle."},{"words":["Tu as","buvé","du café ?"],"bad":1,"fix":"bu","hint":"boire → <b>bu</b>.","look":"Look at the participle."}]},"drill":[["past participle of prendre","pris","prendre → <b>pris</b> (comprendre → compris)."],["past participle of ouvrir","ouvert","ouvrir → <b>ouvert</b> (offrir → offert)."],["past participle of devoir","dû","devoir → <b>dû</b>, with an accent."],["past participle of connaître","connu","connaître → <b>connu</b>."],["past participle of faire","fait","faire → <b>fait</b>."],["past participle of mettre","mis","mettre → <b>mis</b>."]]},"15":{"line":"The <b>passé composé</b> tells what happened: <b>avoir</b> or <b>être</b> in the present + the past participle: j'<b>ai</b> mangé, elle <b>est</b> allée. Most verbs take avoir. About 16 verbs of movement or change (aller, venir, partir, arriver, naître, mourir, rester, tomber…) and all the « se » verbs take être, and then the participle agrees: elle est allé<b>e</b>, ils sont parti<b>s</b>.","words":"","steps":[{"tool":"conj","title":"avoir + participle, être + participle","sub":"Pick a verb, then tap a person. With être, the participle agrees.","neg":true,"verbs":[{"inf":"manger","en":"ate","pasAt":1,"forms":["ai mangé","as mangé","a mangé","avons mangé","avez mangé","ont mangé"],"tail":"une pizza"},{"inf":"finir","en":"finished","pasAt":1,"forms":["ai fini","as fini","a fini","avons fini","avez fini","ont fini"],"tail":"le travail"},{"inf":"aller","en":"went","pasAt":1,"forms":["suis allé(e)","es allé(e)","est allé(e)","sommes allé(e)s","êtes allé(e)(s)","sont allé(e)s"],"tail":"à Paris"}]},{"tool":"sort","title":"avoir or être?","sub":"Tap the helper each verb takes in the passé composé.","boxes":[{"k":"a","label":"avoir","sub":"most verbs"},{"k":"e","label":"être","sub":"movement, change, and « se » verbs"}],"cards":[{"t":"manger","box":"a","why":"j'<b>ai</b> mangé"},{"t":"aller","box":"e","why":"je <b>suis</b> allé(e)"},{"t":"partir","box":"e","why":"je <b>suis</b> parti(e)"},{"t":"faire","box":"a","why":"j'<b>ai</b> fait"},{"t":"arriver","box":"e","why":"je <b>suis</b> arrivé(e)"},{"t":"voir","box":"a","why":"j'<b>ai</b> vu"},{"t":"rester","box":"e","why":"je <b>suis</b> resté(e)"},{"t":"naître","box":"e","why":"je <b>suis</b> né(e)"},{"t":"prendre","box":"a","why":"j'<b>ai</b> pris"},{"t":"se lever","box":"e","why":"je <b>me suis</b> levé(e)"},{"t":"tomber","box":"e","why":"je <b>suis</b> tombé(e)"},{"t":"dormir","box":"a","why":"j'<b>ai</b> dormi"}]},{"tool":"agree","title":"With être, the participle agrees","sub":"Switch the person: the end of the participle follows him, her, them.","cols":["il","elle","ils","elles"],"pre":["il","elle","ils","elles"],"rows":[{"forms":["est allé","est allée","sont allés","sont allées"],"en":["he went","she went","they went","they went (women)"]},{"forms":["est parti","est partie","sont partis","sont parties"],"en":["he left","she left","they left","they left (women)"]},{"forms":["est resté","est restée","sont restés","sont restées"],"en":["he stayed","she stayed","they stayed","they stayed (women)"]},{"forms":["a mangé","a mangé","ont mangé","ont mangé"],"en":["he ate · with avoir, no change","she ate · no change","they ate · no change","they ate · no change"]}]}],"practice":{"choose":[{"q":"J'___ mangé une pizza.","en":"I ate a pizza.","opts":["ai","suis","as","est"],"a":"ai","why":"manger takes…","hint":"<b>avoir</b>: j'ai mangé."},{"q":"Elle est ___ à Paris.","en":"She went to Paris.","opts":["allée","allé","allés","aller"],"a":"allée","why":"With être, it agrees with elle.","hint":"elle est <b>allée</b>."},{"q":"Nous ___ partis tôt.","en":"We left early.","opts":["sommes","avons","êtes","sont"],"a":"sommes","why":"partir takes…","hint":"<b>être</b>: nous sommes partis."},{"q":"Ils ont ___ le film.","en":"They saw the film.","opts":["vu","vus","voir","voyé"],"a":"vu","why":"With avoir, nothing agrees.","hint":"ils ont <b>vu</b>."},{"q":"Nous n'___ pas fini.","en":"We didn't finish.","opts":["avons","sommes","avez","ont"],"a":"avons","why":"finir takes avoir; the no goes round it.","hint":"nous <b>n'avons pas</b> fini."},{"q":"Je suis ___ en 1990.","en":"I was born in 1990.","opts":["né(e)","naît","naissé","eu né"],"a":"né(e)","why":"naître → ?","hint":"je suis <b>né(e)</b>."}],"build":[{"en":"I ate.","tiles":["J'ai","mangé."],"trap":"suis","why":"manger takes avoir.","hint":"<b>j'ai</b> mangé."},{"en":"She went.","tiles":["Elle","est","allée."],"trap":"a","why":"aller takes être.","hint":"elle <b>est allée</b>."},{"en":"We didn't finish.","tiles":["Nous","n'avons","pas","fini."],"trap":"sommes","why":"finir takes avoir; the no goes round it.","hint":"nous <b>n'avons pas</b> fini."},{"en":"They (m) left.","tiles":["Ils","sont","partis."],"trap":"ont","why":"partir takes être.","hint":"ils <b>sont partis</b>."},{"en":"She stayed at home.","tiles":["Elle","est","restée","à la maison."],"trap":"a","why":"rester takes être.","hint":"elle <b>est restée</b>."}],"spot":[{"words":["Elle","a","allée."],"bad":1,"fix":"est","hint":"aller takes <b>être</b>.","look":"Which helper does aller take?"},{"words":["Elle","est","parti."],"bad":2,"fix":"partie.","hint":"With être it agrees: <b>partie</b>.","look":"Does the participle match elle?"},{"words":["Nous","sommes","mangé."],"bad":1,"fix":"avons","hint":"manger takes <b>avoir</b>.","look":"Which helper does manger take?"},{"words":["Ils","ont","vus","le film."],"bad":2,"fix":"vu","hint":"With avoir, no agreement: <b>vu</b>.","look":"Does the participle agree with avoir?"},{"words":["Je n'ai","fini","pas."],"bad":1,"fix":"pas fini.","hint":"pas goes before the participle: je n'ai <b>pas fini</b>.","look":"Where does pas go?","say":"Je n'ai pas fini."}]},"drill":[["I ate (manger)","J'ai mangé.","manger takes <b>avoir</b>."],["She went (aller)","Elle est allée.","aller takes <b>être</b>; it agrees: allé<b>e</b>."],["We didn't finish","Nous n'avons pas fini.","The no goes round avoir: <b>n'avons pas</b> fini."],["They (m) left (partir)","Ils sont partis.","partir takes <b>être</b>; it agrees: parti<b>s</b>."],["She stayed (rester)","Elle est restée.","rester takes <b>être</b>: resté<b>e</b>."],["We saw the film.","Nous avons vu le film.","voir takes <b>avoir</b>: avons vu."]]},"18":{"line":"A « se » verb has an extra pronoun that matches the subject: je <b>me</b> lave, tu <b>te</b> laves, il <b>se</b> lave, nous <b>nous</b> lavons, vous <b>vous</b> lavez, ils <b>se</b> lavent. It is often a daily routine (se lever, se coucher) or « each other » (nous nous parlons). In the passé composé it takes <b>être</b>: je me suis levé(e). In an order: Lève-<b>toi</b> !","words":"","steps":[{"tool":"conj","title":"The pronoun follows the subject","sub":"Pick a verb, then tap a person. Tap ne … pas for the no.","neg":true,"verbs":[{"inf":"se lever","en":"to get up","forms":["me lève","te lèves","se lève","nous levons","vous levez","se lèvent"],"tail":"à sept heures"},{"inf":"s'appeler","en":"to be called","forms":["m'appelle","t'appelles","s'appelle","nous appelons","vous appelez","s'appellent"],"tail":"Léa"},{"inf":"se coucher","en":"to go to bed","forms":["me couche","te couches","se couche","nous couchons","vous couchez","se couchent"],"tail":"tard"}]},{"tool":"swap","title":"In the past, with aller, in an order","sub":"Pick a sentence and tap « Change it ».","button":["Change it","Back"],"legend":[["p","the pronoun"],["x","what comes in"]],"items":[{"label":"Je me lave. → past","en":["I wash.","I washed."],"a":[["s","Je",""],["p","me","p"],["v","lave.",""]],"b":[["s","Je",""],["p","me","p"],["x","suis","x"],["v","lavé(e).",""]],"note":"Always <b>être</b> in the past, and the participle agrees."},{"label":"Elle se lève. → past","en":["She gets up.","She got up."],"a":[["s","Elle",""],["p","se","p"],["v","lève.",""]],"b":[["s","Elle",""],["p","s'","p"],["x","est","x"],["v","levée.",""]],"note":"se before a vowel: elle <b>s'est</b> levée."},{"label":"Nous nous couchons. → aller","en":["We go to bed.","We are going to go to bed."],"a":[["s","Nous",""],["p","nous","p"],["v","couchons.",""]],"b":[["s","Nous",""],["x","allons","x"],["p2","nous","p"],["v","coucher.",""]],"note":"With two verbs, the pronoun stays with the second: allons <b>nous coucher</b>."},{"label":"Tu te dépêches. → order","en":["You hurry.","Hurry up!"],"a":[["s","Tu",""],["p","te","p"],["v","dépêches.",""]],"b":[["v","Dépêche-",""],["p","toi !","p"]],"note":"In an order: <b>Dépêche-toi !</b>"}]}],"practice":{"choose":[{"q":"Je ___ lève à sept heures.","en":"I get up at seven.","opts":["me","se","te","m'"],"a":"me","why":"The pronoun matches je.","hint":"je <b>me</b> lève."},{"q":"Elle ___ appelle Anna.","en":"She is called Anna.","opts":["s'","se","m'","elle"],"a":"s'","why":"se before a vowel…","hint":"elle <b>s'</b>appelle."},{"q":"Nous ___ couchons tard.","en":"We go to bed late.","opts":["nous","se","vous","on"],"a":"nous","why":"The pronoun matches nous.","hint":"nous <b>nous</b> couchons."},{"q":"Je me ___ levé(e) tôt.","en":"I got up early.","opts":["suis","ai","es","est"],"a":"suis","why":"In the past, « se » verbs take…","hint":"<b>être</b>: je me suis levé(e)."},{"q":"Dépêche-___ !","en":"Hurry up!","opts":["toi","te","tu","se"],"a":"toi","why":"In an order…","hint":"Dépêche-<b>toi</b> !"},{"q":"Nous allons ___ coucher.","en":"We are going to go to bed.","opts":["nous","se","vous","on"],"a":"nous","why":"The pronoun still matches nous.","hint":"allons <b>nous</b> coucher."}],"build":[{"en":"I get up at seven.","tiles":["Je","me","lève","à sept heures."],"trap":"se","why":"The pronoun matches je.","hint":"je <b>me</b> lève."},{"en":"She is called Anna.","tiles":["Elle","s'appelle","Anna."],"trap":"se appelle","why":"se before a vowel.","hint":"elle <b>s'appelle</b>."},{"en":"We are going to go to bed.","tiles":["Nous","allons","nous","coucher."],"trap":"se","why":"The pronoun matches nous.","hint":"allons <b>nous</b> coucher."},{"en":"She got up early.","tiles":["Elle","s'est","levée","tôt."],"trap":"a","why":"« se » verbs take être.","hint":"elle <b>s'est levée</b>."},{"en":"Don't get up! (tu)","tiles":["Ne","te","lève","pas !"],"trap":"toi","why":"In a no, the pronoun stays before.","hint":"Ne <b>te</b> lève pas !"}],"spot":[{"words":["Je","se","lève tôt."],"bad":1,"fix":"me","hint":"With je: <b>me</b>.","look":"Does the pronoun match je?"},{"words":["Elle","s'a","levée."],"bad":1,"fix":"s'est","hint":"« se » verbs take <b>être</b>.","look":"Which helper?"},{"words":["Nous","se","couchons."],"bad":1,"fix":"nous","hint":"With nous: <b>nous</b>.","look":"Does the pronoun match nous?"},{"words":["Dépêche-","te !"],"bad":1,"fix":"toi !","hint":"In an order: <b>toi</b>.","look":"What does te become in an order?","say":"Dépêche-toi !"},{"words":["Il","se appelle","Paul."],"bad":1,"fix":"s'appelle","hint":"se before a vowel: <b>s'appelle</b>.","look":"appelle starts with a vowel."}]},"drill":[["I get up at 7","Je me lève à sept heures. / Je me lève à 7 heures. / Je me lève à 7 h.","je <b>me</b> lève."],["She is called Anna","Elle s'appelle Anna.","se before a vowel: <b>s'</b>appelle."],["We are going to go to bed","Nous allons nous coucher.","The pronoun stays with the second verb: allons <b>nous coucher</b>."],["Hurry up! (tu)","Dépêche-toi !","In an order: <b>Dépêche-toi !</b>"],["I got up early.","Je me suis levé tôt. / Je me suis levée tôt.","« se » verbs take <b>être</b>: je me suis levé(e)."],["They go to bed late.","Ils se couchent tard.","ils <b>se</b> couchent."]]},"25":{"line":"Like ne … pas, these wrap round the verb: <b>ne … jamais</b> (never), <b>ne … rien</b> (nothing), <b>ne … personne</b> (nobody), <b>ne … plus</b> (no longer). In the passé composé, jamais, rien and plus go before the participle (je n'ai <b>rien</b> mangé), but personne goes after it (je n'ai vu <b>personne</b>).","words":"Time words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:7\">Vocab 7 · Frequency & Time Adverbs</a>.","steps":[{"tool":"swap","title":"Swap pas for another word","sub":"Pick a sentence and tap « Make it a no ».","button":["Make it a no","Back"],"legend":[["n","the two parts of the no"],["x","what goes"]],"items":[{"label":"Je mange de la viande. (never)","en":["I eat meat.","I never eat meat."],"a":[["s","Je",""],["v","mange",""],["o","de la viande.","x"]],"b":[["s","Je",""],["ne","ne","n"],["v","mange",""],["j","jamais","n"],["o","de viande.",""]]},{"label":"Je vois quelqu'un. (nobody)","en":["I see someone.","I don't see anyone."],"a":[["s","Je",""],["v","vois",""],["o","quelqu'un.","x"]],"b":[["s","Je",""],["ne","ne","n"],["v","vois",""],["j","personne.","n"]]},{"label":"Il y a quelque chose ici. (nothing)","en":["There is something here.","There is nothing here."],"a":[["s","Il y a",""],["o","quelque chose","x"],["h","ici.",""]],"b":[["s0","Il",""],["ne","n'","n"],["s1","y a",""],["j","rien","n"],["h","ici.",""]]},{"label":"Elle travaille encore ici. (no longer)","en":["She still works here.","She no longer works here."],"a":[["s","Elle",""],["v","travaille",""],["o","encore","x"],["h","ici.",""]],"b":[["s","Elle",""],["ne","ne","n"],["v","travaille",""],["j","plus","n"],["h","ici.",""]]},{"label":"J'ai mangé quelque chose. (past)","en":["I ate something.","I didn't eat anything."],"a":[["s","J'ai",""],["v","mangé",""],["o","quelque chose.","x"]],"b":[["s0","Je",""],["ne","n'","n"],["a","ai",""],["j","rien","n"],["v","mangé.",""]],"note":"In the past: <b>rien</b> before the participle."},{"label":"J'ai vu quelqu'un. (past)","en":["I saw someone.","I didn't see anyone."],"a":[["s","J'ai",""],["v","vu",""],["o","quelqu'un.","x"]],"b":[["s0","Je",""],["ne","n'","n"],["a","ai",""],["v","vu",""],["j","personne.","n"]],"note":"But <b>personne</b> goes after the participle."}]},{"tool":"flip","title":"Opposites","sub":"Tap a card: the yes word turns into its no.","cards":[{"a":"toujours","b":"ne … jamais","tag":"always → never"},{"a":"quelque chose","b":"ne … rien","tag":"something → nothing"},{"a":"quelqu'un","b":"ne … personne","tag":"someone → nobody"},{"a":"encore","b":"ne … plus","tag":"still → no longer"},{"a":"déjà","b":"ne … pas encore","tag":"already → not yet"}]}],"practice":{"choose":[{"q":"Je ne mange ___ de viande.","en":"I never eat meat.","opts":["jamais","rien","personne","plus"],"a":"jamais","why":"never…","hint":"ne … <b>jamais</b>."},{"q":"Je ne vois ___.","en":"I don't see anyone.","opts":["personne","rien","jamais","plus"],"a":"personne","why":"nobody…","hint":"ne … <b>personne</b>."},{"q":"Il n'y a ___ ici.","en":"There is nothing here.","opts":["rien","personne","jamais","pas"],"a":"rien","why":"nothing…","hint":"ne … <b>rien</b>."},{"q":"Elle ne travaille ___ ici.","en":"She no longer works here.","opts":["plus","jamais","rien","encore"],"a":"plus","why":"no longer…","hint":"ne … <b>plus</b>."},{"q":"Je n'ai ___ mangé.","en":"I didn't eat anything.","opts":["rien","personne","mangé rien","pas rien"],"a":"rien","why":"nothing, in the past…","hint":"je n'ai <b>rien</b> mangé."},{"q":"Je n'ai vu ___.","en":"I didn't see anyone.","opts":["personne","rien","jamais","plus"],"a":"personne","why":"nobody, after the participle.","hint":"je n'ai vu <b>personne</b>."}],"build":[{"en":"I never eat meat.","tiles":["Je","ne","mange","jamais","de","viande."],"trap":"pas","why":"never…","hint":"ne mange <b>jamais</b>."},{"en":"I don't see anyone.","tiles":["Je","ne","vois","personne."],"trap":"pas","why":"nobody…","hint":"ne vois <b>personne</b>."},{"en":"There is nothing here.","tiles":["Il","n'y a","rien","ici."],"trap":"pas","why":"nothing…","hint":"n'y a <b>rien</b>."},{"en":"She no longer works here.","tiles":["Elle","ne","travaille","plus","ici."],"trap":"encore","why":"no longer…","hint":"ne travaille <b>plus</b>."},{"en":"I didn't see anyone.","tiles":["Je","n'ai","vu","personne."],"trap":"pas","why":"personne goes after the participle.","hint":"n'ai vu <b>personne</b>."}],"spot":[{"words":["Je","ne","mange","pas jamais","de viande."],"bad":3,"fix":"jamais","hint":"jamais takes the place of pas.","look":"Two no words?"},{"words":["Je","vois","personne."],"bad":1,"fix":"ne vois","hint":"Written French needs <b>ne</b>.","look":"Something is missing before the verb.","say":"Je ne vois personne."},{"words":["Je n'ai","personne","vu."],"bad":1,"fix":"vu personne","hint":"personne goes <b>after</b> the participle.","look":"Where does personne go in the past?","say":"Je n'ai vu personne."},{"words":["Je n'ai","mangé","rien."],"bad":1,"fix":"rien mangé.","hint":"rien goes <b>before</b> the participle.","look":"Where does rien go in the past?","say":"Je n'ai rien mangé."},{"words":["Elle","ne travaille","encore","ici."],"bad":2,"fix":"plus","hint":"no longer = <b>ne … plus</b>.","look":"Which word means « no longer »?"}]},"drill":[["I never eat meat","Je ne mange jamais de viande.","<b>ne … jamais</b>, and de after it."],["I don't see anyone","Je ne vois personne.","<b>ne … personne</b>."],["There is nothing here","Il n'y a rien ici.","<b>ne … rien</b>."],["She no longer works here","Elle ne travaille plus ici.","<b>ne … plus</b>."],["I didn't eat anything.","Je n'ai rien mangé.","In the past: <b>rien</b> before the participle."],["I didn't see anyone.","Je n'ai vu personne.","<b>personne</b> after the participle."]]},"22":{"line":"Many adverbs are the <b>feminine</b> adjective + <b>-ment</b>: lent → lente → <b>lentement</b>, heureux → heureuse → <b>heureusement</b>. After a vowel, just -ment: vrai → vraiment. -ant / -ent → <b>-amment / -emment</b>. Special: bon → <b>bien</b>, mauvais → <b>mal</b>. The adverb goes after the verb (il parle bien); in the passé composé, short ones go between avoir and the participle (j'ai <b>déjà</b> mangé).","words":"Frequency and time: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:7\">Vocab 7 · Frequency & Time Adverbs</a>.","steps":[{"tool":"flip","title":"Adjective → adverb","sub":"Tap a card: the adjective turns into its adverb.","cards":[{"a":"lent (lente)","b":"lentement","tag":"feminine + -ment"},{"a":"heureux (heureuse)","b":"heureusement","tag":"feminine + -ment"},{"a":"rapide","b":"rapidement","tag":"-e: + ment"},{"a":"vrai","b":"vraiment","tag":"after a vowel: + ment"},{"a":"constant","b":"constamment","tag":"-ant → -amment"},{"a":"évident","b":"évidemment","tag":"-ent → -emment"},{"a":"bon","b":"bien","tag":"special"},{"a":"mauvais","b":"mal","tag":"special"}]},{"tool":"swap","title":"Where it goes","sub":"Pick a sentence and tap « Add the adverb ».","button":["Add the adverb","Back"],"legend":[["x","the adverb"]],"items":[{"label":"Elle parle français.","en":["She speaks French.","She speaks French well."],"a":[["s","Elle",""],["v","parle",""],["o","français.",""]],"b":[["s","Elle",""],["v","parle",""],["a","bien","x"],["o","français.",""]],"note":"Right after the verb: parle <b>bien</b>."},{"label":"J'ai mangé.","en":["I have eaten.","I have already eaten."],"a":[["s","J'ai",""],["v","mangé.",""]],"b":[["s","J'ai",""],["a","déjà","x"],["v","mangé.",""]],"note":"Short adverbs go between avoir and the participle: ai <b>déjà</b> mangé."},{"label":"Il travaille.","en":["He works.","He works a lot."],"a":[["s","Il",""],["v","travaille.",""]],"b":[["s","Il",""],["v","travaille",""],["a","beaucoup.","x"]]},{"label":"Nous avons bien dormi. → long adverb","en":["We slept well.","We slept peacefully."],"a":[["s","Nous avons",""],["a","bien","x"],["v","dormi.",""]],"b":[["s","Nous avons",""],["v","dormi",""],["a2","tranquillement.","x"]],"note":"Long -ment adverbs usually go after the participle."}]}],"practice":{"choose":[{"q":"lent → ___","en":"slowly","opts":["lentement","lentment","lenement","lentemant"],"a":"lentement","why":"The feminine is lente.","hint":"lente + ment = <b>lentement</b>."},{"q":"heureux → ___","en":"fortunately","opts":["heureusement","heureuxment","heureument","heureusemant"],"a":"heureusement","why":"The feminine is heureuse.","hint":"<b>heureusement</b>."},{"q":"vrai → ___","en":"really","opts":["vraiment","vraiement","vraiemment","vraimant"],"a":"vraiment","why":"After a vowel, just -ment.","hint":"<b>vraiment</b>."},{"q":"évident → ___","en":"obviously","opts":["évidemment","évidentment","évidamment","évidement"],"a":"évidemment","why":"-ent has its own form.","hint":"-ent → <b>-emment</b>."},{"q":"Elle parle ___ français.","en":"She speaks French well.","opts":["bien","bon","bonne","mieux"],"a":"bien","why":"How she speaks: an adverb.","hint":"bon → <b>bien</b>."},{"q":"J'ai ___ mangé.","en":"I have already eaten.","opts":["déjà","déjà déjà","avant","encore"],"a":"déjà","why":"already…","hint":"j'ai <b>déjà</b> mangé."}],"build":[{"en":"She speaks French well.","tiles":["Elle","parle","bien","français."],"trap":"bon","why":"How she speaks: an adverb.","hint":"parle <b>bien</b>."},{"en":"I've already eaten.","tiles":["J'ai","déjà","mangé."],"trap":"encore","why":"Between avoir and the participle.","hint":"ai <b>déjà</b> mangé."},{"en":"He drives slowly.","tiles":["Il","conduit","lentement."],"trap":"lent","why":"How he drives: an adverb.","hint":"conduit <b>lentement</b>."},{"en":"Fortunately, it is sunny.","tiles":["Heureusement,","il","fait","beau."],"trap":"Heureux,","why":"An adverb at the front.","hint":"<b>Heureusement</b>, …"},{"en":"We work a lot.","tiles":["Nous","travaillons","beaucoup."],"trap":"très","why":"a lot = beaucoup.","hint":"travaillons <b>beaucoup</b>."}],"spot":[{"words":["Elle","parle","bon","français."],"bad":2,"fix":"bien","hint":"How she speaks: <b>bien</b>.","look":"Is it about the French or how she speaks?"},{"words":["Il","conduit","lentment."],"bad":2,"fix":"lentement.","hint":"lente + ment: <b>lentement</b>.","look":"Start from the feminine."},{"words":["J'ai","mangé","déjà."],"bad":1,"fix":"déjà mangé.","hint":"Between avoir and the participle: ai <b>déjà mangé</b>.","look":"Where does déjà go in the past?","say":"J'ai déjà mangé."},{"words":["Il chante","mauvais."],"bad":1,"fix":"mal.","hint":"mauvais → <b>mal</b>.","look":"How he sings: an adverb."},{"words":["Évidentment,","c'est vrai."],"bad":0,"fix":"Évidemment,","hint":"-ent → <b>-emment</b>.","look":"Look at the spelling of the -ent adverb."}]},"drill":[["slowly (lent)","lentement","feminine lente + <b>-ment</b>."],["fortunately (heureux)","heureusement","feminine heureuse + <b>-ment</b>."],["She speaks French well","Elle parle bien français. / Elle parle bien le français.","bon → <b>bien</b>, after the verb."],["I've already eaten","J'ai déjà mangé.","Short adverbs between avoir and the participle."],["really (vrai)","vraiment","After a vowel, just <b>-ment</b>."],["obviously (évident)","évidemment","-ent → <b>-emment</b>."]]},"26":{"line":"A relative pronoun glues two sentences into one. <b>qui</b> = the one who does it (the subject): un ami <b>qui</b> habite à Paris. <b>que</b> (qu') = the one it is done to (the object): le film <b>que</b> j'ai vu. <b>où</b> = where, or when: la ville <b>où</b> j'habite, le jour <b>où</b> tu es arrivé.","words":"","steps":[{"tool":"swap","title":"Glue two sentences","sub":"Pick a pair and tap « Glue them »: the repeated word turns into qui, que or où.","button":["Glue them","Two sentences again"],"legend":[["p","the glue word"],["x","what it replaces"]],"items":[{"label":"J'ai un ami. Il habite à Paris.","en":["I have a friend. He lives in Paris.","I have a friend who lives in Paris."],"a":[["a","J'ai un ami.",""],["x","Il","x"],["b","habite à Paris.",""]],"b":[["a","J'ai un ami",""],["p","qui","p"],["b","habite à Paris.",""]],"note":"Il does the action (the subject) → <b>qui</b>."},{"label":"Le film est génial. J'ai vu ce film.","en":["The film is great. I saw the film.","The film that I saw is great."],"a":[["a","Le film est génial.",""],["b","J'ai vu",""],["x","ce film.","x"]],"b":[["a0","Le film",""],["p","que","p"],["b","j'ai vu",""],["a1","est génial.",""]],"note":"ce film is what I saw (the object) → <b>que</b>."},{"label":"C'est la ville. J'habite dans cette ville.","en":["It's the town. I live in that town.","It's the town where I live."],"a":[["a","C'est la ville.",""],["b","J'habite",""],["x","dans cette ville.","x"]],"b":[["a","C'est la ville",""],["p","où","p"],["b","j'habite.",""]],"note":"A place → <b>où</b>."},{"label":"Je me souviens du jour. Tu es arrivé ce jour-là.","en":["I remember the day. You arrived that day.","I remember the day when you arrived."],"a":[["a","Je me souviens du jour.",""],["b","Tu es arrivé",""],["x","ce jour-là.","x"]],"b":[["a","Je me souviens du jour",""],["p","où","p"],["b","tu es arrivé.",""]],"note":"A time, too → <b>où</b> (not quand)."},{"label":"C'est un livre. Marie aime ce livre.","en":["It's a book. Marie loves this book.","It's a book that Marie loves."],"a":[["a","C'est un livre.",""],["b","Marie aime",""],["x","ce livre.","x"]],"b":[["a","C'est un livre",""],["p","qu'","p"],["b","Marie aime.",""]],"note":"que before a vowel: <b>qu'</b>Marie."}]},{"tool":"sort","title":"qui, que or où?","sub":"Look at what follows the gap. Tap the box.","boxes":[{"k":"qui","label":"qui","sub":"+ a verb (it is the subject)"},{"k":"que","label":"que","sub":"+ a subject and a verb"},{"k":"ou","label":"où","sub":"a place or a time"}],"cards":[{"t":"le livre … est sur la table","box":"qui","why":"Followed by a verb (est): <b>qui</b>."},{"t":"le livre … je lis","box":"que","why":"Followed by je lis: <b>que</b>."},{"t":"la maison … j'habite","box":"ou","why":"A place: <b>où</b>."},{"t":"la fille … chante","box":"qui","why":"<b>qui</b> chante."},{"t":"la fille … tu connais","box":"que","why":"<b>que</b> tu connais."},{"t":"le jour … il est né","box":"ou","why":"A time: <b>où</b>."},{"t":"les amis … viennent ce soir","box":"qui","why":"<b>qui</b> viennent."},{"t":"le café … nous aimons","box":"que","why":"<b>que</b> nous aimons."}]}],"practice":{"choose":[{"q":"J'ai un ami ___ habite à Paris.","en":"I have a friend who lives in Paris.","opts":["qui","que","où","quoi"],"a":"qui","why":"A verb follows the gap.","hint":"<b>qui</b> + verb."},{"q":"le film ___ j'ai vu","en":"the film that I saw","opts":["que","qui","où","dont"],"a":"que","why":"A subject (j') follows the gap.","hint":"<b>que</b> + subject + verb."},{"q":"la ville ___ j'habite","en":"the town where I live","opts":["où","que","qui","quand"],"a":"où","why":"A place…","hint":"<b>où</b>."},{"q":"Le livre ___ est sur la table.","en":"The book that is on the table.","opts":["qui","que","qu'","où"],"a":"qui","why":"A verb follows the gap.","hint":"<b>qui</b> est sur la table."},{"q":"le jour ___ il est né","en":"the day he was born","opts":["où","quand","que","qui"],"a":"où","why":"A time, in French…","hint":"A time: <b>où</b>, not quand."},{"q":"la robe ___ elle porte","en":"the dress she is wearing","opts":["qu'","que","qui","où"],"a":"qu'","why":"que before a vowel…","hint":"<b>qu'</b>elle porte."}],"build":[{"en":"I have a friend who lives in Paris.","tiles":["J'ai","un","ami","qui","habite","à Paris."],"trap":"que","why":"A verb follows.","hint":"<b>qui</b> habite."},{"en":"the film that I saw","tiles":["le","film","que","j'ai","vu"],"trap":"qui","why":"A subject follows.","hint":"<b>que</b> j'ai vu."},{"en":"the town where I live","tiles":["la","ville","où","j'habite"],"trap":"que","why":"A place.","hint":"<b>où</b> j'habite."},{"en":"the girl you know","tiles":["la","fille","que","tu","connais"],"trap":"qui","why":"A subject follows.","hint":"<b>que</b> tu connais."},{"en":"the day when you arrived","tiles":["le","jour","où","tu","es arrivé"],"trap":"quand","why":"A time.","hint":"<b>où</b> tu es arrivé."}],"spot":[{"words":["J'ai un ami","que","habite ici."],"bad":1,"fix":"qui","hint":"A verb follows: <b>qui</b>.","look":"What follows the glue word?"},{"words":["le film","qui","j'ai vu"],"bad":1,"fix":"que","hint":"A subject follows: <b>que</b>.","look":"What follows the glue word?"},{"words":["la ville","que","j'habite"],"bad":1,"fix":"où","hint":"A place: <b>où</b>.","look":"Is it a place?"},{"words":["le jour","quand","il est né"],"bad":1,"fix":"où","hint":"A time after a noun: <b>où</b>.","look":"Which word for a time after le jour?"},{"words":["le livre","que","elle lit"],"bad":1,"fix":"qu'","hint":"que before a vowel: <b>qu'</b>elle.","look":"Look before elle.","say":"le livre qu'elle lit"}]},"drill":[["I have a friend who lives in Paris","J'ai un ami qui habite à Paris. / J'ai une amie qui habite à Paris. / J'ai un ami qui vit à Paris.","A verb follows: <b>qui</b>."],["the film that I saw","le film que j'ai vu","A subject follows: <b>que</b>."],["the town where I live","la ville où j'habite / la ville où je vis","A place: <b>où</b>."],["Qui or que? Le livre ___ est sur la table","qui","A verb follows, so it is the subject: <b>qui</b>."],["the day when he was born","le jour où il est né","A time: <b>où</b>."],["the girl you know (tu)","la fille que tu connais","<b>que</b> + tu connais."]]},"16":{"line":"The <b>imparfait</b> says how things were or used to be: descriptions, background, habits. Take the nous form of the present, drop -ons, add <b>-ais, -ais, -ait, -ions, -iez, -aient</b>: nous parl<i>ons</i> → je parl<b>ais</b>. Only être is different: j'<b>étais</b>. Quand j'étais petit, nous habitions à Lyon.","words":"","steps":[{"tool":"conj","title":"One set of endings for every verb","sub":"Pick a verb, then tap a person: the ending lights up.","neg":true,"verbs":[{"inf":"parler","en":"was speaking / used to speak","stem":"parl","forms":["parlais","parlais","parlait","parlions","parliez","parlaient"],"tail":"souvent"},{"inf":"finir","en":"was finishing","stem":"finiss","forms":["finissais","finissais","finissait","finissions","finissiez","finissaient"],"tail":"tard"},{"inf":"faire","en":"was doing","stem":"fais","forms":["faisais","faisais","faisait","faisions","faisiez","faisaient"],"tail":"du sport"},{"inf":"être","en":"was","stem":"ét","forms":["étais","étais","était","étions","étiez","étaient"],"tail":"content"}]},{"tool":"flip","title":"From the nous form","sub":"Tap a card: nous … -ons gives the imparfait.","cards":[{"a":"nous parlons","b":"je parlais","tag":"parl-"},{"a":"nous finissons","b":"je finissais","tag":"finiss-"},{"a":"nous faisons","b":"je faisais","tag":"fais-"},{"a":"nous prenons","b":"je prenais","tag":"pren-"},{"a":"nous avons","b":"j'avais","tag":"av-"},{"a":"nous mangeons","b":"je mangeais","tag":"mange- (keeps the e)"},{"a":"nous sommes","b":"j'étais","tag":"the only exception"}]},{"tool":"sort","title":"What is it for?","sub":"Tap what each sentence does.","boxes":[{"k":"d","label":"a description","sub":"how it was"},{"k":"h","label":"a habit","sub":"what used to happen"},{"k":"b","label":"the background","sub":"what was going on"}],"cards":[{"t":"La maison était grande.","box":"d"},{"t":"Le dimanche, nous allions chez mamie.","box":"h"},{"t":"Il pleuvait.","box":"b"},{"t":"Elle avait les yeux bleus.","box":"d"},{"t":"Je jouais au foot tous les jours.","box":"h"},{"t":"Tout le monde dormait.","box":"b"}]}],"practice":{"choose":[{"q":"J'___ petit.","en":"I was little.","opts":["étais","étai","était","été"],"a":"étais","why":"être with je.","hint":"<b>j'étais</b>."},{"q":"Nous ___ (manger) à midi.","en":"We used to eat at noon.","opts":["mangions","mangeions","mangeons","mangiez"],"a":"mangions","why":"nous + -ions.","hint":"nous <b>mangions</b>."},{"q":"Elle ___ (habiter) à Paris.","en":"She used to live in Paris.","opts":["habitait","habitais","habitaient","a habité"],"a":"habitait","why":"elle + -ait.","hint":"elle <b>habitait</b>."},{"q":"Il y ___ un café ici.","en":"There was a café here.","opts":["avait","était","a eu","avais"],"a":"avait","why":"il y a in the imparfait…","hint":"il y <b>avait</b>."},{"q":"Ils ___ (faire) du sport.","en":"They used to do sport.","opts":["faisaient","faisait","faisions","fasaient"],"a":"faisaient","why":"ils + -aient.","hint":"ils <b>faisaient</b>."},{"q":"Vous ___ (être) fatigués.","en":"You were tired.","opts":["étiez","étaient","êtiez","étions"],"a":"étiez","why":"vous + -iez.","hint":"vous <b>étiez</b>."}],"build":[{"en":"I was little.","tiles":["J'","étais","petit."],"trap":"ai été","why":"A description: imparfait.","hint":"<b>j'étais</b>."},{"en":"We used to eat at noon.","tiles":["Nous","mangions","à","midi."],"trap":"mangeons","why":"A habit: imparfait.","hint":"nous <b>mangions</b>."},{"en":"She used to live in Paris.","tiles":["Elle","habitait","à","Paris."],"trap":"habite","why":"A habit: imparfait.","hint":"elle <b>habitait</b>."},{"en":"There was a café.","tiles":["Il","y","avait","un","café."],"trap":"était","why":"il y a → ?","hint":"il y <b>avait</b>."},{"en":"It was raining.","tiles":["Il","pleuvait."],"trap":"a plu","why":"The background: imparfait.","hint":"il <b>pleuvait</b>."}],"spot":[{"words":["Nous","mangeions","tard."],"bad":1,"fix":"mangions","hint":"nous: <b>mangions</b> (no extra e before i).","look":"Look at the spelling with nous."},{"words":["J'","étai","content."],"bad":1,"fix":"étais","hint":"je: <b>étais</b>.","look":"Look at the ending with je.","say":"J'étais content."},{"words":["Ils","faisait","du sport."],"bad":1,"fix":"faisaient","hint":"ils: <b>-aient</b>.","look":"Look at the ending with ils."},{"words":["Il y","était","un café."],"bad":1,"fix":"avait","hint":"il y a → il y <b>avait</b>.","look":"Which verb is in il y a?"},{"words":["Tu","parlait","vite."],"bad":1,"fix":"parlais","hint":"tu: <b>-ais</b>.","look":"Look at the ending with tu."}]},"drill":[["I was (être)","J'étais","être: <b>j'étais</b>."],["we ate (manger)","nous mangions","nous <b>-ions</b>: mangions."],["She used to live in Paris","Elle habitait à Paris. / Elle vivait à Paris. / Elle habitait Paris.","A habit: elle <b>habitait</b>."],["There was a café","Il y avait un café.","il y a → il y <b>avait</b>."],["they did (faire, imparfait)","ils faisaient","ils <b>-aient</b>: faisaient."],["It was raining.","Il pleuvait.","The background: <b>il pleuvait</b>."]]},"17":{"line":"Two pasts, two jobs. The <b>passé composé</b> moves the story on: what happened, once, at a moment (le téléphone <b>a sonné</b>). The <b>imparfait</b> sets the scene: what was going on, how it was, what used to happen (il <b>pleuvait</b>, j'<b>étais</b> fatigué). Often together: Je <b>dormais</b> quand il <b>a appelé</b>.","words":"","steps":[{"tool":"line","title":"The scene and the event","sub":"Tap a point: the long stretch is the imparfait, the dots are the passé composé.","now":"","marks":[{"at":-0.85,"label":"il pleuvait…","fr":"Il pleuvait.","html":"Il <span class=\"gt-end\">pleuvait</span>.","en":"It was raining (all along).","note":"The background, no start or end: <b>imparfait</b>."},{"at":-0.4,"label":"je dormais…","fr":"Je dormais.","html":"Je <span class=\"gt-end\">dormais</span>.","en":"I was sleeping (all along).","note":"What was going on: <b>imparfait</b>."},{"at":0.0,"label":"• il a appelé","fr":"Il a appelé.","html":"Il <span class=\"gt-end\">a appelé</span>.","en":"He called (once).","note":"An event at one moment: <b>passé composé</b>."},{"at":0.45,"label":"• je me suis levé","fr":"Je me suis levé.","html":"Je <span class=\"gt-end\">me suis levé</span>.","en":"I got up.","note":"The next event: <b>passé composé</b>."},{"at":0.9,"label":"both","fr":"Je dormais quand il a appelé.","html":"Je <span class=\"gt-end\">dormais</span> quand il <span class=\"gt-end\">a appelé</span>.","en":"I was sleeping when he called.","note":"The scene (imparfait) is cut by an event (passé composé)."}]},{"tool":"sort","title":"Passé composé or imparfait?","sub":"Tap the box for each verb.","boxes":[{"k":"pc","label":"passé composé","sub":"what happened, once"},{"k":"imp","label":"imparfait","sub":"the scene, how it was, habits"}],"cards":[{"t":"Hier, j'… (manger) une pizza.","box":"pc","why":"Once, yesterday: <b>j'ai mangé</b>.","say":"Hier, j'ai mangé une pizza."},{"t":"Quand j'… (être) petit…","box":"imp","why":"How it was: <b>j'étais</b>.","say":"Quand j'étais petit…"},{"t":"Il … (faire) beau.","box":"imp","why":"The weather, the scene: <b>il faisait</b> beau.","say":"Il faisait beau."},{"t":"Soudain, la porte … (s'ouvrir).","box":"pc","why":"Suddenly: an event, <b>s'est ouverte</b>.","say":"Soudain, la porte s'est ouverte."},{"t":"Tous les étés, nous … (aller) à la mer.","box":"imp","why":"A habit: <b>nous allions</b>.","say":"Tous les étés, nous allions à la mer."},{"t":"En 2010, elle … (arriver) en France.","box":"pc","why":"One moment: <b>elle est arrivée</b>.","say":"En 2010, elle est arrivée en France."},{"t":"Elle … (avoir) les cheveux longs.","box":"imp","why":"A description: <b>elle avait</b>.","say":"Elle avait les cheveux longs."},{"t":"Il … (téléphoner) trois fois.","box":"pc","why":"Counted events: <b>il a téléphoné</b>.","say":"Il a téléphoné trois fois."}]}],"practice":{"choose":[{"q":"Hier, j'___ une pizza.","en":"Yesterday I ate a pizza.","opts":["ai mangé","mangeais","mange","mangé"],"a":"ai mangé","why":"Once, yesterday…","hint":"<b>passé composé</b>."},{"q":"Quand j'___ petit, j'habitais à Lyon.","en":"When I was little, I lived in Lyon.","opts":["étais","ai été","suis","été"],"a":"étais","why":"How it was…","hint":"<b>imparfait</b>: j'étais."},{"q":"Il ___ quand je suis parti.","en":"It was raining when I left.","opts":["pleuvait","a plu","pleut","pleuvra"],"a":"pleuvait","why":"The scene…","hint":"<b>imparfait</b>: il pleuvait."},{"q":"Je dormais quand il ___.","en":"I was sleeping when he called.","opts":["a appelé","appelait","appelle","appelé"],"a":"a appelé","why":"The event that cuts in…","hint":"<b>passé composé</b>: il a appelé."},{"q":"Tous les étés, nous ___ à la mer.","en":"Every summer we went to the sea.","opts":["allions","sommes allés","allons","irons"],"a":"allions","why":"A habit…","hint":"<b>imparfait</b>: nous allions."},{"q":"Soudain, la porte ___.","en":"Suddenly the door opened.","opts":["s'est ouverte","s'ouvrait","s'ouvre","ouvert"],"a":"s'est ouverte","why":"Suddenly: one event.","hint":"<b>passé composé</b>."}],"build":[{"en":"It was raining when I left.","tiles":["Il","pleuvait","quand","je","suis","parti."],"trap":"a plu","why":"The scene, then the event.","hint":"il <b>pleuvait</b> quand je <b>suis parti</b>."},{"en":"I was sleeping when he called.","tiles":["Je","dormais","quand","il","a","appelé."],"trap":"ai dormi","why":"The scene, then the event.","hint":"je <b>dormais</b> quand il <b>a appelé</b>."},{"en":"Yesterday I saw a film.","tiles":["Hier,","j'ai","vu","un","film."],"trap":"voyais","why":"Once, yesterday.","hint":"<b>j'ai vu</b>."},{"en":"When I was little, we lived in Lyon.","tiles":["Quand j'étais","petit,","nous","habitions","à Lyon."],"trap":"avons habité","why":"How it was, for a long time.","hint":"nous <b>habitions</b>."},{"en":"The weather was nice.","tiles":["Il","faisait","beau."],"trap":"a fait","why":"A description.","hint":"il <b>faisait</b> beau."}],"spot":[{"words":["Quand j'","ai été","petit…"],"bad":1,"fix":"étais","hint":"How it was: <b>imparfait</b>.","look":"Is it an event or how it was?","say":"Quand j'étais petit…"},{"words":["Hier,","je mangeais","une pizza."],"bad":1,"fix":"j'ai mangé","hint":"Once, yesterday: <b>passé composé</b>.","look":"Is it an event or the scene?"},{"words":["Il","a plu","quand je suis sorti."],"bad":1,"fix":"pleuvait","hint":"The scene: <b>imparfait</b>.","look":"Was it going on, or did it happen once?"},{"words":["Je dormais","quand il","appelait."],"bad":2,"fix":"a appelé.","hint":"The event that cuts in: <b>passé composé</b>.","look":"What cut the sleep?"},{"words":["Tous les jours,","nous sommes allés","au parc."],"bad":1,"fix":"nous allions","hint":"A habit: <b>imparfait</b>.","look":"Every day: an event or a habit?"}]},"drill":[["It was raining when I left","Il pleuvait quand je suis parti(e). / Il pleuvait quand je suis sorti(e).","The scene (imparfait), then the event (passé composé)."],["Hier, j'___ (manger) une pizza.","j'ai mangé","Once, yesterday: <b>passé composé</b>."],["Quand j'___ (être) petit...","j'étais","How it was: <b>imparfait</b>."],["I was sleeping when he called","Je dormais quand il a téléphoné. / Je dormais quand il a appelé.","je <b>dormais</b> (scene) quand il <b>a appelé</b> (event)."],["Every summer we went to the sea.","Tous les étés, nous allions à la mer.","A habit: <b>imparfait</b>."],["Suddenly the door opened.","Soudain, la porte s'est ouverte.","Suddenly: <b>passé composé</b>."]]},"28":{"line":"Four time words: <b>depuis</b> = since / for, still going on (present tense: j'habite ici <b>depuis</b> trois ans). <b>pendant</b> = for, finished (elle a dormi <b>pendant</b> dix heures). <b>il y a</b> = ago (je suis arrivé <b>il y a</b> une heure). <b>dans</b> = in, from now (je pars <b>dans</b> deux jours).","words":"Time words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:5\">Vocab 5 · The Calendar & Timeline</a> · <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:7\">Vocab 7 · Frequency & Time Adverbs</a>.","steps":[{"tool":"line","title":"Which one?","sub":"Tap each word on the line.","now":"","marks":[{"at":-0.8,"label":"il y a","fr":"Je suis arrivé il y a une heure.","html":"Je suis arrivé <span class=\"gt-end\">il y a</span> une heure.","en":"I arrived an hour ago.","note":"A point in the past, counted back from now. Passé composé."},{"at":-0.35,"label":"pendant","fr":"Elle a dormi pendant dix heures.","html":"Elle a dormi <span class=\"gt-end\">pendant</span> dix heures.","en":"She slept for ten hours.","note":"A stretch that is over."},{"at":0.0,"label":"depuis → now","fr":"J'habite ici depuis trois ans.","html":"J'habite ici <span class=\"gt-end\">depuis</span> trois ans.","en":"I have lived here for three years.","note":"It started in the past and is <b>still going on</b>: present tense in French."},{"at":0.65,"label":"dans","fr":"Je pars dans deux jours.","html":"Je pars <span class=\"gt-end\">dans</span> deux jours.","en":"I'm leaving in two days.","note":"A point in the future, counted from now."}]},{"tool":"sort","title":"depuis, pendant, il y a or dans?","sub":"Tap the box for each sentence.","boxes":[{"k":"dep","label":"depuis","sub":"still going on"},{"k":"pen","label":"pendant","sub":"a finished stretch"},{"k":"ily","label":"il y a","sub":"ago"},{"k":"dans","label":"dans","sub":"from now"}],"cards":[{"t":"J'apprends le français … deux ans.","box":"dep","why":"Still learning: <b>depuis</b>.","say":"J'apprends le français depuis deux ans."},{"t":"Il a plu … tout le week-end.","box":"pen","why":"Over: <b>pendant</b>.","say":"Il a plu pendant tout le week-end."},{"t":"Elle est partie … une semaine.","box":"ily","why":"A week ago: <b>il y a</b>.","say":"Elle est partie il y a une semaine."},{"t":"Le train part … dix minutes.","box":"dans","why":"Ten minutes from now: <b>dans</b>.","say":"Le train part dans dix minutes."},{"t":"Je t'attends … une heure !","box":"dep","why":"Still waiting: <b>depuis</b>.","say":"Je t'attends depuis une heure !"},{"t":"Nous avons travaillé … trois heures.","box":"pen","why":"Over: <b>pendant</b>.","say":"Nous avons travaillé pendant trois heures."}]}],"practice":{"choose":[{"q":"J'habite ici ___ trois ans.","en":"I have lived here for three years.","opts":["depuis","pendant","il y a","dans"],"a":"depuis","why":"Still living here…","hint":"<b>depuis</b>."},{"q":"Je suis arrivé ___ une heure.","en":"I arrived an hour ago.","opts":["il y a","depuis","dans","pendant"],"a":"il y a","why":"ago…","hint":"<b>il y a</b>."},{"q":"Je pars ___ deux jours.","en":"I'm leaving in two days.","opts":["dans","en","depuis","il y a"],"a":"dans","why":"From now…","hint":"<b>dans</b>."},{"q":"Elle a dormi ___ dix heures.","en":"She slept for ten hours.","opts":["pendant","depuis","il y a","dans"],"a":"pendant","why":"A finished stretch.","hint":"<b>pendant</b>."},{"q":"J'___ le français depuis deux ans.","en":"I have been learning French for two years.","opts":["apprends","ai appris","apprenais","apprendrai"],"a":"apprends","why":"With depuis, still going on: which tense?","hint":"depuis + the <b>present</b>."},{"q":"Je t'attends ___ midi.","en":"I've been waiting for you since noon.","opts":["depuis","pendant","il y a","dans"],"a":"depuis","why":"since…","hint":"<b>depuis</b> midi."}],"build":[{"en":"I have lived here for three years.","tiles":["J'habite","ici","depuis","trois ans."],"trap":"J'ai habité","why":"Still going on: the present.","hint":"<b>j'habite</b> ici depuis …"},{"en":"I arrived an hour ago.","tiles":["Je","suis","arrivé","il y a","une heure."],"trap":"depuis","why":"ago…","hint":"<b>il y a</b> une heure."},{"en":"I'm leaving in two days.","tiles":["Je","pars","dans","deux jours."],"trap":"en","why":"From now…","hint":"<b>dans</b> deux jours."},{"en":"She slept for ten hours.","tiles":["Elle","a","dormi","pendant","dix heures."],"trap":"depuis","why":"Over…","hint":"<b>pendant</b> dix heures."},{"en":"The train leaves in ten minutes.","tiles":["Le train","part","dans","dix minutes."],"trap":"il y a","why":"From now…","hint":"<b>dans</b> dix minutes."}],"spot":[{"words":["J'ai habité","ici","depuis trois ans."],"bad":0,"fix":"J'habite","hint":"Still going on, with depuis: the <b>present</b>.","look":"Which tense goes with depuis?"},{"words":["Je suis arrivé","depuis","une heure."],"bad":1,"fix":"il y a","hint":"ago: <b>il y a</b>.","look":"Is it still going on, or ago?"},{"words":["Je pars","en","deux jours."],"bad":1,"fix":"dans","hint":"From now: <b>dans</b>.","look":"Two days from now…"},{"words":["Elle a dormi","depuis","dix heures."],"bad":1,"fix":"pendant","hint":"A finished stretch: <b>pendant</b>.","look":"Is the sleep over?"},{"words":["Il est parti","dans","une semaine."],"bad":1,"fix":"il y a","hint":"In the past: <b>il y a</b>.","look":"est parti is in the past…"}]},"drill":[["I have lived here for 3 years","J'habite ici depuis trois ans. / Je vis ici depuis trois ans.","Still going on: <b>depuis</b> + the present."],["I arrived an hour ago","Je suis arrivé(e) il y a une heure.","ago: <b>il y a</b>."],["I'm leaving in two days","Je pars dans deux jours.","From now: <b>dans</b>."],["She slept for ten hours","Elle a dormi pendant dix heures. / Elle a dormi dix heures.","Over: <b>pendant</b>."],["I've been waiting for an hour.","J'attends depuis une heure.","Still waiting: <b>depuis</b> + the present."],["The train leaves in ten minutes.","Le train part dans dix minutes.","<b>dans</b> dix minutes."]]},"23":{"line":"The <b>futur simple</b> is one word: the infinitive + <b>-ai, -as, -a, -ons, -ez, -ont</b>: je parler<b>ai</b>, nous finir<b>ons</b> (-re verbs drop the e: je vendr<b>ai</b>). Some stems are irregular: <b>ser-</b> (être), <b>aur-</b> (avoir), <b>ir-</b> (aller), <b>fer-</b> (faire), <b>viendr-</b>, <b>pourr-</b>, <b>voudr-</b>, <b>verr-</b>. After quand about the future, French uses the future: Quand j'arriverai, je t'appellerai.","words":"","steps":[{"tool":"conj","title":"Infinitive + the endings","sub":"Pick a verb, then tap a person.","neg":true,"verbs":[{"inf":"parler","en":"will speak","stem":"parler","forms":["parlerai","parleras","parlera","parlerons","parlerez","parleront"],"tail":"français"},{"inf":"vendre","en":"will sell","stem":"vendr","forms":["vendrai","vendras","vendra","vendrons","vendrez","vendront"],"tail":"la voiture"},{"inf":"être","en":"will be","stem":"ser","forms":["serai","seras","sera","serons","serez","seront"],"tail":"là"},{"inf":"aller","en":"will go","stem":"ir","forms":["irai","iras","ira","irons","irez","iront"],"tail":"à Paris"}]},{"tool":"flip","title":"The irregular stems","sub":"Tap a card: the verb turns into its future stem.","cards":[{"a":"être","b":"je serai","tag":"ser-"},{"a":"avoir","b":"j'aurai","tag":"aur-"},{"a":"aller","b":"j'irai","tag":"ir-"},{"a":"faire","b":"je ferai","tag":"fer-"},{"a":"venir","b":"je viendrai","tag":"viendr-"},{"a":"pouvoir","b":"je pourrai","tag":"pourr-"},{"a":"vouloir","b":"je voudrai","tag":"voudr-"},{"a":"voir","b":"je verrai","tag":"verr-"},{"a":"devoir","b":"je devrai","tag":"devr-"},{"a":"savoir","b":"je saurai","tag":"saur-"}]},{"tool":"swap","title":"Near future → futur simple","sub":"Pick a sentence and tap « One word ».","button":["One word","Back"],"legend":[["x","the future"]],"items":[{"label":"Je vais parler.","en":["I'm going to speak.","I will speak."],"a":[["s","Je",""],["a","vais","x"],["v","parler.","x"]],"b":[["s","Je",""],["v","parlerai.","x"]]},{"label":"Nous allons partir.","en":["We're going to leave.","We will leave."],"a":[["s","Nous",""],["a","allons","x"],["v","partir.","x"]],"b":[["s","Nous",""],["v","partirons.","x"]]},{"label":"Quand j'arrive, je t'appelle.","en":["When I arrive, I call you.","When I arrive, I'll call you."],"a":[["q","Quand j'",""],["v","arrive,","x"],["s","je",""],["v2","t'appelle.","x"]],"b":[["q","Quand j'",""],["v","arriverai,","x"],["s","je",""],["v2","t'appellerai.","x"]],"note":"About the future, <b>both</b> verbs are in the future (English says « when I arrive »)."}]}],"practice":{"choose":[{"q":"Je ___ (parler) demain.","en":"I will speak tomorrow.","opts":["parlerai","parlerais","parlai","vais parlerai"],"a":"parlerai","why":"je + -ai.","hint":"je <b>parlerai</b>."},{"q":"Nous ___ (aller) en France.","en":"We will go to France.","opts":["irons","allerons","irions","allons"],"a":"irons","why":"aller has its own stem.","hint":"nous <b>irons</b>."},{"q":"Elle ___ (être) contente.","en":"She will be happy.","opts":["sera","serait","étera","est"],"a":"sera","why":"être has its own stem.","hint":"elle <b>sera</b>."},{"q":"Ils ___ (faire) du sport.","en":"They will do sport.","opts":["feront","faireront","feraient","font"],"a":"feront","why":"faire has its own stem.","hint":"ils <b>feront</b>."},{"q":"Quand j'___, je t'appellerai.","en":"When I arrive, I'll call you.","opts":["arriverai","arrive","arriverais","suis arrivé"],"a":"arriverai","why":"About the future, after quand…","hint":"quand + the <b>future</b>."},{"q":"Tu ___ (vendre) ta voiture ?","en":"Will you sell your car?","opts":["vendras","vendreras","vendrais","vends"],"a":"vendras","why":"-re verbs drop the e.","hint":"tu <b>vendras</b>."}],"build":[{"en":"I will speak.","tiles":["Je","parlerai."],"trap":"parlerais","why":"je + -ai.","hint":"je <b>parlerai</b>."},{"en":"We will go to Paris.","tiles":["Nous","irons","à","Paris."],"trap":"allerons","why":"aller → ir-.","hint":"nous <b>irons</b>."},{"en":"She will be there.","tiles":["Elle","sera","là."],"trap":"étera","why":"être → ser-.","hint":"elle <b>sera</b>."},{"en":"When I arrive, I'll call you.","tiles":["Quand j'","arriverai,","je","t'appellerai."],"trap":"arrive,","why":"After quand about the future: the future.","hint":"quand j'<b>arriverai</b>."},{"en":"They will have time.","tiles":["Ils","auront","le","temps."],"trap":"averont","why":"avoir → aur-.","hint":"ils <b>auront</b>."}],"spot":[{"words":["Nous","allerons","à Paris."],"bad":1,"fix":"irons","hint":"aller → <b>ir-</b>: nous irons.","look":"aller has its own stem."},{"words":["Elle","étera","là."],"bad":1,"fix":"sera","hint":"être → <b>ser-</b>.","look":"être has its own stem."},{"words":["Quand j'","arrive,","je t'appellerai."],"bad":1,"fix":"arriverai,","hint":"About the future: <b>quand j'arriverai</b>.","look":"Look at the verb after quand.","say":"Quand j'arriverai, je t'appellerai."},{"words":["Je","vendreai","ma voiture."],"bad":1,"fix":"vendrai","hint":"-re verbs drop the e: <b>vendrai</b>.","look":"Look at the -re verb."},{"words":["Ils","faireront","la fête."],"bad":1,"fix":"feront","hint":"faire → <b>fer-</b>.","look":"faire has its own stem."}]},"drill":[["I will speak (parler)","Je parlerai.","The infinitive + <b>-ai</b>."],["We will go (aller)","Nous irons.","aller → <b>ir-</b>."],["She will be (être)","Elle sera.","être → <b>ser-</b>."],["When I arrive, I'll call you","Quand j'arriverai, je t'appellerai. / Quand j'arriverai, je vous appellerai.","After quand about the future: the <b>future</b>."],["They will do (faire)","Ils feront.","faire → <b>fer-</b>."],["I will have (avoir)","J'aurai.","avoir → <b>aur-</b>."]]},"v17":{"line":"Most irregular verbs belong to a <b>family</b>: learn the head of the family and the others copy it, in every tense. <b>venir</b> → devenir, revenir, se souvenir (and tenir, obtenir). <b>prendre</b> → apprendre, comprendre, surprendre. <b>mettre</b> → permettre, promettre. <b>dire</b>: careful, vous <b>dites</b> (but vous contredisez). A good review of the present, the passé composé and the future.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"sort","title":"Which family?","sub":"Tap the head of the family for each verb.","boxes":[{"k":"venir","label":"venir"},{"k":"prendre","label":"prendre"},{"k":"mettre","label":"mettre"},{"k":"tenir","label":"tenir"}],"cards":[{"t":"devenir","box":"venir","why":"je deviens, je suis devenu(e)"},{"t":"apprendre","box":"prendre","why":"j'apprends, j'ai appris"},{"t":"permettre","box":"mettre","why":"je permets, j'ai permis"},{"t":"obtenir","box":"tenir","why":"j'obtiens, j'ai obtenu"},{"t":"revenir","box":"venir","why":"je reviens, je suis revenu(e)"},{"t":"comprendre","box":"prendre","why":"je comprends, j'ai compris"},{"t":"promettre","box":"mettre","why":"je promets, j'ai promis"},{"t":"appartenir","box":"tenir","why":"j'appartiens, j'ai appartenu"},{"t":"se souvenir","box":"venir","why":"je me souviens, je me suis souvenu(e)"}]},{"tool":"conj","title":"Heads of the family, in the present","sub":"Pick a verb, then tap a person.","neg":true,"verbs":[{"inf":"dire","en":"to say","forms":["dis","dis","dit","disons","dites","disent"],"tail":"bonjour"},{"inf":"mettre","en":"to put","forms":["mets","mets","met","mettons","mettez","mettent"],"tail":"la table"},{"inf":"tenir","en":"to hold","forms":["tiens","tiens","tient","tenons","tenez","tiennent"],"tail":"la porte"},{"inf":"connaître","en":"to know (a person, a place)","forms":["connais","connais","connaît","connaissons","connaissez","connaissent"],"tail":"Paris"}]},{"tool":"flip","title":"The family across the tenses","sub":"Tap a card: present → passé composé or future.","cards":[{"a":"je deviens","b":"je suis devenu(e)","tag":"passé composé, with être"},{"a":"nous mettons","b":"nous mettrons","tag":"future"},{"a":"ils prennent","b":"ils ont pris","tag":"passé composé"},{"a":"je viens","b":"je viendrai","tag":"future: viendr-"},{"a":"vous dites","b":"vous avez dit","tag":"passé composé"},{"a":"il obtient","b":"il obtiendra","tag":"future: obtiendr-"}]}],"practice":{"choose":[{"q":"Ils ___ le bus. (prendre)","en":"They take the bus.","opts":["prennent","prenent","prendent","prend"],"a":"prennent","why":"prendre with ils.","hint":"ils <b>prennent</b>."},{"q":"Vous ___ quoi ? (dire)","en":"What are you saying?","opts":["dites","disez","disent","dit"],"a":"dites","why":"dire with vous: irregular.","hint":"vous <b>dites</b>."},{"q":"Je suis ___ médecin. (devenir)","en":"I became a doctor.","opts":["devenu(e)","devenir","devient","devené"],"a":"devenu(e)","why":"Like venir in the past.","hint":"je suis <b>devenu(e)</b>."},{"q":"Nous ___ la table. (mettre, future)","en":"We will set the table.","opts":["mettrons","metterons","mettons","mettions"],"a":"mettrons","why":"mettre + -ons, drop the e.","hint":"nous <b>mettrons</b>."},{"q":"Elle ___ son diplôme. (obtenir, passé composé)","en":"She got her degree.","opts":["a obtenu","est obtenue","a obtient","a obteni"],"a":"a obtenu","why":"Like tenir: avoir + -u.","hint":"elle <b>a obtenu</b>."},{"q":"Tu ___ Marie ? (connaître)","en":"Do you know Marie?","opts":["connais","connait","connaît","connaissez"],"a":"connais","why":"connaître with tu.","hint":"tu <b>connais</b>."}],"build":[{"en":"They take the train.","tiles":["Ils","prennent","le","train."],"trap":"prenent","why":"Double n.","hint":"ils <b>prennent</b>."},{"en":"What are you saying? (vous)","tiles":["Vous","dites","quoi ?"],"trap":"disez","why":"dire with vous.","hint":"vous <b>dites</b>."},{"en":"I became a doctor.","tiles":["Je","suis","devenu","médecin."],"trap":"ai","why":"Like venir: être.","hint":"je <b>suis devenu</b>."},{"en":"We will set the table.","tiles":["Nous","mettrons","la","table."],"trap":"metterons","why":"mettre → mettr-.","hint":"nous <b>mettrons</b>."},{"en":"I understood.","tiles":["J'ai","compris."],"trap":"comprendu","why":"Like prendre: pris.","hint":"j'ai <b>compris</b>."}],"spot":[{"words":["Vous","disez","la vérité."],"bad":1,"fix":"dites","hint":"vous <b>dites</b>.","look":"Look at dire with vous."},{"words":["J'ai","comprendu."],"bad":1,"fix":"compris.","hint":"Like prendre: <b>compris</b>.","look":"Look at the participle."},{"words":["Il","a","devenu","riche."],"bad":1,"fix":"est","hint":"Like venir: <b>être</b>.","look":"Which helper?"},{"words":["Ils","tienent","la porte."],"bad":1,"fix":"tiennent","hint":"Double n: <b>tiennent</b>.","look":"Look at tenir with ils."},{"words":["Nous","metterons","la table."],"bad":1,"fix":"mettrons","hint":"Drop the e: <b>mettrons</b>.","look":"Look at the future of mettre."}]},"drill":[["they take (prendre)","ils prennent","prendre: ils <b>prennent</b>."],["you (vous) say (dire)","vous dites","dire: vous <b>dites</b>."],["I became (devenir, passé composé)","je suis devenu(e)","Like venir: <b>être</b> + devenu."],["we will put (mettre)","nous mettrons","mettre → <b>mettr-</b>."],["I understood (comprendre, passé composé)","j'ai compris","Like prendre: <b>compris</b>."],["they hold (tenir)","ils tiennent","Like venir: ils <b>tiennent</b>."]]},"43":{"line":"A pronoun can stand for a whole « my book » or « that one ». <b>Possessive</b>: le mien, la mienne, les miens, les miennes (mine), le tien… (yours), le sien… (his or hers), le nôtre, le vôtre, le leur. <b>Demonstrative</b>: celui, celle, ceux, celles (the one, the ones), never alone: celui-<b>ci</b>, celle-<b>là</b>, celui <b>de</b> Paul, celle <b>que</b> j'aime. Both follow the thing, not the owner.","words":"","steps":[{"tool":"agree","title":"The pronoun follows the thing owned","sub":"Switch the thing: the pronoun changes with it, whoever the owner is.","cols":["un livre","une maison","des livres","des maisons"],"rows":[{"forms":["le mien","la mienne","les miens","les miennes"],"en":"mine"},{"forms":["le tien","la tienne","les tiens","les tiennes"],"en":"yours (tu)"},{"forms":["le sien","la sienne","les siens","les siennes"],"en":"his or hers"},{"forms":["le nôtre","la nôtre","les nôtres","les nôtres"],"en":"ours"},{"forms":["le vôtre","la vôtre","les vôtres","les vôtres"],"en":"yours (vous)"},{"forms":["le leur","la leur","les leurs","les leurs"],"en":"theirs"}]},{"tool":"swap","title":"Replace the noun","sub":"Pick a sentence and tap « Use a pronoun ».","button":["Use a pronoun","Back"],"legend":[["p","the pronoun"],["x","what it replaces"]],"items":[{"label":"C'est ton livre.","en":["It's your book.","It's yours."],"a":[["s","C'est",""],["o","ton livre.","x"]],"b":[["s","C'est",""],["p","le tien.","p"]]},{"label":"Sa voiture est rouge.","en":["His car is red.","His is red."],"a":[["o","Sa voiture","x"],["v","est rouge.",""]],"b":[["p","La sienne","p"],["v","est rouge.",""]],"note":"voiture is feminine: <b>la sienne</b>, for his or for hers."},{"label":"Je préfère ce gâteau-ci.","en":["I prefer this cake.","I prefer this one."],"a":[["s","Je préfère",""],["o","ce gâteau-ci.","x"]],"b":[["s","Je préfère",""],["p","celui-ci.","p"]]},{"label":"la voiture de Paul","en":["Paul's car","Paul's (one)"],"a":[["o","la voiture","x"],["d","de Paul",""]],"b":[["p","celle","p"],["d","de Paul",""]],"note":"celle never stands alone: <b>celle de</b> Paul."},{"label":"Les chaussures que j'aime…","en":["The shoes I like…","The ones I like…"],"a":[["o","Les chaussures","x"],["q","que j'aime…",""]],"b":[["p","Celles","p"],["q","que j'aime…",""]]},{"label":"Je pense à mes amis.","en":["I think of my friends.","I think of mine."],"a":[["s","Je pense",""],["o","à mes amis.","x"]],"b":[["s","Je pense",""],["p","aux miens.","p"]],"note":"à + les → <b>aux</b> miens; de + le → <b>du</b> mien."}]}],"practice":{"choose":[{"q":"Ce n'est pas ton stylo, c'est ___.","en":"It's not your pen, it's mine.","opts":["le mien","la mienne","mon","le mon"],"a":"le mien","why":"stylo is masculine.","hint":"<b>le mien</b>."},{"q":"Ma maison est grande, ___ est petite. (ours)","en":"My house is big, ours is small.","opts":["la nôtre","le nôtre","notre","la notre"],"a":"la nôtre","why":"maison is feminine; ours has an accent.","hint":"<b>la nôtre</b>."},{"q":"Paul a perdu ses clés. Il cherche ___.","en":"Paul lost his keys. He is looking for his.","opts":["les siennes","les siens","la sienne","leurs"],"a":"les siennes","why":"clés is feminine plural.","hint":"<b>les siennes</b>."},{"q":"Tu préfères ce pull-ci ou ___ ?","en":"Do you prefer this jumper or that one?","opts":["celui-là","celle-là","cela","ce-là"],"a":"celui-là","why":"pull is masculine.","hint":"<b>celui-là</b>."},{"q":"___ qui parle est mon frère.","en":"The one who is speaking is my brother.","opts":["Celui","Ce","Celle","Cela"],"a":"Celui","why":"A man, then qui.","hint":"<b>Celui qui</b>…"},{"q":"Je parle ___ (de + le mien).","en":"I'm talking about mine.","opts":["du mien","de le mien","des miens","de mien"],"a":"du mien","why":"de + le…","hint":"<b>du</b> mien."},{"q":"Ces chaussures ? Ce sont ___ de Marie.","en":"These shoes? They're Marie's.","opts":["celles","ceux","celle","les siennes de"],"a":"celles","why":"chaussures is feminine plural.","hint":"<b>celles</b> de Marie."}],"build":[{"en":"No, it's yours. (tu, a book)","tiles":["Non,","c'est","le","tien."],"trap":"ton","why":"A pronoun, not an adjective.","hint":"c'est <b>le tien</b>."},{"en":"Her house is big, ours is small.","tiles":["Sa","maison","est grande,","la nôtre","est petite."],"trap":"notre","why":"ours (a house)…","hint":"<b>la nôtre</b>."},{"en":"this one (a cake)","tiles":["celui-ci"],"trap":"celle-ci","why":"gâteau is masculine.","hint":"<b>celui-ci</b>."},{"en":"the ones I like (shoes)","tiles":["celles","que","j'aime"],"trap":"ceux","why":"chaussures is feminine plural.","hint":"<b>celles</b> que j'aime."},{"en":"Paul's car","tiles":["la","voiture","de","Paul"],"trap":"Paul's","why":"French says « the car of Paul ».","hint":"la voiture <b>de</b> Paul."}],"spot":[{"words":["Ma voiture est bleue,","le sien","est rouge."],"bad":1,"fix":"la sienne","hint":"voiture is feminine: <b>la sienne</b>.","look":"Does it match voiture?"},{"words":["Ce livre","n'est pas","mon."],"bad":2,"fix":"le mien.","hint":"Alone, use the pronoun: <b>le mien</b>.","look":"Is there a noun after it?"},{"words":["Tu préfères","celui","ou celui-là ?"],"bad":1,"fix":"celui-ci","hint":"celui never stands alone: <b>celui-ci</b>.","look":"What does celui need?"},{"words":["Je pense","à les miens."],"bad":1,"fix":"aux miens.","hint":"à + les → <b>aux</b>.","look":"Look at à + les."},{"words":["Nos enfants et","les leur","jouent ensemble."],"bad":1,"fix":"les leurs","hint":"Plural: <b>les leurs</b>.","look":"One child or several?"}]},"drill":[["No, it's yours (tu, masc.)","Non, c'est le tien.","The pronoun follows the thing: <b>le tien</b>."],["Her house is big, ours is small","Sa maison est grande, la nôtre est petite.","maison is feminine: <b>la nôtre</b>."],["this one (masc.)","celui-ci","celui never alone: <b>celui-ci</b>."],["The ones I like (fem. pl.)","celles que j'aime","<b>celles que</b> …"],["Paul's (a car)","celle de Paul","<b>celle de</b> + the owner."],["They are looking for theirs (keys)","Ils cherchent les leurs.","Plural thing, several owners: <b>les leurs</b>."]]},"44":{"line":"Words for people or things not named exactly. Before a noun: <b>chaque</b> (each, always singular), <b>quelques</b> (a few), <b>plusieurs</b> (several), <b>tout / toute / tous / toutes</b> (all, every: tous les jours, toute la nuit), <b>certains</b>, <b>autre</b>, <b>même</b>. On their own: <b>quelqu'un</b>, <b>quelque chose</b>, <b>chacun</b>, <b>tout</b> (everything), <b>tous</b> (all of them, the s is heard). quelqu'un / quelque chose + <b>de</b> + adjective: quelque chose <b>d'</b>intéressant.","words":"","steps":[{"tool":"agree","title":"The four forms of tout","sub":"Switch the noun: tout follows it.","cols":["masc. singular","fem. singular","masc. plural","fem. plural"],"rows":[{"forms":["tout le temps","toute la journée","tous les jours","toutes les semaines"],"en":["all the time","all day","every day","every week"]},{"forms":["tout le monde","toute la ville","tous mes amis","toutes mes amies"],"en":["everyone","the whole town","all my friends","all my (girl)friends"]}]},{"tool":"sort","title":"Before a noun, or on its own?","sub":"Tap the box: does it need a noun after it?","boxes":[{"k":"adj","label":"+ a noun","sub":"chaque jour"},{"k":"pro","label":"on its own","sub":"chacun"}],"cards":[{"t":"chaque","box":"adj","why":"<b>chaque</b> élève: always with a noun."},{"t":"chacun","box":"pro","why":"<b>Chacun</b> a son livre."},{"t":"quelques","box":"adj","why":"<b>quelques</b> amis"},{"t":"quelqu'un","box":"pro","why":"<b>Quelqu'un</b> frappe à la porte."},{"t":"quelque chose","box":"pro","why":"J'ai <b>quelque chose</b> à dire."},{"t":"plusieurs (fois)","box":"adj","why":"<b>plusieurs</b> fois"},{"t":"Tout va bien.","box":"pro","why":"everything: <b>tout</b> on its own."},{"t":"certains (étudiants)","box":"adj","why":"<b>certains</b> étudiants"}]},{"tool":"flip","en":"a","title":"quelque chose de… , quelqu'un de…","sub":"Tap a card: an adjective after them needs de.","cards":[{"a":"something interesting","b":"quelque chose d'intéressant","tag":"de + masc. adjective"},{"a":"someone nice","b":"quelqu'un de gentil","tag":"de + adjective"},{"a":"nothing new","b":"rien de nouveau","tag":"the same with rien"},{"a":"nobody important","b":"personne d'important","tag":"the same with personne"}]}],"practice":{"choose":[{"q":"___ jour, je prends un café.","en":"Every day I have a coffee.","opts":["Chaque","Chacun","Tous","Toute"],"a":"Chaque","why":"Before a singular noun.","hint":"<b>Chaque</b> jour."},{"q":"Je vais à la piscine ___ les jours.","en":"I go to the pool every day.","opts":["tous","tout","toutes","chaque"],"a":"tous","why":"jours is masculine plural.","hint":"<b>tous</b> les jours."},{"q":"J'ai travaillé ___ la nuit.","en":"I worked all night.","opts":["toute","tout","toutes","tous"],"a":"toute","why":"nuit is feminine.","hint":"<b>toute</b> la nuit."},{"q":"___ a son livre.","en":"Each one has his book.","opts":["Chacun","Chaque","Tout","Quelques"],"a":"Chacun","why":"On its own…","hint":"<b>Chacun</b>."},{"q":"J'ai vu quelque chose ___ bizarre.","en":"I saw something strange.","opts":["de","du","que","—"],"a":"de","why":"quelque chose + adjective…","hint":"quelque chose <b>de</b> bizarre."},{"q":"J'ai invité ___ amis.","en":"I invited a few friends.","opts":["quelques","quelque","chaque","quelqu'un"],"a":"quelques","why":"a few, plural.","hint":"<b>quelques</b> amis."},{"q":"Ils sont ___ venus.","en":"They all came.","opts":["tous","tout","toutes","chacun"],"a":"tous","why":"all of them (masculine).","hint":"ils sont <b>tous</b> venus."}],"build":[{"en":"every day","tiles":["tous","les","jours"],"trap":"chaque","why":"every + the plural…","hint":"<b>tous les</b> jours."},{"en":"something interesting","tiles":["quelque chose","d'","intéressant"],"trap":"intéressante","why":"de + the masculine adjective.","hint":"quelque chose <b>d'</b>intéressant."},{"en":"Everyone is here.","tiles":["Tout le monde","est","là."],"trap":"sont","why":"tout le monde is singular.","hint":"tout le monde <b>est</b>."},{"en":"Each one has his book.","tiles":["Chacun","a","son","livre."],"trap":"Chaque","why":"On its own: chacun.","hint":"<b>Chacun</b> a…"},{"en":"I worked all day.","tiles":["J'ai","travaillé","toute","la","journée."],"trap":"tout","why":"journée is feminine.","hint":"<b>toute</b> la journée."}],"spot":[{"words":["Chaque","élèves","a un livre."],"bad":1,"fix":"élève","hint":"chaque is always singular.","look":"Look at the noun after chaque."},{"words":["Tout","les jours","je cours."],"bad":0,"fix":"Tous","hint":"jours is plural: <b>tous</b> les jours.","look":"Does tout match jours?"},{"words":["Chaque","a son livre."],"bad":0,"fix":"Chacun","hint":"On its own: <b>chacun</b>.","look":"Is there a noun after it?","say":"Chacun a son livre."},{"words":["J'ai vu quelque chose","intéressant."],"bad":1,"fix":"d'intéressant.","hint":"quelque chose <b>d'</b>intéressant.","look":"Something is missing before the adjective."},{"words":["Tout le monde","sont","là."],"bad":1,"fix":"est","hint":"tout le monde is singular: <b>est</b>.","look":"Singular or plural?"}]},"drill":[["every day (tout)","tous les jours","jours is plural: <b>tous</b> les jours."],["something interesting","quelque chose d'intéressant","<b>de</b> + adjective: d'intéressant."],["Everyone is here","Tout le monde est là. / Tout le monde est ici.","tout le monde is singular: <b>est</b>."],["Each one has his book (chacun)","Chacun a son livre.","On its own: <b>chacun</b>."],["all night","toute la nuit","nuit is feminine: <b>toute</b>."],["They all came.","Ils sont tous venus.","all of them: <b>tous</b> (the s is heard)."]]},"45":{"line":"Many verbs come with their own little word, <b>à</b>, <b>de</b> or none, and it is often not the English one. Learn them as a chunk: <b>penser à</b>, <b>répondre à</b>, <b>commencer à</b>; <b>parler de</b>, <b>avoir besoin de</b>, <b>essayer de</b>, <b>décider de</b>. And no little word where English has one: <b>attendre</b> le bus (wait for), <b>chercher</b> (look for), <b>écouter</b> (listen to), <b>regarder</b> (look at), <b>payer</b> (pay for).","words":"","steps":[{"tool":"sort","title":"à, de or nothing?","sub":"Tap the box each verb takes.","boxes":[{"k":"a","label":"à","sub":"penser à"},{"k":"de","label":"de","sub":"parler de"},{"k":"0","label":"nothing","sub":"attendre le bus"}],"cards":[{"t":"penser … mes vacances","box":"a","why":"Je pense <b>à</b> mes vacances.","say":"Je pense à mes vacances."},{"t":"avoir besoin … aide","box":"de","why":"J'ai besoin <b>d'</b>aide.","say":"J'ai besoin d'aide."},{"t":"attendre … le bus","box":"0","why":"J'attends le bus (no word).","say":"J'attends le bus."},{"t":"répondre … la question","box":"a","why":"Réponds <b>à</b> la question.","say":"Réponds à la question."},{"t":"essayer … comprendre","box":"de","why":"J'essaie <b>de</b> comprendre.","say":"J'essaie de comprendre."},{"t":"chercher … mes clés","box":"0","why":"Je cherche mes clés (no word).","say":"Je cherche mes clés."},{"t":"commencer … pleuvoir","box":"a","why":"Il commence <b>à</b> pleuvoir.","say":"Il commence à pleuvoir."},{"t":"décider … partir","box":"de","why":"Elle a décidé <b>de</b> partir.","say":"Elle a décidé de partir."},{"t":"écouter … la radio","box":"0","why":"J'écoute la radio (no word).","say":"J'écoute la radio."},{"t":"jouer … la guitare","box":"de","why":"An instrument: jouer <b>de</b> la guitare.","say":"Il joue de la guitare."},{"t":"jouer … tennis","box":"a","why":"A sport: jouer <b>au</b> tennis.","say":"Il joue au tennis."},{"t":"payer … le repas","box":"0","why":"Je paie le repas (no word).","say":"Je paie le repas."}]},{"tool":"swap","title":"Replace it with y or en","sub":"Pick a sentence and tap « Replace it »: à + a thing → y, de + a thing → en.","button":["Replace it","Back"],"legend":[["p","y / en"],["x","what it replaces"]],"items":[{"label":"Je pense à mon voyage.","en":["I'm thinking about my trip.","I'm thinking about it."],"a":[["s","Je",""],["v","pense",""],["o","à mon voyage.","x"]],"b":[["s","J'",""],["p","y","p"],["v","pense.",""]]},{"label":"Nous parlons de politique.","en":["We talk about politics.","We talk about it."],"a":[["s","Nous",""],["v","parlons",""],["o","de politique.","x"]],"b":[["s","Nous",""],["p","en","p"],["v","parlons.",""]]},{"label":"J'ai besoin de ce livre.","en":["I need this book.","I need it."],"a":[["s","J'ai",""],["v","besoin",""],["o","de ce livre.","x"]],"b":[["s","J'",""],["p","en","p"],["v","ai besoin.",""]]},{"label":"Je pense à Marie.","en":["I'm thinking of Marie.","I'm thinking of her."],"a":[["s","Je",""],["v","pense",""],["o","à Marie.","x"]],"b":[["s","Je",""],["v","pense",""],["p","à elle.","p"]],"note":"A person after penser à: <b>à elle</b>, not y."}]}],"practice":{"choose":[{"q":"Je pense ___ mes vacances.","en":"I'm thinking about my holiday.","opts":["à","de","sur","—"],"a":"à","why":"penser…","hint":"penser <b>à</b>."},{"q":"J'ai besoin ___ aide.","en":"I need help.","opts":["d'","à","de l'","—"],"a":"d'","why":"avoir besoin…","hint":"avoir besoin <b>de</b>."},{"q":"J'attends ___ bus.","en":"I'm waiting for the bus.","opts":["le","pour le","au","du"],"a":"le","why":"attendre takes no little word.","hint":"j'attends <b>le</b> bus."},{"q":"Il a décidé ___ partir.","en":"He decided to leave.","opts":["de","à","pour","—"],"a":"de","why":"décider…","hint":"décider <b>de</b>."},{"q":"Elle joue ___ piano.","en":"She plays the piano.","opts":["du","au","le","de le"],"a":"du","why":"An instrument…","hint":"jouer <b>de</b> + le → <b>du</b> piano."},{"q":"Je cherche ___ clés.","en":"I'm looking for my keys.","opts":["mes","pour mes","à mes","de mes"],"a":"mes","why":"chercher takes no little word.","hint":"je cherche <b>mes</b> clés."},{"q":"J'apprends ___ conduire.","en":"I'm learning to drive.","opts":["à","de","—","pour"],"a":"à","why":"apprendre…","hint":"apprendre <b>à</b>."}],"build":[{"en":"I'm thinking about my trip.","tiles":["Je","pense","à","mon","voyage."],"trap":"de","why":"penser…","hint":"penser <b>à</b>."},{"en":"I need help.","tiles":["J'ai","besoin","d'","aide."],"trap":"à","why":"avoir besoin…","hint":"besoin <b>d'</b>aide."},{"en":"I'm waiting for the bus.","tiles":["J'attends","le","bus."],"trap":"pour","why":"attendre: no little word.","hint":"j'attends <b>le</b> bus."},{"en":"He decided to leave.","tiles":["Il","a","décidé","de","partir."],"trap":"à","why":"décider…","hint":"décidé <b>de</b> partir."},{"en":"I'm listening to music.","tiles":["J'écoute","de la","musique."],"trap":"à","why":"écouter: no little word.","hint":"j'écoute de la musique."}],"spot":[{"words":["J'attends","pour","le bus."],"bad":1,"fix":"—","hint":"attendre takes no little word: <b>J'attends le bus.</b>","look":"Is a little word needed?","say":"J'attends le bus."},{"words":["Je pense","de","mes vacances."],"bad":1,"fix":"à","hint":"penser <b>à</b>.","look":"Which little word with penser?"},{"words":["Il joue","au","piano."],"bad":1,"fix":"du","hint":"An instrument: jouer <b>du</b> piano.","look":"A sport or an instrument?"},{"words":["Elle a décidé","à","partir."],"bad":1,"fix":"de","hint":"décider <b>de</b>.","look":"Which little word with décider?"},{"words":["Marie ?","J'y pense","souvent."],"bad":1,"fix":"Je pense à elle","hint":"A person is not y: <b>Je pense souvent à elle.</b>","look":"Is Marie a thing?","say":"Marie ? Je pense souvent à elle."}]},"drill":[["I'm thinking about my trip","Je pense à mon voyage.","<b>penser à</b>."],["I need help","J'ai besoin d'aide.","<b>avoir besoin de</b>."],["I'm waiting for the bus","J'attends le bus.","<b>attendre</b>: no little word."],["He decided to leave","Il a décidé de partir.","<b>décider de</b> + the verb."],["She plays the guitar.","Elle joue de la guitare.","An instrument: <b>jouer de</b>."],["I'm looking for my keys.","Je cherche mes clés.","<b>chercher</b>: no little word."]]},"37":{"line":"Two pronouns before one verb follow a fixed order: <b>me, te, se, nous, vous</b> → <b>le, la, les</b> → <b>lui, leur</b> → <b>y</b> → <b>en</b>. Il <b>me le</b> donne. Je <b>le lui</b> donne. Il <b>y en</b> a trois. In a yes-order they go after the verb, the « it » first: Donne-<b>le-moi</b> !","words":"","steps":[{"tool":"swap","title":"Two nouns become two pronouns","sub":"Pick a sentence and tap « Use pronouns »: watch the order.","button":["Use pronouns","Back"],"legend":[["p","first pronoun"],["x","second pronoun"]],"items":[{"label":"Je donne le livre à Paul.","en":["I give the book to Paul.","I give it to him."],"a":[["s","Je",""],["v","donne",""],["o","le livre","p"],["i","à Paul.","x"]],"b":[["s","Je",""],["o","le","p"],["i","lui","x"],["v","donne.",""]],"note":"le before lui."},{"label":"Il me donne la clé.","en":["He gives me the key.","He gives it to me."],"a":[["s","Il",""],["i","me","p"],["v","donne",""],["o","la clé.","x"]],"b":[["s","Il",""],["i","me","p"],["o","la","x"],["v","donne.",""]],"note":"me before la."},{"label":"J'envoie les photos à mes parents.","en":["I send the photos to my parents.","I send them to them."],"a":[["s","J'",""],["v","envoie",""],["o","les photos","p"],["i","à mes parents.","x"]],"b":[["s","Je",""],["o","les","p"],["i","leur","x"],["v","envoie.",""]]},{"label":"Je parle de mon projet à Marie.","en":["I talk to Marie about my project.","I talk to her about it."],"a":[["s","Je",""],["v","parle",""],["o","de mon projet","x"],["i","à Marie.","p"]],"b":[["s","Je",""],["i","lui","p"],["o","en","x"],["v","parle.",""]],"note":"lui before en."},{"label":"Il y a trois chambres.","en":["There are three bedrooms.","There are three (of them)."],"a":[["s","Il",""],["y","y","p"],["v","a",""],["n","trois",""],["o","chambres.","x"]],"b":[["s","Il",""],["y","y","p"],["o","en","x"],["v","a",""],["n","trois.",""]],"note":"y before en."},{"label":"Donne le sel à moi ! → an order","en":["Give the salt to me!","Give it to me!"],"a":[["v","Donne",""],["o","le sel","p"],["i","à moi !","x"]],"b":[["v","Donne-",""],["o","le-","p"],["i","moi !","x"]],"note":"In a yes-order: verb, then <b>le</b>, then <b>moi</b>."}]},{"tool":"sort","title":"Which goes first?","sub":"Tap the pronoun that comes first in each pair.","boxes":[{"k":"1","label":"the first one","sub":"in the list"},{"k":"2","label":"the second one","sub":"in the list"}],"cards":[{"t":"me / le: which is first?","box":"1","why":"<b>me</b> le: Il me le donne.","say":"Il me le donne."},{"t":"lui / le: is lui first?","box":"2","why":"No: <b>le</b> lui. Je le lui donne.","say":"Je le lui donne."},{"t":"en / y: is en first?","box":"2","why":"No: <b>y</b> en. Il y en a.","say":"Il y en a."},{"t":"nous / les: is nous first?","box":"1","why":"<b>nous</b> les: Il nous les montre.","say":"Il nous les montre."},{"t":"leur / en: is leur first?","box":"1","why":"<b>leur</b> en: Je leur en parle.","say":"Je leur en parle."},{"t":"la / te: is la first?","box":"2","why":"No: <b>te</b> la. Je te la prête.","say":"Je te la prête."}]}],"practice":{"choose":[{"q":"Le livre ? Je ___ donne.","en":"The book? I give it to him.","opts":["le lui","lui le","le leur","lui"],"a":"le lui","why":"le / la / les before lui.","hint":"je <b>le lui</b> donne."},{"q":"La clé ? Il ___ donne.","en":"The key? He gives it to me.","opts":["me la","la me","moi la","la moi"],"a":"me la","why":"me before la.","hint":"il <b>me la</b> donne."},{"q":"Des chambres ? Il ___ a trois.","en":"Bedrooms? There are three.","opts":["y en","en y","y","en"],"a":"y en","why":"y before en.","hint":"il <b>y en</b> a trois."},{"q":"Les photos ? Je vais ___ envoyer.","en":"The photos? I'm going to send them to you.","opts":["te les","les te","te","les toi"],"a":"te les","why":"Before the verb they belong to.","hint":"je vais <b>te les</b> envoyer."},{"q":"Donne-___ !","en":"Give it to me!","opts":["le-moi","moi-le","me-le","le-me"],"a":"le-moi","why":"In a yes-order: « it » first.","hint":"Donne-<b>le-moi</b> !"},{"q":"Ne ___ dis pas !","en":"Don't tell me (it)!","opts":["me le","le moi","le me","moi le"],"a":"me le","why":"In a no, the normal order comes back.","hint":"Ne <b>me le</b> dis pas !"},{"q":"La lettre ? Je ___ ai envoyée.","en":"The letter? I sent it to them.","opts":["la leur","leur la","les leur","la lui"],"a":"la leur","why":"la before leur.","hint":"je <b>la leur</b> ai envoyée."}],"build":[{"en":"I give it to him.","tiles":["Je","le","lui","donne."],"trap":"leur","why":"le before lui.","hint":"je <b>le lui</b> donne."},{"en":"I'm going to send them to you.","tiles":["Je","vais","te","les","envoyer."],"trap":"toi","why":"te before les, before envoyer.","hint":"vais <b>te les</b> envoyer."},{"en":"Don't tell me (it)!","tiles":["Ne","me","le","dis","pas !"],"trap":"moi","why":"In a no: me le.","hint":"Ne <b>me le</b> dis pas !"},{"en":"There are three of them.","tiles":["Il","y","en","a","trois."],"trap":"les","why":"y before en.","hint":"il <b>y en</b> a trois."},{"en":"Give it to me!","tiles":["Donne-le-moi","!"],"trap":"Donne-moi-le","why":"Yes-order: le, then moi.","hint":"Donne-<b>le-moi</b> !"}],"spot":[{"words":["Je","lui le","donne."],"bad":1,"fix":"le lui","hint":"le before lui: <b>le lui</b>.","look":"Look at the order."},{"words":["Il","en y","a trois."],"bad":1,"fix":"y en","hint":"y before en: <b>y en</b>.","look":"Look at the order."},{"words":["Il","la me","donne."],"bad":1,"fix":"me la","hint":"me before la: <b>me la</b>.","look":"Look at the order."},{"words":["Donne-moi-le","!"],"bad":0,"fix":"Donne-le-moi","hint":"Yes-order: <b>le</b> before moi.","look":"Which comes first in an order?"},{"words":["Je vais","les te","envoyer."],"bad":1,"fix":"te les","hint":"te before les.","look":"Look at the order."}]},"drill":[["I give it to him","Je le lui donne.","le / la / les before lui: <b>le lui</b>."],["I'm going to send them to you","Je vais te les envoyer.","te before les, before the infinitive."],["Don't tell it to me","Ne me le dis pas.","In a no, the normal order: <b>me le</b>."],["There are three of them","Il y en a trois.","y before en: <b>y en</b>."],["Give it to me! (tu)","Donne-le-moi !","Yes-order: <b>le</b> then <b>moi</b>."],["I talk to her about it.","Je lui en parle.","lui before en: <b>lui en</b>."]]},"38":{"line":"More glue words. <b>dont</b> replaces <b>de</b> + a noun: le film <b>dont</b> je parle (parler de), l'homme <b>dont</b> la fille est médecin (whose). After another preposition: <b>avec qui</b> (a person), <b>dans lequel / sur laquelle</b> (a thing). With no noun before: <b>ce qui</b> (subject), <b>ce que</b> (object), <b>ce dont</b> (with de) = what.","words":"","steps":[{"tool":"swap","title":"Glue with dont, lequel, ce que","sub":"Pick a pair and tap « Glue them ».","button":["Glue them","Two sentences again"],"legend":[["p","the glue word"],["x","what it replaces"]],"items":[{"label":"Le film est super. Je parle de ce film.","en":["The film is great. I'm talking about this film.","The film I'm talking about is great."],"a":[["a","Le film est super.",""],["b","Je parle",""],["x","de ce film.","x"]],"b":[["a0","Le film",""],["p","dont","p"],["b","je parle",""],["a1","est super.",""]],"note":"parler <b>de</b> → <b>dont</b>."},{"label":"C'est l'homme. La fille de cet homme est médecin.","en":["That's the man. This man's daughter is a doctor.","That's the man whose daughter is a doctor."],"a":[["a","C'est l'homme.",""],["b0","La fille",""],["x","de cet homme","x"],["b1","est médecin.",""]],"b":[["a","C'est l'homme",""],["p","dont","p"],["b0","la fille",""],["b1","est médecin.",""]],"note":"whose = <b>dont</b> + the noun with its article."},{"label":"Voici le sac. J'ai mis mes clés dans ce sac.","en":["Here is the bag. I put my keys in this bag.","Here is the bag I put my keys in."],"a":[["a","Voici le sac.",""],["b","J'ai mis mes clés",""],["x","dans ce sac.","x"]],"b":[["a","Voici le sac",""],["p","dans lequel","p"],["b","j'ai mis mes clés.",""]],"note":"A preposition + a thing: <b>lequel</b> (le sac, masculine)."},{"label":"C'est mon collègue. Je travaille avec lui.","en":["That's my colleague. I work with him.","That's the colleague I work with."],"a":[["a","C'est mon collègue.",""],["b","Je travaille",""],["x","avec lui.","x"]],"b":[["a","C'est le collègue",""],["p","avec qui","p"],["b","je travaille.",""]],"note":"A preposition + a person: <b>qui</b>."},{"label":"Tu veux quelque chose. Dis-le-moi.","en":["You want something. Tell me.","Tell me what you want."],"a":[["b","Tu veux",""],["x","quelque chose.","x"],["a","Dis-le-moi.",""]],"b":[["a","Dis-moi",""],["p","ce que","p"],["b","tu veux.",""]],"note":"what (the object): <b>ce que</b>."}]},{"tool":"sort","title":"ce qui, ce que or ce dont?","sub":"Look at what follows. Tap the box.","boxes":[{"k":"qui","label":"ce qui","sub":"+ a verb"},{"k":"que","label":"ce que","sub":"+ a subject and a verb"},{"k":"dont","label":"ce dont","sub":"a verb with de"}],"cards":[{"t":"Je sais … se passe.","box":"qui","why":"A verb follows: <b>ce qui</b> se passe.","say":"Je sais ce qui se passe."},{"t":"Dis-moi … tu veux.","box":"que","why":"tu veux follows: <b>ce que</b>.","say":"Dis-moi ce que tu veux."},{"t":"Voilà … j'ai besoin.","box":"dont","why":"avoir besoin <b>de</b>: <b>ce dont</b>.","say":"Voilà ce dont j'ai besoin."},{"t":"… me plaît, c'est la mer.","box":"qui","why":"A verb follows: <b>Ce qui</b> me plaît.","say":"Ce qui me plaît, c'est la mer."},{"t":"Je ne comprends pas … il dit.","box":"que","why":"il dit follows: <b>ce que</b>.","say":"Je ne comprends pas ce qu'il dit."},{"t":"… il parle est important.","box":"dont","why":"parler <b>de</b>: <b>Ce dont</b>.","say":"Ce dont il parle est important."}]}],"practice":{"choose":[{"q":"Le film ___ je parle est super.","en":"The film I'm talking about is great.","opts":["dont","que","qui","où"],"a":"dont","why":"parler de…","hint":"de + noun → <b>dont</b>."},{"q":"C'est la femme ___ le fils est médecin.","en":"She's the woman whose son is a doctor.","opts":["dont","que","qui","de qui"],"a":"dont","why":"whose…","hint":"<b>dont</b> le fils."},{"q":"Voici la maison dans ___ j'ai grandi.","en":"Here is the house I grew up in.","opts":["laquelle","lequel","qui","que"],"a":"laquelle","why":"A preposition + a feminine thing.","hint":"dans <b>laquelle</b>."},{"q":"La personne avec ___ je travaille.","en":"The person I work with.","opts":["qui","laquelle","que","dont"],"a":"qui","why":"A preposition + a person.","hint":"avec <b>qui</b>."},{"q":"Je ne comprends pas ___ tu dis.","en":"I don't understand what you're saying.","opts":["ce que","ce qui","que","quoi"],"a":"ce que","why":"tu dis follows: the object.","hint":"<b>ce que</b>."},{"q":"___ se passe m'intéresse.","en":"What is happening interests me.","opts":["Ce qui","Ce que","Qui","Que"],"a":"Ce qui","why":"A verb follows: the subject.","hint":"<b>Ce qui</b> se passe."},{"q":"C'est ___ j'ai besoin.","en":"That's what I need.","opts":["ce dont","ce que","dont","ce qui"],"a":"ce dont","why":"avoir besoin de, and no noun before.","hint":"<b>ce dont</b>."}],"build":[{"en":"The film I'm talking about","tiles":["Le","film","dont","je","parle"],"trap":"que","why":"parler de…","hint":"<b>dont</b> je parle."},{"en":"I don't know what you want.","tiles":["Je","ne sais pas","ce que","tu","veux."],"trap":"ce qui","why":"tu veux follows.","hint":"<b>ce que</b> tu veux."},{"en":"The table I put my book on","tiles":["La","table","sur","laquelle","j'ai posé","mon livre"],"trap":"lequel","why":"table is feminine.","hint":"sur <b>laquelle</b>."},{"en":"What is happening interests me.","tiles":["Ce qui","se passe","m'intéresse."],"trap":"Ce que","why":"A verb follows.","hint":"<b>Ce qui</b> se passe."},{"en":"That's the man whose daughter is a doctor.","tiles":["C'est","l'homme","dont","la fille","est médecin."],"trap":"de qui","why":"whose…","hint":"<b>dont</b> la fille."}],"spot":[{"words":["Le film","que","je parle","est super."],"bad":1,"fix":"dont","hint":"parler de → <b>dont</b>.","look":"parler takes which little word?"},{"words":["Dis-moi","ce qui","tu veux."],"bad":1,"fix":"ce que","hint":"tu veux follows: <b>ce que</b>.","look":"What follows the glue word?"},{"words":["Le sac","dans qui","j'ai mis mes clés"],"bad":1,"fix":"dans lequel","hint":"A thing: <b>lequel</b>.","look":"Is a bag a person?"},{"words":["L'homme","dont","sa fille","est médecin"],"bad":2,"fix":"la fille","hint":"After dont: <b>la</b> fille, not sa.","look":"Look at the word after dont."},{"words":["C'est","ce que","j'ai besoin."],"bad":1,"fix":"ce dont","hint":"avoir besoin de: <b>ce dont</b>.","look":"avoir besoin takes which little word?"}]},"drill":[["The film I'm talking about","Le film dont je parle","parler <b>de</b> → <b>dont</b>."],["I don't know what you want","Je ne sais pas ce que tu veux. / Je ne sais pas ce que vous voulez.","The object: <b>ce que</b>."],["The table on which I put my book","La table sur laquelle j'ai posé mon livre","A preposition + a feminine thing: <b>laquelle</b>."],["What is happening interests me","Ce qui se passe m'intéresse.","The subject: <b>ce qui</b>."],["That's what I need.","C'est ce dont j'ai besoin. / Voilà ce dont j'ai besoin.","avoir besoin <b>de</b>: <b>ce dont</b>."],["the person I work with","la personne avec qui je travaille","A preposition + a person: <b>qui</b>."]]},"36":{"line":"When does the past participle change? <b>With être</b>: it agrees with the subject (elle est allé<b>e</b>). <b>With avoir</b>: only when the direct object comes <b>before</b> the verb (les fleurs ? je les ai acheté<b>es</b>; la robe que j'ai acheté<b>e</b>), never when it comes after (j'ai acheté une robe). <b>Reflexives</b> agree with se when it is the direct object (elle s'est levé<b>e</b>), not when another object follows (elle s'est lavé les mains).","words":"","steps":[{"tool":"swap","title":"Move the object in front","sub":"Pick a sentence and tap « Move it »: when the object jumps before avoir, the participle agrees.","button":["Move it","Back"],"legend":[["x","the object"],["p","the ending that appears"]],"items":[{"label":"J'ai acheté les fleurs.","en":["I bought the flowers.","I bought them."],"a":[["s","J'ai",""],["v","acheté",""],["o","les fleurs.","x"]],"b":[["s","Je",""],["o","les","x"],["a","ai",""],["v","achetées.","p"]],"note":"les fleurs (fem. plural) is now before: achet<b>ées</b>."},{"label":"J'ai acheté une robe.","en":["I bought a dress.","the dress that I bought"],"a":[["s","J'ai",""],["v","acheté",""],["o","une robe.","x"]],"b":[["o","la robe","x"],["q","que",""],["s","j'ai",""],["v","achetée","p"]],"note":"que stands for la robe, before the verb: achet<b>ée</b>."},{"label":"Il a vu Marie et Anne.","en":["He saw Marie and Anne.","He saw them."],"a":[["s","Il a",""],["v","vu",""],["o","Marie et Anne.","x"]],"b":[["s","Il",""],["o","les","x"],["a","a",""],["v","vues.","p"]]},{"label":"Elle a mis la table.","en":["She set the table.","She set it."],"a":[["s","Elle a",""],["v","mis",""],["o","la table.","x"]],"b":[["s","Elle",""],["o","l'","x"],["a","a",""],["v","mise.","p"]],"note":"Here you can <b>hear</b> it: mis → mise."},{"label":"Elle a parlé à ses amies.","en":["She spoke to her friends.","She spoke to them."],"a":[["s","Elle a",""],["v","parlé",""],["o","à ses amies.","x"]],"b":[["s","Elle",""],["o","leur","x"],["a","a",""],["v","parlé.",""]],"note":"leur is an indirect object (à): <b>no</b> agreement."}]},{"tool":"sort","title":"Does it agree?","sub":"Tap the box for each participle.","boxes":[{"k":"y","label":"it agrees","sub":"add -e, -s, -es"},{"k":"n","label":"no change","sub":""}],"cards":[{"t":"Marie est (partir)…","box":"y","why":"être: <b>partie</b>.","say":"Marie est partie."},{"t":"J'ai (acheter) une robe.","box":"n","why":"Object after: <b>acheté</b>.","say":"J'ai acheté une robe."},{"t":"Les clés ? Je les ai (perdre).","box":"y","why":"les before: <b>perdues</b>.","say":"Les clés ? Je les ai perdues."},{"t":"Elles ont (parler).","box":"n","why":"No direct object: <b>parlé</b>.","say":"Elles ont parlé."},{"t":"Elle s'est (lever).","box":"y","why":"se is the object: <b>levée</b>.","say":"Elle s'est levée."},{"t":"Elle s'est (laver) les mains.","box":"n","why":"les mains is the object, after: <b>lavé</b>.","say":"Elle s'est lavé les mains."},{"t":"Quelle robe as-tu (choisir) ?","box":"y","why":"quelle robe comes before: <b>choisie</b>.","say":"Quelle robe as-tu choisie ?"},{"t":"Elles se sont (téléphoner).","box":"n","why":"téléphoner à: se is indirect, <b>téléphoné</b>.","say":"Elles se sont téléphoné."}]}],"practice":{"choose":[{"q":"Marie est ___ hier.","en":"Marie left yesterday.","opts":["partie","parti","parties","partis"],"a":"partie","why":"être: agree with Marie.","hint":"<b>partie</b>."},{"q":"Les fleurs ? Je les ai ___.","en":"The flowers? I bought them.","opts":["achetées","acheté","achetés","achetée"],"a":"achetées","why":"les (fleurs, fem. pl.) is before.","hint":"<b>achetées</b>."},{"q":"J'ai ___ une robe.","en":"I bought a dress.","opts":["acheté","achetée","achetés","achetées"],"a":"acheté","why":"The object comes after.","hint":"<b>acheté</b>."},{"q":"Elle s'est ___ tôt.","en":"She got up early.","opts":["levée","levé","levés","lever"],"a":"levée","why":"se is the direct object.","hint":"<b>levée</b>."},{"q":"Elle s'est ___ les mains.","en":"She washed her hands.","opts":["lavé","lavée","lavées","lavés"],"a":"lavé","why":"les mains is the object, after.","hint":"<b>lavé</b>."},{"q":"La lettre que tu as ___ est belle.","en":"The letter you wrote is beautiful.","opts":["écrite","écrit","écrits","écrites"],"a":"écrite","why":"que = la lettre, before.","hint":"<b>écrite</b> (you can hear the t)."},{"q":"Elles leur ont ___.","en":"They spoke to them.","opts":["parlé","parlées","parlés","parlée"],"a":"parlé","why":"leur is indirect.","hint":"<b>parlé</b>: no agreement."}],"build":[{"en":"The flowers? I bought them.","tiles":["Les fleurs ?","Je","les","ai","achetées."],"trap":"acheté.","why":"les is before the verb.","hint":"je les ai <b>achetées</b>."},{"en":"the car we rented","tiles":["la","voiture","que","nous avons","louée"],"trap":"loué","why":"que is before the verb.","hint":"que nous avons <b>louée</b>."},{"en":"She got up early.","tiles":["Elle","s'est","levée","tôt."],"trap":"levé","why":"se is the object.","hint":"s'est <b>levée</b>."},{"en":"She washed her hands.","tiles":["Elle","s'est","lavé","les mains."],"trap":"lavée","why":"The object comes after.","hint":"s'est <b>lavé</b> les mains."},{"en":"I saw them. (the girls)","tiles":["Je","les","ai","vues."],"trap":"vu.","why":"les (fem. pl.) before.","hint":"je les ai <b>vues</b>."}],"spot":[{"words":["Les clés ?","Je les ai","perdu."],"bad":2,"fix":"perdues.","hint":"les before: <b>perdues</b>.","look":"Where is the object?"},{"words":["J'ai","achetée","une robe."],"bad":1,"fix":"acheté","hint":"Object after: <b>acheté</b>.","look":"Where is the object?"},{"words":["Marie","est","parti."],"bad":2,"fix":"partie.","hint":"être: <b>partie</b>.","look":"Does it agree with Marie?"},{"words":["Elle","s'est","lavée","les mains."],"bad":2,"fix":"lavé","hint":"les mains comes after: <b>lavé</b>.","look":"What is the object?"},{"words":["Elles se sont","téléphonées."],"bad":1,"fix":"téléphoné.","hint":"téléphoner à: <b>téléphoné</b>.","look":"Is se a direct object here?"}]},"drill":[["Marie est ___ (partir)","partie","être: agrees with Marie, <b>partie</b>."],["Les fleurs ? Je les ai ___ (acheter)","achetées","les is before the verb: <b>achetées</b>."],["J'ai ___ (acheter) une robe","acheté","The object comes after: <b>acheté</b>."],["Elle s'est ___ (lever)","levée","se is the direct object: <b>levée</b>."],["La lettre que tu as ___ (écrire)","écrite","que (la lettre) is before: <b>écrite</b>."],["Elle s'est ___ (laver) les mains","lavé","les mains is the object, after: <b>lavé</b>."]]},"32":{"line":"The <b>plus-que-parfait</b> is the past before the past: « had done ». The <b>imparfait</b> of avoir or être + the past participle: j'<b>avais</b> fini, elle <b>était</b> partie. Same helper and agreement rules as the passé composé. Quand je suis arrivé, le train <b>était</b> déjà <b>parti</b>.","words":"","steps":[{"tool":"line","title":"Two moments in the past","sub":"Tap a point: the plus-que-parfait comes first.","now":"","marks":[{"at":-0.85,"label":"first","fr":"Le train était parti.","html":"Le train <span class=\"gt-end\">était parti</span>.","en":"The train had left.","note":"The earlier past: <b>plus-que-parfait</b>."},{"at":-0.35,"label":"then","fr":"Je suis arrivé.","html":"Je <span class=\"gt-end\">suis arrivé</span>.","en":"I arrived.","note":"The later past: <b>passé composé</b>."},{"at":0.15,"label":"together","fr":"Quand je suis arrivé, le train était déjà parti.","html":"Quand je <span class=\"gt-end\">suis arrivé</span>, le train <span class=\"gt-end\">était</span> déjà <span class=\"gt-end\">parti</span>.","en":"When I arrived, the train had already left."},{"at":0.65,"label":"why","fr":"Elle était fatiguée parce qu'elle n'avait pas dormi.","html":"Elle était fatiguée parce qu'elle <span class=\"gt-end\">n'avait pas dormi</span>.","en":"She was tired because she hadn't slept.","note":"The cause, earlier still: <b>plus-que-parfait</b>."}]},{"tool":"conj","title":"avais + participle, étais + participle","sub":"Pick a verb, then tap a person.","neg":true,"verbs":[{"inf":"finir","en":"had finished","forms":["avais fini","avais fini","avait fini","avions fini","aviez fini","avaient fini"],"tail":"","pasAt":1},{"inf":"partir","en":"had left","forms":["étais parti(e)","étais parti(e)","était parti(e)","étions parti(e)s","étiez parti(e)(s)","étaient parti(e)s"],"tail":"","pasAt":1},{"inf":"se lever","en":"had got up","forms":["m'étais levé(e)","t'étais levé(e)","s'était levé(e)","nous étions levé(e)s","vous étiez levé(e)(s)","s'étaient levé(e)s"],"tail":"tôt","pasAt":[1,1,1,2,2,1]}]},{"tool":"flip","title":"Passé composé → plus-que-parfait","sub":"Tap a card: only the helper changes.","cards":[{"a":"j'ai mangé","b":"j'avais mangé","tag":"ai → avais"},{"a":"elle est partie","b":"elle était partie","tag":"est → était"},{"a":"nous avons vu","b":"nous avions vu","tag":"avons → avions"},{"a":"ils se sont trompés","b":"ils s'étaient trompés","tag":"sont → étaient"},{"a":"je n'ai pas dormi","b":"je n'avais pas dormi","tag":"the no wraps the helper"}]}],"practice":{"choose":[{"q":"J'___ fini.","en":"I had finished.","opts":["avais","ai","étais","aurais"],"a":"avais","why":"avoir in the imparfait.","hint":"j'<b>avais</b> fini."},{"q":"Elle ___ partie.","en":"She had left.","opts":["était","avait","est","a"],"a":"était","why":"partir takes être.","hint":"elle <b>était</b> partie."},{"q":"Quand je suis arrivé, il ___ déjà mangé.","en":"When I arrived, he had already eaten.","opts":["avait","a","était","aura"],"a":"avait","why":"The earlier action.","hint":"il <b>avait</b> déjà mangé."},{"q":"Nous ne l'___ jamais vu.","en":"We had never seen it.","opts":["avions","avons","étions","avaient"],"a":"avions","why":"avoir with nous.","hint":"nous ne l'<b>avions</b> jamais vu."},{"q":"Elle m'a dit qu'elle s'était ___.","en":"She told me she had made a mistake.","opts":["trompée","trompé","tromper","trompait"],"a":"trompée","why":"A « se » verb agrees.","hint":"s'était <b>trompée</b>."},{"q":"Ils ___ arrivés avant nous.","en":"They had arrived before us.","opts":["étaient","avaient","sont","étions"],"a":"étaient","why":"arriver takes être.","hint":"ils <b>étaient</b> arrivés."}],"build":[{"en":"I had finished.","tiles":["J'","avais","fini."],"trap":"ai","why":"avoir in the imparfait.","hint":"j'<b>avais</b> fini."},{"en":"She had left.","tiles":["Elle","était","partie."],"trap":"avait","why":"partir takes être.","hint":"elle <b>était partie</b>."},{"en":"We had never seen it.","tiles":["Nous","ne","l'avions","jamais","vu."],"trap":"avons","why":"The no wraps the helper.","hint":"ne l'<b>avions</b> jamais vu."},{"en":"He said he had finished.","tiles":["Il","a dit","qu'il","avait","fini."],"trap":"a","why":"Earlier than « he said ».","hint":"qu'il <b>avait</b> fini."},{"en":"I had forgotten my wallet.","tiles":["J'","avais","oublié","mon portefeuille."],"trap":"étais","why":"oublier takes avoir.","hint":"j'<b>avais</b> oublié."}],"spot":[{"words":["Elle","avait","partie."],"bad":1,"fix":"était","hint":"partir takes <b>être</b>.","look":"Which helper does partir take?"},{"words":["Quand je suis arrivé,","le train","est parti."],"bad":2,"fix":"était déjà parti.","hint":"The earlier action: <b>était parti</b>.","look":"Which happened first?"},{"words":["J'","ai eu","fini."],"bad":1,"fix":"avais","hint":"« had »: <b>avais</b>.","look":"Look at the helper.","say":"J'avais fini."},{"words":["Ils","étaient","arrivé","avant nous."],"bad":2,"fix":"arrivés","hint":"être: it agrees, <b>arrivés</b>.","look":"Does the participle match ils?"},{"words":["Nous","ne","avions","pas mangé."],"bad":1,"fix":"n'","hint":"ne before a vowel: <b>n'avions</b>.","look":"Look before avions.","say":"Nous n'avions pas mangé."}]},"drill":[["I had finished","J'avais fini.","avoir in the imparfait: <b>avais</b> + fini."],["She had left (partir)","Elle était partie.","être in the imparfait: <b>était</b> + partie."],["We had never seen it","Nous ne l'avions jamais vu.","The no wraps the helper: <b>ne … avions jamais</b>."],["When I arrived, he had already eaten","Quand je suis arrivé(e), il avait déjà mangé.","The earlier action: <b>avait mangé</b>."],["They had arrived before us.","Ils étaient arrivés avant nous.","être: <b>étaient arrivés</b>."],["He said he had finished.","Il a dit qu'il avait fini.","Earlier than « he said »: <b>avait fini</b>."]]},"42":{"line":"The <b>futur antérieur</b> is « will have done »: finished before another future moment. The <b>future</b> of avoir or être + the past participle: j'<b>aurai</b> fini, elle <b>sera</b> partie. After <b>quand, dès que, après que</b> about the future, French uses it where English uses the present: Quand j'<b>aurai fini</b>, je t'appellerai.","words":"","steps":[{"tool":"line","title":"Two moments in the future","sub":"Tap a point: the futur antérieur is done first.","now":"","marks":[{"at":0.1,"label":"now","fr":"Je travaille.","en":"I'm working.","note":"Now."},{"at":0.45,"label":"first: done","fr":"J'aurai fini.","html":"J'<span class=\"gt-end\">aurai fini</span>.","en":"I will have finished.","note":"Finished before the next thing: <b>futur antérieur</b>."},{"at":0.85,"label":"then","fr":"Je t'appellerai.","html":"Je <span class=\"gt-end\">t'appellerai</span>.","en":"I will call you.","note":"The later future: <b>futur simple</b>."},{"at":-0.6,"label":"together","fr":"Quand j'aurai fini, je t'appellerai.","html":"Quand j'<span class=\"gt-end\">aurai fini</span>, je <span class=\"gt-end\">t'appellerai</span>.","en":"When I've finished, I'll call you."}]},{"tool":"conj","title":"aurai + participle, serai + participle","sub":"Pick a verb, then tap a person.","neg":true,"verbs":[{"inf":"finir","en":"will have finished","forms":["aurai fini","auras fini","aura fini","aurons fini","aurez fini","auront fini"],"tail":"","pasAt":1},{"inf":"partir","en":"will have left","forms":["serai parti(e)","seras parti(e)","sera parti(e)","serons parti(e)s","serez parti(e)(s)","seront parti(e)s"],"tail":"","pasAt":1}]},{"tool":"swap","title":"After quand: a future, not a present","sub":"Pick a sentence and tap « In French ».","button":["In French","English way"],"legend":[["x","English uses a present"],["p","French uses a future"]],"items":[{"label":"When I've finished, I'll call you.","en":["English: « when I have finished » (a present)","French: a future (futur antérieur)"],"a":[["q","Quand j'",""],["v","ai fini,","x"],["m","je t'appellerai.",""]],"b":[["q","Quand j'",""],["v","aurai fini,","p"],["m","je t'appellerai.",""]],"note":"Not « quand j'ai fini »: <b>quand j'aurai fini</b>."},{"label":"As soon as you've arrived, we'll leave.","en":["English: « as soon as you have arrived »","French: dès que + a future"],"a":[["q","Dès que tu",""],["v","es arrivé,","x"],["m","nous partirons.",""]],"b":[["q","Dès que tu",""],["v","seras arrivé,","p"],["m","nous partirons.",""]]}]}],"practice":{"choose":[{"q":"Quand j'___ fini, je t'appellerai.","en":"When I've finished, I'll call you.","opts":["aurai","ai","avais","aurais"],"a":"aurai","why":"After quand, about the future.","hint":"quand j'<b>aurai</b> fini."},{"q":"Elle ___ partie avant midi.","en":"She will have left before noon.","opts":["sera","aura","est","serait"],"a":"sera","why":"partir takes être.","hint":"elle <b>sera</b> partie."},{"q":"Dès que tu ___ arrivé, nous partirons.","en":"As soon as you've arrived, we'll leave.","opts":["seras","es","auras","étais"],"a":"seras","why":"arriver takes être; about the future.","hint":"dès que tu <b>seras</b> arrivé."},{"q":"D'ici demain, j'___ terminé.","en":"By tomorrow I'll have finished.","opts":["aurai","ai","avais","serai"],"a":"aurai","why":"Done before a future moment.","hint":"j'<b>aurai</b> terminé."},{"q":"Ils ne ___ pas encore rentrés.","en":"They won't be back yet.","opts":["seront","auront","sont","seraient"],"a":"seront","why":"rentrer takes être.","hint":"ils ne <b>seront</b> pas encore rentrés."},{"q":"Il est en retard. Il ___ oublié.","en":"He's late. He must have forgotten.","opts":["aura","sera","a","avait"],"a":"aura","why":"A guess about the past.","hint":"il <b>aura</b> oublié."}],"build":[{"en":"When I've finished, I'll call you.","tiles":["Quand j'","aurai","fini,","je","t'appellerai."],"trap":"ai","why":"After quand: a future.","hint":"quand j'<b>aurai</b> fini."},{"en":"She will have left.","tiles":["Elle","sera","partie."],"trap":"aura","why":"partir takes être.","hint":"elle <b>sera</b> partie."},{"en":"By tomorrow I'll have finished.","tiles":["D'ici","demain,","j'aurai","fini."],"trap":"j'ai","why":"Done before tomorrow.","hint":"<b>j'aurai</b> fini."},{"en":"As soon as you've arrived, we'll leave.","tiles":["Dès que","tu","seras","arrivé,","nous","partirons."],"trap":"es","why":"After dès que: a future.","hint":"tu <b>seras</b> arrivé."},{"en":"In a year, she'll have finished her studies.","tiles":["Dans un an,","elle","aura","terminé","ses études."],"trap":"sera","why":"terminer takes avoir.","hint":"elle <b>aura</b> terminé."}],"spot":[{"words":["Quand j'","ai fini,","je t'appellerai."],"bad":1,"fix":"aurai fini,","hint":"About the future: <b>quand j'aurai fini</b>.","look":"Look after quand.","say":"Quand j'aurai fini, je t'appellerai."},{"words":["Elle","aura","partie."],"bad":1,"fix":"sera","hint":"partir takes <b>être</b>.","look":"Which helper does partir take?"},{"words":["Dès que tu","es arrivé,","nous partirons."],"bad":1,"fix":"seras arrivé,","hint":"About the future: <b>seras arrivé</b>.","look":"Look after dès que."},{"words":["Nous","serons","fini","à midi."],"bad":1,"fix":"aurons","hint":"finir takes <b>avoir</b>.","look":"Which helper does finir take?"},{"words":["Ils","seront","parti","demain."],"bad":2,"fix":"partis","hint":"être: it agrees, <b>partis</b>.","look":"Does it match ils?"}]},"drill":[["When I've finished, I'll call you","Quand j'aurai fini, je t'appellerai. / Quand j'aurai fini, je vous appellerai.","After quand about the future: <b>j'aurai fini</b>."],["She will have left (partir)","Elle sera partie.","être in the future: <b>sera</b> partie."],["By tomorrow I'll have finished","D'ici demain, j'aurai fini.","Done before tomorrow: <b>j'aurai fini</b>."],["As soon as you have arrived, we'll leave","Dès que tu seras arrivé(e), nous partirons. / Dès que tu seras arrivé(e), on partira.","After dès que: <b>seras arrivé</b>."],["He must have forgotten.","Il aura oublié.","A guess about the past: <b>aura oublié</b>."],["They won't be back yet.","Ils ne seront pas encore rentrés.","rentrer takes être: <b>seront rentrés</b>."]]},"33":{"line":"The <b>conditionnel</b> is « would ». The <b>future stem</b> + the <b>imparfait endings</b>: je parler<b>ais</b>, nous finir<b>ions</b>, je <b>ser</b>ais, j'<b>aur</b>ais, je <b>voudr</b>ais, je <b>pourr</b>ais. It makes a request polite (je voudrais, pourriez-vous ?), gives advice (tu <b>devrais</b>), a wish (j'<b>aimerais</b>), or what would happen (je voyagerais).","words":"Polite requests: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:18\">Vocab 18 · Café, Food & Ordering</a> · <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:1\">Vocab 1 · Greetings & Politeness</a>.","steps":[{"tool":"conj","title":"The future stem + -ais, -ait, -ions…","sub":"Pick a verb, then tap a person.","neg":true,"verbs":[{"inf":"parler","en":"would speak","stem":"parler","forms":["parlerais","parlerais","parlerait","parlerions","parleriez","parleraient"],"tail":"français"},{"inf":"vouloir","en":"would like","stem":"voudr","forms":["voudrais","voudrais","voudrait","voudrions","voudriez","voudraient"],"tail":"un café"},{"inf":"pouvoir","en":"could","stem":"pourr","forms":["pourrais","pourrais","pourrait","pourrions","pourriez","pourraient"],"tail":"venir"},{"inf":"devoir","en":"should","stem":"devr","forms":["devrais","devrais","devrait","devrions","devriez","devraient"],"tail":"partir"}]},{"tool":"flip","title":"Future or conditional?","sub":"Tap a card: will → would. Only the ending changes.","cards":[{"a":"je parlerai","b":"je parlerais","tag":"will → would"},{"a":"je ferai","b":"je ferais","tag":"fer-"},{"a":"j'irai","b":"j'irais","tag":"ir-"},{"a":"nous serons","b":"nous serions","tag":"ser-"},{"a":"ils auront","b":"ils auraient","tag":"aur-"},{"a":"tu viendras","b":"tu viendrais","tag":"viendr-"}]},{"tool":"swap","title":"Make it polite","sub":"Pick a request and tap « Soften it ».","button":["Soften it","Back"],"legend":[["x","the conditional"]],"items":[{"label":"Je veux un café.","en":["I want a coffee.","I'd like a coffee."],"a":[["s","Je",""],["v","veux",""],["o","un café.",""]],"b":[["s","Je",""],["v","voudrais","x"],["o","un café.",""]]},{"label":"Pouvez-vous répéter ?","en":["Can you repeat?","Could you repeat, please?"],"a":[["v","Pouvez-vous",""],["o","répéter ?",""]],"b":[["v","Pourriez-vous","x"],["o","répéter, s'il vous plaît ?",""]]},{"label":"Tu dois te reposer.","en":["You must rest.","You should rest."],"a":[["s","Tu",""],["v","dois",""],["o","te reposer.",""]],"b":[["s","Tu",""],["v","devrais","x"],["o","te reposer.",""]],"note":"devoir in the conditional = <b>should</b>."},{"label":"J'aime voyager.","en":["I like travelling.","I'd like to travel."],"a":[["s","J'",""],["v","aime",""],["o","voyager.",""]],"b":[["s","J'",""],["v","aimerais","x"],["o","voyager.",""]]}]}],"practice":{"choose":[{"q":"Je ___ un café, s'il vous plaît.","en":"I'd like a coffee, please.","opts":["voudrais","voudrai","veux","voulais"],"a":"voudrais","why":"Polite: the conditional.","hint":"je <b>voudrais</b>."},{"q":"Tu ___ te reposer.","en":"You should rest.","opts":["devrais","devras","dois","devais"],"a":"devrais","why":"should = devoir in the conditional.","hint":"tu <b>devrais</b>."},{"q":"___-vous m'aider ?","en":"Could you help me?","opts":["Pourriez","Pourrez","Pouvez","Pouviez"],"a":"Pourriez","why":"could…","hint":"<b>Pourriez</b>-vous …?"},{"q":"Nous ___ visiter le musée.","en":"We'd like to visit the museum.","opts":["aimerions","aimerons","aimions","aimons"],"a":"aimerions","why":"nous + -ions on the future stem.","hint":"nous <b>aimerions</b>."},{"q":"Elle a dit qu'elle ___.","en":"She said she would come.","opts":["viendrait","viendra","venait","vienne"],"a":"viendrait","why":"would…","hint":"qu'elle <b>viendrait</b>."},{"q":"À ta place, je ___.","en":"In your place, I would leave.","opts":["partirais","partirai","pars","partais"],"a":"partirais","why":"would…","hint":"je <b>partirais</b>."},{"q":"Ce ___ génial !","en":"That would be great!","opts":["serait","sera","était","est"],"a":"serait","why":"être → ser-.","hint":"ce <b>serait</b> génial."}],"build":[{"en":"I'd like a coffee.","tiles":["Je","voudrais","un","café."],"trap":"voudrai","why":"would: -ais.","hint":"je <b>voudrais</b>."},{"en":"You should rest.","tiles":["Tu","devrais","te","reposer."],"trap":"dois","why":"should = devrais.","hint":"tu <b>devrais</b>."},{"en":"Could you help me?","tiles":["Pourriez-vous","m'aider ?"],"trap":"Pouvez-vous","why":"Polite: the conditional.","hint":"<b>Pourriez-vous</b> …?"},{"en":"She said she would come.","tiles":["Elle","a dit","qu'elle","viendrait."],"trap":"viendra.","why":"would: -ait.","hint":"qu'elle <b>viendrait</b>."},{"en":"We'd like to visit the museum.","tiles":["Nous","aimerions","visiter","le musée."],"trap":"aimerons","why":"would: -ions.","hint":"nous <b>aimerions</b>."}],"spot":[{"words":["Je","voudrai","un café, s'il vous plaît."],"bad":1,"fix":"voudrais","hint":"would: <b>voudrais</b> (with an s).","look":"will or would?"},{"words":["Tu","devras","te reposer."],"bad":1,"fix":"devrais","hint":"should: <b>devrais</b>.","look":"will or would?"},{"words":["Nous","aimerons","voyager."],"bad":1,"fix":"aimerions","hint":"would: <b>aimerions</b>.","look":"will or would?"},{"words":["Elle a dit qu'elle","viendra."],"bad":1,"fix":"viendrait.","hint":"After a past « she said »: <b>viendrait</b>.","look":"will or would?"},{"words":["Ils","pouveraient","venir."],"bad":1,"fix":"pourraient","hint":"pouvoir → <b>pourr-</b>.","look":"Look at the stem."}]},"drill":[["I would like (vouloir)","Je voudrais","The future stem voudr- + <b>-ais</b>."],["You should rest (devoir, tu)","Tu devrais te reposer.","should = <b>devrais</b>."],["She said she would come","Elle a dit qu'elle viendrait.","would come: <b>viendrait</b>."],["Could you help me? (vous)","Pourriez-vous m'aider ?","could: <b>pourriez</b>."],["We'd like to visit the museum.","Nous aimerions visiter le musée.","nous: <b>aimerions</b>."],["That would be great!","Ce serait génial !","être → <b>serait</b>."]]},"34":{"line":"Two patterns with <b>si</b> (if). <b>Real</b>: si + <b>present</b>, then present, future or an order: Si tu viens, je <b>serai</b> content. <b>Imagined</b>: si + <b>imparfait</b>, then <b>conditional</b>: Si j'<b>avais</b> le temps, je <b>voyagerais</b>. Never a future or a conditional right after si. si → <b>s'</b> only before il and ils.","words":"","steps":[{"tool":"swap","title":"Real or imagined?","sub":"Pick a sentence and tap « Imagine it »: both verbs move back one step.","button":["Imagine it","Back to real"],"legend":[["x","after si"],["p","the result"]],"items":[{"label":"Si j'ai le temps, je voyagerai.","en":["If I have time, I'll travel.","If I had time, I would travel."],"a":[["q","Si",""],["s","j'",""],["v","ai","x"],["o","le temps,",""],["r","je voyagerai.","p"]],"b":[["q","Si",""],["s","j'",""],["v","avais","x"],["o","le temps,",""],["r","je voyagerais.","p"]],"note":"present + future → <b>imparfait + conditional</b>."},{"label":"S'il fait beau, nous irons à la plage.","en":["If it's nice, we'll go to the beach.","If it were nice, we would go to the beach."],"a":[["q","S'il",""],["v","fait","x"],["o","beau,",""],["r","nous irons","p"],["t","à la plage.",""]],"b":[["q","S'il",""],["v","faisait","x"],["o","beau,",""],["r","nous irions","p"],["t","à la plage.",""]]},{"label":"Si tu viens, je serai content.","en":["If you come, I'll be happy.","If you came, I would be happy."],"a":[["q","Si tu",""],["v","viens,","x"],["r","je serai","p"],["o","content.",""]],"b":[["q","Si tu",""],["v","venais,","x"],["r","je serais","p"],["o","content.",""]]},{"label":"Si je gagne au loto, j'achète une maison.","en":["If I win the lottery, I buy a house.","If I won the lottery, I would buy a house."],"a":[["q","Si je",""],["v","gagne","x"],["o","au loto,",""],["r","j'achète","p"],["t","une maison.",""]],"b":[["q","Si je",""],["v","gagnais","x"],["o","au loto,",""],["r","j'achèterais","p"],["t","une maison.",""]]}]},{"tool":"sort","title":"Which tense after si?","sub":"Tap the box for the verb that goes after si.","boxes":[{"k":"pres","label":"present","sub":"real: ... will"},{"k":"imp","label":"imparfait","sub":"imagined: ... would"}],"cards":[{"t":"If it rains, we'll stay home.","box":"pres","why":"<b>S'il pleut</b>, nous resterons à la maison.","say":"S'il pleut, nous resterons à la maison."},{"t":"If I were you, I would wait.","box":"imp","why":"<b>Si j'étais</b> toi, j'attendrais.","say":"Si j'étais toi, j'attendrais."},{"t":"If you're hungry, eat something.","box":"pres","why":"<b>Si tu as</b> faim, mange quelque chose.","say":"Si tu as faim, mange quelque chose."},{"t":"If I had a car, I would come.","box":"imp","why":"<b>Si j'avais</b> une voiture, je viendrais.","say":"Si j'avais une voiture, je viendrais."},{"t":"If we leave now, we'll be on time.","box":"pres","why":"<b>Si nous partons</b> maintenant, nous arriverons à l'heure.","say":"Si nous partons maintenant, nous arriverons à l'heure."},{"t":"If I were rich, I would travel.","box":"imp","why":"<b>Si j'étais</b> riche, je voyagerais.","say":"Si j'étais riche, je voyagerais."}]}],"practice":{"choose":[{"q":"S'il ___, je resterai à la maison.","en":"If it rains, I'll stay home.","opts":["pleut","pleuvra","pleuvait","pleuvrait"],"a":"pleut","why":"Real: si + present.","hint":"s'il <b>pleut</b>."},{"q":"Si j'___ le temps, je voyagerais.","en":"If I had time, I would travel.","opts":["avais","aurais","ai","aurai"],"a":"avais","why":"Imagined: si + imparfait.","hint":"si j'<b>avais</b>."},{"q":"Si j'étais toi, j'___.","en":"If I were you, I would wait.","opts":["attendrais","attendrai","attendais","attends"],"a":"attendrais","why":"Imagined: the conditional.","hint":"j'<b>attendrais</b>."},{"q":"Si tu es fatigué, ___-toi !","en":"If you're tired, rest!","opts":["repose","reposes","reposerais","reposeras"],"a":"repose","why":"Real + an order.","hint":"<b>repose-toi</b> !"},{"q":"___ elle vient, on sera contents.","en":"If she comes, we'll be happy.","opts":["Si","S'","Quand","Si elle"],"a":"Si","why":"s' only before il and ils.","hint":"<b>Si</b> elle vient."},{"q":"Si nous partons maintenant, nous ___ à l'heure.","en":"If we leave now, we'll arrive on time.","opts":["arriverons","arriverions","arrivions","arrivons"],"a":"arriverons","why":"Real: the future.","hint":"nous <b>arriverons</b>."}],"build":[{"en":"If it rains, I'll stay home.","tiles":["S'il","pleut,","je","resterai","à la maison."],"trap":"pleuvra,","why":"Real: si + present.","hint":"s'il <b>pleut</b>."},{"en":"If I had time, I'd travel.","tiles":["Si j'","avais","le temps,","je","voyagerais."],"trap":"aurais","why":"Imagined: si + imparfait.","hint":"si j'<b>avais</b>."},{"en":"If I were you, I'd wait.","tiles":["Si j'","étais","toi,","j'","attendrais."],"trap":"serais","why":"Imagined: si + imparfait.","hint":"si j'<b>étais</b> toi."},{"en":"If you're tired, rest!","tiles":["Si tu","es","fatigué,","repose-toi !"],"trap":"seras","why":"Real + an order.","hint":"si tu <b>es</b> fatigué."},{"en":"I'd travel if I had time.","tiles":["Je","voyagerais","si j'","avais","le temps."],"trap":"aurais","why":"The two parts can swap.","hint":"je voyagerais <b>si j'avais</b> …"}],"spot":[{"words":["Si tu","viendras,","je serai content."],"bad":1,"fix":"viens,","hint":"Never a future after si: <b>si tu viens</b>.","look":"Look right after si."},{"words":["Si j'","aurais","le temps, je voyagerais."],"bad":1,"fix":"avais","hint":"Never a conditional after si: <b>si j'avais</b>.","look":"Look right after si.","say":"Si j'avais le temps, je voyagerais."},{"words":["Si j'avais une voiture,","je viendrai","te voir."],"bad":1,"fix":"je viendrais","hint":"Imagined: the conditional, <b>viendrais</b>.","look":"will or would?"},{"words":["S'elle","vient,","on sera contents."],"bad":0,"fix":"Si elle","hint":"s' only before il and ils: <b>si elle</b>.","look":"Look at si before elle."},{"words":["S'il pleut,","nous restions","à la maison."],"bad":1,"fix":"nous resterons","hint":"Real: <b>resterons</b>.","look":"Is this real or imagined?"}]},"drill":[["If it rains, I'll stay home","S'il pleut, je resterai à la maison. / S'il pleut, je resterai chez moi.","Real: <b>si + present</b>, then the future."],["If I had time, I'd travel","Si j'avais le temps, je voyagerais.","Imagined: <b>si + imparfait</b>, then the conditional."],["If you're tired, rest!","Si tu es fatigué(e), repose-toi !","Real + an order."],["If I were you, I'd wait","Si j'étais toi, j'attendrais.","Imagined: <b>si j'étais</b>, j'attendrais."],["If she comes, we'll be happy.","Si elle vient, nous serons contents. / Si elle vient, on sera contents.","<b>si elle</b>: no elision."],["If I won the lottery, I'd buy a house.","Si je gagnais au loto, j'achèterais une maison.","Imagined: <b>gagnais</b>, <b>achèterais</b>."]]},"41":{"line":"Reported speech tells what someone said, after <b>que</b>. The pronouns follow the speaker (« Je suis fatigué » → il a dit qu'<b>il</b> était fatigué). After a <b>past</b> « il a dit », the tenses step back: present → <b>imparfait</b>, passé composé → <b>plus-que-parfait</b>, future → <b>conditional</b>. Questions: <b>si</b>, or the question word, with normal word order. Orders: <b>de</b> + the verb.","words":"","steps":[{"tool":"swap","title":"Report it","sub":"Pick a quote and tap « Report it »: the tense steps back.","button":["Report it","The quote"],"legend":[["x","the verb that steps back"],["p","the glue word"]],"items":[{"label":"« Je suis fatigué. »","en":["\"I am tired.\"","He said he was tired."],"a":[["q","« Je",""],["v","suis","x"],["o","fatigué. »",""]],"b":[["i","Il a dit",""],["p","qu'il","p"],["v","était","x"],["o","fatigué.",""]],"note":"present → <b>imparfait</b>."},{"label":"« J'ai fini. »","en":["\"I have finished.\"","He said he had finished."],"a":[["q","« J'",""],["v","ai fini. »","x"]],"b":[["i","Il a dit",""],["p","qu'il","p"],["v","avait fini.","x"]],"note":"passé composé → <b>plus-que-parfait</b>."},{"label":"« Je viendrai demain. »","en":["\"I will come tomorrow.\"","She said she would come the next day."],"a":[["q","« Je",""],["v","viendrai","x"],["o","demain. »",""]],"b":[["i","Elle a dit",""],["p","qu'elle","p"],["v","viendrait","x"],["o","le lendemain.",""]],"note":"future → <b>conditional</b>; demain → <b>le lendemain</b>."},{"label":"« Tu viens ? »","en":["\"Are you coming?\"","He asked me if I was coming."],"a":[["q","« Tu",""],["v","viens ? »","x"]],"b":[["i","Il m'a demandé",""],["p","si","p"],["s","je",""],["v","venais.","x"]],"note":"A yes / no question: <b>si</b>."},{"label":"« Qu'est-ce que tu fais ? »","en":["\"What are you doing?\"","He asked me what I was doing."],"a":[["q","« Qu'est-ce que tu",""],["v","fais ? »","x"]],"b":[["i","Il m'a demandé",""],["p","ce que","p"],["s","je",""],["v","faisais.","x"]],"note":"qu'est-ce que → <b>ce que</b>."},{"label":"« Ne pars pas ! »","en":["\"Don't leave!\"","She told me not to leave."],"a":[["q","« Ne",""],["v","pars pas ! »","x"]],"b":[["i","Elle m'a dit",""],["p","de","p"],["v","ne pas partir.","x"]],"note":"An order: <b>de</b> + the verb (ne pas before it)."}]},{"tool":"flip","title":"Time words shift too","sub":"Tap a card: from the quote to the report.","cards":[{"a":"demain","b":"le lendemain","tag":"tomorrow → the next day"},{"a":"hier","b":"la veille","tag":"yesterday → the day before"},{"a":"aujourd'hui","b":"ce jour-là","tag":"today → that day"},{"a":"maintenant","b":"alors","tag":"now → then"},{"a":"la semaine prochaine","b":"la semaine suivante","tag":"next week → the following week"},{"a":"ici","b":"là","tag":"here → there"}]}],"practice":{"choose":[{"q":"« Je suis fatigué. » → Il a dit qu'il ___ fatigué.","en":"He said he was tired.","opts":["était","est","sera","a été"],"a":"était","why":"present → ?","hint":"<b>imparfait</b>: était."},{"q":"« Je viendrai. » → Elle a dit qu'elle ___.","en":"She said she would come.","opts":["viendrait","viendra","venait","est venue"],"a":"viendrait","why":"future → ?","hint":"<b>conditional</b>: viendrait."},{"q":"« J'ai fini. » → Il a dit qu'il ___ fini.","en":"He said he had finished.","opts":["avait","a","aurait","avais"],"a":"avait","why":"passé composé → ?","hint":"<b>plus-que-parfait</b>: avait fini."},{"q":"« Tu viens ? » → Il m'a demandé ___ je venais.","en":"He asked me if I was coming.","opts":["si","que","est-ce que","quoi"],"a":"si","why":"A yes / no question.","hint":"<b>si</b>."},{"q":"« Où habites-tu ? » → Il a demandé où j'___.","en":"He asked where I lived.","opts":["habitais","habite","habitait","ai habité"],"a":"habitais","why":"present → imparfait, normal order.","hint":"où j'<b>habitais</b>."},{"q":"« Viens ! » → Il m'a dit ___ venir.","en":"He told me to come.","opts":["de","que","à","pour"],"a":"de","why":"An order…","hint":"dire <b>de</b> + the verb."},{"q":"« Je pars demain. » → Il a dit qu'il partait ___.","en":"He said he was leaving the next day.","opts":["le lendemain","demain","la veille","hier"],"a":"le lendemain","why":"demain shifts…","hint":"<b>le lendemain</b>."}],"build":[{"en":"He said he was tired.","tiles":["Il","a dit","qu'il","était","fatigué."],"trap":"est","why":"present → imparfait.","hint":"qu'il <b>était</b>."},{"en":"She said she would come.","tiles":["Elle","a dit","qu'elle","viendrait."],"trap":"viendra.","why":"future → conditional.","hint":"qu'elle <b>viendrait</b>."},{"en":"He asked me if I was hungry.","tiles":["Il","m'a demandé","si","j'avais","faim."],"trap":"que","why":"A yes / no question: si.","hint":"<b>si</b> j'avais faim."},{"en":"She told me not to leave.","tiles":["Elle","m'a dit","de","ne pas","partir."],"trap":"que","why":"An order: de + verb.","hint":"<b>de ne pas partir</b>."},{"en":"He asked me what I was doing.","tiles":["Il","m'a demandé","ce que","je","faisais."],"trap":"qu'est-ce que","why":"qu'est-ce que → ce que.","hint":"<b>ce que</b> je faisais."}],"spot":[{"words":["Il a dit","qu'il","est","fatigué."],"bad":2,"fix":"était","hint":"After a past « il a dit »: <b>était</b>.","look":"Does the tense step back?"},{"words":["Elle a dit qu'elle","viendra","le lendemain."],"bad":1,"fix":"viendrait","hint":"future → <b>viendrait</b>.","look":"Does the tense step back?"},{"words":["Il m'a demandé","est-ce que","je venais."],"bad":1,"fix":"si","hint":"A yes / no question: <b>si</b>.","look":"Look at the glue word."},{"words":["Il m'a demandé","où","habitais-je."],"bad":2,"fix":"j'habitais.","hint":"Normal word order: <b>où j'habitais</b>.","look":"Look at the word order.","say":"Il m'a demandé où j'habitais."},{"words":["Il m'a dit","que","venir."],"bad":1,"fix":"de","hint":"An order: <b>de</b> + the verb.","look":"Look at the glue word."}]},"drill":[["« Je suis fatigué. » → Il a dit...","Il a dit qu'il était fatigué.","present → <b>imparfait</b>."],["« Je viendrai. » → Elle a dit...","Elle a dit qu'elle viendrait.","future → <b>conditional</b>."],["« Où habites-tu ? » → Il a demandé...","Il a demandé où j'habitais.","Normal word order, present → imparfait."],["« Ne pars pas ! » → Elle m'a dit...","Elle m'a dit de ne pas partir.","An order: <b>de ne pas</b> + the verb."],["« J'ai fini. » → Il a dit...","Il a dit qu'il avait fini.","passé composé → <b>plus-que-parfait</b>."],["« Tu viens ? » → Il m'a demandé...","Il m'a demandé si je venais.","A yes / no question: <b>si</b>."]]},"39":{"line":"In the <b>passive</b>, the subject receives the action: <b>être</b> (in any tense) + the past participle, which agrees with the subject. The doer comes after <b>par</b>: Le repas <b>est préparé par</b> le chef. Passé composé: <b>a été</b> préparé. French often prefers <b>on</b> instead: Ici, <b>on</b> parle français.","words":"","steps":[{"tool":"swap","title":"Turn it round","sub":"Pick a sentence and tap « Make it passive »: the object becomes the subject.","button":["Make it passive","Back to active"],"legend":[["x","être + participle"],["p","par + the doer"]],"items":[{"label":"Le chef prépare le repas.","en":["The chef prepares the meal.","The meal is prepared by the chef."],"a":[["d","Le chef",""],["v","prépare",""],["o","le repas.",""]],"b":[["o","Le repas",""],["v","est préparé","x"],["d","par le chef.","p"]]},{"label":"Le chef a préparé le repas.","en":["The chef prepared the meal.","The meal was prepared by the chef."],"a":[["d","Le chef",""],["v","a préparé",""],["o","le repas.",""]],"b":[["o","Le repas",""],["v","a été préparé","x"],["d","par le chef.","p"]],"note":"Passé composé: <b>a été</b> + participle."},{"label":"Ses amis ont invité Marie.","en":["Her friends invited Marie.","Marie was invited by her friends."],"a":[["d","Ses amis",""],["v","ont invité",""],["o","Marie.",""]],"b":[["o","Marie",""],["v","a été invitée","x"],["d","par ses amis.","p"]],"note":"It agrees with Marie: invit<b>ée</b>."},{"label":"On fermera le musée lundi.","en":["They will close the museum on Monday.","The museum will be closed on Monday."],"a":[["d","On",""],["v","fermera",""],["o","le musée",""],["t","lundi.",""]],"b":[["o","Le musée",""],["v","sera fermé","x"],["t","lundi.",""]],"note":"Future: <b>sera</b> + participle. No doer needed."},{"label":"Le français est parlé ici. → with on","en":["French is spoken here.","Here, they speak French. (more natural)"],"a":[["o","Le français",""],["v","est parlé","x"],["t","ici.",""]],"b":[["t","Ici,",""],["d","on","p"],["v","parle",""],["o","français.",""]],"note":"French often prefers <b>on</b> + an active verb."}]},{"tool":"agree","title":"The participle follows the subject","sub":"Switch the subject.","cols":["le livre","la porte","les livres","les portes"],"rows":[{"forms":["est fermé","est fermée","sont fermés","sont fermées"],"en":"is / are closed"},{"forms":["a été vendu","a été vendue","ont été vendus","ont été vendues"],"en":"was / were sold"}]}],"practice":{"choose":[{"q":"Le repas est préparé ___ le chef.","en":"The meal is prepared by the chef.","opts":["par","de","pour","avec"],"a":"par","why":"by + the doer.","hint":"<b>par</b> le chef."},{"q":"Le livre ___ publié en 2020.","en":"The book was published in 2020.","opts":["a été","est été","était été","avait"],"a":"a été","why":"Passé composé of être.","hint":"<b>a été</b> publié."},{"q":"Les portes sont ___.","en":"The doors are closed.","opts":["fermées","fermé","fermés","fermée"],"a":"fermées","why":"portes is feminine plural.","hint":"<b>fermées</b>."},{"q":"Elle a été ___ par ses amis.","en":"She was invited by her friends.","opts":["invitée","invité","invités","inviter"],"a":"invitée","why":"Agree with elle.","hint":"<b>invitée</b>."},{"q":"Ici, ___ parle français.","en":"French is spoken here.","opts":["on","il","est","se"],"a":"on","why":"The French way: on + active.","hint":"ici, <b>on</b> parle français."},{"q":"Le musée ___ fermé lundi.","en":"The museum will be closed on Monday.","opts":["sera","aura","est","a été"],"a":"sera","why":"Future of être.","hint":"<b>sera</b> fermé."}],"build":[{"en":"The meal is prepared by the chef.","tiles":["Le repas","est","préparé","par","le chef."],"trap":"de","why":"by + the doer: par.","hint":"<b>par</b> le chef."},{"en":"The book was published.","tiles":["Le livre","a été","publié."],"trap":"est été","why":"Passé composé of être: a été.","hint":"<b>a été</b> publié."},{"en":"French is spoken here. (use on)","tiles":["Ici,","on","parle","français."],"trap":"est parlé","why":"on + an active verb.","hint":"<b>on parle</b>."},{"en":"The doors are closed.","tiles":["Les portes","sont","fermées."],"trap":"fermés.","why":"portes is feminine plural.","hint":"<b>fermées</b>."},{"en":"This church was built in the 12th century.","tiles":["Cette église","a été","construite","au XIIe siècle."],"trap":"construit","why":"Agree with église.","hint":"<b>construite</b>."}],"spot":[{"words":["Le repas est préparé","de","le chef."],"bad":1,"fix":"par","hint":"by + the doer: <b>par</b>.","look":"How do you say « by »?"},{"words":["Le livre","est été","publié."],"bad":1,"fix":"a été","hint":"être in the passé composé: <b>a été</b>.","look":"Look at the helper."},{"words":["Les portes","sont","fermé."],"bad":2,"fix":"fermées.","hint":"Agree with portes: <b>fermées</b>.","look":"Does the participle match?"},{"words":["Marie","a été","invité."],"bad":2,"fix":"invitée.","hint":"Agree with Marie: <b>invitée</b>.","look":"Does the participle match?"},{"words":["Les billets","est vendus","à la gare."],"bad":1,"fix":"sont vendus","hint":"Plural subject: <b>sont</b>.","look":"Singular or plural?"}]},"drill":[["The meal is prepared by the chef","Le repas est préparé par le chef.","<b>être</b> + participle, <b>par</b> + the doer."],["The book was published (passé composé)","Le livre a été publié.","Passé composé: <b>a été</b> publié."],["French is spoken here (use on)","Ici, on parle français.","French often prefers <b>on</b>."],["The doors are closed","Les portes sont fermées.","It agrees: <b>fermées</b>."],["She was invited by her friends.","Elle a été invitée par ses amis.","It agrees: <b>invitée</b>."],["The museum will be closed on Monday.","Le musée sera fermé lundi.","Future: <b>sera</b> fermé."]]},"40":{"line":"Take the <b>nous</b> form, drop -ons, add <b>-ant</b>: nous parl<i>ons</i> → <b>parlant</b>. Three exceptions: <b>étant</b>, <b>ayant</b>, <b>sachant</b>. The <b>gérondif</b> is <b>en</b> + -ant: it says how, when or why, with the same subject as the main verb: Il mange <b>en regardant</b> la télé. It never changes.","words":"","steps":[{"tool":"flip","title":"From the nous form","sub":"Tap a card: nous … -ons gives the -ant form.","cards":[{"a":"nous parlons","b":"en parlant","tag":"parl-"},{"a":"nous finissons","b":"en finissant","tag":"finiss-"},{"a":"nous prenons","b":"en prenant","tag":"pren-"},{"a":"nous faisons","b":"en faisant","tag":"fais-"},{"a":"nous mangeons","b":"en mangeant","tag":"mange- (keeps the e)"},{"a":"être","b":"en étant","tag":"exception"},{"a":"avoir","b":"en ayant","tag":"exception"},{"a":"savoir","b":"en sachant","tag":"exception"}]},{"tool":"swap","title":"Two sentences, one subject","sub":"Pick a pair and tap « Join with en ».","button":["Join with en","Two sentences"],"legend":[["x","the gérondif"]],"items":[{"label":"Il mange. Il regarde la télé.","en":["He eats. He watches TV.","He eats while watching TV."],"a":[["a","Il mange.",""],["s","Il",""],["v","regarde",""],["o","la télé.",""]],"b":[["a","Il mange",""],["v","en regardant","x"],["o","la télé.",""]],"note":"At the same time."},{"label":"On pratique. On apprend.","en":["You practise. You learn.","You learn by practising."],"a":[["s","On",""],["v","pratique.",""],["a","On apprend.",""]],"b":[["a","On apprend",""],["v","en pratiquant.","x"]],"note":"How: by doing it."},{"label":"Elle travaille. Elle chante.","en":["She works. She sings.","She sings while working."],"a":[["s","Elle",""],["v","travaille.",""],["a","Elle chante.",""]],"b":[["a","Elle chante",""],["v","en travaillant.","x"]]},{"label":"Il courait. Il est tombé.","en":["He was running. He fell.","He fell while running."],"a":[["s","Il",""],["v","courait.",""],["a","Il est tombé.",""]],"b":[["a","Il est tombé",""],["v","en courant.","x"]],"note":"courir → nous courons → <b>en courant</b>."}]}],"practice":{"choose":[{"q":"Il mange en ___ la télé.","en":"He eats while watching TV.","opts":["regardant","regarder","regarde","regardé"],"a":"regardant","why":"en + -ant.","hint":"en <b>regardant</b>."},{"q":"On apprend en ___.","en":"You learn by practising.","opts":["pratiquant","pratiquer","pratiquons","pratique"],"a":"pratiquant","why":"en + -ant.","hint":"en <b>pratiquant</b>."},{"q":"Elle chante en ___.","en":"She sings while cooking.","opts":["cuisinant","cuisinante","cuisiner","cuisinait"],"a":"cuisinant","why":"It never changes.","hint":"en <b>cuisinant</b>."},{"q":"en ___ (manger)","en":"while eating","opts":["mangeant","mangant","mangent","mangeons"],"a":"mangeant","why":"Keep the e: nous mangeons.","hint":"en <b>mangeant</b>."},{"q":"___ malade, il est resté chez lui.","en":"Being ill, he stayed at home.","opts":["Étant","Être","Ayant","Sachant"],"a":"Étant","why":"être has its own -ant form.","hint":"<b>Étant</b> malade…"},{"q":"Elle m'a répondu en ___.","en":"She answered me, smiling.","opts":["souriant","sourire","sourit","souriante"],"a":"souriant","why":"en + -ant, no agreement.","hint":"en <b>souriant</b>."}],"build":[{"en":"while eating","tiles":["en","mangeant"],"trap":"mangant","why":"Keep the e.","hint":"en <b>mangeant</b>."},{"en":"by working","tiles":["en","travaillant"],"trap":"travailler","why":"en + -ant.","hint":"en <b>travaillant</b>."},{"en":"She sings while cooking.","tiles":["Elle","chante","en","cuisinant."],"trap":"cuisinante.","why":"It never changes.","hint":"en <b>cuisinant</b>."},{"en":"He fell while running.","tiles":["Il","est tombé","en","courant."],"trap":"courir.","why":"courir → courant.","hint":"en <b>courant</b>."},{"en":"By reading this book, I learned a lot.","tiles":["En","lisant","ce livre,","j'ai","beaucoup appris."],"trap":"lire","why":"lire → nous lisons → lisant.","hint":"<b>En lisant</b> …"}],"spot":[{"words":["Il mange","en regarder","la télé."],"bad":1,"fix":"en regardant","hint":"en + -ant: <b>en regardant</b>.","look":"Look at the verb after en."},{"words":["Elle chante","en","cuisinante."],"bad":2,"fix":"cuisinant.","hint":"The gérondif never changes.","look":"Does it agree?"},{"words":["en","mangant"],"bad":1,"fix":"mangeant","hint":"Keep the e: <b>mangeant</b>.","look":"Look at the nous form."},{"words":["Ayant","malade,","il est resté chez lui."],"bad":0,"fix":"Étant","hint":"être → <b>étant</b>.","look":"Which verb is it?"},{"words":["Je suis","en lisant","un livre."],"bad":1,"fix":"en train de lire","hint":"For « I am reading » use <b>être en train de</b>.","look":"Is this how or when, or what is going on?","say":"Je suis en train de lire un livre."}]},"drill":[["while eating (manger)","en mangeant","nous mangeons → <b>en mangeant</b>."],["by working (travailler)","en travaillant","en + <b>-ant</b>."],["She sings while cooking","Elle chante en cuisinant. / Elle chante en faisant la cuisine.","Same subject: <b>en cuisinant</b>."],["The present participle of être","étant","An exception: <b>étant</b>."],["He fell while running.","Il est tombé en courant.","courir → <b>en courant</b>."],["You learn by practising.","On apprend en pratiquant.","How: <b>en pratiquant</b>."]]},"35":{"line":"The <b>subjonctif</b> comes after <b>que</b> when the first part is a wish, a need, a feeling or a doubt, and the two subjects are <b>different</b>: Il faut que tu <b>viennes</b>. Take the <b>ils</b> form, drop -ent, add <b>-e, -es, -e, -ions, -iez, -ent</b>: ils parl<i>ent</i> → que je parl<b>e</b>. Same subject? Use the infinitive: je veux <b>partir</b>.","words":"","steps":[{"tool":"conj","title":"From the ils form","sub":"Pick a verb, then tap a person: the ending lights up.","neg":false,"pre":"Il faut que","verbs":[{"inf":"parler","en":"that … speak","stem":"parl","forms":["parle","parles","parle","parlions","parliez","parlent"],"tail":""},{"inf":"finir","en":"that … finish","stem":"finiss","forms":["finisse","finisses","finisse","finissions","finissiez","finissent"],"tail":""},{"inf":"partir","en":"that … leave","stem":"part","forms":["parte","partes","parte","partions","partiez","partent"],"tail":""},{"inf":"venir","en":"that … come","forms":["vienne","viennes","vienne","venions","veniez","viennent"],"tail":""}]},{"tool":"sort","title":"Subjonctif or not?","sub":"Tap the box for the verb after que.","boxes":[{"k":"s","label":"subjonctif","sub":"need, wish, feeling, doubt"},{"k":"i","label":"normal (indicatif)","sub":"sure, I think, I know"}],"cards":[{"t":"Il faut que tu (venir).","box":"s","why":"need: <b>viennes</b>.","say":"Il faut que tu viennes."},{"t":"Je sais qu'il (venir).","box":"i","why":"sure: <b>vient</b>.","say":"Je sais qu'il vient."},{"t":"Je veux que vous (être) là.","box":"s","why":"wish: <b>soyez</b>.","say":"Je veux que vous soyez là."},{"t":"Je pense qu'il (avoir) raison.","box":"i","why":"I think: <b>a</b>.","say":"Je pense qu'il a raison."},{"t":"Elle est contente que nous (partir).","box":"s","why":"feeling: <b>partions</b>.","say":"Elle est contente que nous partions."},{"t":"Je doute qu'il (savoir).","box":"s","why":"doubt: <b>sache</b>.","say":"Je doute qu'il sache."},{"t":"Je ne pense pas qu'il (venir).","box":"s","why":"A no to « I think » brings doubt: <b>vienne</b>.","say":"Je ne pense pas qu'il vienne."},{"t":"Il est sûr que tu (réussir).","box":"i","why":"sure: <b>réussiras</b>.","say":"Il est sûr que tu réussiras."}]},{"tool":"swap","title":"Same subject? No que","sub":"Pick a sentence and tap « Change the subject ».","button":["Change the subject","Same subject"],"legend":[["x","the subjonctif"],["p","que + a new subject"]],"items":[{"label":"Je veux partir.","en":["I want to leave.","I want you to leave."],"a":[["s","Je",""],["m","veux",""],["v","partir.",""]],"b":[["s","Je",""],["m","veux",""],["q","que tu","p"],["v","partes.","x"]]},{"label":"Je suis content de venir.","en":["I'm glad to come.","I'm glad you're coming."],"a":[["s","Je suis content",""],["d","de",""],["v","venir.",""]],"b":[["s","Je suis content",""],["q","que tu","p"],["v","viennes.","x"]]},{"label":"Il faut partir.","en":["We have to leave.","You have to leave."],"a":[["s","Il faut",""],["v","partir.",""]],"b":[["s","Il faut",""],["q","que tu","p"],["v","partes.","x"]]}]}],"practice":{"choose":[{"q":"Il faut que tu ___ demain.","en":"You have to come tomorrow.","opts":["viennes","viens","viendras","venir"],"a":"viennes","why":"Need + a new subject.","hint":"que tu <b>viennes</b>."},{"q":"Je veux que vous ___ à l'heure.","en":"I want you to be on time.","opts":["soyez","êtes","serez","être"],"a":"soyez","why":"être in the subjonctif.","hint":"que vous <b>soyez</b>."},{"q":"Je veux ___.","en":"I want to leave.","opts":["partir","que je parte","parte","pars"],"a":"partir","why":"Same subject…","hint":"just the infinitive: <b>partir</b>."},{"q":"Je sais qu'il ___.","en":"I know he is coming.","opts":["vient","vienne","venir","viennes"],"a":"vient","why":"Sure: no subjonctif.","hint":"je sais qu'il <b>vient</b>."},{"q":"Elle est contente que nous ___.","en":"She's glad we're leaving.","opts":["partions","partons","partirons","partir"],"a":"partions","why":"A feeling.","hint":"que nous <b>partions</b>."},{"q":"Je ne pense pas qu'il ___ raison.","en":"I don't think he's right.","opts":["ait","a","aura","avoir"],"a":"ait","why":"A no to « I think » brings doubt.","hint":"qu'il <b>ait</b> raison."},{"q":"Il vaut mieux que nous ___ un taxi.","en":"It's better that we take a taxi.","opts":["prenions","prenons","prendrons","prendre"],"a":"prenions","why":"prendre: like the nous form.","hint":"que nous <b>prenions</b>."}],"build":[{"en":"You have to come.","tiles":["Il faut","que","tu","viennes."],"trap":"viens.","why":"Need + a new subject.","hint":"que tu <b>viennes</b>."},{"en":"I want you to be on time.","tiles":["Je veux","que","tu","sois","à l'heure."],"trap":"es","why":"être in the subjonctif.","hint":"que tu <b>sois</b>."},{"en":"I want to leave.","tiles":["Je","veux","partir."],"trap":"que","why":"Same subject: no que.","hint":"je veux <b>partir</b>."},{"en":"I doubt he knows.","tiles":["Je doute","qu'il","sache."],"trap":"sait.","why":"Doubt.","hint":"qu'il <b>sache</b>."},{"en":"She's glad we're leaving.","tiles":["Elle est contente","que","nous","partions."],"trap":"partons.","why":"A feeling.","hint":"que nous <b>partions</b>."}],"spot":[{"words":["Il faut que","tu viens","demain."],"bad":1,"fix":"tu viennes","hint":"Need: <b>viennes</b>.","look":"Is it a need?"},{"words":["Je veux","que je parte."],"bad":1,"fix":"partir.","hint":"Same subject: <b>Je veux partir.</b>","look":"Who leaves?","say":"Je veux partir."},{"words":["Je sais qu'il","vienne."],"bad":1,"fix":"vient.","hint":"Sure: <b>vient</b>.","look":"Is it a doubt?"},{"words":["Je veux que vous","êtes","à l'heure."],"bad":1,"fix":"soyez","hint":"A wish: <b>soyez</b>.","look":"Is it a wish?"},{"words":["Je doute qu'il","sait","la réponse."],"bad":1,"fix":"sache","hint":"Doubt: <b>sache</b>.","look":"Is it a doubt?"}]},"drill":[["You have to come (il faut que, venir)","Il faut que tu viennes.","Need + a new subject: <b>viennes</b>."],["I want you to be on time (être)","Je veux que tu sois à l'heure. / Je veux que vous soyez à l'heure.","être: <b>sois</b>, <b>soyez</b>."],["Same subject: I want to leave","Je veux partir.","Same subject: the infinitive."],["I doubt he knows (savoir)","Je doute qu'il sache.","Doubt: <b>sache</b>."],["She's glad we're leaving.","Elle est contente que nous partions.","A feeling: <b>partions</b>."],["I don't think he's right.","Je ne pense pas qu'il ait raison.","A no to « I think »: <b>ait</b>."]]},"v25":{"line":"Seven common verbs have their own subjonctif: learn them as whole words. <b>être</b>: sois, soit, soyons. <b>avoir</b>: aie, ait, ayons. <b>aller</b>: aille, allions. <b>faire</b>: fasse. <b>pouvoir</b>: puisse. <b>savoir</b>: sache. <b>vouloir</b>: veuille, voulions. (devoir is regular: que je doive, que nous devions.)","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"conj","title":"The irregular seven","sub":"Pick a verb, then tap a person.","neg":false,"pre":"Il faut que","verbs":[{"inf":"être","en":"that … be","forms":["sois","sois","soit","soyons","soyez","soient"],"tail":""},{"inf":"avoir","en":"that … have","forms":["aie","aies","ait","ayons","ayez","aient"],"tail":""},{"inf":"aller","en":"that … go","forms":["aille","ailles","aille","allions","alliez","aillent"],"tail":""},{"inf":"faire","en":"that … do","forms":["fasse","fasses","fasse","fassions","fassiez","fassent"],"tail":""},{"inf":"pouvoir","en":"that … can","forms":["puisse","puisses","puisse","puissions","puissiez","puissent"],"tail":""},{"inf":"savoir","en":"that … know","forms":["sache","saches","sache","sachions","sachiez","sachent"],"tail":""},{"inf":"vouloir","en":"that … want","forms":["veuille","veuilles","veuille","voulions","vouliez","veuillent"],"tail":""}]},{"tool":"flip","title":"Present → subjonctif","sub":"Tap a card.","cards":[{"a":"je suis","b":"que je sois","tag":"être"},{"a":"j'ai","b":"que j'aie","tag":"avoir"},{"a":"je vais","b":"que j'aille","tag":"aller"},{"a":"nous allons","b":"que nous allions","tag":"aller: two stems"},{"a":"je fais","b":"que je fasse","tag":"faire"},{"a":"je peux","b":"que je puisse","tag":"pouvoir"},{"a":"je sais","b":"que je sache","tag":"savoir"},{"a":"je dois","b":"que je doive","tag":"devoir: regular"}]}],"practice":{"choose":[{"q":"Il faut que tu ___ à l'heure.","en":"You have to be on time.","opts":["sois","es","soit","seras"],"a":"sois","why":"être with tu.","hint":"que tu <b>sois</b>."},{"q":"Je veux que vous ___ un bon voyage.","en":"I want you to have a good trip.","opts":["ayez","avez","ayiez","aurez"],"a":"ayez","why":"avoir with vous.","hint":"que vous <b>ayez</b>."},{"q":"Il est important que nous ___ attention.","en":"It is important that we be careful.","opts":["fassions","faisons","fassons","ferons"],"a":"fassions","why":"faire with nous.","hint":"que nous <b>fassions</b>."},{"q":"Elle est contente que tu ___ venir.","en":"She's glad you can come.","opts":["puisses","peux","puisse","pourras"],"a":"puisses","why":"pouvoir with tu.","hint":"que tu <b>puisses</b>."},{"q":"Je ne pense pas qu'il ___ la réponse.","en":"I don't think he knows the answer.","opts":["sache","sait","saches","sachent"],"a":"sache","why":"savoir with il.","hint":"qu'il <b>sache</b>."},{"q":"Il faut que nous ___ à la gare.","en":"We have to go to the station.","opts":["allions","aillons","allons","irons"],"a":"allions","why":"aller with nous uses the other stem.","hint":"que nous <b>allions</b>."}],"build":[{"en":"that I be","tiles":["que","je","sois"],"trap":"suis","why":"être.","hint":"que je <b>sois</b>."},{"en":"that you (tu) have","tiles":["que","tu","aies"],"trap":"as","why":"avoir.","hint":"que tu <b>aies</b>."},{"en":"that we do","tiles":["que","nous","fassions"],"trap":"faisons","why":"faire.","hint":"que nous <b>fassions</b>."},{"en":"that they can","tiles":["qu'ils","puissent"],"trap":"peuvent","why":"pouvoir.","hint":"qu'ils <b>puissent</b>."},{"en":"that I go","tiles":["que","j'","aille"],"trap":"vais","why":"aller.","hint":"que j'<b>aille</b>."}],"spot":[{"words":["Il faut que","je suis","à l'heure."],"bad":1,"fix":"je sois","hint":"After il faut que: <b>je sois</b>.","look":"Look at être."},{"words":["Je veux que tu","as","du courage."],"bad":1,"fix":"aies","hint":"avoir: <b>aies</b>.","look":"Look at avoir."},{"words":["Il faut que nous","aillions","à la gare."],"bad":1,"fix":"allions","hint":"nous: <b>allions</b>.","look":"aller has two stems."},{"words":["Je doute","qu'il","peut","venir."],"bad":2,"fix":"puisse","hint":"pouvoir: <b>puisse</b>.","look":"Look at pouvoir."},{"words":["Il faut que vous","faisiez","attention."],"bad":1,"fix":"fassiez","hint":"faire: <b>fassiez</b>.","look":"Look at faire."}]},"drill":[["that I be (être)","que je sois","être: <b>sois</b>."],["that you (tu) have (avoir)","que tu aies","avoir: <b>aies</b>."],["that we do (faire)","que nous fassions","faire: <b>fassions</b>."],["that they can (pouvoir)","qu'ils puissent","pouvoir: <b>puissent</b>."],["that he knows (savoir)","qu'il sache","savoir: <b>sache</b>."],["that we go (aller)","que nous allions","aller with nous: <b>allions</b>."]]},"46":{"line":"Small words to say <b>why</b>, <b>so what</b>, and <b>what you think</b>. Cause: <b>parce que</b> (because), <b>car</b> (written), <b>puisque</b> (since, as we know), <b>comme</b> (as, at the start), <b>à cause de</b> (because of, bad) / <b>grâce à</b> (thanks to, good). Result: <b>donc</b>, <b>alors</b>, <b>c'est pourquoi</b>. Opinion: <b>je pense que</b> + normal verb, but <b>je ne pense pas que</b> + subjonctif; <b>à mon avis</b>, <b>selon moi</b>.","words":"Debate words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:44\">Vocab 44 · Ideas & Opinions</a> · <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:50\">Vocab 50 · Arguing & Debating</a>.","steps":[{"tool":"sort","title":"Cause or result?","sub":"Tap the box for each little word.","boxes":[{"k":"c","label":"cause (why)","sub":"parce que"},{"k":"r","label":"result (so)","sub":"donc"}],"cards":[{"t":"parce que","box":"c"},{"t":"donc","box":"r"},{"t":"puisque","box":"c"},{"t":"c'est pourquoi","box":"r"},{"t":"à cause de","box":"c"},{"t":"alors","box":"r"},{"t":"grâce à","box":"c"},{"t":"si bien que","box":"r"},{"t":"comme (at the start)","box":"c","say":"Comme il pleut, je reste."},{"t":"car","box":"c"}]},{"tool":"swap","title":"à cause de or grâce à?","sub":"Pick a sentence and tap « Turn it round »: bad cause or good cause?","button":["Turn it round","Back"],"legend":[["x","the cause word"]],"items":[{"label":"Je suis en retard à cause du trafic.","en":["I'm late because of the traffic.","Thanks to the train, I was on time."],"a":[["s","Je suis en retard",""],["c","à cause du","x"],["o","trafic.",""]],"b":[["c","Grâce au","x"],["o","train,",""],["s","je suis arrivé à l'heure.",""]],"note":"Bad: <b>à cause de</b>. Good: <b>grâce à</b>."},{"label":"Il pleut, donc je reste.","en":["It's raining, so I'm staying.","As it's raining, I'm staying."],"a":[["s","Il pleut,",""],["c","donc","x"],["o","je reste.",""]],"b":[["c","Comme","x"],["s","il pleut,",""],["o","je reste.",""]],"note":"<b>comme</b> goes at the start."},{"label":"Je pense qu'il vient.","en":["I think he's coming.","I don't think he's coming."],"a":[["s","Je",""],["v","pense",""],["q","qu'il",""],["o","vient.","x"]],"b":[["s","Je",""],["n","ne",""],["v","pense",""],["p","pas",""],["q","qu'il",""],["o","vienne.","x"]],"note":"A no brings doubt: the <b>subjonctif</b>, vienne."}]}],"practice":{"choose":[{"q":"Je suis en retard ___ trafic.","en":"I'm late because of the traffic.","opts":["à cause du","grâce au","parce que","car"],"a":"à cause du","why":"A bad cause + a noun.","hint":"<b>à cause du</b> trafic."},{"q":"___ toi, j'ai réussi.","en":"Thanks to you, I passed.","opts":["Grâce à","À cause de","Parce que","Comme"],"a":"Grâce à","why":"A good cause.","hint":"<b>Grâce à</b> toi."},{"q":"Il est malade, ___ il ne vient pas.","en":"He's ill, so he isn't coming.","opts":["donc","car","parce que","puisque"],"a":"donc","why":"A result.","hint":"<b>donc</b>."},{"q":"___ il pleut, nous restons.","en":"As it's raining, we're staying in.","opts":["Comme","Car","Donc","Grâce à"],"a":"Comme","why":"At the start of the sentence.","hint":"<b>Comme</b> il pleut."},{"q":"Je ne pense pas qu'il ___.","en":"I don't think he's coming.","opts":["vienne","vient","viendra","venir"],"a":"vienne","why":"A no to « I think ».","hint":"<b>vienne</b>."},{"q":"___, c'est trop cher.","en":"In my opinion, it's too expensive.","opts":["À mon avis","Selon mon avis","Pour mon avis","En mon avis"],"a":"À mon avis","why":"in my opinion…","hint":"<b>À mon avis</b>."},{"q":"Pourquoi tu pars ? ___ je suis fatigué.","en":"Why are you leaving? Because I'm tired.","opts":["Parce que","Car","Donc","À cause de"],"a":"Parce que","why":"An answer to pourquoi.","hint":"<b>Parce que</b>."}],"build":[{"en":"because of the traffic","tiles":["à cause","du","trafic"],"trap":"grâce","why":"A bad cause.","hint":"<b>à cause du</b> trafic."},{"en":"thanks to you","tiles":["grâce","à","toi"],"trap":"de","why":"A good cause.","hint":"<b>grâce à</b> toi."},{"en":"In my opinion, it's too expensive.","tiles":["À mon avis,","c'est","trop","cher."],"trap":"Selon mon avis,","why":"in my opinion…","hint":"<b>À mon avis</b>."},{"en":"I don't think he's coming.","tiles":["Je","ne pense pas","qu'il","vienne."],"trap":"vient.","why":"A no to « I think »: the subjonctif.","hint":"qu'il <b>vienne</b>."},{"en":"He's ill, so he isn't coming.","tiles":["Il est malade,","donc","il ne vient pas."],"trap":"car","why":"A result.","hint":"<b>donc</b>."}],"spot":[{"words":["Grâce à","la pluie,","le match a été annulé."],"bad":0,"fix":"À cause de","hint":"A bad cause: <b>à cause de</b>.","look":"Is the rain a good thing here?"},{"words":["Je suis en retard","parce que","le trafic."],"bad":1,"fix":"à cause du","hint":"Before a noun: <b>à cause du</b>.","look":"Is a verb or a noun after it?","say":"Je suis en retard à cause du trafic."},{"words":["Je ne pense pas qu'il","vient."],"bad":1,"fix":"vienne.","hint":"A no to « I think »: <b>vienne</b>.","look":"Look at the verb."},{"words":["Car","il pleut,","nous restons."],"bad":0,"fix":"Comme","hint":"At the start: <b>Comme</b> (car never starts a sentence).","look":"Which word can start the sentence?"},{"words":["Je pense qu'il","ait","raison."],"bad":1,"fix":"a","hint":"I think (yes): the normal verb, <b>a</b>.","look":"Is it a doubt?"}]},"drill":[["because of the traffic","à cause du trafic / à cause de la circulation","A bad cause + a noun: <b>à cause de</b>."],["thanks to you","grâce à toi","A good cause: <b>grâce à</b>."],["In my opinion, it's too expensive","À mon avis, c'est trop cher.","<b>À mon avis</b>."],["I don't think he's coming (subjunctive)","Je ne pense pas qu'il vienne.","A no to « I think »: <b>vienne</b>."],["He's ill, so he isn't coming.","Il est malade, donc il ne vient pas.","A result: <b>donc</b>."],["As it's raining, we're staying.","Comme il pleut, nous restons. / Comme il pleut, on reste.","At the start: <b>comme</b>."]]},"48":{"line":"The <b>conditionnel passé</b> says what <b>would have</b> happened, but didn't. The conditional of avoir or être + the past participle: j'<b>aurais</b> fait, elle <b>serait</b> partie. Three phrases to know: j'<b>aurais dû</b> (I should have), j'<b>aurais pu</b> (I could have), j'<b>aurais aimé</b> (I would have liked to). Never right after si.","words":"","steps":[{"tool":"conj","title":"aurais + participle, serais + participle","sub":"Pick a verb, then tap a person.","neg":true,"verbs":[{"inf":"faire","en":"would have done","forms":["aurais fait","aurais fait","aurait fait","aurions fait","auriez fait","auraient fait"],"tail":"autrement","pasAt":1},{"inf":"aller","en":"would have gone","forms":["serais allé(e)","serais allé(e)","serait allé(e)","serions allé(e)s","seriez allé(e)(s)","seraient allé(e)s"],"tail":"à la fête","pasAt":1},{"inf":"devoir","en":"should have","forms":["aurais dû","aurais dû","aurait dû","aurions dû","auriez dû","auraient dû"],"tail":"partir","pasAt":1}]},{"tool":"flip","en":"a","title":"Regret, reproach, wish","sub":"Tap a card: the English comes back as one French pattern.","cards":[{"a":"I should have left.","b":"J'aurais dû partir.","tag":"aurais dû + infinitive"},{"a":"You could have called me!","b":"Tu aurais pu m'appeler !","tag":"aurais pu + infinitive"},{"a":"I would have liked to speak to you.","b":"J'aurais aimé vous parler.","tag":"aurais aimé + infinitive"},{"a":"She would have left.","b":"Elle serait partie.","tag":"être verbs agree"},{"a":"The minister has reportedly resigned.","b":"Le ministre aurait démissionné.","tag":"news not confirmed"}]}],"practice":{"choose":[{"q":"J'___ dû partir plus tôt.","en":"I should have left earlier.","opts":["aurais","aurai","avais","serais"],"a":"aurais","why":"should have = aurais dû.","hint":"j'<b>aurais</b> dû."},{"q":"Tu aurais ___ m'appeler !","en":"You could have called me!","opts":["pu","pouvoir","dû","peux"],"a":"pu","why":"could have…","hint":"aurais <b>pu</b>."},{"q":"Elle ___ aimé venir.","en":"She would have liked to come.","opts":["aurait","serait","aura","avait"],"a":"aurait","why":"aimer takes avoir.","hint":"elle <b>aurait</b> aimé."},{"q":"Nous ___ partis plus tôt.","en":"We would have left earlier.","opts":["serions","aurions","serons","étions"],"a":"serions","why":"partir takes être.","hint":"nous <b>serions</b> partis."},{"q":"Si j'avais su, je ___ venu.","en":"If I had known, I would have come.","opts":["serais","aurais","suis","étais"],"a":"serais","why":"venir takes être.","hint":"je <b>serais</b> venu."},{"q":"Le ministre ___ démissionné.","en":"The minister has reportedly resigned.","opts":["aurait","a","aura","avait"],"a":"aurait","why":"News not confirmed.","hint":"il <b>aurait</b> démissionné."}],"build":[{"en":"I should have left.","tiles":["J'","aurais","dû","partir."],"trap":"parti","why":"aurais dû + the infinitive.","hint":"j'aurais dû <b>partir</b>."},{"en":"You could have called.","tiles":["Tu","aurais","pu","téléphoner."],"trap":"as","why":"could have = aurais pu.","hint":"tu <b>aurais pu</b>."},{"en":"She would have liked to come.","tiles":["Elle","aurait","aimé","venir."],"trap":"serait","why":"aimer takes avoir.","hint":"elle <b>aurait aimé</b>."},{"en":"They would have gone.","tiles":["Ils","seraient","allés."],"trap":"auraient","why":"aller takes être.","hint":"ils <b>seraient allés</b>."},{"en":"We wouldn't have done it.","tiles":["Nous","ne","l'aurions","pas","fait."],"trap":"serions","why":"The no wraps the helper.","hint":"ne l'<b>aurions</b> pas fait."}],"spot":[{"words":["J'","aurai","dû partir."],"bad":1,"fix":"aurais","hint":"should have: <b>aurais</b> (conditional).","look":"will or would?","say":"J'aurais dû partir."},{"words":["Elle","aurait","partie."],"bad":1,"fix":"serait","hint":"partir takes <b>être</b>.","look":"Which helper?"},{"words":["Si j'","aurais su,","je serais venu."],"bad":1,"fix":"avais su,","hint":"After si: the <b>plus-que-parfait</b>.","look":"Look right after si.","say":"Si j'avais su, je serais venu."},{"words":["J'aurais dû","parti."],"bad":1,"fix":"partir.","hint":"aurais dû + the <b>infinitive</b>.","look":"Look at the second verb."},{"words":["Ils","auraient","venus."],"bad":1,"fix":"seraient","hint":"venir takes <b>être</b>.","look":"Which helper?"}]},"drill":[["I should have left","J'aurais dû partir.","<b>aurais dû</b> + the infinitive."],["You could have called (tu)","Tu aurais pu téléphoner. / Tu aurais pu appeler.","<b>aurais pu</b> + the infinitive."],["If I had known, I would have come","Si j'avais su, je serais venu(e).","si + plus-que-parfait, then <b>serais venu</b>."],["She would have liked to come","Elle aurait aimé venir.","<b>aurait aimé</b> + the infinitive."],["We would have left (partir)","Nous serions partis. / Nous serions parties.","être: <b>serions partis</b>."],["They would have done it","Ils l'auraient fait.","<b>auraient fait</b>."]]},"49":{"line":"<b>Type 3</b> imagines a past that didn't happen: si + <b>plus-que-parfait</b>, then the <b>conditionnel passé</b>: Si j'<b>avais su</b>, je <b>serais venu</b>. <b>Mixed</b>: a past cause with a present result (si j'avais fait des études, je <b>serais</b> médecin aujourd'hui). Other ways in: <b>même si</b> + indicative, <b>au cas où</b> + conditional, <b>à condition que</b> + subjonctif.","words":"","steps":[{"tool":"swap","title":"Push it into the past","sub":"Pick a sentence and tap « Type 3 »: both verbs go one step further back.","button":["Type 3","Type 2"],"legend":[["x","after si"],["p","the result"]],"items":[{"label":"Si je savais, je viendrais.","en":["If I knew, I would come.","If I had known, I would have come."],"a":[["q","Si je",""],["v","savais,","x"],["r","je viendrais.","p"]],"b":[["q","Si j'",""],["v","avais su,","x"],["r","je serais venu.","p"]],"note":"imparfait + conditional → <b>plus-que-parfait + conditionnel passé</b>."},{"label":"S'il venait, nous mangerions.","en":["If he came, we would eat.","If he had come, we would have eaten."],"a":[["q","S'il",""],["v","venait,","x"],["r","nous mangerions.","p"]],"b":[["q","S'il",""],["v","était venu,","x"],["r","nous aurions mangé.","p"]]},{"label":"Si tu partais, je serais triste.","en":["If you left, I would be sad.","If you had left, I would have been sad."],"a":[["q","Si tu",""],["v","partais,","x"],["r","je serais triste.","p"]],"b":[["q","Si tu",""],["v","étais parti,","x"],["r","j'aurais été triste.","p"]]},{"label":"Mixed: past cause, result now","en":["If I studied, I would be a doctor.","If I had studied, I would be a doctor today."],"a":[["q","Si je",""],["v","faisais des études,","x"],["r","je serais médecin.","p"]],"b":[["q","Si j'",""],["v","avais fait des études,","x"],["r","je serais médecin aujourd'hui.","p"]],"note":"The cause is past (<b>avais fait</b>), the result is now (<b>serais</b>)."}]},{"tool":"sort","title":"Which mood after it?","sub":"Tap the box for the verb that follows.","boxes":[{"k":"ind","label":"indicative","sub":"même si, sauf si, si jamais"},{"k":"cond","label":"conditional","sub":"au cas où"},{"k":"subj","label":"subjonctif","sub":"à condition que"}],"cards":[{"t":"même si","box":"ind","why":"<b>Même s'il pleut</b>, nous sortirons."},{"t":"au cas où","box":"cond","why":"Prends un parapluie <b>au cas où il pleuvrait</b>."},{"t":"à condition que","box":"subj","why":"Je viendrai <b>à condition que tu m'invites</b>."},{"t":"sauf si","box":"ind","why":"Nous partirons <b>sauf s'il pleut</b>."},{"t":"pourvu que","box":"subj","why":"Nous irons <b>pourvu qu'il fasse</b> beau."},{"t":"dans l'hypothèse où","box":"cond","why":"<b>Dans l'hypothèse où il refuserait</b>…"}]}],"practice":{"choose":[{"q":"Si j'___ su, je l'aurais dit.","en":"If I had known, I would have said it.","opts":["avais","aurais","ai","aurai"],"a":"avais","why":"Type 3: si + plus-que-parfait.","hint":"si j'<b>avais</b> su."},{"q":"S'il était venu, nous ___ mangé.","en":"If he had come, we would have eaten.","opts":["aurions","avions","aurons","serions"],"a":"aurions","why":"The result: conditionnel passé.","hint":"nous <b>aurions</b> mangé."},{"q":"Même s'il ___, je sortirai.","en":"Even if it rains, I'll go out.","opts":["pleut","pleuvrait","pleuve","pleuvra"],"a":"pleut","why":"même si + indicative.","hint":"même s'il <b>pleut</b>."},{"q":"au cas où il ___","en":"in case it rained","opts":["pleuvrait","pleut","pleuve","pleuvait"],"a":"pleuvrait","why":"au cas où + conditional.","hint":"au cas où il <b>pleuvrait</b>."},{"q":"Si j'avais fait des études, je ___ médecin aujourd'hui.","en":"If I had studied, I'd be a doctor today.","opts":["serais","aurais été","serai","étais"],"a":"serais","why":"The result is now.","hint":"je <b>serais</b> médecin."},{"q":"Je viendrai à condition que tu m'___.","en":"I'll come provided you invite me.","opts":["invites","invites-tu","inviterais","invitais"],"a":"invites","why":"à condition que + subjonctif.","hint":"que tu m'<b>invites</b>."}],"build":[{"en":"If I had known, I would have said it.","tiles":["Si j'","avais","su,","je","l'aurais","dit."],"trap":"aurais","why":"si + plus-que-parfait.","hint":"si j'<b>avais su</b>, je l'<b>aurais dit</b>."},{"en":"If he had come, we would have eaten.","tiles":["S'il","était","venu,","nous","aurions","mangé."],"trap":"avait","why":"venir takes être.","hint":"s'il <b>était venu</b>."},{"en":"Even if it rains, I'll go out.","tiles":["Même s'il","pleut,","je","sortirai."],"trap":"pleuvrait,","why":"même si + indicative.","hint":"même s'il <b>pleut</b>."},{"en":"in case it rained","tiles":["au cas où","il","pleuvrait"],"trap":"pleuve","why":"au cas où + conditional.","hint":"au cas où il <b>pleuvrait</b>."},{"en":"I would have come if I had known.","tiles":["Je","serais","venu","si j'","avais su."],"trap":"aurais","why":"The two parts can swap.","hint":"je <b>serais venu</b> si j'avais su."}],"spot":[{"words":["Si j'","aurais su,","je l'aurais dit."],"bad":1,"fix":"avais su,","hint":"Never the conditional after si: <b>avais su</b>.","look":"Look right after si.","say":"Si j'avais su, je l'aurais dit."},{"words":["S'il était venu,","nous mangerions","ensemble hier."],"bad":1,"fix":"nous aurions mangé","hint":"A past result (hier): <b>aurions mangé</b>.","look":"Is the result past or now?"},{"words":["Même s'il","pleuvrait,","je sortirai."],"bad":1,"fix":"pleut,","hint":"même si + <b>indicative</b>.","look":"Look after même si."},{"words":["au cas où","il pleuve"],"bad":1,"fix":"il pleuvrait","hint":"au cas où + <b>conditional</b>.","look":"Which mood after au cas où?"},{"words":["Si tu","avais parti,","j'aurais été triste."],"bad":1,"fix":"étais parti,","hint":"partir takes <b>être</b>.","look":"Which helper?"}]},"drill":[["If I had known, I would have said it","Si j'avais su, je l'aurais dit.","si + <b>plus-que-parfait</b>, then <b>conditionnel passé</b>."],["If he had come, we would have eaten","S'il était venu, nous aurions mangé. / S'il était venu, on aurait mangé.","<b>était venu</b> … <b>aurions mangé</b>."],["Even if it rains, I'll go out","Même s'il pleut, je sortirai.","même si + <b>indicative</b>."],["in case it rained","au cas où il pleuvrait","au cas où + <b>conditional</b>."],["If I had studied, I'd be a doctor today","Si j'avais fait des études, je serais médecin aujourd'hui.","Mixed: past cause, result <b>now</b>."],["I'll come provided you invite me","Je viendrai à condition que tu m'invites.","à condition que + <b>subjonctif</b>."]]},"60":{"line":"Ways to suppose, each with its own mood. <b>Subjonctif</b>: admettons que, supposons que, à supposer que, il est possible que, il se peut que, il est peu probable que. <b>Conditional</b>: au cas où, dans l'hypothèse où. <b>Indicative</b>: si jamais, peut-être que, il est <b>probable</b> que. The surer it is, the more likely the indicative. Formal: <b>Peut-être viendra-t-il</b>.","words":"","steps":[{"tool":"line","title":"From sure to unlikely","sub":"Tap a point: the mood changes as the certainty drops.","now":"","marks":[{"at":-0.9,"label":"sûrement","fr":"Il viendra sûrement.","en":"He'll surely come.","note":"Very likely: <b>indicative</b>."},{"at":-0.45,"label":"il est probable que","fr":"Il est probable qu'il viendra.","html":"Il est probable qu'il <span class=\"gt-end\">viendra</span>.","en":"He'll probably come.","note":"Likely: still the <b>indicative</b>."},{"at":0.0,"label":"peut-être","fr":"Peut-être qu'il viendra.","html":"Peut-être qu'il <span class=\"gt-end\">viendra</span>.","en":"Maybe he will come.","note":"peut-être que: <b>indicative</b>."},{"at":0.45,"label":"il est possible que","fr":"Il est possible qu'il vienne.","html":"Il est possible qu'il <span class=\"gt-end\">vienne</span>.","en":"It's possible he'll come.","note":"Possible: <b>subjonctif</b>."},{"at":0.9,"label":"peu probable","fr":"Il est peu probable qu'il vienne.","html":"Il est peu probable qu'il <span class=\"gt-end\">vienne</span>.","en":"He's unlikely to come.","note":"Unlikely: <b>subjonctif</b>."}]},{"tool":"sort","title":"Which mood?","sub":"Tap the box for the verb that follows.","boxes":[{"k":"subj","label":"subjonctif"},{"k":"cond","label":"conditional"},{"k":"ind","label":"indicative"}],"cards":[{"t":"Admettons que ce … vrai.","box":"subj","why":"<b>soit</b>","say":"Admettons que ce soit vrai."},{"t":"Au cas où tu … en retard…","box":"cond","why":"<b>serais</b>","say":"Au cas où tu serais en retard, préviens-moi."},{"t":"Si jamais tu … un problème…","box":"ind","why":"<b>as</b>","say":"Si jamais tu as un problème, appelle-moi."},{"t":"Il se pourrait qu'il … malade.","box":"subj","why":"<b>soit</b>","say":"Il se pourrait qu'il soit malade."},{"t":"Dans l'hypothèse où il …","box":"cond","why":"<b>refuserait</b>","say":"Dans l'hypothèse où il refuserait…"},{"t":"Il est probable qu'il …","box":"ind","why":"<b>viendra</b>","say":"Il est probable qu'il viendra."},{"t":"À supposer qu'il …","box":"subj","why":"<b>vienne</b>","say":"À supposer qu'il vienne…"},{"t":"Peut-être qu'il …","box":"ind","why":"<b>viendra</b>","say":"Peut-être qu'il viendra."}]}],"practice":{"choose":[{"q":"Admettons que ce ___ vrai.","en":"Let's suppose it's true.","opts":["soit","est","serait","sera"],"a":"soit","why":"admettons que + subjonctif.","hint":"<b>soit</b>."},{"q":"au cas où il ___","en":"in case he refuses","opts":["refuserait","refuse","refusât","refusera"],"a":"refuserait","why":"au cas où + conditional.","hint":"<b>refuserait</b>."},{"q":"Il est probable qu'il ___.","en":"He'll probably come.","opts":["viendra","vienne","viendrait","venir"],"a":"viendra","why":"Likely: indicative.","hint":"<b>viendra</b>."},{"q":"Il est possible qu'il ___.","en":"He may come.","opts":["vienne","viendra","vient","viendrait"],"a":"vienne","why":"Possible: subjonctif.","hint":"<b>vienne</b>."},{"q":"Si jamais tu ___ besoin d'aide, appelle-moi.","en":"If you ever need help, call me.","opts":["as","aies","aurais","auras"],"a":"as","why":"si jamais + indicative.","hint":"si jamais tu <b>as</b>."},{"q":"Peut-être ___.","en":"Perhaps he will come.","opts":["viendra-t-il","il viendra-t-il","vienne-t-il","viendrait-il"],"a":"viendra-t-il","why":"Formal: inversion after peut-être.","hint":"<b>Peut-être viendra-t-il.</b>"}],"build":[{"en":"Let's suppose it's true.","tiles":["Admettons","que","ce","soit","vrai."],"trap":"est","why":"admettons que + subjonctif.","hint":"que ce <b>soit</b> vrai."},{"en":"in case he refuses","tiles":["au cas où","il","refuserait"],"trap":"refuse","why":"au cas où + conditional.","hint":"<b>refuserait</b>."},{"en":"It's likely he'll come.","tiles":["Il est probable","qu'il","viendra."],"trap":"vienne.","why":"Likely: indicative.","hint":"qu'il <b>viendra</b>."},{"en":"If you ever need help","tiles":["Si jamais","tu as","besoin","d'aide"],"trap":"aies","why":"si jamais + indicative.","hint":"si jamais <b>tu as</b> …"},{"en":"He is probably ill.","tiles":["Il","est","probablement","malade."],"trap":"probable","why":"An adverb after the verb.","hint":"il est <b>probablement</b> malade."}],"spot":[{"words":["Admettons que ce","est","vrai."],"bad":1,"fix":"soit","hint":"admettons que + <b>subjonctif</b>.","look":"Which mood?"},{"words":["Au cas où tu","sois","en retard, préviens-moi."],"bad":1,"fix":"serais","hint":"au cas où + <b>conditional</b>.","look":"Which mood?"},{"words":["Il est peu probable qu'il","viendra."],"bad":1,"fix":"vienne.","hint":"Unlikely: <b>subjonctif</b>.","look":"Which mood?"},{"words":["Il est probable qu'il","vienne."],"bad":1,"fix":"viendra.","hint":"Likely: <b>indicative</b>.","look":"How sure is it?"},{"words":["Si jamais tu","aurais","un problème, appelle-moi."],"bad":1,"fix":"as","hint":"si jamais + <b>indicative</b>.","look":"Look after si."}]},"drill":[["Let's suppose it's true","Admettons que ce soit vrai. / Supposons que ce soit vrai.","admettons que + <b>subjonctif</b>."],["in case he refuses","au cas où il refuserait","au cas où + <b>conditional</b>."],["It's likely he'll come","Il est probable qu'il viendra.","Likely: <b>indicative</b>."],["If you ever need help","Si jamais tu as besoin d'aide / Si jamais vous avez besoin d'aide","si jamais + <b>indicative</b>."],["It's possible he'll come","Il est possible qu'il vienne.","Possible: <b>subjonctif</b>."],["Perhaps he will come (formal)","Peut-être viendra-t-il.","Inversion after peut-être: <b>viendra-t-il</b>."]]},"47":{"line":"The <b>subjonctif</b> after need, wish, feeling, doubt and judgment (il est dommage que…). The <b>past subjonctif</b> = the subjonctif of avoir or être + participle, for something <b>earlier</b> than the main verb: Je suis content que tu <b>sois venu</b>. Watch: <b>espérer que</b> and <b>il me semble que</b> take the indicative; <b>il semble que</b> takes the subjonctif. Same subject? The infinitive: je regrette <b>de partir</b>.","words":"","steps":[{"tool":"conj","title":"The past subjonctif","sub":"Pick a verb, then tap a person.","neg":false,"pre":"Je suis content que","verbs":[{"inf":"finir","en":"that … have finished","forms":["aie fini","aies fini","ait fini","ayons fini","ayez fini","aient fini"],"tail":""},{"inf":"venir","en":"that … have come","forms":["sois venu(e)","sois venu(e)","soit venu(e)","soyons venu(e)s","soyez venu(e)(s)","soient venu(e)s"],"tail":""},{"inf":"réussir","en":"that … have passed","forms":["aie réussi","aies réussi","ait réussi","ayons réussi","ayez réussi","aient réussi"],"tail":""}]},{"tool":"sort","title":"Subjonctif or indicative?","sub":"Tap the box for the verb after que.","boxes":[{"k":"s","label":"subjonctif"},{"k":"i","label":"indicative"}],"cards":[{"t":"J'espère qu'il …","box":"i","why":"espérer: <b>viendra</b> (indicative).","say":"J'espère qu'il viendra."},{"t":"Il semble qu'il … malade.","box":"s","why":"il semble que: <b>soit</b>.","say":"Il semble qu'il soit malade."},{"t":"Il me semble qu'il … raison.","box":"i","why":"il me semble que: <b>a</b>.","say":"Il me semble qu'il a raison."},{"t":"Il est dommage que tu … malade.","box":"s","why":"A judgment: <b>sois</b>.","say":"Il est dommage que tu sois malade."},{"t":"Il est évident qu'il … raison.","box":"i","why":"Certain: <b>a</b>.","say":"Il est évident qu'il a raison."},{"t":"Je regrette que tu …","box":"s","why":"A feeling: <b>partes</b>.","say":"Je regrette que tu partes."},{"t":"Penses-tu qu'il … prêt ?","box":"s","why":"A question brings doubt: <b>soit</b>.","say":"Penses-tu qu'il soit prêt ?"},{"t":"Je sais que tu …","box":"i","why":"Certain: <b>viens</b>.","say":"Je sais que tu viens."}]}],"practice":{"choose":[{"q":"Je suis content que tu ___ venu.","en":"I'm glad you came.","opts":["sois","es","aies","seras"],"a":"sois","why":"Earlier + venir takes être.","hint":"que tu <b>sois</b> venu."},{"q":"J'espère qu'il ___.","en":"I hope he'll come.","opts":["viendra","vienne","viendrait","soit venu"],"a":"viendra","why":"espérer: indicative.","hint":"<b>viendra</b>."},{"q":"Je ne pense pas qu'il ___ compris.","en":"I don't think he understood.","opts":["ait","a","aura","avait"],"a":"ait","why":"Doubt, and earlier: past subjonctif.","hint":"qu'il <b>ait</b> compris."},{"q":"Il semble qu'il ___ malade.","en":"It seems he is ill.","opts":["soit","est","sera","serait"],"a":"soit","why":"il semble que…","hint":"<b>soit</b>."},{"q":"Je regrette ___ partir.","en":"I'm sorry to leave.","opts":["de","que je","à","—"],"a":"de","why":"Same subject…","hint":"je regrette <b>de</b> partir."},{"q":"Il est dommage que vous ___ déjà partis.","en":"It's a shame you've already left.","opts":["soyez","êtes","ayez","serez"],"a":"soyez","why":"partir takes être; earlier.","hint":"que vous <b>soyez</b> partis."}],"build":[{"en":"I'm glad you came.","tiles":["Je suis content","que tu","sois","venu."],"trap":"es","why":"Earlier: past subjonctif.","hint":"que tu <b>sois venu</b>."},{"en":"I want you to come.","tiles":["Je veux","que tu","viennes."],"trap":"viens.","why":"A wish: subjonctif.","hint":"que tu <b>viennes</b>."},{"en":"I hope he'll come.","tiles":["J'espère","qu'il","viendra."],"trap":"vienne.","why":"espérer: indicative.","hint":"qu'il <b>viendra</b>."},{"en":"I don't think he understood.","tiles":["Je ne pense pas","qu'il","ait","compris."],"trap":"a","why":"Doubt + earlier.","hint":"qu'il <b>ait</b> compris."},{"en":"I'm sorry to leave.","tiles":["Je","regrette","de","partir."],"trap":"que","why":"Same subject: de + infinitive.","hint":"je regrette <b>de</b> partir."}],"spot":[{"words":["J'espère qu'il","vienne."],"bad":1,"fix":"viendra.","hint":"espérer takes the <b>indicative</b>.","look":"Which mood after espérer?"},{"words":["Je suis content que tu","es venu."],"bad":1,"fix":"sois venu.","hint":"A feeling: <b>sois venu</b>.","look":"Which mood after a feeling?"},{"words":["Il me semble qu'il","ait","raison."],"bad":1,"fix":"a","hint":"il me semble que: <b>indicative</b>.","look":"il semble or il me semble?"},{"words":["Je regrette","que je","parte."],"bad":1,"fix":"de","hint":"Same subject: <b>Je regrette de partir.</b>","look":"Who leaves?","say":"Je regrette de partir."},{"words":["Je ne pense pas qu'il","a compris."],"bad":1,"fix":"ait compris.","hint":"Doubt: <b>ait compris</b>.","look":"Which mood after a no to « I think »?"}]},"drill":[["I'm glad you came (past)","Je suis content que tu sois venu(e).","Earlier: <b>sois venu</b>."],["I want you to come","Je veux que tu viennes.","A wish: <b>viennes</b>."],["I hope he'll come","J'espère qu'il viendra.","espérer: <b>indicative</b>."],["I don't think he understood","Je ne pense pas qu'il ait compris.","Doubt + earlier: <b>ait compris</b>."],["It seems he is ill","Il semble qu'il soit malade.","il semble que: <b>subjonctif</b>."],["I'm sorry to leave","Je regrette de partir.","Same subject: <b>de</b> + infinitive."]]},"53":{"line":"Admit a fact, then turn it round. <b>bien que, quoique</b> + <b>subjonctif</b> (bien qu'il <b>soit</b> fatigué). <b>même si, alors que, tandis que</b> + indicative. <b>malgré, en dépit de</b> + a <b>noun</b> (malgré la pluie). Adverbs: <b>pourtant, cependant, toutefois, néanmoins</b>. Opposition: <b>en revanche, au contraire, contrairement à</b>.","words":"Linking words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:50\">Vocab 50 · Arguing & Debating</a>.","steps":[{"tool":"sort","title":"What comes after it?","sub":"Tap the box.","boxes":[{"k":"s","label":"+ subjonctif","sub":"a clause"},{"k":"i","label":"+ indicative","sub":"a clause"},{"k":"n","label":"+ a noun","sub":""}],"cards":[{"t":"bien que","box":"s","why":"<b>Bien qu'il soit</b> fatigué…"},{"t":"même si","box":"i","why":"<b>Même s'il est</b> fatigué…"},{"t":"malgré","box":"n","why":"<b>Malgré la pluie</b>…"},{"t":"quoique","box":"s","why":"<b>Quoiqu'il pleuve</b>…"},{"t":"alors que","box":"i","why":"Il sort <b>alors qu'il pleut</b>."},{"t":"en dépit de","box":"n","why":"<b>En dépit de ses efforts</b>…"},{"t":"tandis que","box":"i","why":"Elle aime la mer <b>tandis que lui préfère</b> la montagne."},{"t":"contrairement à","box":"n","why":"<b>Contrairement à Paul</b>…"}]},{"tool":"swap","title":"Clause or noun?","sub":"Pick a sentence and tap « Use a noun »: bien que + clause becomes malgré + noun.","button":["Use a noun","Use a clause"],"legend":[["x","the concession word"]],"items":[{"label":"Bien qu'il pleuve, nous sortons.","en":["Although it's raining, we're going out.","Despite the rain, we're going out."],"a":[["c","Bien qu'il","x"],["v","pleuve,",""],["r","nous sortons.",""]],"b":[["c","Malgré","x"],["v","la pluie,",""],["r","nous sortons.",""]]},{"label":"Bien qu'il ait fait des efforts, il a échoué.","en":["Although he made efforts, he failed.","In spite of his efforts, he failed."],"a":[["c","Bien qu'il","x"],["v","ait fait des efforts,",""],["r","il a échoué.",""]],"b":[["c","En dépit de","x"],["v","ses efforts,",""],["r","il a échoué.",""]]},{"label":"Il est riche. Il se plaint.","en":["He is rich. He complains.","He is rich, yet he complains."],"a":[["a","Il est riche.",""],["r","Il se plaint.",""]],"b":[["a","Il est riche,",""],["c","pourtant","x"],["r","il se plaint.",""]]}]}],"practice":{"choose":[{"q":"Bien qu'il ___ fatigué, il travaille.","en":"Although he is tired, he works.","opts":["soit","est","sera","serait"],"a":"soit","why":"bien que + subjonctif.","hint":"bien qu'il <b>soit</b>."},{"q":"___ la pluie, nous sommes sortis.","en":"Despite the rain, we went out.","opts":["Malgré","Bien que","Même si","Alors que"],"a":"Malgré","why":"A noun follows.","hint":"<b>Malgré</b> la pluie."},{"q":"Même s'il ___, je sors.","en":"Even if it rains, I'm going out.","opts":["pleut","pleuve","pleuvrait","pleuvra"],"a":"pleut","why":"même si + indicative.","hint":"même s'il <b>pleut</b>."},{"q":"Le train est cher ; ___, il est rapide.","en":"The train is expensive; on the other hand, it is fast.","opts":["en revanche","malgré","bien que","au contraire de"],"a":"en revanche","why":"on the other hand…","hint":"<b>en revanche</b>."},{"q":"___ Paul, Marie est ponctuelle.","en":"Unlike Paul, Marie is punctual.","opts":["Contrairement à","Au contraire","Malgré","Tandis que"],"a":"Contrairement à","why":"unlike + a person.","hint":"<b>Contrairement à</b> Paul."},{"q":"Il sort ___ il pleut.","en":"He goes out even though it is raining.","opts":["alors qu'","bien qu'","malgré qu'","pourtant"],"a":"alors qu'","why":"+ indicative (pleut).","hint":"<b>alors qu'</b>il pleut."}],"build":[{"en":"Although he is tired","tiles":["Bien","qu'il","soit","fatigué"],"trap":"est","why":"bien que + subjonctif.","hint":"bien qu'il <b>soit</b>."},{"en":"Despite the rain","tiles":["Malgré","la","pluie"],"trap":"que","why":"malgré + a noun.","hint":"<b>Malgré</b> la pluie."},{"en":"Even if it rains","tiles":["Même","s'il","pleut"],"trap":"pleuve","why":"même si + indicative.","hint":"même s'il <b>pleut</b>."},{"en":"He is rich, yet he complains.","tiles":["Il est riche,","pourtant","il se plaint."],"trap":"malgré","why":"yet = pourtant.","hint":"<b>pourtant</b>."},{"en":"She likes the sea whereas he prefers the mountains.","tiles":["Elle aime la mer","tandis que","lui","préfère","la montagne."],"trap":"préfère-t-il","why":"tandis que + indicative.","hint":"<b>tandis que</b> lui préfère."}],"spot":[{"words":["Bien qu'il","est","fatigué, il travaille."],"bad":1,"fix":"soit","hint":"bien que + <b>subjonctif</b>.","look":"Which mood?"},{"words":["Malgré","qu'il pleuve,","nous sortons."],"bad":0,"fix":"Bien que","hint":"A clause: <b>bien que</b> (malgré + a noun).","look":"A noun or a clause follows?","say":"Bien qu'il pleuve, nous sortons."},{"words":["Même s'il","pleuve,","je sors."],"bad":1,"fix":"pleut,","hint":"même si + <b>indicative</b>.","look":"Which mood?"},{"words":["Bien que","la pluie,","nous sortons."],"bad":0,"fix":"Malgré","hint":"A noun: <b>malgré</b>.","look":"A noun or a clause follows?"},{"words":["Quoiqu'il","pleut,","nous sortons."],"bad":1,"fix":"pleuve,","hint":"quoique + <b>subjonctif</b>.","look":"Which mood?"}]},"drill":[["Although he is tired","Bien qu'il soit fatigué / Quoiqu'il soit fatigué","bien que + <b>subjonctif</b>."],["Despite the rain","Malgré la pluie / En dépit de la pluie","malgré + a <b>noun</b>."],["Even if it rains","Même s'il pleut","même si + <b>indicative</b>."],["on the other hand","en revanche / par contre","<b>en revanche</b>."],["He is rich, yet he complains.","Il est riche, pourtant il se plaint.","yet: <b>pourtant</b>."],["Unlike Paul, Marie is punctual.","Contrairement à Paul, Marie est ponctuelle.","unlike: <b>contrairement à</b>."]]},"54":{"line":"Goals and conditions. <b>Same subject</b>: a preposition + the infinitive (<b>pour</b> partir, <b>afin de</b>, <b>avant de</b>, <b>à condition de</b>, <b>sans</b>). <b>Different subjects</b>: que + <b>subjonctif</b> (<b>pour que</b> tu comprennes, <b>avant que</b>, <b>à condition que</b>, <b>pourvu que</b>, <b>à moins que</b>, <b>sans que</b>, <b>jusqu'à ce que</b>). Not these: <b>sauf si</b> (indicative), <b>au cas où</b> (conditional).","words":"","steps":[{"tool":"swap","title":"Same subject or not?","sub":"Pick a sentence and tap « Another subject »: the infinitive becomes que + subjonctif.","button":["Another subject","Same subject"],"legend":[["x","the link"],["p","the subjonctif"]],"items":[{"label":"J'explique pour comprendre.","en":["I explain so as to understand.","I explain so that you understand."],"a":[["s","J'explique",""],["c","pour","x"],["v","comprendre.",""]],"b":[["s","Je t'explique",""],["c","pour que tu","x"],["v","comprennes.","p"]]},{"label":"Je pars avant de dîner.","en":["I leave before having dinner.","I leave before you have dinner."],"a":[["s","Je pars",""],["c","avant de","x"],["v","dîner.",""]],"b":[["s","Je pars",""],["c","avant que tu","x"],["v","dînes.","p"]]},{"label":"Tu réussiras à condition de travailler.","en":["You'll pass provided you work.","You'll pass provided they help you."],"a":[["s","Tu réussiras",""],["c","à condition de","x"],["v","travailler.",""]],"b":[["s","Tu réussiras",""],["c","à condition qu'on","x"],["v","t'aide.","p"]]},{"label":"Il est parti sans dire au revoir.","en":["He left without saying goodbye.","He left without anyone seeing him."],"a":[["s","Il est parti",""],["c","sans","x"],["v","dire au revoir.",""]],"b":[["s","Il est parti",""],["c","sans que personne","x"],["v","le voie.","p"]]}]},{"tool":"sort","title":"Which mood after it?","sub":"Tap the box.","boxes":[{"k":"s","label":"subjonctif"},{"k":"i","label":"indicative"},{"k":"c","label":"conditional"}],"cards":[{"t":"pour que","box":"s"},{"t":"à moins que","box":"s","why":"à moins qu'il (ne) <b>pleuve</b>."},{"t":"sauf si","box":"i","why":"sauf s'il <b>pleut</b>."},{"t":"au cas où","box":"c","why":"au cas où il <b>pleuvrait</b>."},{"t":"jusqu'à ce que","box":"s","why":"jusqu'à ce que j'<b>aie</b> fini."},{"t":"pourvu que","box":"s","why":"pourvu qu'il <b>fasse</b> beau."},{"t":"après que","box":"i","why":"après qu'il <b>est</b> parti (standard grammar)."},{"t":"de peur que","box":"s","why":"de peur qu'on (ne) l'<b>entende</b>."}]}],"practice":{"choose":[{"q":"Je t'explique pour que tu ___.","en":"I'm explaining so that you understand.","opts":["comprennes","comprends","comprendre","comprendras"],"a":"comprennes","why":"pour que + subjonctif.","hint":"pour que tu <b>comprennes</b>."},{"q":"___ partir, ferme la porte.","en":"Before leaving, close the door.","opts":["Avant de","Avant que","Avant","Après de"],"a":"Avant de","why":"Same subject + infinitive.","hint":"<b>Avant de</b> partir."},{"q":"Je viendrai à condition que tu ___.","en":"I'll come provided you come.","opts":["viennes","viens","viendras","venir"],"a":"viennes","why":"à condition que + subjonctif.","hint":"que tu <b>viennes</b>."},{"q":"Nous partirons sauf s'il ___.","en":"We'll leave unless it rains.","opts":["pleut","pleuve","pleuvrait","pleuvra"],"a":"pleut","why":"sauf si + indicative.","hint":"sauf s'il <b>pleut</b>."},{"q":"Attends jusqu'à ce que j'___ fini.","en":"Wait until I've finished.","opts":["aie","ai","aurai","avais"],"a":"aie","why":"jusqu'à ce que + subjonctif.","hint":"que j'<b>aie</b> fini."},{"q":"Il part tôt afin ___ arriver à l'heure.","en":"He leaves early in order to arrive on time.","opts":["d'","que","de que","pour"],"a":"d'","why":"Same subject: afin de.","hint":"afin <b>d'</b>arriver."}],"build":[{"en":"so that you understand","tiles":["pour","que","tu","comprennes"],"trap":"comprends","why":"pour que + subjonctif.","hint":"pour que tu <b>comprennes</b>."},{"en":"Before leaving","tiles":["Avant","de","partir"],"trap":"que","why":"Same subject.","hint":"avant <b>de</b> partir."},{"en":"provided that you come","tiles":["à condition","que","tu","viennes"],"trap":"viens","why":"à condition que + subjonctif.","hint":"que tu <b>viennes</b>."},{"en":"in case it rains","tiles":["au cas où","il","pleuvrait"],"trap":"pleuve","why":"au cas où + conditional.","hint":"au cas où il <b>pleuvrait</b>."},{"en":"He left without anyone seeing him.","tiles":["Il est parti","sans que","personne","le","voie."],"trap":"voit.","why":"sans que + subjonctif.","hint":"sans que personne le <b>voie</b>."}],"spot":[{"words":["Je t'explique","pour que tu","comprends."],"bad":2,"fix":"comprennes.","hint":"pour que + <b>subjonctif</b>.","look":"Which mood?"},{"words":["Avant que","partir,","ferme la porte."],"bad":0,"fix":"Avant de","hint":"Same subject: <b>avant de</b> + infinitive.","look":"Who leaves?"},{"words":["Nous partirons sauf s'il","pleuve."],"bad":1,"fix":"pleut.","hint":"sauf si + <b>indicative</b>.","look":"Which mood after sauf si?"},{"words":["au cas où","il pleuve"],"bad":1,"fix":"il pleuvrait","hint":"au cas où + <b>conditional</b>.","look":"Which mood after au cas où?"},{"words":["Je travaille","pour que je","gagne de l'argent."],"bad":1,"fix":"pour","hint":"Same subject: <b>pour gagner</b>.","look":"Who earns the money?","say":"Je travaille pour gagner de l'argent."}]},"drill":[["so that you understand","pour que tu comprennes / pour que vous compreniez / afin que tu comprennes","pour que + <b>subjonctif</b>."],["Before leaving","Avant de partir","Same subject: <b>avant de</b> + infinitive."],["provided that you come","à condition que tu viennes / pourvu que tu viennes","à condition que + <b>subjonctif</b>."],["in case it rains","au cas où il pleuvrait","au cas où + <b>conditional</b>."],["Wait until I've finished.","Attends jusqu'à ce que j'aie fini.","jusqu'à ce que + <b>subjonctif</b>."],["We'll leave unless it rains.","Nous partirons sauf s'il pleut. / Nous partirons à moins qu'il ne pleuve.","sauf si + indicative, à moins que + subjonctif."]]},"50":{"line":"After a <b>past</b> reporting verb, each tense steps back: présent → <b>imparfait</b>, passé composé → <b>plus-que-parfait</b>, futur → <b>conditionnel</b>, futur antérieur → <b>conditionnel passé</b>, aller + verb → <b>allait</b> + verb. The imparfait, plus-que-parfait, conditional and subjonctif stay. Orders: <b>de</b> + infinitive. Vary the verb: affirmer, ajouter, avouer, prétendre, promettre de, conseiller de, reprocher de.","words":"","steps":[{"tool":"swap","title":"Every tense steps back","sub":"Pick a quote and tap « Report it ».","button":["Report it","The quote"],"legend":[["x","the verb that changes"],["p","stays as it is"]],"items":[{"label":"« J'aurai fini. »","en":["\"I will have finished.\"","He said he would have finished."],"a":[["q","« J'",""],["v","aurai fini. »","x"]],"b":[["i","Il a dit",""],["s","qu'il",""],["v","aurait fini.","x"]],"note":"futur antérieur → <b>conditionnel passé</b>."},{"label":"« Je vais partir. »","en":["\"I'm going to leave.\"","He said he was going to leave."],"a":[["q","« Je",""],["v","vais","x"],["o","partir. »",""]],"b":[["i","Il a dit",""],["s","qu'il",""],["v","allait","x"],["o","partir.",""]]},{"label":"« J'avais oublié. »","en":["\"I had forgotten.\"","He said he had forgotten."],"a":[["q","« J'",""],["v","avais oublié. »","p"]],"b":[["i","Il a dit",""],["s","qu'il",""],["v","avait oublié.","p"]],"note":"The plus-que-parfait <b>stays</b>."},{"label":"« Je voudrais partir. »","en":["\"I would like to leave.\"","He said he would like to leave."],"a":[["q","« Je",""],["v","voudrais","p"],["o","partir. »",""]],"b":[["i","Il a dit",""],["s","qu'il",""],["v","voudrait","p"],["o","partir.",""]],"note":"The conditional <b>stays</b>."},{"label":"« Qu'est-ce qui se passe ? »","en":["\"What is happening?\"","He asked what was happening."],"a":[["q","« Qu'est-ce qui",""],["v","se passe ? »","x"]],"b":[["i","Il a demandé",""],["s","ce qui",""],["v","se passait.","x"]],"note":"qu'est-ce qui → <b>ce qui</b>."},{"label":"« Reste ici ! »","en":["\"Stay here!\"","She told me to stay there."],"a":[["q","«",""],["v","Reste","x"],["o","ici ! »",""]],"b":[["i","Elle m'a dit",""],["v","de rester","x"],["o","là.",""]],"note":"ici → <b>là</b>."}]},{"tool":"flip","en":"a","title":"Better reporting verbs","sub":"Tap a card: « il a dit » becomes something more precise.","cards":[{"a":"He said it was not true. (insisting)","b":"Il a affirmé que ce n'était pas vrai.","tag":"affirmer que"},{"a":"She said she would come. (a promise)","b":"Elle a promis de venir.","tag":"promettre de"},{"a":"He said I should leave. (advice)","b":"Il m'a conseillé de partir.","tag":"conseiller à qqn de"},{"a":"He said he had lied. (admitting)","b":"Il a avoué qu'il avait menti.","tag":"avouer que"},{"a":"She blamed him for being late.","b":"Elle lui a reproché d'être en retard.","tag":"reprocher à qqn de"},{"a":"He claims he was not there.","b":"Il prétend qu'il n'était pas là.","tag":"prétendre que"}]}],"practice":{"choose":[{"q":"« J'ai fini. » → Elle a dit qu'elle ___ fini.","en":"She said she had finished.","opts":["avait","a","aurait","aura"],"a":"avait","why":"passé composé → ?","hint":"<b>avait</b> fini."},{"q":"« Je partirai demain. » → Il a dit qu'il ___ le lendemain.","en":"He said he would leave the next day.","opts":["partirait","partira","partait","était parti"],"a":"partirait","why":"futur → ?","hint":"<b>partirait</b>."},{"q":"« J'aurai fini. » → Il a dit qu'il ___ fini.","en":"He said he would have finished.","opts":["aurait","aura","avait","a"],"a":"aurait","why":"futur antérieur → ?","hint":"<b>aurait</b> fini."},{"q":"« Je vais partir. » → Il a dit qu'il ___ partir.","en":"He said he was going to leave.","opts":["allait","va","irait","est allé"],"a":"allait","why":"aller + verb → ?","hint":"<b>allait</b> partir."},{"q":"« Qu'est-ce que tu fais ? » → Il m'a demandé ___ je faisais.","en":"He asked me what I was doing.","opts":["ce que","qu'est-ce que","que","ce qui"],"a":"ce que","why":"qu'est-ce que → ?","hint":"<b>ce que</b>."},{"q":"Elle a promis ___ venir.","en":"She promised to come.","opts":["de","que","à","—"],"a":"de","why":"promettre…","hint":"promettre <b>de</b>."}],"build":[{"en":"She said she had finished.","tiles":["Elle","a dit","qu'elle","avait","fini."],"trap":"a","why":"passé composé → plus-que-parfait.","hint":"<b>avait</b> fini."},{"en":"He said he would leave the next day.","tiles":["Il","a dit","qu'il","partirait","le lendemain."],"trap":"demain.","why":"demain → le lendemain.","hint":"<b>le lendemain</b>."},{"en":"He asked me what I was doing.","tiles":["Il","m'a demandé","ce que","je","faisais."],"trap":"qu'est-ce que","why":"qu'est-ce que → ce que.","hint":"<b>ce que</b> je faisais."},{"en":"She told me to stay there.","tiles":["Elle","m'a dit","de","rester","là."],"trap":"ici.","why":"ici → là.","hint":"de rester <b>là</b>."},{"en":"He advised me to leave.","tiles":["Il","m'a","conseillé","de","partir."],"trap":"que","why":"conseiller de + infinitive.","hint":"conseillé <b>de</b> partir."}],"spot":[{"words":["Elle a dit qu'elle","a fini."],"bad":1,"fix":"avait fini.","hint":"passé composé → <b>avait fini</b>.","look":"Does the tense step back?"},{"words":["Il a dit qu'il","aura fini."],"bad":1,"fix":"aurait fini.","hint":"futur antérieur → <b>aurait fini</b>.","look":"Does the tense step back?"},{"words":["Il a dit qu'il viendrait","demain."],"bad":1,"fix":"le lendemain.","hint":"demain → <b>le lendemain</b>.","look":"Look at the time word."},{"words":["Il a demandé","qu'est-ce qui","se passait."],"bad":1,"fix":"ce qui","hint":"qu'est-ce qui → <b>ce qui</b>.","look":"Look at the question word."},{"words":["Il m'a dit","que je reste","là."],"bad":1,"fix":"de rester","hint":"An order: <b>de</b> + infinitive.","look":"Look at the order."}]},"drill":[["« J'ai fini. » → Elle a dit...","Elle a dit qu'elle avait fini.","passé composé → <b>plus-que-parfait</b>."],["« Je partirai demain. » → Il a dit...","Il a dit qu'il partirait le lendemain.","futur → <b>conditionnel</b>; demain → <b>le lendemain</b>."],["« Qu'est-ce que tu fais ? » → Il m'a demandé...","Il m'a demandé ce que je faisais.","qu'est-ce que → <b>ce que</b>."],["« Reste ici ! » → Elle m'a dit...","Elle m'a dit de rester là.","An order: <b>de</b> + infinitive; ici → là."],["« J'aurai fini. » → Il a dit...","Il a dit qu'il aurait fini.","futur antérieur → <b>conditionnel passé</b>."],["« Je vais partir. » → Il a dit...","Il a dit qu'il allait partir.","aller → <b>allait</b> + infinitive."]]},"51":{"line":"<b>lequel</b> follows the noun: lequel, laquelle, lesquels, lesquelles. After <b>à</b> and <b>de</b> it joins up like the articles: <b>auquel, auxquels, auxquelles</b> (but à laquelle), <b>duquel, desquels, desquelles</b> (but de laquelle). Check the verb's preposition: penser <b>à</b> → le projet <b>auquel</b> je pense; just <b>de</b> → <b>dont</b>; près <b>de</b>, à côté <b>de</b> → <b>duquel</b>. For people, <b>à qui, avec qui</b> are more natural.","words":"","steps":[{"tool":"agree","title":"lequel follows the noun","sub":"Switch the noun: the pronoun changes with it.","cols":["le projet","la question","les sujets","les raisons"],"rows":[{"forms":["lequel","laquelle","lesquels","lesquelles"],"en":"after avec, pour, sur…"},{"forms":["auquel","à laquelle","auxquels","auxquelles"],"en":"à + lequel"},{"forms":["duquel","de laquelle","desquels","desquelles"],"en":"près de, à côté de + lequel"}]},{"tool":"sort","title":"Which one?","sub":"Look at the verb or preposition. Tap the box.","boxes":[{"k":"au","label":"auquel / à laquelle…","sub":"a verb with à"},{"k":"du","label":"duquel…","sub":"près de, à côté de"},{"k":"dont","label":"dont","sub":"a verb with just de"},{"k":"qui","label":"à qui / avec qui","sub":"a person"}],"cards":[{"t":"le projet … je pense (penser à)","box":"au","why":"le projet <b>auquel</b> je pense","say":"le projet auquel je pense"},{"t":"l'arbre à côté … nous avons pique-niqué","box":"du","why":"l'arbre à côté <b>duquel</b>…","say":"l'arbre à côté duquel nous avons pique-niqué"},{"t":"l'homme … je parle (parler de)","box":"dont","why":"l'homme <b>dont</b> je parle","say":"l'homme dont je parle"},{"t":"l'amie … j'écris (écrire à)","box":"qui","why":"l'amie <b>à qui</b> j'écris","say":"l'amie à qui j'écris"},{"t":"les sujets … elle s'intéresse","box":"au","why":"les sujets <b>auxquels</b> elle s'intéresse","say":"les sujets auxquels elle s'intéresse"},{"t":"la rue près … j'habite","box":"du","why":"la rue près <b>de laquelle</b> j'habite","say":"la rue près de laquelle j'habite"},{"t":"le livre … j'ai besoin (avoir besoin de)","box":"dont","why":"le livre <b>dont</b> j'ai besoin","say":"le livre dont j'ai besoin"},{"t":"les collègues … je travaille","box":"qui","why":"les collègues <b>avec qui</b> je travaille","say":"les collègues avec qui je travaille"}]}],"practice":{"choose":[{"q":"Le projet ___ je pense est difficile.","en":"The project I'm thinking about is difficult.","opts":["auquel","duquel","dont","lequel"],"a":"auquel","why":"penser à + lequel.","hint":"<b>auquel</b>."},{"q":"Les raisons pour ___ il est parti.","en":"The reasons why he left.","opts":["lesquelles","lesquels","laquelle","quoi"],"a":"lesquelles","why":"raisons is feminine plural.","hint":"pour <b>lesquelles</b>."},{"q":"Les questions ___ nous nous intéressons.","en":"The questions we're interested in.","opts":["auxquelles","auxquels","à laquelle","dont"],"a":"auxquelles","why":"s'intéresser à + feminine plural.","hint":"<b>auxquelles</b>."},{"q":"La rue près de ___ j'habite.","en":"The street I live near.","opts":["laquelle","dont","où","lequel"],"a":"laquelle","why":"près de + a feminine noun.","hint":"près <b>de laquelle</b>."},{"q":"L'écrivain ___ j'admire l'œuvre.","en":"The writer whose work I admire.","opts":["dont","que","duquel","auquel"],"a":"dont","why":"whose…","hint":"<b>dont</b>."},{"q":"La réunion à ___ j'ai assisté.","en":"The meeting I attended.","opts":["laquelle","auquelle","lequel","qui"],"a":"laquelle","why":"à + feminine never joins up.","hint":"<b>à laquelle</b>."}],"build":[{"en":"The project I'm thinking about","tiles":["Le","projet","auquel","je","pense"],"trap":"dont","why":"penser à.","hint":"<b>auquel</b> je pense."},{"en":"The reasons for which he left","tiles":["Les","raisons","pour","lesquelles","il est parti"],"trap":"lesquels","why":"raisons is feminine.","hint":"pour <b>lesquelles</b>."},{"en":"The table on which I put my book","tiles":["La","table","sur","laquelle","j'ai posé","mon livre"],"trap":"lequel","why":"table is feminine.","hint":"sur <b>laquelle</b>."},{"en":"The questions we're interested in","tiles":["Les","questions","auxquelles","nous nous intéressons"],"trap":"auxquels","why":"questions is feminine plural.","hint":"<b>auxquelles</b>."},{"en":"the tree next to which we had a picnic","tiles":["l'arbre","à côté","duquel","nous avons pique-niqué"],"trap":"dont","why":"à côté de + lequel.","hint":"à côté <b>duquel</b>."}],"spot":[{"words":["Le projet","dont","je pense","est difficile."],"bad":1,"fix":"auquel","hint":"penser <b>à</b>: auquel.","look":"penser takes which little word?"},{"words":["Les raisons pour","lesquels","il est parti."],"bad":1,"fix":"lesquelles","hint":"raisons is feminine: <b>lesquelles</b>.","look":"Does it match raisons?"},{"words":["La réunion","auquelle","j'ai assisté."],"bad":1,"fix":"à laquelle","hint":"à + laquelle never joins up.","look":"Look at the feminine."},{"words":["L'arbre à côté","dont","nous avons mangé."],"bad":1,"fix":"duquel","hint":"After à côté de: <b>duquel</b>.","look":"dont cannot follow à côté."},{"words":["L'homme","duquel","je parle."],"bad":1,"fix":"dont","hint":"Just de: <b>dont</b>.","look":"Is it just « de »?"}]},"drill":[["The project I'm thinking about","Le projet auquel je pense","penser à: <b>auquel</b>."],["The reasons for which he left","Les raisons pour lesquelles il est parti","pour + feminine plural: <b>lesquelles</b>."],["The table on which I put my book","La table sur laquelle j'ai posé mon livre","sur + feminine: <b>laquelle</b>."],["The questions we are interested in (fem. pl.)","Les questions auxquelles nous nous intéressons","s'intéresser à: <b>auxquelles</b>."],["La rue près de ___ j'habite. (laquelle / dont / où)","laquelle","près de + feminine: <b>de laquelle</b>."],["L'écrivain ___ j'admire l'œuvre. (dont / que / duquel)","dont","whose: <b>dont</b>."]]},"55":{"line":"Spotlight a word. <b>C'est … qui</b> for the subject (C'est Marie <b>qui</b> a téléphoné), <b>c'est … que</b> for anything else, place and time too (C'est à Lyon <b>que</b>…). After qui the verb agrees with the spotlit word: C'est moi qui <b>suis</b>. A whole idea: <b>Ce que</b> je veux, <b>c'est</b>… / <b>Ce dont</b> j'ai besoin, <b>c'est</b>… Or move it out and repeat it: Ce film, je <b>l'</b>ai adoré.","words":"","steps":[{"tool":"swap","title":"Put it in the spotlight","sub":"Pick a sentence and tap « Spotlight it ».","button":["Spotlight it","Plain"],"legend":[["x","the frame"],["p","what is spotlit"]],"items":[{"label":"Marie a téléphoné.","en":["Marie called.","It's Marie who called."],"a":[["p","Marie","p"],["v","a téléphoné.",""]],"b":[["c","C'est","x"],["p","Marie","p"],["q","qui","x"],["v","a téléphoné.",""]],"note":"The subject: <b>qui</b>."},{"label":"Je cherche ce livre.","en":["I'm looking for this book.","It's this book that I'm looking for."],"a":[["s","Je cherche",""],["p","ce livre.","p"]],"b":[["c","C'est","x"],["p","ce livre","p"],["q","que","x"],["s","je cherche.",""]],"note":"The object: <b>que</b>."},{"label":"Nous nous sommes rencontrés à Lyon.","en":["We met in Lyon.","It was in Lyon that we met."],"a":[["s","Nous nous sommes rencontrés",""],["p","à Lyon.","p"]],"b":[["c","C'est","x"],["p","à Lyon","p"],["q","que","x"],["s","nous nous sommes rencontrés.",""]],"note":"A place: <b>que</b>, and à stays with it."},{"label":"J'ai besoin de repos.","en":["I need rest.","What I need is rest."],"a":[["s","J'ai besoin",""],["p","de repos.","p"]],"b":[["c","Ce dont","x"],["s","j'ai besoin,",""],["q","c'est","x"],["p","de repos.","p"]]},{"label":"J'ai adoré ce film.","en":["I loved that film.","That film, I loved it."],"a":[["s","J'ai adoré",""],["p","ce film.","p"]],"b":[["p","Ce film,","p"],["s","je",""],["c","l'","x"],["v","ai adoré.",""]],"note":"Moved to the front, with <b>l'</b> to repeat it."}]},{"tool":"sort","title":"qui or que?","sub":"Is the spotlit word the subject? Tap the box.","boxes":[{"k":"qui","label":"c'est … qui","sub":"the subject"},{"k":"que","label":"c'est … que","sub":"anything else"}],"cards":[{"t":"C'est Paul … a gagné.","box":"qui","why":"<b>qui</b>: Paul won.","say":"C'est Paul qui a gagné."},{"t":"C'est demain … il part.","box":"que","why":"A time: <b>que</b>.","say":"C'est demain qu'il part."},{"t":"C'est à toi … je parle.","box":"que","why":"à toi: <b>que</b>.","say":"C'est à toi que je parle."},{"t":"C'est moi … suis responsable.","box":"qui","why":"<b>qui</b>, and suis agrees with moi.","say":"C'est moi qui suis responsable."},{"t":"Ce sont mes parents … ont payé.","box":"qui","why":"<b>qui</b>.","say":"Ce sont mes parents qui ont payé."},{"t":"C'est ce film … je préfère.","box":"que","why":"The object: <b>que</b>.","say":"C'est ce film que je préfère."}]}],"practice":{"choose":[{"q":"C'est Marie ___ a téléphoné.","en":"It's Marie who called.","opts":["qui","que","qu'","dont"],"a":"qui","why":"Marie is the subject.","hint":"<b>qui</b>."},{"q":"C'est ce livre ___ je cherche.","en":"It's this book I'm looking for.","opts":["que","qui","dont","lequel"],"a":"que","why":"The object.","hint":"<b>que</b>."},{"q":"C'est moi qui ___ raison.","en":"I'm the one who's right.","opts":["ai","a","as","avons"],"a":"ai","why":"The verb agrees with moi.","hint":"moi qui <b>ai</b>."},{"q":"C'est nous qui ___ gagné.","en":"We're the ones who won.","opts":["avons","ont","a","avez"],"a":"avons","why":"The verb agrees with nous.","hint":"nous qui <b>avons</b>."},{"q":"___ j'ai besoin, c'est de repos.","en":"What I need is rest.","opts":["Ce dont","Ce que","Ce qui","Dont"],"a":"Ce dont","why":"avoir besoin de…","hint":"<b>Ce dont</b>."},{"q":"Ce film, je ___ ai adoré.","en":"That film, I loved it.","opts":["l'","le","lui","en"],"a":"l'","why":"Repeat it with a pronoun.","hint":"je <b>l'</b>ai adoré."}],"build":[{"en":"It's Marie who called.","tiles":["C'est","Marie","qui","a","téléphoné."],"trap":"que","why":"The subject: qui.","hint":"C'est Marie <b>qui</b>…"},{"en":"It's this book that I'm looking for.","tiles":["C'est","ce livre","que","je","cherche."],"trap":"qui","why":"The object: que.","hint":"<b>que</b> je cherche."},{"en":"What I need is rest.","tiles":["Ce dont","j'ai besoin,","c'est","de repos."],"trap":"Ce que","why":"avoir besoin de.","hint":"<b>Ce dont</b> j'ai besoin…"},{"en":"It's me who is responsible.","tiles":["C'est","moi","qui","suis","responsable."],"trap":"est","why":"The verb agrees with moi.","hint":"moi qui <b>suis</b>."},{"en":"It was in Lyon that we met.","tiles":["C'est","à Lyon","que","nous nous sommes","rencontrés."],"trap":"où","why":"A place: que.","hint":"C'est à Lyon <b>que</b>…"}],"spot":[{"words":["C'est Marie","que","a téléphoné."],"bad":1,"fix":"qui","hint":"The subject: <b>qui</b>.","look":"Is Marie the subject?"},{"words":["C'est moi qui","est","responsable."],"bad":1,"fix":"suis","hint":"Agrees with moi: <b>suis</b>.","look":"Who is responsible?"},{"words":["C'est à Lyon","où","nous nous sommes rencontrés."],"bad":1,"fix":"que","hint":"With c'est: <b>que</b>, even for a place.","look":"Which glue word goes with c'est?"},{"words":["Ce que","j'ai besoin,","c'est de repos."],"bad":0,"fix":"Ce dont","hint":"avoir besoin de: <b>ce dont</b>.","look":"avoir besoin takes which little word?"},{"words":["C'est","toi","que je parle."],"bad":1,"fix":"à toi","hint":"The preposition stays with it: <b>à toi</b>.","look":"parler takes which little word?","say":"C'est à toi que je parle."}]},"drill":[["It's Marie who called","C'est Marie qui a téléphoné. / C'est Marie qui a appelé.","The subject: <b>qui</b>."],["It's this book that I'm looking for","C'est ce livre que je cherche.","The object: <b>que</b>."],["What I need is rest","Ce dont j'ai besoin, c'est de repos.","avoir besoin de: <b>ce dont</b>."],["It's me who is responsible","C'est moi qui suis responsable.","Agrees with moi: <b>suis</b>."],["C'est moi qui ___ raison. (ai / a)","ai","Agrees with moi: <b>ai</b>."],["Emphasise the place: Nous nous sommes rencontrés à Lyon.","C'est à Lyon que nous nous sommes rencontrés.","A place: <b>c'est … que</b>."]]},"56":{"line":"More ways to wrap round the verb: <b>ne … que</b> = only (je n'ai <b>qu'</b>un frère: the article stays), <b>ne … ni … ni</b> = neither… nor (no article), <b>ne … aucun(e)</b> = no, not one, <b>ne … nulle part</b> = nowhere, <b>ne … guère</b> = hardly. The <b>ne explétif</b> is a formal ne that means nothing: avant qu'il <b>ne</b> parte, plus grand que je <b>ne</b> pensais. Read it, don't translate it as « not ».","words":"","steps":[{"tool":"swap","title":"Swap in another negative","sub":"Pick a sentence and tap « Change it ».","button":["Change it","Back"],"legend":[["n","the two parts"],["x","what changes"]],"items":[{"label":"J'ai dix euros. (only)","en":["I have ten euros.","I only have ten euros."],"a":[["s","J'ai",""],["o","dix euros.",""]],"b":[["s0","Je",""],["ne","n'","n"],["v","ai",""],["q","que","n"],["o","dix euros.",""]],"note":"ne … que is « only », so it is not really a no."},{"label":"Il boit du café et du thé. (neither… nor)","en":["He drinks coffee and tea.","He drinks neither coffee nor tea."],"a":[["s","Il",""],["v","boit",""],["o","du café et du thé.","x"]],"b":[["s","Il",""],["ne","ne","n"],["v","boit",""],["o","ni café ni thé.","n"]],"note":"ni … ni: <b>no article</b>."},{"label":"J'ai une idée. (not one)","en":["I have an idea.","I have no idea."],"a":[["s","J'ai",""],["o","une idée.","x"]],"b":[["s0","Je",""],["ne","n'","n"],["v","ai",""],["o","aucune idée.","n"]]},{"label":"Je le trouve partout. (nowhere)","en":["I find it everywhere.","I can't find it anywhere."],"a":[["s","Je le",""],["v","trouve",""],["o","partout.","x"]],"b":[["s","Je",""],["ne","ne","n"],["l","le",""],["v","trouve",""],["o","nulle part.","n"]]}]},{"tool":"sort","title":"A real no, or a ne explétif?","sub":"Does the ne make it negative? Tap the box.","boxes":[{"k":"neg","label":"a real no","sub":"ne … pas, ne … que…"},{"k":"exp","label":"ne explétif","sub":"no negative meaning"}],"cards":[{"t":"Pars avant qu'il ne revienne.","box":"exp","why":"Leave before he comes back."},{"t":"Il ne revient pas.","box":"neg","why":"He isn't coming back."},{"t":"Je crains qu'il ne soit trop tard.","box":"exp","why":"I'm afraid it's too late."},{"t":"Il est plus grand que je ne pensais.","box":"exp","why":"He is taller than I thought."},{"t":"Je n'ai aucune idée.","box":"neg","why":"I have no idea."},{"t":"À moins qu'il ne pleuve…","box":"exp","why":"Unless it rains…"}]}],"practice":{"choose":[{"q":"Je n'ai ___ dix euros.","en":"I only have ten euros.","opts":["que","pas","aucun","rien"],"a":"que","why":"only…","hint":"ne … <b>que</b>."},{"q":"Il ne boit ___ café ___ thé.","en":"He drinks neither coffee nor tea.","opts":["ni … ni","pas … ni","ni … ou","ou … ou"],"a":"ni … ni","why":"neither… nor…","hint":"<b>ni</b> café <b>ni</b> thé."},{"q":"Je n'ai ___ idée.","en":"I have no idea.","opts":["aucune","aucun","pas de","nulle"],"a":"aucune","why":"idée is feminine.","hint":"<b>aucune</b> idée."},{"q":"Je n'ai qu'___ frère.","en":"I only have one brother.","opts":["un","de","d'","—"],"a":"un","why":"ne … que: the article stays.","hint":"qu'<b>un</b> frère."},{"q":"Il n'a ___ frère ni sœur.","en":"He has neither brother nor sister.","opts":["ni","pas de","aucun","que"],"a":"ni","why":"ni … ni.","hint":"<b>ni</b> frère <b>ni</b> sœur."},{"q":"Pars avant qu'il ___ revienne.","en":"Leave before he comes back.","opts":["ne","ne … pas","pas","n'"],"a":"ne","why":"A formal ne with no negative meaning.","hint":"avant qu'il <b>ne</b> revienne."}],"build":[{"en":"I only have ten euros.","tiles":["Je","n'ai","que","dix euros."],"trap":"pas","why":"only = ne … que.","hint":"<b>n'ai que</b>…"},{"en":"He drinks neither coffee nor tea.","tiles":["Il","ne","boit","ni café","ni thé."],"trap":"pas","why":"No pas with ni … ni.","hint":"<b>ne</b> boit <b>ni</b> … <b>ni</b> …"},{"en":"I have no idea.","tiles":["Je","n'ai","aucune","idée."],"trap":"aucun","why":"idée is feminine.","hint":"<b>aucune</b> idée."},{"en":"I can't find it anywhere.","tiles":["Je","ne","le","trouve","nulle part."],"trap":"partout.","why":"nowhere = nulle part.","hint":"<b>nulle part</b>."},{"en":"taller than I thought","tiles":["plus grand","que","je","ne","pensais"],"trap":"pas","why":"A formal ne, no pas.","hint":"que je <b>ne</b> pensais."}],"spot":[{"words":["Je n'ai","pas que","dix euros."],"bad":1,"fix":"que","hint":"only: <b>ne … que</b> (no pas).","look":"Two negatives?"},{"words":["Il ne boit","pas ni café","ni thé."],"bad":1,"fix":"ni café","hint":"ni … ni takes no <b>pas</b>.","look":"Two negatives?"},{"words":["Je n'ai qu'","de","frère."],"bad":1,"fix":"un","hint":"ne … que: the article <b>stays</b>.","look":"Is it really a no?","say":"Je n'ai qu'un frère."},{"words":["Je n'ai","aucun","idée."],"bad":1,"fix":"aucune","hint":"idée is feminine: <b>aucune</b>.","look":"Does it match idée?"},{"words":["Il ne boit ni","du café","ni du thé."],"bad":1,"fix":"café","hint":"ni … ni: <b>no article</b>.","look":"Look at the article.","say":"Il ne boit ni café ni thé."}]},"drill":[["I only have ten euros","Je n'ai que dix euros.","only: <b>ne … que</b>."],["He drinks neither coffee nor tea","Il ne boit ni café ni thé.","<b>ne … ni … ni</b>, no article."],["I have no idea","Je n'ai aucune idée.","<b>ne … aucune</b>."],["taller than I thought","plus grand que je ne pensais / plus grand que je ne le pensais / plus grand que je pensais","A formal <b>ne</b> with no negative meaning."],["I only have one brother","Je n'ai qu'un frère.","ne … que: the article <b>stays</b>."],["I can't find it anywhere","Je ne le trouve nulle part.","nowhere: <b>ne … nulle part</b>."]]},"58":{"line":"<b>faire</b> + infinitive = to have something done, or to make someone do it: Je <b>fais réparer</b> ma voiture. Il me <b>fait rire</b>. <b>se faire</b> + infinitive = it is done to you: Elle s'est <b>fait couper</b> les cheveux. <b>laisser</b> + infinitive = to let: <b>Laisse-le parler</b>. Pronouns go before faire, which stays glued to the infinitive; <b>fait</b> never agrees here: je les ai <b>fait</b> venir.","words":"","steps":[{"tool":"swap","title":"Do it, or have it done","sub":"Pick a sentence and tap « Have it done ».","button":["Have it done","Do it yourself"],"legend":[["x","faire / laisser"],["p","the pronoun"]],"items":[{"label":"Je répare ma voiture.","en":["I repair my car.","I'm having my car repaired."],"a":[["s","Je",""],["v","répare",""],["o","ma voiture.",""]],"b":[["s","Je",""],["f","fais","x"],["v","réparer",""],["o","ma voiture.",""]]},{"label":"Je la répare. (it)","en":["I repair it.","I'm having it repaired."],"a":[["s","Je",""],["p","la","p"],["v","répare.",""]],"b":[["s","Je",""],["p","la","p"],["f","fais","x"],["v","réparer.",""]],"note":"The pronoun goes before <b>faire</b>."},{"label":"Elle a coupé ses cheveux.","en":["She cut her hair.","She had her hair cut."],"a":[["s","Elle",""],["v","a coupé",""],["o","ses cheveux.",""]],"b":[["s","Elle",""],["p","s'est","p"],["f","fait","x"],["v","couper",""],["o","les cheveux.",""]],"note":"<b>se faire</b> + infinitive: done to her. fait does not agree."},{"label":"Il parle. (let him)","en":["He speaks.","Let him speak!"],"a":[["s","Il",""],["v","parle.",""]],"b":[["f","Laisse-","x"],["p","le","p"],["v","parler !",""]]},{"label":"Ils sont venus. (I had them come)","en":["They came.","I sent for them."],"a":[["s","Ils",""],["v","sont venus.",""]],"b":[["s","Je",""],["p","les","p"],["f","ai fait","x"],["v","venir.",""]],"note":"<b>fait</b>, never faits, in this pattern."}]},{"tool":"flip","en":"b","title":"Useful faire phrases","sub":"Tap a card.","cards":[{"a":"faire savoir","b":"to let someone know"},{"a":"faire venir","b":"to send for"},{"a":"faire attendre","b":"to keep waiting"},{"a":"faire peur à","b":"to frighten"},{"a":"faire semblant de","b":"to pretend to"},{"a":"laisser tomber","b":"to drop, give up"},{"a":"se faire voler","b":"to have something stolen"}]}],"practice":{"choose":[{"q":"Je ___ réparer ma voiture.","en":"I'm having my car repaired.","opts":["fais","laisse","répare","suis"],"a":"fais","why":"to have it done…","hint":"je <b>fais</b> réparer."},{"q":"Ça m'a fait ___.","en":"It made me laugh.","opts":["rire","ri","rit","riant"],"a":"rire","why":"faire + the infinitive.","hint":"fait <b>rire</b>."},{"q":"Laisse-___ parler !","en":"Let him speak!","opts":["le","lui","il","se"],"a":"le","why":"In a yes-order, after the verb.","hint":"Laisse-<b>le</b> parler."},{"q":"Elle s'est ___ couper les cheveux.","en":"She had her hair cut.","opts":["fait","faite","faits","faire"],"a":"fait","why":"fait never agrees here.","hint":"s'est <b>fait</b> couper."},{"q":"Je ___ fais réparer.","en":"I'm having it repaired.","opts":["la","lui","en","y"],"a":"la","why":"Before faire.","hint":"je <b>la</b> fais réparer."},{"q":"Je les ai ___ venir.","en":"I sent for them.","opts":["fait","faits","faites","faire"],"a":"fait","why":"fait never agrees here.","hint":"ai <b>fait</b> venir."}],"build":[{"en":"I'm having my car repaired.","tiles":["Je","fais","réparer","ma voiture."],"trap":"répare","why":"faire + infinitive.","hint":"je <b>fais réparer</b>."},{"en":"It made me laugh.","tiles":["Ça","m'a","fait","rire."],"trap":"ri.","why":"faire + infinitive.","hint":"<b>m'a fait rire</b>."},{"en":"Let him speak!","tiles":["Laisse-le","parler !"],"trap":"Laisse-lui","why":"laisser + le.","hint":"<b>Laisse-le</b> parler."},{"en":"She had her hair cut.","tiles":["Elle","s'est","fait","couper","les cheveux."],"trap":"faite","why":"se faire + infinitive.","hint":"s'est <b>fait couper</b>."},{"en":"I'm having it repaired.","tiles":["Je","la","fais","réparer."],"trap":"réparée.","why":"The pronoun before faire.","hint":"je <b>la fais</b> réparer."}],"spot":[{"words":["Je","fais la","réparer."],"bad":1,"fix":"la fais","hint":"The pronoun goes <b>before faire</b>.","look":"Where does the pronoun go?","say":"Je la fais réparer."},{"words":["Elle","s'est","faite","couper les cheveux."],"bad":2,"fix":"fait","hint":"<b>fait</b> never agrees here.","look":"Does fait agree?"},{"words":["Je les ai","faits","venir."],"bad":1,"fix":"fait","hint":"<b>fait</b> never agrees here.","look":"Does fait agree?"},{"words":["Ça","m'a fait","ri."],"bad":2,"fix":"rire.","hint":"faire + the <b>infinitive</b>.","look":"Look at the second verb."},{"words":["Laisse-","lui","parler !"],"bad":1,"fix":"le","hint":"The person is the direct object: <b>le</b>.","look":"le or lui?","say":"Laisse-le parler !"}]},"drill":[["I'm having my car repaired","Je fais réparer ma voiture.","<b>faire</b> + infinitive."],["It made me laugh","Ça m'a fait rire. / Cela m'a fait rire.","<b>faire rire</b>."],["Let him speak","Laisse-le parler.","<b>laisser</b> + infinitive."],["She had her hair cut","Elle s'est fait couper les cheveux.","<b>se faire</b> + infinitive; fait does not agree."],["I'm having it repaired (la voiture)","Je la fais réparer.","The pronoun before <b>faire</b>."],["I sent for them","Je les ai fait venir.","<b>fait</b> never agrees here."]]},"52":{"line":"Two -ant forms that look alike. The <b>participe présent</b> is a verb: it <b>never changes</b> and can take an object (des enfants <b>courant</b> dans la rue). The <b>adjectif verbal</b> is an adjective: it <b>agrees</b> and you can put très before it (une histoire <b>passionnante</b>). Some are spelt differently: fatiguant / <b>fatigant</b>, différant / <b>différent</b>, convainquant / <b>convaincant</b>. Past form: <b>Ayant fini</b>, il est parti.","words":"","steps":[{"tool":"sort","title":"Verb or adjective?","sub":"Could you say très, or put it after être? Then it is an adjective. Tap the box.","boxes":[{"k":"v","label":"participe présent","sub":"never changes"},{"k":"a","label":"adjectif verbal","sub":"agrees"}],"cards":[{"t":"une histoire passionnante","box":"a","why":"très passionnante: an adjective."},{"t":"des enfants courant dans la rue","box":"v","why":"qui courent: a verb."},{"t":"des chiffres surprenants","box":"a","why":"très surprenants."},{"t":"Surprenant tout le monde, il a gagné.","box":"v","why":"It has an object (tout le monde)."},{"t":"une journée fatigante","box":"a","why":"Adjective spelling: <b>fatigant</b>."},{"t":"Fatiguant ses amis, il parlait sans cesse.","box":"v","why":"Verb spelling: <b>fatiguant</b>."}]},{"tool":"flip","title":"Two spellings","sub":"Tap a card: the verb form, then the adjective.","cards":[{"a":"fatiguant","b":"fatigant","tag":"fatiguer"},{"a":"différant","b":"différent","tag":"différer"},{"a":"excellant","b":"excellent","tag":"exceller"},{"a":"négligeant","b":"négligent","tag":"négliger"},{"a":"convainquant","b":"convaincant","tag":"convaincre"},{"a":"provoquant","b":"provocant","tag":"provoquer"},{"a":"précédant","b":"précédent","tag":"précéder"}]}],"practice":{"choose":[{"q":"une histoire ___","en":"an exciting story","opts":["passionnante","passionnant","passionnants","en passionnant"],"a":"passionnante","why":"An adjective agrees.","hint":"une histoire <b>passionnante</b>."},{"q":"Les enfants, ___, criaient.","en":"The children, running, were shouting.","opts":["courant","courants","courantes","couru"],"a":"courant","why":"A verb: never changes.","hint":"<b>courant</b>."},{"q":"___ mangé, il est parti.","en":"Having eaten, he left.","opts":["Ayant","Étant","Avant","En"],"a":"Ayant","why":"manger takes avoir.","hint":"<b>Ayant</b> mangé."},{"q":"une journée ___","en":"a tiring day","opts":["fatigante","fatiguante","fatigant","fatiguant"],"a":"fatigante","why":"The adjective spelling, feminine.","hint":"<b>fatigante</b>."},{"q":"un argument ___","en":"a convincing argument","opts":["convaincant","convainquant","convaincu","convaincante"],"a":"convaincant","why":"The adjective spelling.","hint":"<b>convaincant</b>."},{"q":"___ parti tôt, elle est arrivée à l'heure.","en":"Having left early, she arrived on time.","opts":["Étant","Ayant","En","Été"],"a":"Étant","why":"partir takes être.","hint":"<b>Étant</b> partie…"}],"build":[{"en":"an exciting story","tiles":["une","histoire","passionnante"],"trap":"passionnant","why":"The adjective agrees.","hint":"<b>passionnante</b>."},{"en":"The children, running, were shouting.","tiles":["Les enfants,","courant,","criaient."],"trap":"courants,","why":"A verb: never changes.","hint":"<b>courant</b>."},{"en":"Having eaten, he left.","tiles":["Ayant","mangé,","il","est parti."],"trap":"Étant","why":"manger takes avoir.","hint":"<b>Ayant mangé</b>."},{"en":"a tiring day","tiles":["une","journée","fatigante"],"trap":"fatiguante","why":"The adjective spelling.","hint":"<b>fatigante</b>."},{"en":"different opinions","tiles":["des","opinions","différentes"],"trap":"différantes","why":"The adjective spelling, feminine plural.","hint":"<b>différentes</b>."}],"spot":[{"words":["une histoire","passionnant"],"bad":1,"fix":"passionnante","hint":"The adjective <b>agrees</b>.","look":"Does it agree with histoire?"},{"words":["Les enfants,","courants,","criaient."],"bad":1,"fix":"courant,","hint":"The participle <b>never changes</b>.","look":"Verb or adjective?"},{"words":["une journée","fatiguante"],"bad":1,"fix":"fatigante","hint":"Adjective spelling: <b>fatigante</b>.","look":"Look at the spelling."},{"words":["un argument","convainquant"],"bad":1,"fix":"convaincant","hint":"Adjective spelling: <b>convaincant</b>.","look":"Look at the spelling."},{"words":["Étant","mangé,","il est parti."],"bad":0,"fix":"Ayant","hint":"manger takes <b>avoir</b>.","look":"Which helper?"}]},"drill":[["an exciting story (passionner)","une histoire passionnante","An adjective: it <b>agrees</b>."],["The children, running, shouted (courir)","Les enfants, courant, criaient.","A verb: it <b>never changes</b>."],["Having eaten, he left (manger)","Ayant mangé, il est parti.","<b>Ayant</b> + participle."],["The participle of fatiguer","fatiguant","The verb keeps the u: <b>fatiguant</b>."],["a tiring day","une journée fatigante","The adjective: <b>fatigante</b>."],["a convincing argument","un argument convaincant","The adjective: <b>convaincant</b>."]]},"57":{"line":"<b>Nominalisation</b> turns a verb or an adjective into a noun, for a compact, formal style: Les prix ont augmenté → <b>l'augmentation des prix</b>. The thing affected follows <b>de</b>. Endings tell the gender: <b>-tion, -sion, -ité, -ance, -ure</b> feminine; <b>-ment, -age</b> masculine. Link the nouns with entraîner, permettre, favoriser, provoquer. Mix with verbs: only nouns sounds heavy.","words":"Formal words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:54\">Vocab 54 · Formal & Official French</a> · <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:40\">Vocab 40 · Business & the Economy</a>.","steps":[{"tool":"flip","title":"Verb → noun","sub":"Tap a card.","cards":[{"a":"arriver","b":"l'arrivée"},{"a":"partir","b":"le départ"},{"a":"décider","b":"la décision"},{"a":"augmenter","b":"l'augmentation"},{"a":"réduire","b":"la réduction"},{"a":"développer","b":"le développement"},{"a":"échouer","b":"l'échec"},{"a":"réussir","b":"la réussite"},{"a":"choisir","b":"le choix"},{"a":"croître","b":"la croissance"},{"a":"perdre","b":"la perte"},{"a":"mettre en place","b":"la mise en place"}]},{"tool":"swap","title":"From a sentence to a noun phrase","sub":"Pick a sentence and tap « Make it formal ».","button":["Make it formal","Plain"],"legend":[["x","the new noun"]],"items":[{"label":"Les prix ont augmenté, ce qui inquiète les clients.","en":["Prices have gone up, which worries customers.","The rise in prices worries customers."],"a":[["a","Les prix",""],["v","ont augmenté,","x"],["r","ce qui inquiète les clients.",""]],"b":[["v","L'augmentation","x"],["a","des prix",""],["r","inquiète les clients.",""]]},{"label":"Il est arrivé en retard, ce qui a surpris tout le monde.","en":["He arrived late, which surprised everyone.","His late arrival surprised everyone."],"a":[["a","Il",""],["v","est arrivé en retard,","x"],["r","ce qui a surpris tout le monde.",""]],"b":[["v","Son arrivée tardive","x"],["r","a surpris tout le monde.",""]]},{"label":"Si on développe les transports, on réduit la pollution.","en":["If we develop transport, we reduce pollution.","Developing transport allows a reduction in pollution."],"a":[["a","Si on",""],["v","développe","x"],["o","les transports,",""],["r","on réduit la pollution.",""]],"b":[["v","Le développement","x"],["o","des transports",""],["r","permet une réduction de la pollution.",""]]},{"label":"C'est difficile, et c'est important.","en":["It's difficult, and it matters.","The difficulty, and the importance."],"a":[["a","C'est",""],["v","difficile,","x"],["r","et c'est important.",""]],"b":[["v","La difficulté","x"],["r","et l'importance","x"]],"note":"Adjectives too: difficile → <b>la difficulté</b>."}]},{"tool":"sort","title":"le or la?","sub":"The ending gives the gender. Tap the box.","boxes":[{"k":"m","label":"le (masculine)","sub":"-ment, -age"},{"k":"f","label":"la (feminine)","sub":"-tion, -ité, -ance, -ure"}],"cards":[{"t":"développement","box":"m","why":"<b>le</b> développement"},{"t":"création","box":"f","why":"<b>la</b> création"},{"t":"apprentissage","box":"m","why":"<b>l'</b>apprentissage (m.)"},{"t":"possibilité","box":"f","why":"<b>la</b> possibilité"},{"t":"importance","box":"f","why":"<b>l'</b>importance (f.)"},{"t":"changement","box":"m","why":"<b>le</b> changement"},{"t":"ouverture","box":"f","why":"<b>l'</b>ouverture (f.)"},{"t":"silence","box":"m","why":"A trap: <b>le</b> silence."}]}],"practice":{"choose":[{"q":"décider → la ___","en":"the decision","opts":["décision","décidement","décidation","décide"],"a":"décision","why":"-sion…","hint":"la <b>décision</b>."},{"q":"l'augmentation ___ prix","en":"the increase in prices","opts":["des","de","aux","les"],"a":"des","why":"The thing affected follows de.","hint":"l'augmentation <b>des</b> prix."},{"q":"croître → la ___","en":"growth","opts":["croissance","croîtrement","croissement","croisure"],"a":"croissance","why":"An -ance noun.","hint":"la <b>croissance</b>."},{"q":"échouer → ___","en":"failure","opts":["l'échec","l'échouement","l'échouage","l'échoue"],"a":"l'échec","why":"A short irregular one.","hint":"<b>l'échec</b>."},{"q":"___ développement","en":"the development","opts":["le","la","les","l'"],"a":"le","why":"-ment is masculine.","hint":"<b>le</b> développement."},{"q":"difficile → la ___","en":"difficulty","opts":["difficulté","difficultance","difficilement","difficilité"],"a":"difficulté","why":"An -té noun.","hint":"la <b>difficulté</b>."}],"build":[{"en":"the increase in prices","tiles":["l'augmentation","des","prix"],"trap":"aux","why":"de + les = des.","hint":"l'augmentation <b>des</b> prix."},{"en":"the reduction in taxes","tiles":["la","réduction","des","impôts"],"trap":"le","why":"-tion is feminine.","hint":"<b>la</b> réduction."},{"en":"His late arrival surprised everyone.","tiles":["Son","arrivée","tardive","a surpris","tout le monde."],"trap":"arrivé","why":"The noun: arrivée.","hint":"son <b>arrivée</b> tardive."},{"en":"The development of transport","tiles":["Le","développement","des","transports"],"trap":"La","why":"-ment is masculine.","hint":"<b>le</b> développement."},{"en":"the opening of the shop","tiles":["l'","ouverture","du","magasin"],"trap":"le","why":"de + le = du.","hint":"l'ouverture <b>du</b> magasin."}],"spot":[{"words":["La","développement","des transports"],"bad":0,"fix":"Le","hint":"-ment is masculine: <b>le</b>.","look":"Look at the ending."},{"words":["L'augmentation","de les","prix"],"bad":1,"fix":"des","hint":"de + les → <b>des</b>.","look":"Look at de + les."},{"words":["Le","décision","est prise."],"bad":0,"fix":"La","hint":"-sion is feminine: <b>la</b>.","look":"Look at the ending."},{"words":["La","réussissement","du projet"],"bad":1,"fix":"réussite","hint":"réussir → <b>la réussite</b>.","look":"Look at the noun."},{"words":["La","silence","était total."],"bad":0,"fix":"Le","hint":"A trap: <b>le</b> silence.","look":"Is -ence always feminine?"}]},"drill":[["the decision","la décision","décider → <b>la décision</b>."],["the increase in prices","l'augmentation des prix","The thing affected follows <b>de</b>."],["the development","le développement","-ment: <b>masculine</b>."],["the difficulty","la difficulté","difficile → <b>la difficulté</b>."],["croître → noun","la croissance","croître → <b>la croissance</b>."],["diminuer → noun","la diminution","diminuer → <b>la diminution</b>."]]},"59":{"line":"The <b>passé simple</b> is the past of written stories (novels, tales, history): read it, but speak and write with the passé composé. Spot it by the endings, mostly <b>il</b> and <b>ils</b>: <b>-a / -èrent</b> (-er verbs: il parla, ils parlèrent), <b>-it / -irent</b>, <b>-ut / -urent</b>, <b>-int / -inrent</b>. Common ones: il <b>fut</b> (être), il <b>eut</b> (avoir), il <b>fit</b>, il <b>vit</b>, il <b>prit</b>, il <b>vint</b>, il <b>naquit</b>. Watch il parla (past) vs il parlera (future).","words":"","steps":[{"tool":"conj","title":"The regular endings","sub":"Pick a verb, then tap a person.","neg":false,"verbs":[{"inf":"parler","en":"spoke","stem":"parl","forms":["parlai","parlas","parla","parlâmes","parlâtes","parlèrent"],"tail":""},{"inf":"finir","en":"finished","stem":"fin","forms":["finis","finis","finit","finîmes","finîtes","finirent"],"tail":""},{"inf":"vendre","en":"sold","stem":"vend","forms":["vendis","vendis","vendit","vendîmes","vendîtes","vendirent"],"tail":""},{"inf":"être","en":"was","forms":["fus","fus","fut","fûmes","fûtes","furent"],"tail":""}]},{"tool":"flip","title":"Back to the infinitive","sub":"Tap a card: which verb is it?","cards":[{"a":"il fut","b":"être"},{"a":"il eut","b":"avoir"},{"a":"il alla","b":"aller"},{"a":"il fit","b":"faire"},{"a":"il vit","b":"voir"},{"a":"il prit","b":"prendre"},{"a":"il mit","b":"mettre"},{"a":"il vint","b":"venir"},{"a":"il put","b":"pouvoir"},{"a":"il sut","b":"savoir"},{"a":"il naquit","b":"naître"},{"a":"il mourut","b":"mourir"}]},{"tool":"swap","title":"From a story to speech","sub":"Pick a sentence and tap « Say it »: the passé simple becomes the passé composé.","button":["Say it","Write it"],"legend":[["x","the past verbs"]],"items":[{"label":"Il ouvrit la porte et entra.","en":["He opened the door and went in. (written)","He opened the door and went in. (spoken)"],"a":[["s","Il",""],["v","ouvrit","x"],["o","la porte et",""],["w","entra.","x"]],"b":[["s","Il",""],["v","a ouvert","x"],["o","la porte et",""],["w","il est entré.","x"]]},{"label":"Ils allèrent au marché.","en":["They went to the market. (written)","They went to the market. (spoken)"],"a":[["s","Ils",""],["v","allèrent","x"],["o","au marché.",""]],"b":[["s","Ils",""],["v","sont allés","x"],["o","au marché.",""]]},{"label":"Victor Hugo naquit en 1802.","en":["Victor Hugo was born in 1802. (written)","Victor Hugo was born in 1802. (spoken)"],"a":[["s","Victor Hugo",""],["v","naquit","x"],["o","en 1802.",""]],"b":[["s","Victor Hugo",""],["v","est né","x"],["o","en 1802.",""]]}]}],"practice":{"choose":[{"q":"il alla → ___","en":"he went","opts":["aller","allumer","avoir","aimer"],"a":"aller","why":"Which infinitive?","hint":"<b>aller</b>."},{"q":"ils furent → ___","en":"they were","opts":["être","faire","fuir","avoir"],"a":"être","why":"Which infinitive?","hint":"<b>être</b>."},{"q":"elle prit → ___","en":"she took","opts":["prendre","prier","pouvoir","plaire"],"a":"prendre","why":"Which infinitive?","hint":"<b>prendre</b>."},{"q":"il vit → ___","en":"he saw","opts":["voir","vivre","venir","vouloir"],"a":"voir","why":"il vit can be vivre in the present, but in a story…","hint":"<b>voir</b> (passé simple)."},{"q":"Il ___ longtemps. (parler, passé simple)","en":"He spoke for a long time.","opts":["parla","parlera","parlait","parlerait"],"a":"parla","why":"-er verbs: -a, with no r.","hint":"il <b>parla</b> (il parlera is the future)."},{"q":"Ils ___ au marché. (aller, passé simple)","en":"They went to the market.","opts":["allèrent","allaient","allirent","iront"],"a":"allèrent","why":"-er verbs: -èrent.","hint":"ils <b>allèrent</b>."}],"build":[{"en":"he went (passé simple)","tiles":["il","alla"],"trap":"alla-t","why":"-er verb: -a.","hint":"il <b>alla</b>."},{"en":"they were (passé simple)","tiles":["ils","furent"],"trap":"étaient","why":"être.","hint":"ils <b>furent</b>."},{"en":"she took (passé simple)","tiles":["elle","prit"],"trap":"prenit","why":"prendre.","hint":"elle <b>prit</b>."},{"en":"he had (passé simple)","tiles":["il","eut"],"trap":"avait","why":"avoir.","hint":"il <b>eut</b>."},{"en":"He opened the door and went in. (spoken)","tiles":["Il","a ouvert","la porte","et","il est entré."],"trap":"ouvrit","why":"In speech: the passé composé.","hint":"il <b>a ouvert</b>."}],"spot":[{"words":["ils","allirent"],"bad":1,"fix":"allèrent","hint":"-er verbs: <b>-èrent</b>.","look":"Look at the ending."},{"words":["il","prenit"],"bad":1,"fix":"prit","hint":"prendre: <b>prit</b>.","look":"An irregular one."},{"words":["elle","venit"],"bad":1,"fix":"vint","hint":"venir: <b>vint</b>.","look":"An irregular one."},{"words":["il","naissa","en 1802"],"bad":1,"fix":"naquit","hint":"naître: <b>naquit</b>.","look":"An irregular one."},{"words":["Hier, au téléphone,","je parlai","avec Paul."],"bad":1,"fix":"j'ai parlé","hint":"In speech: the <b>passé composé</b>.","look":"Is this a written story?","say":"Hier, au téléphone, j'ai parlé avec Paul."}]},"drill":[["Passé simple: il (aller)","il alla","-er verbs: <b>-a</b>."],["Passé simple: ils (être)","ils furent","être: <b>furent</b>."],["Passé simple: elle (prendre)","elle prit","prendre: <b>prit</b>."],["Passé simple: il (avoir)","il eut","avoir: <b>eut</b>."],["Passé simple: il (venir)","il vint","venir: <b>vint</b>."],["Passé simple: ils (parler)","ils parlèrent","-er verbs: <b>-èrent</b>."]]},"v33":{"line":"At B2, pick the tense from the <b>meaning</b>. On one line: before the past (<b>plus-que-parfait</b>), the past (<b>passé composé</b> for events, <b>imparfait</b> for scenes), now (<b>présent</b>), after now (<b>futur</b>), done before a future moment (<b>futur antérieur</b>). Off the line: unreal (<b>conditionnel</b>), wished or doubted (<b>subjonctif</b>). Time words are the fastest clue.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"line","title":"One verb on the line: faire","sub":"Tap a point.","now":"","marks":[{"at":-0.9,"label":"plus-que-parfait","fr":"J'avais fait.","en":"I had done."},{"at":-0.55,"label":"passé composé","fr":"J'ai fait.","en":"I did."},{"at":-0.25,"label":"imparfait","fr":"Je faisais.","en":"I was doing."},{"at":0.0,"label":"présent","fr":"Je fais.","en":"I do."},{"at":0.4,"label":"futur antérieur","fr":"J'aurai fait.","en":"I will have done."},{"at":0.75,"label":"futur","fr":"Je ferai.","en":"I will do."}]},{"tool":"sort","title":"Which tense after it?","sub":"Tap the box for the tense the time word asks for.","boxes":[{"k":"pres","label":"présent"},{"k":"pc","label":"passé composé"},{"k":"fut","label":"futur / futur antérieur"}],"cards":[{"t":"J'habite ici depuis deux ans.","box":"pres","why":"depuis, still true: <b>présent</b>."},{"t":"Je suis arrivé il y a une heure.","box":"pc","why":"il y a: <b>passé composé</b>."},{"t":"Je pars dans deux heures.","box":"fut","why":"dans: <b>futur</b> (or the present)."},{"t":"Ça fait deux ans que j'étudie le français.","box":"pres","why":"ça fait … que: <b>présent</b>."},{"t":"Dès que j'aurai fini, je partirai.","box":"fut","why":"dès que, future: <b>futur antérieur</b>."},{"t":"J'ai travaillé pendant trois heures.","box":"pc","why":"pendant, finished: <b>passé composé</b>."}]}],"practice":{"choose":[{"q":"J'___ ici depuis deux ans.","en":"I've lived here for two years.","opts":["habite","ai habité","habitais","habiterai"],"a":"habite","why":"depuis, still true.","hint":"<b>j'habite</b>."},{"q":"Il travaillait depuis une heure quand j'___.","en":"He had been working for an hour when I called.","opts":["ai appelé","appelais","appelle","avais appelé"],"a":"ai appelé","why":"The event that cuts in.","hint":"j'<b>ai appelé</b>."},{"q":"Dès que j'___ fini, je partirai.","en":"As soon as I've finished, I'll leave.","opts":["aurai","ai","aurais","avais"],"a":"aurai","why":"Done before a future moment.","hint":"j'<b>aurai</b> fini."},{"q":"Si j'avais su, je ___ venu.","en":"If I had known, I would have come.","opts":["serais","suis","serai","étais"],"a":"serais","why":"Unreal past.","hint":"<b>serais</b> venu."},{"q":"Il faut que tu le ___.","en":"You must do it.","opts":["fasses","fais","feras","ferais"],"a":"fasses","why":"Need: subjonctif.","hint":"que tu le <b>fasses</b>."},{"q":"Quand je suis arrivé, il ___ déjà parti.","en":"When I arrived, he had already left.","opts":["était","est","a","sera"],"a":"était","why":"Before the past.","hint":"<b>était</b> parti."}],"build":[{"en":"I've lived here for two years.","tiles":["J'","habite","ici","depuis","deux ans."],"trap":"ai habité","why":"depuis, still true: present.","hint":"j'<b>habite</b>."},{"en":"I arrived an hour ago.","tiles":["Je","suis arrivé","il y a","une heure."],"trap":"depuis","why":"il y a = ago.","hint":"<b>il y a</b> une heure."},{"en":"As soon as I've finished, I'll leave.","tiles":["Dès que j'","aurai fini,","je","partirai."],"trap":"ai fini,","why":"futur antérieur after dès que.","hint":"dès que j'<b>aurai fini</b>."},{"en":"He finished in two hours.","tiles":["Il","a fini","en","deux heures."],"trap":"pendant","why":"en = the time it takes.","hint":"<b>en</b> deux heures."},{"en":"I had done it.","tiles":["Je l'","avais","fait."],"trap":"ai","why":"Before the past.","hint":"je l'<b>avais</b> fait."}],"spot":[{"words":["J'","ai habité","ici depuis deux ans."],"bad":1,"fix":"habite","hint":"depuis, still true: <b>présent</b>.","look":"Is it still true?"},{"words":["Dès que j'","ai fini,","je partirai."],"bad":1,"fix":"aurai fini,","hint":"About the future: <b>aurai fini</b>.","look":"Is it the future?"},{"words":["Je suis arrivé","depuis","une heure."],"bad":1,"fix":"il y a","hint":"ago: <b>il y a</b>.","look":"Still going on, or ago?"},{"words":["Si j'","aurais su,","je serais venu."],"bad":1,"fix":"avais su,","hint":"After si: <b>avais su</b>.","look":"Look right after si."},{"words":["Il faut que tu le","fais."],"bad":1,"fix":"fasses.","hint":"Need: <b>fasses</b>.","look":"Which mood after il faut que?"}]},"drill":[["I've lived here for two years (depuis)","J'habite ici depuis deux ans.","depuis, still true: <b>présent</b>."],["I arrived an hour ago","Je suis arrivé(e) il y a une heure.","il y a: <b>passé composé</b>."],["As soon as I've finished, I'll leave","Dès que j'aurai fini, je partirai.","dès que, future: <b>futur antérieur</b>."],["I had done (faire)","J'avais fait.","Before the past: <b>plus-que-parfait</b>."],["I would have done (faire)","J'aurais fait.","Unreal past: <b>conditionnel passé</b>."],["that I do (faire, subjonctif)","que je fasse","<b>subjonctif</b>: fasse."]]},"v34":{"line":"The <b>passé simple</b> in every person, for reading. Four families, each with its own endings: <b>-ai</b> (all -er verbs and aller: je parlai, ils parlèrent), <b>-is</b> (finir, vendre, faire, voir, prendre, dire: je fis), <b>-us</b> (verbs with a participle in -u, plus être: je pus, je fus), <b>-ins</b> (venir, tenir: je vins). nous and vous always take a circumflex: parl<b>â</b>mes, fin<b>î</b>mes, v<b>în</b>mes.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"conj","title":"The four families","sub":"Pick a verb, then tap a person: the ending lights up.","neg":false,"verbs":[{"inf":"parler","en":"-ai family","stem":"parl","forms":["parlai","parlas","parla","parlâmes","parlâtes","parlèrent"],"tail":""},{"inf":"faire","en":"-is family","stem":"f","forms":["fis","fis","fit","fîmes","fîtes","firent"],"tail":""},{"inf":"vouloir","en":"-us family","stem":"voul","forms":["voulus","voulus","voulut","voulûmes","voulûtes","voulurent"],"tail":""},{"inf":"venir","en":"-ins family","stem":"v","forms":["vins","vins","vint","vînmes","vîntes","vinrent"],"tail":""}]},{"tool":"sort","title":"Which family?","sub":"Tap the box for each verb.","boxes":[{"k":"ai","label":"-ai","sub":"-er verbs, aller"},{"k":"is","label":"-is","sub":"finir, voir…"},{"k":"us","label":"-us","sub":"pouvoir, lire…"},{"k":"ins","label":"-ins","sub":"venir, tenir"}],"cards":[{"t":"aller","box":"ai","why":"j'<b>allai</b>"},{"t":"prendre","box":"is","why":"je <b>pris</b>"},{"t":"lire","box":"us","why":"je <b>lus</b>"},{"t":"tenir","box":"ins","why":"je <b>tins</b>"},{"t":"écrire","box":"is","why":"j'<b>écrivis</b>"},{"t":"boire","box":"us","why":"je <b>bus</b>"},{"t":"manger","box":"ai","why":"je <b>mangeai</b>"},{"t":"obtenir","box":"ins","why":"j'<b>obtins</b>"},{"t":"naître","box":"is","why":"je <b>naquis</b>"},{"t":"vivre","box":"us","why":"je <b>vécus</b>"}]}],"practice":{"choose":[{"q":"je ___ (parler)","en":"I spoke","opts":["parlai","parlais","parla","parlerai"],"a":"parlai","why":"-ai family.","hint":"je <b>parlai</b> (je parlais is the imparfait)."},{"q":"nous ___ (finir)","en":"we finished","opts":["finîmes","finimes","finissons","finissions"],"a":"finîmes","why":"nous: a circumflex.","hint":"nous <b>finîmes</b>."},{"q":"ils ___ (venir)","en":"they came","opts":["vinrent","vinèrent","venirent","viennent"],"a":"vinrent","why":"-ins family.","hint":"ils <b>vinrent</b>."},{"q":"elle ___ (boire)","en":"she drank","opts":["but","buvit","bua","boit"],"a":"but","why":"-us family.","hint":"elle <b>but</b>."},{"q":"nous ___ (manger)","en":"we ate","opts":["mangeâmes","mangâmes","mangeames","mangions"],"a":"mangeâmes","why":"Keep the e before a.","hint":"nous <b>mangeâmes</b>."},{"q":"je ___ (commencer)","en":"I began","opts":["commençai","commencai","commenci","commençais"],"a":"commençai","why":"ç before a.","hint":"je <b>commençai</b>."}],"build":[{"en":"I spoke","tiles":["je","parlai"],"trap":"parlais","why":"-ai family.","hint":"je <b>parlai</b>."},{"en":"we finished","tiles":["nous","finîmes"],"trap":"finimes","why":"A circumflex with nous.","hint":"nous <b>finîmes</b>."},{"en":"they came","tiles":["ils","vinrent"],"trap":"venirent","why":"-ins family.","hint":"ils <b>vinrent</b>."},{"en":"she lived","tiles":["elle","vécut"],"trap":"vivit","why":"vivre: vécu → vécut.","hint":"elle <b>vécut</b>."},{"en":"you (vous) were","tiles":["vous","fûtes"],"trap":"futes","why":"A circumflex with vous.","hint":"vous <b>fûtes</b>."}],"spot":[{"words":["nous","finimes"],"bad":1,"fix":"finîmes","hint":"nous: a circumflex, <b>finîmes</b>.","look":"Look at the accent."},{"words":["ils","venirent"],"bad":1,"fix":"vinrent","hint":"-ins family: <b>vinrent</b>.","look":"Look at the stem."},{"words":["nous","mangâmes"],"bad":1,"fix":"mangeâmes","hint":"Keep the e: <b>mangeâmes</b>.","look":"Look before â."},{"words":["elle","buvit"],"bad":1,"fix":"but","hint":"-us family: <b>but</b>.","look":"Which family is boire?"},{"words":["je","commencai"],"bad":1,"fix":"commençai","hint":"ç before a: <b>commençai</b>.","look":"Look at the c."}]},"drill":[["Passé simple: je (parler)","parlai","-ai family: je <b>parlai</b>."],["Passé simple: nous (finir)","finîmes","nous: a circumflex, <b>finîmes</b>."],["Passé simple: ils (venir)","vinrent","-ins family: <b>vinrent</b>."],["Passé simple: elle (boire)","but","-us family: <b>but</b>."],["Passé simple: je (faire)","fis","-is family: <b>fis</b>."],["Passé simple: nous (être)","fûmes","être: <b>fûmes</b>."]]},"v35":{"line":"The <b>passé antérieur</b> = the passé simple of avoir or être + the participle: il <b>eut fini</b>, elle <b>fut arrivée</b>. In a story, it is the action done <b>just before</b> the next one in the passé simple, after <b>quand, lorsque, dès que, aussitôt que, après que, à peine… que</b>: Dès qu'il <b>eut fini</b>, il <b>partit</b>. In speech: Dès qu'il <b>a eu fini</b>, il est parti.","words":"","steps":[{"tool":"conj","title":"eus + participle, fus + participle","sub":"Pick a verb, then tap a person.","neg":false,"verbs":[{"inf":"finir","en":"had finished","forms":["eus fini","eus fini","eut fini","eûmes fini","eûtes fini","eurent fini"],"tail":""},{"inf":"arriver","en":"had arrived","forms":["fus arrivé(e)","fus arrivé(e)","fut arrivé(e)","fûmes arrivé(e)s","fûtes arrivé(e)(s)","furent arrivé(e)s"],"tail":""}]},{"tool":"swap","title":"Story or speech?","sub":"Pick a sentence and tap « Say it »: the literary pair becomes the spoken one.","button":["Say it","Write it"],"legend":[["x","the verbs that change"]],"items":[{"label":"Dès qu'il eut fini, il partit.","en":["As soon as he had finished, he left. (written)","(spoken)"],"a":[["q","Dès qu'il",""],["v","eut fini,","x"],["s","il",""],["w","partit.","x"]],"b":[["q","Dès qu'il",""],["v","a eu fini,","x"],["s","il",""],["w","est parti.","x"]]},{"label":"Quand elle fut arrivée, ils dînèrent.","en":["When she had arrived, they had dinner. (written)","(spoken)"],"a":[["q","Quand elle",""],["v","fut arrivée,","x"],["s","ils",""],["w","dînèrent.","x"]],"b":[["q","Quand elle",""],["v","est arrivée,","x"],["s","ils",""],["w","ont dîné.","x"]]},{"label":"Lorsqu'ils eurent compris, ils se turent.","en":["Once they had understood, they fell silent. (written)","(spoken)"],"a":[["q","Lorsqu'ils",""],["v","eurent compris,","x"],["s","ils",""],["w","se turent.","x"]],"b":[["q","Quand ils",""],["v","ont compris,","x"],["s","ils",""],["w","se sont tus.","x"]]}]}],"practice":{"choose":[{"q":"Dès qu'il ___ fini, il partit.","en":"As soon as he had finished, he left.","opts":["eut","avait","a eu","aura"],"a":"eut","why":"Just before, in a story.","hint":"<b>eut</b> fini."},{"q":"Quand elle fut ___, ils dînèrent.","en":"When she had arrived, they had dinner.","opts":["arrivée","arrivé","arrivées","arriver"],"a":"arrivée","why":"être: it agrees.","hint":"fut <b>arrivée</b>."},{"q":"Lorsqu'ils ___ compris, ils se turent.","en":"Once they had understood, they fell silent.","opts":["eurent","eut","furent","avaient"],"a":"eurent","why":"avoir, ils, passé simple.","hint":"<b>eurent</b> compris."},{"q":"À peine eut-il parlé ___ on l'interrompit.","en":"He had barely spoken when he was interrupted.","opts":["qu'","quand","lorsqu'","et"],"a":"qu'","why":"à peine … que.","hint":"<b>qu'</b>on l'interrompit."},{"q":"Spoken: Dès qu'il ___ fini, il est parti.","en":"As soon as he had finished, he left. (spoken)","opts":["a eu","eut","avait eu","aura eu"],"a":"a eu","why":"In speech: the passé surcomposé.","hint":"<b>a eu</b> fini."},{"q":"Après qu'elle ___ signé, il sortit.","en":"After she had signed, he went out.","opts":["eut","ait","avait eu","eût"],"a":"eut","why":"après que + indicative, just before.","hint":"<b>eut</b> signé."}],"build":[{"en":"as soon as he had finished","tiles":["dès","qu'il","eut","fini"],"trap":"avait","why":"Just before, in a story.","hint":"<b>eut fini</b>."},{"en":"when she had arrived","tiles":["quand","elle","fut","arrivée"],"trap":"eut","why":"arriver takes être.","hint":"<b>fut arrivée</b>."},{"en":"once they had understood","tiles":["lorsqu'ils","eurent","compris"],"trap":"furent","why":"comprendre takes avoir.","hint":"<b>eurent compris</b>."},{"en":"As soon as he had finished, he left. (spoken)","tiles":["Dès qu'il","a eu fini,","il","est parti."],"trap":"eut fini,","why":"In speech.","hint":"<b>a eu fini</b>."},{"en":"After she had signed, he went out.","tiles":["Après qu'elle","eut signé,","il","sortit."],"trap":"ait signé,","why":"après que + indicative.","hint":"<b>eut signé</b>."}],"spot":[{"words":["Dès qu'il","fut fini,","il partit."],"bad":1,"fix":"eut fini,","hint":"finir takes <b>avoir</b>.","look":"Which helper?"},{"words":["Quand elle","eut arrivée,","ils dînèrent."],"bad":1,"fix":"fut arrivée,","hint":"arriver takes <b>être</b>.","look":"Which helper?"},{"words":["Lorsqu'ils","eut compris,","ils se turent."],"bad":1,"fix":"eurent compris,","hint":"ils: <b>eurent</b>.","look":"Does it match ils?"},{"words":["Quand elle fut","arrivé,","ils dînèrent."],"bad":1,"fix":"arrivée,","hint":"être: it agrees, <b>arrivée</b>.","look":"Does it match elle?"},{"words":["À peine eut-il parlé","quand","on l'interrompit."],"bad":1,"fix":"qu'","hint":"à peine … <b>que</b>.","look":"à peine pairs with which word?","say":"À peine eut-il parlé qu'on l'interrompit."}]},"drill":[["Passé antérieur: dès qu'il (finir)","eut fini","avoir in the passé simple: <b>eut</b> fini."],["Passé antérieur: quand elle (arriver)","fut arrivée","être in the passé simple: <b>fut</b> arrivée."],["Passé antérieur: lorsqu'ils (comprendre)","eurent compris","ils: <b>eurent</b> compris."],["Spoken form of « Dès qu'il eut fini »","Dès qu'il a eu fini","In speech: <b>a eu fini</b>."],["Passé antérieur: nous (partir)","nous fûmes partis / nous fûmes parties","être: <b>fûmes</b> partis."],["Passé antérieur: après qu'elle (signer)","eut signé","<b>eut</b> signé."]]},"v39":{"line":"To show one action is done before the next: the <b>infinitif passé</b> (avoir / être + participle) after <b>après, sans, pour</b>: <b>Après avoir mangé</b>, il est sorti (never après manger). Or the <b>participe passé composé</b> (ayant / étant + participle): <b>Ayant terminé</b> ses études, elle est partie. Same subject in both parts. Pronouns go before the helper: après <b>l'avoir</b> vu. Negative: <b>ne pas avoir</b> compris, <b>n'ayant pas</b> compris.","words":"","steps":[{"tool":"swap","title":"Two sentences, one subject","sub":"Pick a pair and tap « Join them ».","button":["Join them","Two sentences"],"legend":[["x","the compound form"]],"items":[{"label":"Il a mangé. Puis il est sorti.","en":["He ate. Then he went out.","After eating, he went out."],"a":[["a","Il a mangé.",""],["r","Puis il est sorti.",""]],"b":[["x","Après avoir mangé,","x"],["r","il est sorti.",""]],"note":"après + <b>avoir mangé</b> (never après manger)."},{"label":"Ils sont arrivés. Ils ont mangé.","en":["They arrived. They ate.","After arriving, they ate."],"a":[["a","Ils sont arrivés.",""],["r","Ils ont mangé.",""]],"b":[["x","Après être arrivés,","x"],["r","ils ont mangé.",""]],"note":"être verbs agree: arrivé<b>s</b>."},{"label":"Elle a terminé ses études. Elle est partie.","en":["She finished her studies. She left.","Having finished her studies, she left."],"a":[["a","Elle a terminé ses études.",""],["r","Elle est partie.",""]],"b":[["x","Ayant terminé","x"],["o","ses études,",""],["r","elle est partie.",""]]},{"label":"Il n'a pas compris. Il a demandé.","en":["He didn't understand. He asked.","Not having understood, he asked."],"a":[["a","Il n'a pas compris.",""],["r","Il a demandé.",""]],"b":[["x","N'ayant pas compris,","x"],["r","il a demandé.",""]]},{"label":"Il a menti. Il a été puni.","en":["He lied. He was punished.","He was punished for having lied."],"a":[["a","Il a menti.",""],["r","Il a été puni.",""]],"b":[["r","Il a été puni",""],["x","pour avoir menti.","x"]]}]},{"tool":"flip","title":"Simple → compound","sub":"Tap a card.","cards":[{"a":"après manger ✗","b":"après avoir mangé","tag":"after eating"},{"a":"sans comprendre","b":"sans avoir compris","tag":"without having understood"},{"a":"après se lever","b":"après s'être levé(e)","tag":"pronoun before the helper"},{"a":"après les voir","b":"après les avoir vus","tag":"agrees with les"},{"a":"ne pas comprendre","b":"ne pas avoir compris","tag":"ne pas before avoir"},{"a":"finissant","b":"ayant fini","tag":"having finished"}]}],"practice":{"choose":[{"q":"Après ___ mangé, il est sorti.","en":"After eating, he went out.","opts":["avoir","être","ayant","a"],"a":"avoir","why":"après + infinitif passé.","hint":"après <b>avoir</b> mangé."},{"q":"Il est parti sans avoir ___.","en":"He left without having understood.","opts":["compris","comprendre","comprenant","comprit"],"a":"compris","why":"avoir + participle.","hint":"sans avoir <b>compris</b>."},{"q":"___ fini son travail, elle est partie.","en":"Having finished her work, she left.","opts":["Ayant","Étant","Avoir","En"],"a":"Ayant","why":"finir takes avoir.","hint":"<b>Ayant</b> fini."},{"q":"Après ___ levée, elle a ouvert la fenêtre.","en":"After getting up, she opened the window.","opts":["s'être","se avoir","être","s'avoir"],"a":"s'être","why":"A « se » verb takes être.","hint":"après <b>s'être</b> levée."},{"q":"Après être ___, ils ont mangé.","en":"After arriving, they ate.","opts":["arrivés","arrivé","arriver","arrivant"],"a":"arrivés","why":"être: agrees with ils.","hint":"<b>arrivés</b>."},{"q":"___ arrivée en retard, elle a manqué le début.","en":"Having arrived late, she missed the start.","opts":["Étant","Ayant","Être","En étant"],"a":"Étant","why":"arriver takes être.","hint":"<b>Étant</b> arrivée."}],"build":[{"en":"After eating, he went out.","tiles":["Après","avoir","mangé,","il est sorti."],"trap":"manger,","why":"après + infinitif passé.","hint":"après <b>avoir mangé</b>."},{"en":"without having understood","tiles":["sans","avoir","compris"],"trap":"comprendre","why":"sans + infinitif passé.","hint":"sans <b>avoir compris</b>."},{"en":"Having finished, she left.","tiles":["Ayant","fini,","elle est partie."],"trap":"Étant","why":"finir takes avoir.","hint":"<b>Ayant fini</b>."},{"en":"After getting up, she opened the window.","tiles":["Après","s'être","levée,","elle a ouvert la fenêtre."],"trap":"se lever,","why":"A « se » verb: s'être.","hint":"après <b>s'être levée</b>."},{"en":"Not having understood, he asked.","tiles":["N'ayant","pas","compris,","il a demandé."],"trap":"Ne pas","why":"ne … pas round ayant.","hint":"<b>N'ayant pas</b> compris."}],"spot":[{"words":["Après","manger,","il est sorti."],"bad":1,"fix":"avoir mangé,","hint":"après + <b>infinitif passé</b>.","look":"What does après need?"},{"words":["Après être","arrivé,","elles ont mangé."],"bad":1,"fix":"arrivées,","hint":"être: agrees with elles, <b>arrivées</b>.","look":"Does it match elles?"},{"words":["Ayant fini,","la porte","s'est fermée."],"bad":1,"fix":"elle a fermé la porte.","hint":"Same subject: the door did not finish.","look":"Who finished?","say":"Ayant fini, elle a fermé la porte."},{"words":["Après","se être","levée…"],"bad":1,"fix":"s'être","hint":"se before a vowel: <b>s'être</b>.","look":"Look at se."},{"words":["Étant","fini","son travail, il est parti."],"bad":0,"fix":"Ayant","hint":"finir takes <b>avoir</b>.","look":"Which helper?"}]},"drill":[["Après (manger), il est sorti. (infinitif passé)","avoir mangé","après + <b>avoir mangé</b>."],["Sans (comprendre), il est parti.","avoir compris","sans + <b>avoir compris</b>."],["(Finir) son travail, elle est partie. (participe composé)","Ayant fini","<b>Ayant fini</b>."],["Après (se lever), elle a ouvert la fenêtre.","s'être levée","<b>s'être levée</b>: être, and it agrees."],["Not having understood, he asked.","N'ayant pas compris, il a demandé.","<b>N'ayant pas</b> compris."],["He was punished for having lied.","Il a été puni pour avoir menti.","pour + <b>avoir menti</b>."]]},"67":{"line":"Formal writing swaps a clause for a participle. <b>Sachant</b> que tu es occupé… (= comme je sais), <b>Ayant lu</b> le rapport… (= après avoir lu), <b>Arrivés</b> à Paris… (= quand ils sont arrivés), <b>Épuisé</b>, il s'est endormi. The subject must be the same as the main verb's. Unless the clause has <b>its own subject</b> (absolute construction): <b>Le travail terminé</b>, les ouvriers sont partis. <b>Une fois</b> la décision <b>prise</b>…","words":"","steps":[{"tool":"swap","title":"Clause → participle","sub":"Pick a sentence and tap « Make it compact ».","button":["Make it compact","Full clause"],"legend":[["x","the participle clause"]],"items":[{"label":"Comme je savais que tu étais occupé, je ne t'ai pas dérangé.","en":["As I knew you were busy, I didn't disturb you.","Knowing you were busy, I didn't disturb you."],"a":[["x","Comme je savais","x"],["o","que tu étais occupé,",""],["r","je ne t'ai pas dérangé.",""]],"b":[["x","Sachant","x"],["o","que tu étais occupé,",""],["r","je ne t'ai pas dérangé.",""]]},{"label":"Quand elle a eu lu le rapport, elle a téléphoné.","en":["When she had read the report, she phoned.","Having read the report, she phoned."],"a":[["x","Quand elle a eu lu","x"],["o","le rapport,",""],["r","elle a téléphoné.",""]],"b":[["x","Ayant lu","x"],["o","le rapport,",""],["r","elle a téléphoné.",""]]},{"label":"Quand ils sont arrivés à Paris, ils ont pris le métro.","en":["When they arrived in Paris, they took the metro.","Arrived in Paris, they took the metro."],"a":[["x","Quand ils sont arrivés","x"],["o","à Paris,",""],["r","ils ont pris le métro.",""]],"b":[["x","Arrivés","x"],["o","à Paris,",""],["r","ils ont pris le métro.",""]],"note":"The participle agrees: arrivé<b>s</b>."},{"label":"Quand le travail a été terminé, les ouvriers sont partis.","en":["When the work was done, the workers left.","The work done, the workers left."],"a":[["x","Quand le travail a été terminé,","x"],["r","les ouvriers sont partis.",""]],"b":[["x","Le travail terminé,","x"],["r","les ouvriers sont partis.",""]],"note":"Its own subject (le travail): an <b>absolute construction</b>."},{"label":"Dès que la décision est prise, il faut agir.","en":["As soon as the decision is made, we must act.","Once the decision is made, we must act."],"a":[["x","Dès que la décision est prise,","x"],["r","il faut agir.",""]],"b":[["x","Une fois la décision prise,","x"],["r","il faut agir.",""]]}]},{"tool":"sort","title":"Correct or a dangling participle?","sub":"Is the participle's subject the main subject? Tap the box.","boxes":[{"k":"ok","label":"correct"},{"k":"no","label":"wrong subject"}],"cards":[{"t":"Ayant fini, elle est partie.","box":"ok","why":"She finished, she left."},{"t":"Ayant fini, la porte s'est fermée.","box":"no","why":"The door did not finish."},{"t":"Le soleil couché, nous sommes rentrés.","box":"ok","why":"Absolute: le soleil has its own participle."},{"t":"Épuisé, il s'est endormi.","box":"ok","why":"He was exhausted, he fell asleep."},{"t":"Arrivés à la gare, le train était parti.","box":"no","why":"The train did not arrive at the station: <b>nous</b> did."},{"t":"Ne sachant pas quoi dire, il s'est tu.","box":"ok","why":"He did not know, he fell silent."}]}],"practice":{"choose":[{"q":"___ la vérité, il s'est tu.","en":"Knowing the truth, he said nothing.","opts":["Sachant","Savant","Su","En savoir"],"a":"Sachant","why":"savoir → ?","hint":"<b>Sachant</b>."},{"q":"___ son travail, elle est partie.","en":"Having finished her work, she left.","opts":["Ayant fini","Étant fini","Finissant","Fini"],"a":"Ayant fini","why":"Done before: ayant + participle.","hint":"<b>Ayant fini</b>."},{"q":"Une fois la décision ___, il faut agir.","en":"Once the decision is made, we must act.","opts":["prise","pris","prendre","prenant"],"a":"prise","why":"Agrees with décision.","hint":"<b>prise</b>."},{"q":"Le repas ___, ils ont quitté la table.","en":"The meal over, they left the table.","opts":["terminé","terminée","terminant","ayant terminé"],"a":"terminé","why":"Agrees with repas.","hint":"<b>terminé</b>."},{"q":"___ à Paris, elles ont pris le métro.","en":"Having arrived in Paris, they took the metro.","opts":["Arrivées","Arrivés","Arrivant","Arrivé"],"a":"Arrivées","why":"Agrees with elles.","hint":"<b>Arrivées</b>."},{"q":"___, il s'est endormi.","en":"Exhausted, he fell asleep.","opts":["Épuisé","Épuisant","Épuisée","En épuisant"],"a":"Épuisé","why":"An adjective about him.","hint":"<b>Épuisé</b>."}],"build":[{"en":"Knowing the truth, he said nothing.","tiles":["Sachant","la vérité,","il s'est","tu."],"trap":"Savant","why":"savoir → sachant.","hint":"<b>Sachant</b>…"},{"en":"Having finished her work, she left.","tiles":["Ayant","fini","son travail,","elle est partie."],"trap":"Étant","why":"finir takes avoir.","hint":"<b>Ayant fini</b>…"},{"en":"Once the decision is made","tiles":["Une fois","la décision","prise"],"trap":"pris","why":"Agrees with décision.","hint":"une fois la décision <b>prise</b>."},{"en":"The meal over, they left the table.","tiles":["Le repas","terminé,","ils","ont quitté","la table."],"trap":"terminée,","why":"Agrees with repas.","hint":"le repas <b>terminé</b>…"},{"en":"Not knowing what to say, he fell silent.","tiles":["Ne","sachant","pas","quoi dire,","il s'est tu."],"trap":"savant","why":"ne … pas round the participle.","hint":"<b>Ne sachant pas</b>…"}],"spot":[{"words":["Ayant fini,","la porte","s'est fermée."],"bad":1,"fix":"elle a fermé la porte","hint":"Same subject: <b>she</b> finished.","look":"Who finished?","say":"Ayant fini, elle a fermé la porte."},{"words":["Une fois la décision","pris,","il faut agir."],"bad":1,"fix":"prise,","hint":"Agrees with décision: <b>prise</b>.","look":"Does it match décision?"},{"words":["Arrivé","à Paris,","elles ont pris le métro."],"bad":0,"fix":"Arrivées","hint":"Agrees with elles: <b>Arrivées</b>.","look":"Does it match elles?"},{"words":["Savant","la vérité,","il s'est tu."],"bad":0,"fix":"Sachant","hint":"savoir → <b>sachant</b>.","look":"Look at the -ant form."},{"words":["Étant","lu","le rapport, elle a téléphoné."],"bad":0,"fix":"Ayant","hint":"lire takes <b>avoir</b>.","look":"Which helper?"}]},"drill":[["Comme il savait la vérité → ___ la vérité, il s'est tu.","Sachant","savoir → <b>sachant</b>."],["Quand elle a fini son travail → ___ son travail, elle est partie.","Ayant fini","Done before: <b>Ayant fini</b>."],["Une fois la décision ___ (prendre)","prise","Agrees with décision: <b>prise</b>."],["Le repas ___ (terminer), ils ont quitté la table.","terminé","Absolute construction: <b>terminé</b>."],["Exhausted, he fell asleep.","Épuisé, il s'est endormi.","An adjective in front: <b>Épuisé</b>."],["Arrived in Paris (elles), they took the metro.","Arrivées à Paris, elles ont pris le métro.","Agrees with elles: <b>Arrivées</b>."]]},"68":{"line":"The subjonctif beyond il faut que. After a <b>superlative</b> or <b>le seul, le premier, le dernier</b>, as an opinion: le plus beau film que j'<b>aie</b> vu. In a relative clause for something <b>sought or doubtful</b>: je cherche quelqu'un qui <b>sache</b> le russe; il n'y a rien que je <b>puisse</b> faire. After <b>avant que, jusqu'à ce que, sans que, pourvu que, à moins que</b>. But <b>après que</b> takes the indicative: après qu'il <b>est</b> parti.","words":"","steps":[{"tool":"swap","title":"Known, or sought?","sub":"Pick a sentence and tap « Make it uncertain »: the mood changes.","button":["Make it uncertain","Known"],"legend":[["x","the verb"]],"items":[{"label":"J'ai un ami qui sait le russe.","en":["I have a friend who knows Russian.","I'm looking for someone who knows Russian."],"a":[["s","J'ai un ami",""],["q","qui",""],["v","sait","x"],["o","le russe.",""]],"b":[["s","Je cherche quelqu'un",""],["q","qui",""],["v","sache","x"],["o","le russe.",""]],"note":"Someone not yet found: <b>sache</b>."},{"label":"Il y a un hôtel qui est bon marché.","en":["There's a cheap hotel.","I'm looking for a hotel that is cheap."],"a":[["s","Il y a un hôtel",""],["q","qui",""],["v","est","x"],["o","bon marché.",""]],"b":[["s","Je cherche un hôtel",""],["q","qui",""],["v","soit","x"],["o","bon marché.",""]]},{"label":"Je peux faire quelque chose.","en":["I can do something.","There's nothing I can do."],"a":[["s","Je",""],["v","peux","x"],["o","faire quelque chose.",""]],"b":[["s","Il n'y a rien",""],["q","que je",""],["v","puisse","x"],["o","faire.",""]]},{"label":"C'est un beau film. Je l'ai vu.","en":["It's a beautiful film. I saw it.","It's the most beautiful film I have seen."],"a":[["s","C'est un beau film.",""],["o","Je l'",""],["v","ai vu.","x"]],"b":[["s","C'est le plus beau film",""],["q","que",""],["o","j'",""],["v","aie vu.","x"]],"note":"After a superlative (an opinion): <b>aie vu</b>."}]},{"tool":"sort","title":"Subjonctif or indicative?","sub":"Tap the box for the verb that follows.","boxes":[{"k":"s","label":"subjonctif"},{"k":"i","label":"indicative"}],"cards":[{"t":"avant que","box":"s","why":"avant qu'il <b>parte</b>"},{"t":"après que","box":"i","why":"après qu'il <b>est</b> parti"},{"t":"jusqu'à ce que","box":"s","why":"jusqu'à ce qu'il <b>vienne</b>"},{"t":"sans que","box":"s","why":"sans que personne le <b>voie</b>"},{"t":"parce que","box":"i","why":"parce qu'il <b>est</b> malade"},{"t":"le seul … qui","box":"s","why":"le seul qui <b>puisse</b> m'aider"},{"t":"pourvu que","box":"s","why":"Pourvu qu'il <b>fasse</b> beau !"},{"t":"pendant que","box":"i","why":"pendant que tu <b>dors</b>"}]}],"practice":{"choose":[{"q":"C'est le plus beau film que j'___ vu.","en":"It's the most beautiful film I've seen.","opts":["aie","ai","avais","aurais"],"a":"aie","why":"After a superlative.","hint":"j'<b>aie</b> vu."},{"q":"Je cherche un hôtel qui ___ bon marché.","en":"I'm looking for a cheap hotel.","opts":["soit","est","sera","serait"],"a":"soit","why":"Not yet found.","hint":"qui <b>soit</b>."},{"q":"Il est parti sans que personne le ___.","en":"He left without anyone seeing him.","opts":["voie","voit","verra","voyait"],"a":"voie","why":"sans que + subjonctif.","hint":"le <b>voie</b>."},{"q":"Après qu'il ___ parti, nous avons mangé.","en":"After he left, we ate.","opts":["est","soit","fût","serait"],"a":"est","why":"après que + indicative.","hint":"après qu'il <b>est</b> parti."},{"q":"Il n'y a rien que je ___ faire.","en":"There's nothing I can do.","opts":["puisse","peux","pourrai","pouvais"],"a":"puisse","why":"A negative relative.","hint":"que je <b>puisse</b>."},{"q":"C'est la seule personne qui ___ m'aider.","en":"She's the only person who can help me.","opts":["puisse","peut","pourrait","pourra"],"a":"puisse","why":"After le seul / la seule.","hint":"qui <b>puisse</b>."}],"build":[{"en":"It's the most beautiful film I've seen.","tiles":["C'est","le plus beau film","que j'","aie","vu."],"trap":"ai","why":"After a superlative.","hint":"que j'<b>aie</b> vu."},{"en":"I'm looking for a hotel that is cheap.","tiles":["Je cherche","un hôtel","qui","soit","bon marché."],"trap":"est","why":"Not yet found.","hint":"qui <b>soit</b>."},{"en":"He left without anyone seeing him.","tiles":["Il est parti","sans que","personne","le","voie."],"trap":"voit.","why":"sans que + subjonctif.","hint":"le <b>voie</b>."},{"en":"After he left, we ate.","tiles":["Après qu'il","est","parti,","nous avons mangé."],"trap":"soit","why":"après que + indicative.","hint":"après qu'il <b>est</b> parti."},{"en":"Wait until he comes.","tiles":["Attends","jusqu'à ce qu'il","vienne."],"trap":"vient.","why":"jusqu'à ce que + subjonctif.","hint":"qu'il <b>vienne</b>."}],"spot":[{"words":["Après qu'il","soit","parti, nous avons mangé."],"bad":1,"fix":"est","hint":"après que + <b>indicative</b>.","look":"Has it really happened?"},{"words":["Je cherche quelqu'un qui","sait","le russe."],"bad":1,"fix":"sache","hint":"Someone sought: <b>sache</b>.","look":"Is the person known?"},{"words":["Il est parti sans que personne le","voit."],"bad":1,"fix":"voie.","hint":"sans que + <b>subjonctif</b>.","look":"Which mood?"},{"words":["Il n'y a rien que je","peux","faire."],"bad":1,"fix":"puisse","hint":"A negative relative: <b>puisse</b>.","look":"Which mood?"},{"words":["Attends","jusqu'à ce qu'il","vient."],"bad":2,"fix":"vienne.","hint":"jusqu'à ce que + <b>subjonctif</b>.","look":"Which mood?"}]},"drill":[["C'est le plus beau film que j'(voir, subj. passé)...","aie vu","After a superlative: <b>aie vu</b>."],["Je cherche un hôtel qui (être) bon marché.","soit","Something sought: <b>soit</b>."],["Il est parti sans que personne le (voir).","voie","sans que + <b>subjonctif</b>."],["Après qu'il (partir), nous avons mangé.","est parti","après que + <b>indicative</b>."],["Il n'y a rien que je (pouvoir) faire.","puisse","A negative relative: <b>puisse</b>."],["Attends jusqu'à ce qu'il (venir).","vienne","jusqu'à ce que + <b>subjonctif</b>."]]},"v36":{"line":"The <b>imparfait du subjonctif</b> is for reading only: formal texts and novels use it after a past main verb, where modern French uses the present subjonctif. Formed from the <b>tu</b> form of the passé simple minus -s, + <b>-sse, -sses, -t, -ssions, -ssiez, -ssent</b>, with a circumflex on <b>il</b>: qu'il <b>parlât</b>, qu'il <b>fît</b>, qu'il <b>fût</b>, qu'il <b>eût</b>, qu'il <b>vînt</b>. Spot it by <b>-ât, -ît, -ût</b> and <b>-ss-</b>.","words":"","steps":[{"tool":"conj","title":"Recognise the forms","sub":"Pick a verb, then tap a person.","neg":false,"pre":"Il fallait que","verbs":[{"inf":"parler","en":"speak","stem":"parl","forms":["parlasse","parlasses","parlât","parlassions","parlassiez","parlassent"],"tail":""},{"inf":"être","en":"be","forms":["fusse","fusses","fût","fussions","fussiez","fussent"],"tail":""},{"inf":"avoir","en":"have","forms":["eusse","eusses","eût","eussions","eussiez","eussent"],"tail":""},{"inf":"venir","en":"come","forms":["vinsse","vinsses","vînt","vinssions","vinssiez","vinssent"],"tail":""}]},{"tool":"swap","title":"Literary → modern","sub":"Pick a sentence and tap « Modern French ».","button":["Modern French","Literary"],"legend":[["x","the subjonctif"]],"items":[{"label":"Il fallait qu'il vînt.","en":["He had to come. (literary)","He had to come. (modern)"],"a":[["s","Il fallait qu'il",""],["v","vînt.","x"]],"b":[["s","Il fallait qu'il",""],["v","vienne.","x"]]},{"label":"Je voulais qu'il fût heureux.","en":["I wanted him to be happy. (literary)","(modern)"],"a":[["s","Je voulais qu'il",""],["v","fût","x"],["o","heureux.",""]],"b":[["s","Je voulais qu'il",""],["v","soit","x"],["o","heureux.",""]]},{"label":"Elle craignait qu'il ne parlât.","en":["She feared he would speak. (literary)","(modern)"],"a":[["s","Elle craignait qu'il ne",""],["v","parlât.","x"]],"b":[["s","Elle craignait qu'il ne",""],["v","parle.","x"]]},{"label":"Il eût fallu qu'il fît un effort.","en":["He should have made an effort. (literary)","(modern)"],"a":[["a","Il eût fallu","x"],["s","qu'il",""],["v","fît","x"],["o","un effort.",""]],"b":[["a","Il aurait fallu","x"],["s","qu'il",""],["v","fasse","x"],["o","un effort.",""]]}]}],"practice":{"choose":[{"q":"qu'il ___ (être, imparfait du subj.)","en":"that he were","opts":["fût","fut","soit","fusse"],"a":"fût","why":"il: a circumflex, no -s.","hint":"qu'il <b>fût</b> (il fut, no accent, is the passé simple)."},{"q":"qu'il ___ (avoir, imparfait du subj.)","en":"that he had","opts":["eût","eut","ait","eusse"],"a":"eût","why":"il: a circumflex.","hint":"qu'il <b>eût</b>."},{"q":"Modern: qu'il vînt → qu'il ___","en":"that he come","opts":["vienne","vint","viendrait","venait"],"a":"vienne","why":"The present subjonctif.","hint":"qu'il <b>vienne</b>."},{"q":"qu'il ___ (faire, imparfait du subj.)","en":"that he did","opts":["fît","fit","fasse","fisse"],"a":"fît","why":"il: a circumflex.","hint":"qu'il <b>fît</b>."},{"q":"Modern: je voulais qu'il fût heureux → qu'il ___ heureux","en":"that he be happy","opts":["soit","est","était","serait"],"a":"soit","why":"The present subjonctif.","hint":"qu'il <b>soit</b>."},{"q":"qu'ils ___ (parler, imparfait du subj.)","en":"that they spoke","opts":["parlassent","parlèrent","parlent","parlaient"],"a":"parlassent","why":"-ss- forms.","hint":"qu'ils <b>parlassent</b>."}],"build":[{"en":"that he were (literary)","tiles":["qu'il","fût"],"trap":"fut","why":"A circumflex on il.","hint":"qu'il <b>fût</b>."},{"en":"that he had (literary)","tiles":["qu'il","eût"],"trap":"eut","why":"A circumflex on il.","hint":"qu'il <b>eût</b>."},{"en":"He had to come. (modern)","tiles":["Il fallait","qu'il","vienne."],"trap":"vînt.","why":"Modern: the present subjonctif.","hint":"qu'il <b>vienne</b>."},{"en":"I wanted him to be happy. (literary)","tiles":["Je voulais","qu'il","fût","heureux."],"trap":"fut","why":"A circumflex.","hint":"qu'il <b>fût</b>."},{"en":"that he did (literary)","tiles":["qu'il","fît"],"trap":"fit","why":"A circumflex.","hint":"qu'il <b>fît</b>."}],"spot":[{"words":["Il fallait qu'il","fut","là."],"bad":1,"fix":"fût","hint":"Subjonctif: <b>fût</b>, with a circumflex.","look":"Look at the accent."},{"words":["Je voulais qu'il","eut","raison."],"bad":1,"fix":"eût","hint":"Subjonctif: <b>eût</b>.","look":"Look at the accent."},{"words":["Modern French:","Il fallait qu'il","vînt."],"bad":2,"fix":"vienne.","hint":"Modern: <b>vienne</b>.","look":"Is this modern?","say":"Il fallait qu'il vienne."},{"words":["Il fallait qu'il","fit","un effort."],"bad":1,"fix":"fît","hint":"Subjonctif: <b>fît</b>.","look":"Look at the accent."},{"words":["qu'ils","parlassèrent"],"bad":1,"fix":"parlassent","hint":"<b>parlassent</b>.","look":"Look at the ending."}]},"drill":[["Imparfait du subjonctif: qu'il (être)","fût","A circumflex: <b>fût</b>."],["Imparfait du subjonctif: qu'il (avoir)","eût","A circumflex: <b>eût</b>."],["Modern form of « qu'il vînt »","qu'il vienne","Modern: the present subjonctif, <b>vienne</b>."],["Imparfait du subjonctif: qu'il (faire)","fît","A circumflex: <b>fît</b>."],["Modern form of « qu'il fût »","qu'il soit","Modern: <b>soit</b>."],["Imparfait du subjonctif: qu'il (parler)","parlât","-er verbs: <b>parlât</b>."]]},"v37":{"line":"Two literary forms, one shape: <b>eût / fût</b> + participle. After <b>que</b>, it is the <b>plus-que-parfait du subjonctif</b> (an earlier action): je doutais qu'il <b>eût compris</b>. At the start of a clause it is the <b>conditionnel passé, 2nd form</b> (would have): il <b>eût aimé</b> = il aurait aimé; <b>Eût-il su</b>, il <b>eût agi</b> autrement = s'il avait su, il aurait agi. Read it, don't write it.","words":"","steps":[{"tool":"swap","title":"Literary → modern","sub":"Pick a sentence and tap « Modern French ».","button":["Modern French","Literary"],"legend":[["x","the forms that change"]],"items":[{"label":"Eût-il su la vérité, il eût agi autrement.","en":["Had he known the truth, he would have acted differently.","(modern)"],"a":[["a","Eût-il su","x"],["o","la vérité,",""],["s","il",""],["v","eût agi","x"],["t","autrement.",""]],"b":[["a","S'il avait su","x"],["o","la vérité,",""],["s","il",""],["v","aurait agi","x"],["t","autrement.",""]],"note":"Eût-il su = <b>s'il avait su</b>."},{"label":"Elle eût aimé qu'il restât.","en":["She would have liked him to stay.","(modern)"],"a":[["a","Elle",""],["v","eût aimé","x"],["s","qu'il",""],["w","restât.","x"]],"b":[["a","Elle",""],["v","aurait aimé","x"],["s","qu'il",""],["w","reste.","x"]]},{"label":"Je doutais qu'il eût compris.","en":["I doubted he had understood.","(modern)"],"a":[["a","Je doutais",""],["s","qu'il",""],["v","eût compris.","x"]],"b":[["a","Je doutais",""],["s","qu'il",""],["v","ait compris.","x"]],"note":"After que: the <b>subjonctif passé</b> today."},{"label":"Il eût suffi d'un mot.","en":["One word would have been enough.","(modern)"],"a":[["s","Il",""],["v","eût suffi","x"],["o","d'un mot.",""]],"b":[["s","Il",""],["v","aurait suffi","x"],["o","d'un mot.",""]]}]},{"tool":"sort","title":"Which job is it doing?","sub":"After que, or at the start of a main clause? Tap the box.","boxes":[{"k":"subj","label":"subjonctif (earlier)","sub":"after que"},{"k":"cond","label":"would have","sub":"conditionnel passé, 2nd form"}],"cards":[{"t":"Je doutais qu'il eût compris.","box":"subj","why":"= ait compris."},{"t":"Il eût aimé venir.","box":"cond","why":"= aurait aimé."},{"t":"Bien qu'elle fût partie…","box":"subj","why":"= soit partie."},{"t":"Eût-il su, il serait venu.","box":"cond","why":"= s'il avait su."},{"t":"Il eût été préférable de partir.","box":"cond","why":"= aurait été."},{"t":"Il fallait qu'ils eussent fini.","box":"subj","why":"= aient fini."}]}],"practice":{"choose":[{"q":"Literary: il ___ aimé","en":"he would have liked","opts":["eût","eut","aurait","avait"],"a":"eût","why":"Conditionnel passé, 2nd form.","hint":"il <b>eût</b> aimé."},{"q":"Modern form of « eût-il su »: ___ su","en":"had he known","opts":["s'il avait","s'il aurait","s'il eut","s'il a"],"a":"s'il avait","why":"si + plus-que-parfait.","hint":"<b>s'il avait</b> su."},{"q":"qu'il ___ fini (plus-que-parfait du subj.)","en":"that he had finished","opts":["eût","eut","ait","avait"],"a":"eût","why":"A circumflex.","hint":"qu'il <b>eût</b> fini."},{"q":"qu'elle ___ partie (plus-que-parfait du subj.)","en":"that she had left","opts":["fût","fut","soit","était"],"a":"fût","why":"partir takes être.","hint":"qu'elle <b>fût</b> partie."},{"q":"Modern: Il eût suffi d'un mot → Il ___ suffi d'un mot.","en":"One word would have been enough.","opts":["aurait","avait","eut","aura"],"a":"aurait","why":"The conditionnel passé.","hint":"il <b>aurait</b> suffi."},{"q":"Modern: Je doutais qu'il eût compris → qu'il ___ compris.","en":"that he had understood","opts":["ait","avait","aurait","a"],"a":"ait","why":"The subjonctif passé.","hint":"qu'il <b>ait</b> compris."}],"build":[{"en":"he would have liked (literary)","tiles":["il","eût","aimé"],"trap":"eut","why":"A circumflex.","hint":"il <b>eût</b> aimé."},{"en":"had he known (modern)","tiles":["s'il","avait","su"],"trap":"aurait","why":"si + plus-que-parfait.","hint":"s'il <b>avait</b> su."},{"en":"that he had finished (literary)","tiles":["qu'il","eût","fini"],"trap":"eut","why":"A circumflex.","hint":"qu'il <b>eût</b> fini."},{"en":"that she had left (literary)","tiles":["qu'elle","fût","partie"],"trap":"eût","why":"partir takes être.","hint":"qu'elle <b>fût</b> partie."},{"en":"One word would have been enough. (modern)","tiles":["Il","aurait","suffi","d'un mot."],"trap":"eût","why":"Modern conditionnel passé.","hint":"il <b>aurait</b> suffi."}],"spot":[{"words":["Il","eut","aimé venir."],"bad":1,"fix":"eût","hint":"would have: <b>eût</b>, with a circumflex.","look":"Look at the accent."},{"words":["Je doutais qu'elle","eût","partie."],"bad":1,"fix":"fût","hint":"partir takes <b>être</b>.","look":"Which helper?"},{"words":["Modern:","S'il aurait su,","il serait venu."],"bad":1,"fix":"S'il avait su,","hint":"si + <b>plus-que-parfait</b>.","look":"Look after si.","say":"S'il avait su, il serait venu."},{"words":["Eût-il su,","il eût","agit autrement."],"bad":2,"fix":"agi autrement.","hint":"The participle: <b>agi</b>.","look":"Look at the participle."},{"words":["Il fallait qu'ils","eût","fini."],"bad":1,"fix":"eussent","hint":"ils: <b>eussent</b>.","look":"Does it match ils?"}]},"drill":[["Literary: il (aimer, conditionnel passé 2e forme)","eût aimé","<b>eût</b> + participle."],["Modern form of « eût-il su »","s'il avait su","<b>si + plus-que-parfait</b>."],["Plus-que-parfait du subj.: qu'il (finir)","eût fini","qu'il <b>eût fini</b>."],["Plus-que-parfait du subj.: qu'elle (partir)","fût partie","être: <b>fût partie</b>."],["Modern form of « Il eût suffi »","Il aurait suffi","The conditionnel passé: <b>aurait suffi</b>."],["Modern form of « qu'il eût compris »","qu'il ait compris","The subjonctif passé: <b>ait compris</b>."]]},"v38":{"line":"In a two-part sentence, the second verb's tense depends on the first verb and on time: <b>same time</b>, <b>earlier</b> or <b>later</b>. Main verb in the <b>present</b>: est / est venu / viendra. Main verb in the <b>past</b>: <b>était</b> / <b>était venu</b> / <b>viendrait</b>. A fact still true can stay in the present (la Terre <b>tourne</b>). The subjonctif today stays présent or passé, even after a past verb.","words":"","steps":[{"tool":"line","title":"The second verb, after a past main verb","sub":"Je savais qu'il … : tap a point.","now":"","marks":[{"at":-0.75,"label":"earlier","fr":"Je savais qu'il était venu.","html":"Je savais qu'il <span class=\"gt-end\">était venu</span>.","en":"I knew he had come.","note":"Earlier: <b>plus-que-parfait</b>."},{"at":-0.25,"label":"same time","fr":"Je savais qu'il était là.","html":"Je savais qu'il <span class=\"gt-end\">était</span> là.","en":"I knew he was there.","note":"Same time: <b>imparfait</b>."},{"at":0.3,"label":"later","fr":"Je savais qu'il viendrait.","html":"Je savais qu'il <span class=\"gt-end\">viendrait</span>.","en":"I knew he would come.","note":"Later: <b>conditionnel présent</b>."},{"at":0.85,"label":"done before later","fr":"Je savais qu'il aurait fini à midi.","html":"Je savais qu'il <span class=\"gt-end\">aurait fini</span> à midi.","en":"I knew he would have finished by noon.","note":"<b>conditionnel passé</b>."}]},{"tool":"swap","title":"Move the main verb into the past","sub":"Pick a sentence and tap « In the past »: the second verb follows.","button":["In the past","In the present"],"legend":[["x","the main verb"],["p","the verb that follows"]],"items":[{"label":"Je sais qu'il est là.","en":["I know he is there.","I knew he was there."],"a":[["s","Je",""],["v","sais","x"],["q","qu'il",""],["w","est","p"],["o","là.",""]],"b":[["s","Je",""],["v","savais","x"],["q","qu'il",""],["w","était","p"],["o","là.",""]]},{"label":"Je pense qu'il a fini.","en":["I think he has finished.","I thought he had finished."],"a":[["s","Je",""],["v","pense","x"],["q","qu'il",""],["w","a fini.","p"]],"b":[["s","Je",""],["v","pensais","x"],["q","qu'il",""],["w","avait fini.","p"]]},{"label":"Il dit qu'il viendra.","en":["He says he'll come.","He said he would come."],"a":[["s","Il",""],["v","dit","x"],["q","qu'il",""],["w","viendra.","p"]],"b":[["s","Il",""],["v","a dit","x"],["q","qu'il",""],["w","viendrait.","p"]]},{"label":"Il faut que tu partes.","en":["You must leave.","You had to leave."],"a":[["s","Il",""],["v","faut","x"],["q","que tu",""],["w","partes.","p"]],"b":[["s","Il",""],["v","fallait","x"],["q","que tu",""],["w","partes.","p"]],"note":"The subjonctif <b>stays</b> présent in modern French."}]}],"practice":{"choose":[{"q":"Je savais qu'il ___ (venir, later).","en":"I knew he would come.","opts":["viendrait","viendra","venait","vienne"],"a":"viendrait","why":"Later, after a past verb.","hint":"<b>viendrait</b>."},{"q":"Je pensais qu'il ___ fini (earlier).","en":"I thought he had finished.","opts":["avait","a","aurait","ait"],"a":"avait","why":"Earlier, after a past verb.","hint":"<b>avait</b> fini."},{"q":"Il a dit qu'il ___ fatigué (same time).","en":"He said he was tired.","opts":["était","est","serait","soit"],"a":"était","why":"Same time, after a past verb.","hint":"<b>était</b>."},{"q":"Il fallait que tu ___.","en":"You had to leave.","opts":["partes","partisses","partais","partirais"],"a":"partes","why":"Modern: the present subjonctif.","hint":"que tu <b>partes</b>."},{"q":"Il a dit que la Terre ___ autour du Soleil.","en":"He said the Earth goes round the Sun.","opts":["tourne","tournait","tournerait","tourne-t-elle"],"a":"tourne","why":"A fact still true.","hint":"la Terre <b>tourne</b> (tournait is also heard)."},{"q":"Je sais qu'il ___ hier (earlier).","en":"I know he came yesterday.","opts":["est venu","était venu","viendrait","vient"],"a":"est venu","why":"Main verb present, earlier.","hint":"<b>est venu</b>."}],"build":[{"en":"I knew he would come.","tiles":["Je","savais","qu'il","viendrait."],"trap":"viendra.","why":"Later, after a past verb.","hint":"<b>viendrait</b>."},{"en":"I thought he had finished.","tiles":["Je","pensais","qu'il","avait","fini."],"trap":"a","why":"Earlier, after a past verb.","hint":"<b>avait</b> fini."},{"en":"He said he was tired.","tiles":["Il","a dit","qu'il","était","fatigué."],"trap":"est","why":"Same time, after a past verb.","hint":"<b>était</b>."},{"en":"You had to leave.","tiles":["Il","fallait","que tu","partes."],"trap":"partisses.","why":"Modern subjonctif.","hint":"que tu <b>partes</b>."},{"en":"I know he'll come.","tiles":["Je","sais","qu'il","viendra."],"trap":"viendrait.","why":"Main verb present, later: futur.","hint":"<b>viendra</b>."}],"spot":[{"words":["Il a dit qu'il","viendra","le lendemain."],"bad":1,"fix":"viendrait","hint":"After a past verb, later: <b>viendrait</b>.","look":"Is the main verb past?"},{"words":["Je pensais qu'il","a fini."],"bad":1,"fix":"avait fini.","hint":"Earlier, after a past verb: <b>avait fini</b>.","look":"Is the main verb past?"},{"words":["Je savais qu'il","est","là."],"bad":1,"fix":"était","hint":"Same time, after a past verb: <b>était</b>.","look":"Is the main verb past?"},{"words":["Je sais qu'il","viendrait."],"bad":1,"fix":"viendra.","hint":"Main verb present, later: <b>viendra</b>.","look":"Is the main verb past?"},{"words":["Il fallait que tu","partirais."],"bad":1,"fix":"partes.","hint":"After il fallait que: <b>partes</b>.","look":"Which mood?"}]},"drill":[["Je savais qu'il (venir, later, conditionnel)...","viendrait","Later, after a past verb: <b>viendrait</b>."],["Je pensais qu'il (finir, earlier)...","avait fini","Earlier: <b>avait fini</b>."],["Il a dit qu'il (être, same time, past)...","était","Same time: <b>était</b>."],["Il fallait que tu (partir, subj.)...","partes","Modern: <b>partes</b>."],["I know he'll come.","Je sais qu'il viendra.","Main verb present, later: <b>viendra</b>."],["I thought he had left.","Je pensais qu'il était parti.","Earlier: <b>était parti</b>."]]},"64":{"line":"Advanced concession, each with its mood. <b>bien que, quoique</b> + subjonctif; <b>même si</b> + indicative; <b>quand bien même</b> + <b>conditional</b> (even if, even supposing); <b>si / aussi / tout … que</b> + subjonctif (<b>si fort qu'il soit</b>); <b>quel que soit</b> (agrees: quelles que soient les raisons); <b>quoi que</b> (whatever) ≠ <b>quoique</b> (although); <b>avoir beau</b> + infinitive (il <b>a beau</b> essayer, il échoue). In writing: <b>certes… mais</b>, <b>néanmoins</b>, <b>en dépit de</b>.","words":"Debate words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:50\">Vocab 50 · Arguing & Debating</a>.","steps":[{"tool":"sort","title":"Which mood?","sub":"Tap the box for the verb that follows.","boxes":[{"k":"s","label":"subjonctif"},{"k":"i","label":"indicative"},{"k":"c","label":"conditional"},{"k":"inf","label":"infinitive"}],"cards":[{"t":"bien que","box":"s"},{"t":"même si","box":"i"},{"t":"quand bien même","box":"c","why":"Quand bien même il le <b>saurait</b>…"},{"t":"si fort que","box":"s","why":"Si fort qu'il <b>soit</b>…"},{"t":"quoi qu'il …","box":"s","why":"Quoi qu'il <b>arrive</b>…"},{"t":"avoir beau","box":"inf","why":"Il a beau <b>essayer</b>…"},{"t":"alors que","box":"i"},{"t":"quitte à","box":"inf","why":"Quitte à <b>perdre</b> du temps…"}]},{"tool":"flip","en":"b","title":"quoique or quoi que? quel que?","sub":"Tap a card.","cards":[{"a":"Quoiqu'il soit jeune…","b":"although (one word)","tag":"quoique"},{"a":"Quoi qu'il dise…","b":"whatever he says (two words)","tag":"quoi que"},{"a":"Quel que soit le prix…","b":"whatever the price","tag":"quel agrees: le prix"},{"a":"Quelles que soient les raisons…","b":"whatever the reasons","tag":"quelles: les raisons"},{"a":"Il a beau essayer, il échoue.","b":"However hard he tries, he fails.","tag":"avoir beau"},{"a":"Certes, c'est cher, mais c'est utile.","b":"Admittedly it's expensive, but it's useful.","tag":"certes … mais"}]}],"practice":{"choose":[{"q":"bien qu'il ___ fatigué","en":"although he is tired","opts":["soit","est","serait","sera"],"a":"soit","why":"bien que + subjonctif.","hint":"<b>soit</b>."},{"q":"___ soit le prix, je l'achète.","en":"Whatever the price, I'm buying it.","opts":["Quel que","Quelle que","Quoi que","Quelque"],"a":"Quel que","why":"le prix is masculine.","hint":"<b>Quel que</b> soit le prix."},{"q":"Il ___ essayer, il échoue.","en":"However hard he tries, he fails.","opts":["a beau","est beau","fait beau","a bien"],"a":"a beau","why":"avoir beau + infinitive.","hint":"il <b>a beau</b> essayer."},{"q":"Quand bien même il le ___, il se tairait.","en":"Even if he knew, he would keep quiet.","opts":["saurait","sait","sache","savait"],"a":"saurait","why":"quand bien même + conditional.","hint":"il le <b>saurait</b>."},{"q":"___ qu'il dise, je ne le crois pas.","en":"Whatever he says, I don't believe him.","opts":["Quoi","Quoique","Quel","Si"],"a":"Quoi","why":"whatever = two words.","hint":"<b>Quoi qu'il</b> dise."},{"q":"___ que soient les raisons…","en":"whatever the reasons…","opts":["Quelles","Quels","Quel","Quelle"],"a":"Quelles","why":"raisons is feminine plural.","hint":"<b>Quelles</b> que soient…"}],"build":[{"en":"although he is tired","tiles":["bien","qu'il","soit","fatigué"],"trap":"est","why":"bien que + subjonctif.","hint":"bien qu'il <b>soit</b>."},{"en":"whatever the price","tiles":["quel","que","soit","le prix"],"trap":"quelle","why":"le prix is masculine.","hint":"<b>quel que soit</b> le prix."},{"en":"However hard he tries, he fails.","tiles":["Il","a beau","essayer,","il échoue."],"trap":"essaie,","why":"avoir beau + infinitive.","hint":"il <b>a beau essayer</b>."},{"en":"come what may (whatever happens)","tiles":["quoi qu'il","arrive"],"trap":"arrivera","why":"quoi que + subjonctif.","hint":"quoi qu'il <b>arrive</b>."},{"en":"Strong as he is, he cannot lift it.","tiles":["Si fort","qu'il","soit,","il ne peut pas","le soulever."],"trap":"est,","why":"si … que + subjonctif.","hint":"si fort qu'il <b>soit</b>."}],"spot":[{"words":["Même s'il","pleuvrait,","nous sortirions."],"bad":1,"fix":"pleuvait,","hint":"même si never takes the conditional: <b>pleuvait</b>.","look":"Look after même si."},{"words":["Quel que soient","les raisons…"],"bad":0,"fix":"Quelles que soient","hint":"Agrees with raisons: <b>quelles</b>.","look":"Does quel match raisons?"},{"words":["Quoiqu'il dise,","je ne le crois pas."],"bad":0,"fix":"Quoi qu'il dise,","hint":"whatever = <b>quoi que</b> (two words).","look":"although, or whatever?"},{"words":["Il a beau","essaie,","il échoue."],"bad":1,"fix":"essayer,","hint":"avoir beau + <b>infinitive</b>.","look":"Look at the verb after beau."},{"words":["Bien qu'il","est","jeune, il est expérimenté."],"bad":1,"fix":"soit","hint":"bien que + <b>subjonctif</b>.","look":"Which mood?"}]},"drill":[["although he is tired (bien que)","bien qu'il soit fatigué","bien que + <b>subjonctif</b>."],["whatever the price","quel que soit le prix","<b>quel que soit</b>, agrees with prix."],["He tries in vain: Il ___ essayer.","a beau","<b>avoir beau</b> + infinitive."],["even if it rains","même s'il pleut","même si + <b>indicative</b>."],["whatever he says","quoi qu'il dise","<b>quoi que</b> + subjonctif."],["whatever the reasons","quelles que soient les raisons","<b>quelles</b>: agrees with raisons."]]},"65":{"line":"Precise links for cause and result. Cause + indicative: <b>puisque</b> (known reason), <b>étant donné que, vu que</b>, <b>d'autant plus que</b>, <b>sous prétexte que</b>. But <b>non que</b> + subjonctif (not that…). + a noun: <b>faute de</b>, <b>en raison de</b>, <b>grâce à</b>. Result: <b>si bien que, au point que</b> + indicative. <b>de sorte que</b>: a fact → indicative, an aim → subjonctif. Aim: <b>afin que, pour que</b>, <b>de peur que</b> (+ ne) + subjonctif.","words":"","steps":[{"tool":"swap","title":"de sorte que: result or aim?","sub":"Pick a sentence and tap « Make it an aim »: the mood changes.","button":["Make it an aim","Make it a result"],"legend":[["x","the verb"]],"items":[{"label":"Il a parlé fort de sorte que tous l'ont entendu.","en":["He spoke loudly, so everyone heard him. (result)","Speak loudly so that everyone hears you. (aim)"],"a":[["s","Il a parlé fort",""],["q","de sorte que tous",""],["v","l'ont entendu.","x"]],"b":[["s","Parle fort",""],["q","de sorte que tous",""],["v","t'entendent.","x"]],"note":"A fact: <b>indicative</b>. An aim: <b>subjonctif</b>."},{"label":"Il a expliqué, si bien que nous avons compris.","en":["He explained, so we understood. (result)","He explained so that we would understand. (aim)"],"a":[["s","Il a expliqué,",""],["q","si bien que nous",""],["v","avons compris.","x"]],"b":[["s","Il a expliqué",""],["q","afin que nous",""],["v","comprenions.","x"]]}]},{"tool":"sort","title":"What follows?","sub":"Tap the box.","boxes":[{"k":"i","label":"+ indicative"},{"k":"s","label":"+ subjonctif"},{"k":"n","label":"+ a noun"}],"cards":[{"t":"puisque","box":"i","why":"Puisque tu <b>es</b> là, aide-moi."},{"t":"non que","box":"s","why":"Non qu'il <b>soit</b> paresseux…"},{"t":"faute de","box":"n","why":"<b>Faute de temps</b>, nous avons renoncé."},{"t":"étant donné que","box":"i"},{"t":"afin que","box":"s"},{"t":"en raison de","box":"n","why":"<b>En raison de la grève</b>…"},{"t":"sous prétexte que","box":"i","why":"sous prétexte qu'il <b>était</b> malade"},{"t":"de peur que","box":"s","why":"de peur qu'on ne le <b>gronde</b>"},{"t":"si bien que","box":"i"}]}],"practice":{"choose":[{"q":"Puisque tu ___ là, aide-moi.","en":"Since you're here, help me.","opts":["es","sois","serais","étais"],"a":"es","why":"puisque + indicative.","hint":"tu <b>es</b>."},{"q":"Parle fort de sorte que tout le monde t'___.","en":"Speak loudly so that everyone hears you.","opts":["entende","entend","entendra","entendait"],"a":"entende","why":"An aim: subjonctif.","hint":"t'<b>entende</b>."},{"q":"Non qu'il ___ paresseux, mais il manque de motivation.","en":"Not that he's lazy, but he lacks motivation.","opts":["soit","est","serait","était"],"a":"soit","why":"non que + subjonctif.","hint":"<b>soit</b>."},{"q":"de peur qu'il ne nous ___","en":"for fear he might see us","opts":["voie","voit","verra","voyait"],"a":"voie","why":"de peur que + subjonctif.","hint":"ne nous <b>voie</b>."},{"q":"___ temps, nous avons renoncé.","en":"For lack of time, we gave up.","opts":["Faute de","Parce que","Puisque","Grâce au"],"a":"Faute de","why":"A noun follows.","hint":"<b>Faute de</b> temps."},{"q":"Il a plu, ___ le match a été annulé.","en":"It rained, so the match was cancelled.","opts":["si bien que","afin que","pour que","non que"],"a":"si bien que","why":"A result.","hint":"<b>si bien que</b>."}],"build":[{"en":"Since you're here, help me.","tiles":["Puisque","tu","es","là,","aide-moi."],"trap":"sois","why":"puisque + indicative.","hint":"tu <b>es</b> là."},{"en":"so that everyone hears you (aim)","tiles":["de sorte que","tout le monde","t'","entende"],"trap":"entend","why":"An aim: subjonctif.","hint":"t'<b>entende</b>."},{"en":"Not that he's lazy…","tiles":["Non","qu'il","soit","paresseux…"],"trap":"est","why":"non que + subjonctif.","hint":"<b>soit</b>."},{"en":"For lack of time, we gave up.","tiles":["Faute de","temps,","nous avons","renoncé."],"trap":"du","why":"faute de + a noun, no article.","hint":"<b>Faute de temps</b>."},{"en":"I'm delighted, all the more so as I know them.","tiles":["Je suis ravie,","d'autant plus que","je","les","connais."],"trap":"connaisse.","why":"d'autant plus que + indicative.","hint":"<b>je les connais</b>."}],"spot":[{"words":["Puisque tu","sois","là, aide-moi."],"bad":1,"fix":"es","hint":"puisque + <b>indicative</b>.","look":"Which mood?"},{"words":["Non qu'il","est","paresseux…"],"bad":1,"fix":"soit","hint":"non que + <b>subjonctif</b>.","look":"Which mood?"},{"words":["Il a parlé fort de sorte que tous","l'entendent","hier."],"bad":1,"fix":"l'ont entendu","hint":"A fact in the past: <b>indicative</b>, l'ont entendu.","look":"Is it a fact or an aim?","say":"Il a parlé fort de sorte que tous l'ont entendu hier."},{"words":["Faute du","temps,","nous avons renoncé."],"bad":0,"fix":"Faute de","hint":"faute de + a noun, <b>no article</b>.","look":"Look at du."},{"words":["de peur qu'il ne nous","voit"],"bad":1,"fix":"voie","hint":"de peur que + <b>subjonctif</b>.","look":"Which mood?"}]},"drill":[["Puisque tu (être) là, aide-moi.","es","puisque + <b>indicative</b>."],["Parle fort de sorte que tout le monde t'(entendre).","entende","An aim: <b>subjonctif</b>."],["Non qu'il (être) paresseux...","soit","non que + <b>subjonctif</b>."],["fear that (he sees us): de peur qu'il ne nous ___ (voir)","voie","de peur que + <b>subjonctif</b>."],["For lack of time","Faute de temps","<b>faute de</b> + a noun."],["It rained, so the match was cancelled.","Il a plu, si bien que le match a été annulé.","A result: <b>si bien que</b> + indicative."]]},"61":{"line":"In formal writing, some adverbs at the <b>start</b> of a sentence swap the subject and verb: <b>Peut-être viendra-t-il</b>. <b>Sans doute a-t-elle</b> oublié. <b>À peine était-il</b> sorti <b>qu'</b>il a plu. <b>Aussi est-il</b> rentré (aussi = therefore here). With a noun subject, keep the noun and add a pronoun: Peut-être <b>Marie viendra-t-elle</b>. Add <b>-t-</b> between two vowels: a-t-il. Easy option: <b>peut-être que</b> + normal order.","words":"Formal words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:54\">Vocab 54 · Formal & Official French</a>.","steps":[{"tool":"swap","title":"Make it formal","sub":"Pick a sentence and tap « Formal »: the adverb goes first and the verb jumps before the subject.","button":["Formal","Plain"],"legend":[["x","the adverb"],["p","verb + pronoun"]],"items":[{"label":"Il a peut-être oublié.","en":["He may have forgotten.","Perhaps he has forgotten."],"a":[["s","Il",""],["v","a",""],["x","peut-être","x"],["o","oublié.",""]],"b":[["x","Peut-être","x"],["v","a-t-il","p"],["o","oublié.",""]],"note":"a + il: add <b>-t-</b>."},{"label":"Elle est sans doute fatiguée.","en":["She's probably tired.","Doubtless she is tired."],"a":[["s","Elle",""],["v","est",""],["x","sans doute","x"],["o","fatiguée.",""]],"b":[["x","Sans doute","x"],["v","est-elle","p"],["o","fatiguée.",""]]},{"label":"Il était fatigué, donc il est rentré tôt.","en":["He was tired, so he went home early.","He was tired; therefore he went home early."],"a":[["a","Il était fatigué,",""],["x","donc","x"],["s","il",""],["v","est rentré tôt.",""]],"b":[["a","Il était fatigué ;",""],["x","aussi","x"],["v","est-il","p"],["o","rentré tôt.",""]],"note":"aussi + inversion = <b>therefore</b>."},{"label":"Marie viendra peut-être.","en":["Marie may come.","Perhaps Marie will come."],"a":[["n","Marie",""],["v","viendra",""],["x","peut-être.","x"]],"b":[["x","Peut-être","x"],["n","Marie",""],["v","viendra-t-elle.","p"]],"note":"A noun subject stays, and <b>-t-elle</b> repeats it."},{"label":"Il venait de sortir quand il a plu.","en":["He had just gone out when it rained.","No sooner had he gone out than it rained."],"a":[["s","Il",""],["v","venait de sortir",""],["q","quand",""],["o","il a plu.",""]],"b":[["x","À peine","x"],["v","était-il","p"],["o","sorti",""],["q","qu'il a plu.",""]],"note":"à peine … <b>que</b>."}]},{"tool":"sort","title":"aussi: also or therefore?","sub":"Tap the box.","boxes":[{"k":"also","label":"also","sub":"no inversion"},{"k":"so","label":"therefore","sub":"aussi + inversion, at the start"}],"cards":[{"t":"Il parle aussi anglais.","box":"also"},{"t":"Aussi est-il parti.","box":"so"},{"t":"Moi aussi.","box":"also"},{"t":"Le train était en retard ; aussi avons-nous manqué le début.","box":"so"},{"t":"Elle est aussi grande que lui.","box":"also","why":"as … as: no inversion."}]}],"practice":{"choose":[{"q":"Peut-être ___ oublié.","en":"Perhaps he has forgotten.","opts":["a-t-il","il a","a-il","at-il"],"a":"a-t-il","why":"Inversion, and -t- between vowels.","hint":"<b>a-t-il</b>."},{"q":"Sans doute ___ fatiguée.","en":"Doubtless she is tired.","opts":["est-elle","elle est","est-t-elle","elle-est"],"a":"est-elle","why":"Inversion after sans doute.","hint":"<b>est-elle</b>."},{"q":"À peine était-il arrivé ___ il a dû repartir.","en":"No sooner had he arrived than he had to leave.","opts":["qu'","quand","et","lorsqu'"],"a":"qu'","why":"à peine … que.","hint":"<b>qu'</b>il a dû…"},{"q":"En vain ___ cherché.","en":"In vain he searched.","opts":["a-t-il","il a","a-il","avait-il-"],"a":"a-t-il","why":"Inversion after en vain.","hint":"<b>a-t-il</b> cherché."},{"q":"Peut-être Marie ___.","en":"Perhaps Marie will come.","opts":["viendra-t-elle","viendra","viendra-elle","elle viendra"],"a":"viendra-t-elle","why":"A noun subject: add the pronoun.","hint":"Marie <b>viendra-t-elle</b>."},{"q":"Peut-être ___ viendra.","en":"Maybe he will come. (no inversion)","opts":["qu'il","il","viendra-t-il","que il"],"a":"qu'il","why":"peut-être que: normal order.","hint":"Peut-être <b>qu'il</b> viendra."}],"build":[{"en":"Perhaps he has forgotten.","tiles":["Peut-être","a-t-il","oublié."],"trap":"il a","why":"Inversion.","hint":"<b>Peut-être a-t-il</b>…"},{"en":"Doubtless she is tired.","tiles":["Sans doute","est-elle","fatiguée."],"trap":"elle est","why":"Inversion.","hint":"<b>Sans doute est-elle</b>…"},{"en":"No sooner had he arrived","tiles":["À peine","était-il","arrivé"],"trap":"il était","why":"Inversion.","hint":"<b>À peine était-il</b>…"},{"en":"In vain he searched.","tiles":["En vain","a-t-il","cherché."],"trap":"il a","why":"Inversion.","hint":"<b>En vain a-t-il</b>…"},{"en":"Perhaps Marie will come.","tiles":["Peut-être","Marie","viendra-t-elle."],"trap":"viendra.","why":"Keep the noun, add the pronoun.","hint":"Marie <b>viendra-t-elle</b>."}],"spot":[{"words":["Peut-être","il a","oublié."],"bad":1,"fix":"a-t-il","hint":"Inversion after peut-être: <b>a-t-il</b>.","look":"What happens after peut-être at the start?"},{"words":["Peut-être","a-il","oublié."],"bad":1,"fix":"a-t-il","hint":"Between two vowels: <b>-t-</b>.","look":"Look between a and il."},{"words":["Sans doute","elle est","fatiguée."],"bad":1,"fix":"est-elle","hint":"Inversion: <b>est-elle</b>.","look":"What happens after sans doute at the start?"},{"words":["À peine était-il sorti","quand","il a plu."],"bad":1,"fix":"qu'","hint":"à peine … <b>que</b>.","look":"à peine pairs with which word?","say":"À peine était-il sorti qu'il a plu."},{"words":["Peut-être","Marie viendra-elle."],"bad":1,"fix":"Marie viendra-t-elle.","hint":"<b>-t-</b> between two vowels.","look":"Look between viendra and elle."}]},"drill":[["Make formal: Il a peut-être oublié.","Peut-être a-t-il oublié.","Inversion after peut-être: <b>a-t-il</b>."],["Sans doute (elle / être) fatiguée.","Sans doute est-elle fatiguée.","Inversion: <b>est-elle</b>."],["À peine (il / arriver), il a dû repartir.","À peine était-il arrivé","Inversion: <b>était-il</b> arrivé."],["En vain (il / chercher).","En vain a-t-il cherché.","Inversion: <b>a-t-il</b> cherché."],["Perhaps Marie will come. (formal)","Peut-être Marie viendra-t-elle.","Noun + <b>viendra-t-elle</b>."],["Perhaps he will come. (no inversion)","Peut-être qu'il viendra.","<b>peut-être que</b> + normal order."]]},"69":{"line":"Three registers. <b>Familier</b> (friends, texting): un bouquin, le boulot, bosser, j'sais pas. <b>Courant</b> (the default): un livre, le travail, je ne sais pas. <b>Soutenu</b> (formal letters, speeches): un ouvrage, l'emploi, je ne saurais le dire. In a written test: no familiar words, keep <b>ne</b>, use <b>vous</b>. Questions climb too: Tu viens ? → Est-ce que tu viens ? → <b>Viens-tu ?</b>","words":"Spoken French: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:56\">Vocab 56 · Everyday Slang & Spoken French</a> · Formal: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:54\">Vocab 54 · Formal & Official French</a>.","steps":[{"tool":"agree","title":"One word, three registers","sub":"Switch the register.","cols":["familier","courant","soutenu"],"rows":[{"forms":["un bouquin","un livre","un ouvrage"],"en":"a book"},{"forms":["le boulot","le travail","l'emploi"],"en":"work, a job"},{"forms":["une bagnole","une voiture","un véhicule"],"en":"a car"},{"forms":["bouffer","manger","se restaurer"],"en":"to eat"},{"forms":["le fric","l'argent","les fonds"],"en":"money"},{"forms":["se planter","se tromper","commettre une erreur"],"en":"to get it wrong"},{"forms":["Tu viens ?","Est-ce que tu viens ?","Viens-tu ?"],"en":"Are you coming?"},{"forms":["Je sais pas.","Je ne sais pas.","Je ne saurais le dire."],"en":"I don't know."}]},{"tool":"sort","title":"Which register?","sub":"Tap the box.","boxes":[{"k":"f","label":"familier"},{"k":"c","label":"courant"},{"k":"s","label":"soutenu"}],"cards":[{"t":"un truc","box":"f"},{"t":"Cordialement","box":"c","why":"A standard email closing."},{"t":"Veuillez agréer mes salutations distinguées.","box":"s"},{"t":"bosser","box":"f"},{"t":"un policier","box":"c"},{"t":"Qu'est-ce donc ?","box":"s"},{"t":"C'est quoi ?","box":"f"},{"t":"un flic","box":"f"},{"t":"apprécier","box":"s","why":"Formal for aimer, adorer."}]}],"practice":{"choose":[{"q":"Formal word for « le boulot »: ___","en":"work, employment","opts":["l'emploi","le job","le taf","le boulot"],"a":"l'emploi","why":"soutenu…","hint":"<b>l'emploi</b>."},{"q":"Standard word for « une bagnole »: ___","en":"a car","opts":["une voiture","une caisse","un véhicule","une tire"],"a":"une voiture","why":"courant…","hint":"<b>une voiture</b>."},{"q":"Familiar word for « un livre »: ___","en":"a book","opts":["un bouquin","un ouvrage","un volume","un tome"],"a":"un bouquin","why":"familier…","hint":"<b>un bouquin</b>."},{"q":"Formal version of « Tu viens ? »: ___","en":"Are you coming?","opts":["Viens-tu ?","Tu viens ?","Tu viens, non ?","Tu viens ou quoi ?"],"a":"Viens-tu ?","why":"Inversion is formal.","hint":"<b>Viens-tu ?</b>"},{"q":"In a letter to a manager: « Je ___ pas disponible. »","en":"I'm not available.","opts":["ne suis","suis","s'suis","suis pas"],"a":"ne suis","why":"Keep ne in writing.","hint":"je <b>ne suis</b> pas."},{"q":"Formal email closing: ___","en":"Kind regards","opts":["Cordialement","Bisous","À plus","Salut"],"a":"Cordialement","why":"Standard and safe.","hint":"<b>Cordialement</b>."}],"build":[{"en":"I don't know. (standard)","tiles":["Je","ne","sais","pas."],"trap":"J'sais","why":"Keep ne.","hint":"je <b>ne</b> sais pas."},{"en":"Are you coming? (formal)","tiles":["Viens-tu","?"],"trap":"Tu viens","why":"Inversion.","hint":"<b>Viens-tu ?</b>"},{"en":"I couldn't say. (formal)","tiles":["Je","ne","saurais","le dire."],"trap":"sais","why":"ne saurais: very formal.","hint":"je <b>ne saurais</b> le dire."},{"en":"a car (standard)","tiles":["une","voiture"],"trap":"bagnole","why":"courant.","hint":"une <b>voiture</b>."},{"en":"Let's go. (standard)","tiles":["Allons-y","!"],"trap":"On y va","why":"nous in the imperative.","hint":"<b>Allons-y !</b>"}],"spot":[{"words":["Madame,","j'sais pas","si je peux venir."],"bad":1,"fix":"je ne sais pas","hint":"In a letter: <b>je ne sais pas</b>.","look":"Is this right for a letter?"},{"words":["Je vous écris","pour le boulot","que vous proposez."],"bad":1,"fix":"pour l'emploi","hint":"Formal: <b>l'emploi</b>.","look":"Is this word right for a letter?"},{"words":["Monsieur,","Bisous,","Paul"],"bad":1,"fix":"Cordialement,","hint":"Formal closing: <b>Cordialement</b>.","look":"How do you close a formal email?"},{"words":["Il a","bouffé","au restaurant."],"bad":1,"fix":"mangé","hint":"Standard: <b>manger</b>.","look":"Which register is bouffer?"},{"words":["Ce","truc","est important pour le projet."],"bad":1,"fix":"élément","hint":"Formal: <b>cet élément</b>.","look":"Which register is truc?","say":"Cet élément est important pour le projet."}]},"drill":[["Formal word for 'le boulot'","l'emploi","soutenu: <b>l'emploi</b>."],["Standard word for 'une bagnole'","une voiture","courant: <b>une voiture</b>."],["Familiar word for 'un livre'","un bouquin","familier: <b>un bouquin</b>."],["Formal version of 'Tu viens ?'","Viens-tu ?","Inversion: <b>Viens-tu ?</b>"],["Standard version of 'Je sais pas.'","Je ne sais pas.","Keep <b>ne</b>."],["Formal word for 'le fric'","les fonds","soutenu: <b>les fonds</b>."]]},"70":{"line":"An opinion text has a plan you can see: <b>introduction</b> (the topic, your question), <b>two or three arguments</b> each with an example, a <b>conclusion</b> (your answer, an opening). Connectors show the plan: introduce (<b>de nos jours</b>), add (<b>en outre, de plus, par ailleurs</b>), contrast (<b>en revanche, cependant, or</b>), explain (<b>en effet</b>), result (<b>par conséquent, dès lors</b>), example (<b>notamment, ainsi</b>), concede (<b>certes… mais</b>), conclude (<b>en somme, en définitive</b>). One per move is enough.","words":"Debate words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:50\">Vocab 50 · Arguing & Debating</a> · <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:44\">Vocab 44 · Ideas & Opinions</a>.","steps":[{"tool":"sort","title":"What does it do?","sub":"Tap the box for each connector.","boxes":[{"k":"add","label":"add"},{"k":"con","label":"contrast"},{"k":"res","label":"result"},{"k":"end","label":"conclude"}],"cards":[{"t":"en outre","box":"add"},{"t":"en revanche","box":"con"},{"t":"par conséquent","box":"res"},{"t":"en somme","box":"end"},{"t":"de plus","box":"add"},{"t":"néanmoins","box":"con"},{"t":"dès lors","box":"res"},{"t":"en définitive","box":"end"},{"t":"par ailleurs","box":"add"},{"t":"or","box":"con","why":"or: yet, now (a turn in the argument)."},{"t":"c'est pourquoi","box":"res"},{"t":"pour conclure","box":"end"}]},{"tool":"flip","title":"Spoken → written","sub":"Tap a card: the everyday word becomes the essay word.","cards":[{"a":"par contre","b":"en revanche","tag":"on the other hand"},{"a":"en plus","b":"en outre","tag":"moreover"},{"a":"donc","b":"par conséquent","tag":"therefore"},{"a":"mais bon","b":"néanmoins","tag":"nevertheless"},{"a":"par exemple","b":"notamment","tag":"in particular"},{"a":"bref","b":"en somme","tag":"in short"},{"a":"c'est vrai que… mais","b":"certes… mais","tag":"admittedly… but"}]}],"practice":{"choose":[{"q":"___, le télétravail réduit les déplacements.","en":"Moreover, remote work reduces travel.","opts":["En outre","Bref","Or","Par contre"],"a":"En outre","why":"moreover (formal)…","hint":"<b>En outre</b>."},{"q":"Le loyer est cher ; ___, le quartier est calme.","en":"The rent is high; on the other hand, the area is quiet.","opts":["en revanche","en outre","en somme","en effet"],"a":"en revanche","why":"on the other hand (formal)…","hint":"<b>en revanche</b>."},{"q":"___, c'est cher, mais c'est utile.","en":"Admittedly it's expensive, but it's useful.","opts":["Certes","Or","Donc","Ainsi"],"a":"Certes","why":"admittedly…","hint":"<b>Certes</b>."},{"q":"___, il faut trouver un équilibre.","en":"In short, a balance must be found.","opts":["En somme","En outre","Par ailleurs","Or"],"a":"En somme","why":"To conclude.","hint":"<b>En somme</b>."},{"q":"Les contacts se raréfient. ___, certains employés se sentent isolés.","en":"Contacts become rarer. As a result, some employees feel isolated.","opts":["Par conséquent","Certes","Néanmoins","Notamment"],"a":"Par conséquent","why":"A result.","hint":"<b>Par conséquent</b>."},{"q":"Plusieurs pays, ___ la France, ont adopté cette loi.","en":"Several countries, notably France, have adopted this law.","opts":["notamment","néanmoins","en revanche","or"],"a":"notamment","why":"An example.","hint":"<b>notamment</b>."}],"build":[{"en":"Moreover, it reduces travel.","tiles":["En outre,","il","réduit","les déplacements."],"trap":"Par contre,","why":"moreover = en outre.","hint":"<b>En outre</b>…"},{"en":"Admittedly it's practical, but it isolates people.","tiles":["Certes,","c'est pratique,","mais","cela isole."],"trap":"Or,","why":"certes … mais.","hint":"<b>Certes</b> … <b>mais</b>…"},{"en":"On the other hand, the area is quiet.","tiles":["En revanche,","le quartier","est","calme."],"trap":"Par contre,","why":"Written style.","hint":"<b>En revanche</b>…"},{"en":"In short, a balance must be found.","tiles":["En somme,","il faut","trouver","un équilibre."],"trap":"Bref,","why":"Written style.","hint":"<b>En somme</b>…"},{"en":"Therefore, we must act.","tiles":["Dès lors,","il faut","agir."],"trap":"Donc,","why":"Written style.","hint":"<b>Dès lors</b>…"}],"spot":[{"words":["Le train est cher ;","par contre,","il est rapide."],"bad":1,"fix":"en revanche,","hint":"In writing: <b>en revanche</b>.","look":"Spoken or written?"},{"words":["Bref,","il faut","trouver un équilibre."],"bad":0,"fix":"En somme,","hint":"In an essay: <b>En somme</b>.","look":"Spoken or written?"},{"words":["En plus,","cela coûte moins cher."],"bad":0,"fix":"En outre,","hint":"In an essay: <b>En outre</b>.","look":"Spoken or written?"},{"words":["C'est vrai que c'est cher,","donc","c'est utile."],"bad":1,"fix":"mais","hint":"A concession then a contrast: <b>mais</b>.","look":"Does « so » fit?"},{"words":["Mais bon,","il reste","des problèmes."],"bad":0,"fix":"Néanmoins,","hint":"In an essay: <b>Néanmoins</b>.","look":"Spoken or written?"}]},"drill":[["'moreover' (formal)","en outre","<b>en outre</b>."],["'on the other hand' (formal)","en revanche","<b>en revanche</b> (par contre is spoken)."],["'in short' (to conclude)","en somme","<b>en somme</b>."],["___, c'est cher, mais utile. (admittedly)","Certes","<b>Certes</b> … mais."],["'therefore' (formal)","par conséquent / dès lors","<b>par conséquent</b>, <b>dès lors</b>."],["'notably, in particular'","notamment","<b>notamment</b>."]]},"v40":{"line":"Tenses can do more than tell time. <b>Présent historique</b>: En 1789, le peuple <b>prend</b> la Bastille (vivid). <b>Imparfait de politesse</b>: Je <b>voulais</b> vous demander… (soft). <b>Futur de conjecture</b>: Ce <b>sera</b> Pierre (it must be). <b>Futur antérieur</b>: Il <b>aura oublié</b> (he must have). <b>Conditionnel de l'information</b>: Le ministre <b>démissionnerait</b> (reportedly). Reproach: Tu <b>aurais dû</b>… Read these for tone, not time.","words":"","steps":[{"tool":"sort","title":"What is the tense doing?","sub":"Tap the box.","boxes":[{"k":"pol","label":"polite"},{"k":"rep","label":"reportedly"},{"k":"guess","label":"a guess"},{"k":"viv","label":"vivid past"}],"cards":[{"t":"Je voulais vous demander un service.","box":"pol","why":"imparfait: softer than je veux."},{"t":"Le ministre démissionnerait demain.","box":"rep","why":"conditionnel: the paper does not confirm it."},{"t":"On sonne. Ce sera Pierre.","box":"guess","why":"futur: it must be Pierre."},{"t":"En 1789, le peuple prend la Bastille.","box":"viv","why":"présent historique."},{"t":"Il est en retard. Il aura oublié.","box":"guess","why":"futur antérieur: he must have forgotten."},{"t":"Pourriez-vous m'aider ?","box":"pol","why":"conditionnel de politesse."},{"t":"L'incendie aurait fait trois victimes.","box":"rep","why":"conditionnel passé: not confirmed."},{"t":"Un instant plus tard, la voiture quittait la route.","box":"viv","why":"imparfait de rupture: a sudden event."}]},{"tool":"flip","en":"b","title":"What does it really mean?","sub":"Tap a card.","cards":[{"a":"Le ministre démissionnerait.","b":"The minister has reportedly resigned / is said to resign.","tag":"not « would »"},{"a":"Je voulais vous demander…","b":"I wanted to ask you… (polite)","tag":"imparfait"},{"a":"Il aura oublié.","b":"He must have forgotten.","tag":"futur antérieur"},{"a":"Tu aurais dû me le dire.","b":"You should have told me. (reproach)","tag":"conditionnel passé"},{"a":"Un pas de plus, il tombait.","b":"One more step and he would have fallen.","tag":"imparfait = would have"},{"a":"Tu feras ça demain.","b":"You'll do that tomorrow. (a soft order)","tag":"futur"}]}],"practice":{"choose":[{"q":"Le ministre ___ demain. (reportedly)","en":"The minister will reportedly resign tomorrow.","opts":["démissionnerait","démissionnera","démissionne","démissionnait"],"a":"démissionnerait","why":"Unconfirmed news: the conditional.","hint":"<b>démissionnerait</b>."},{"q":"Je ___ vous demander un service.","en":"I wanted to ask you a favour. (polite)","opts":["voulais","veux","voudrai","ai voulu"],"a":"voulais","why":"The polite imparfait.","hint":"je <b>voulais</b>."},{"q":"Il est en retard, il ___ oublié.","en":"He's late, he must have forgotten.","opts":["aura","a","aurait","avait"],"a":"aura","why":"A guess about the past.","hint":"il <b>aura</b> oublié."},{"q":"On sonne. Ce ___ Pierre.","en":"Someone's at the door. It must be Pierre.","opts":["sera","est","serait","était"],"a":"sera","why":"A guess: the future.","hint":"ce <b>sera</b> Pierre."},{"q":"Tu ___ me le dire !","en":"You should have told me!","opts":["aurais dû","devrais","as dû","devras"],"a":"aurais dû","why":"A reproach.","hint":"tu <b>aurais dû</b>."},{"q":"L'incendie ___ trois victimes.","en":"The fire reportedly left three victims.","opts":["aurait fait","a fait","fera","avait fait"],"a":"aurait fait","why":"Unconfirmed, in the past.","hint":"<b>aurait fait</b>."}],"build":[{"en":"I wanted to ask you a favour. (polite)","tiles":["Je","voulais","vous demander","un service."],"trap":"veux","why":"The polite imparfait.","hint":"je <b>voulais</b>."},{"en":"He must have forgotten.","tiles":["Il","aura","oublié."],"trap":"a","why":"A guess: futur antérieur.","hint":"il <b>aura</b> oublié."},{"en":"The minister has reportedly resigned.","tiles":["Le ministre","aurait","démissionné."],"trap":"a","why":"Unconfirmed: conditionnel passé.","hint":"<b>aurait démissionné</b>."},{"en":"You should have told me.","tiles":["Tu","aurais dû","me le","dire."],"trap":"devrais","why":"A reproach.","hint":"tu <b>aurais dû</b>."},{"en":"It must be Pierre.","tiles":["Ce","sera","Pierre."],"trap":"est","why":"A guess: the future.","hint":"ce <b>sera</b> Pierre."}],"spot":[{"words":["Selon la presse,","le ministre a démissionné,","mais rien n'est confirmé."],"bad":1,"fix":"le ministre aurait démissionné,","hint":"Not confirmed: <b>aurait démissionné</b>.","look":"Is the fact confirmed?"},{"words":["Je","veux","vous demander un service, si possible."],"bad":1,"fix":"voulais","hint":"Polite: <b>je voulais</b>.","look":"Polite or direct?"},{"words":["Il est en retard.","Il a sûrement","oublié."],"bad":1,"fix":"Il aura","hint":"A guess: <b>Il aura oublié.</b>","look":"Use the tense for a guess.","say":"Il est en retard. Il aura oublié."},{"words":["Tu","devrais","me le dire hier !"],"bad":1,"fix":"aurais dû","hint":"A past reproach: <b>aurais dû</b>.","look":"Is it about the past?"},{"words":["On sonne.","C'est sûrement","Pierre."],"bad":1,"fix":"Ce sera","hint":"A guess: <b>Ce sera</b> Pierre.","look":"Use the tense for a guess."}]},"drill":[["Le ministre démissionnerait = ?","reportedly, unconfirmed","The <b>conditionnel de l'information</b>."],["Je voulais vous demander... = ?","polite softening / politeness / polite","The polite <b>imparfait</b>."],["Il aura oublié = ?","he must have forgotten","A guess: <b>futur antérieur</b>."],["Tu aurais dû... = ?","reproach: you should have / reproach / you should have","A reproach: <b>conditionnel passé</b>."],["It must be Pierre. (a guess)","Ce sera Pierre.","A guess: the <b>futur</b>."],["The fire reportedly left three victims.","L'incendie aurait fait trois victimes.","Unconfirmed: <b>aurait fait</b>."]]},"v41":{"line":"Some verbs exist only in a few forms: learn them in their set phrases. <b>falloir, pleuvoir</b>: only « il ». <b>gésir</b>: <b>ci-gît</b> (here lies). <b>clore</b>: le débat est <b>clos</b>. <b>échoir</b>: le loyer <b>échoit</b> le 1er; <b>le cas échéant</b> (if need be). <b>seoir</b>: cette robe lui <b>sied</b>. <b>faillir</b> + infinitive = almost: j'<b>ai failli</b> tomber (not « j'ai presque tombé »). <b>ouïr</b>: par <b>ouï-dire</b> (by hearsay).","words":"","steps":[{"tool":"pairs","title":"In their set phrases","sub":"Tap the French to hear it.","cap":["French","meaning"],"right":"en","rows":[{"l":"J'ai failli tomber.","r":"I almost fell.","en":"faillir + infinitive"},{"l":"Ci-gît le poète.","r":"Here lies the poet.","en":"gésir"},{"l":"Le débat est clos.","r":"The debate is closed.","en":"clore"},{"l":"Le loyer échoit le premier du mois.","r":"The rent falls due on the 1st.","en":"échoir"},{"l":"le cas échéant","r":"if need be, should the case arise","en":"échoir"},{"l":"Cette robe lui sied à merveille.","r":"This dress suits her perfectly.","en":"seoir"},{"l":"par ouï-dire","r":"by hearsay","en":"ouïr"},{"l":"Faites frire les oignons.","r":"Fry the onions.","en":"frire: use faire frire"}]},{"tool":"flip","title":"Which verb is hiding?","sub":"Tap a card.","cards":[{"a":"il gît","b":"gésir","tag":"he lies (dead, ill)"},{"a":"clos","b":"clore","tag":"closed"},{"a":"échu","b":"échoir","tag":"fallen due"},{"a":"il sied","b":"seoir","tag":"it suits"},{"a":"j'ai failli","b":"faillir","tag":"I almost"},{"a":"il fallut","b":"falloir","tag":"it was necessary (passé simple)"},{"a":"il plut","b":"pleuvoir","tag":"it rained (passé simple)"}]}],"practice":{"choose":[{"q":"Le loyer ___ le premier du mois.","en":"The rent falls due on the 1st.","opts":["échoit","échoue","échouit","échue"],"a":"échoit","why":"échoir, present.","hint":"il <b>échoit</b>."},{"q":"J'ai ___ tomber.","en":"I almost fell.","opts":["failli","presque","faili","fallu"],"a":"failli","why":"faillir + infinitive.","hint":"j'ai <b>failli</b> tomber."},{"q":"Le débat est ___.","en":"The debate is closed.","opts":["clos","closé","clôt","clore"],"a":"clos","why":"clore, participle.","hint":"est <b>clos</b>."},{"q":"le cas ___","en":"if the case arises","opts":["échéant","échouant","échu","échéance"],"a":"échéant","why":"A set phrase.","hint":"le cas <b>échéant</b>."},{"q":"___ le poète.","en":"Here lies the poet.","opts":["Ci-gît","Ici gît","Ci-git","Ici est"],"a":"Ci-gît","why":"On a grave.","hint":"<b>Ci-gît</b>."},{"q":"Je ne le sais que par ___.","en":"I only know it by hearsay.","opts":["ouï-dire","oui-dire","entendu-dire","ouïr"],"a":"ouï-dire","why":"A set phrase.","hint":"par <b>ouï-dire</b>."}],"build":[{"en":"I almost fell.","tiles":["J'ai","failli","tomber."],"trap":"presque","why":"faillir + infinitive.","hint":"j'ai <b>failli</b> tomber."},{"en":"The debate is closed.","tiles":["Le débat","est","clos."],"trap":"closé.","why":"clore → clos.","hint":"est <b>clos</b>."},{"en":"if the case arises","tiles":["le cas","échéant"],"trap":"échu","why":"A set phrase.","hint":"le cas <b>échéant</b>."},{"en":"Here lies the poet.","tiles":["Ci-gît","le poète."],"trap":"Ici","why":"On a grave.","hint":"<b>Ci-gît</b>…"},{"en":"This dress suits her perfectly.","tiles":["Cette robe","lui","sied","à merveille."],"trap":"siège","why":"seoir → sied.","hint":"lui <b>sied</b>."}],"spot":[{"words":["J'ai","presque tombé."],"bad":1,"fix":"failli tomber.","hint":"almost did: <b>j'ai failli tomber</b>.","look":"How do you say « almost fell »?","say":"J'ai failli tomber."},{"words":["Le débat est","closé."],"bad":1,"fix":"clos.","hint":"clore → <b>clos</b>.","look":"Look at the participle."},{"words":["Le loyer","échoue","le premier du mois."],"bad":1,"fix":"échoit","hint":"échoir: <b>échoit</b> (échouer = to fail).","look":"fail or fall due?"},{"words":["le cas","échu"],"bad":1,"fix":"échéant","hint":"A set phrase: <b>le cas échéant</b>.","look":"Look at the set phrase."},{"words":["Ci-git","le poète."],"bad":0,"fix":"Ci-gît","hint":"With a circumflex: <b>Ci-gît</b>.","look":"Look at the accent."}]},"drill":[["Il ___ le premier du mois. (échoir, présent)","échoit","échoir: <b>échoit</b>."],["I almost fell: J'ai ___ tomber.","failli","<b>faillir</b> + infinitive."],["Le débat est ___ (clore, participe).","clos","clore → <b>clos</b>."],["le cas ___ = if the case arises","échéant","<b>le cas échéant</b>."],["Here lies the poet.","Ci-gît le poète.","<b>Ci-gît</b>: gésir."],["by hearsay","par ouï-dire","<b>ouï-dire</b>: ouïr."]]},"v42":{"line":"The last traps in verbs you know. Future stems with <b>-rr-</b>: j'<b>enverrai</b>, je <b>verrai</b>, je <b>pourrai</b>, je <b>courrai</b>, je <b>mourrai</b>, j'<b>acquerrai</b>. <b>cueillir</b> takes -er endings: je <b>cueillerai</b>. Only the masculine singular keeps the circumflex: <b>dû</b> but due, dus; <b>crû</b> (croître) vs cru (croire). Double forms: je m'assois / je m'assieds, je paie / je paye. Don't mix je <b>saurai</b> (savoir) and je <b>serai</b> (être).","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"conj","title":"Future stems with -rr-","sub":"Pick a verb, then tap a person.","neg":false,"verbs":[{"inf":"envoyer","en":"will send","stem":"enverr","forms":["enverrai","enverras","enverra","enverrons","enverrez","enverront"],"tail":""},{"inf":"courir","en":"will run","stem":"courr","forms":["courrai","courras","courra","courrons","courrez","courront"],"tail":""},{"inf":"mourir","en":"will die","stem":"mourr","forms":["mourrai","mourras","mourra","mourrons","mourrez","mourront"],"tail":""},{"inf":"cueillir","en":"will pick","stem":"cueiller","forms":["cueillerai","cueilleras","cueillera","cueillerons","cueillerez","cueilleront"],"tail":""}]},{"tool":"agree","title":"The circumflex only on the masculine singular","sub":"Switch the form.","cols":["masc. sing.","fem. sing.","masc. pl.","fem. pl."],"rows":[{"forms":["dû","due","dus","dues"],"en":"devoir"},{"forms":["mû","mue","mus","mues"],"en":"mouvoir"},{"forms":["crû","crue","crus","crues"],"en":"croître (cru = croire)"},{"forms":["absous","absoute","absous","absoutes"],"en":"absoudre"}]}],"practice":{"choose":[{"q":"Futur: j'___ (envoyer)","en":"I will send","opts":["enverrai","envoierai","envoyerai","enverai"],"a":"enverrai","why":"An -rr- stem.","hint":"j'<b>enverrai</b>."},{"q":"Futur: il ___ (mourir)","en":"he will die","opts":["mourra","mourira","moura","meurera"],"a":"mourra","why":"An -rr- stem.","hint":"il <b>mourra</b>."},{"q":"Participe passé masculin de devoir: ___","en":"had to (masc.)","opts":["dû","du","dut","dûe"],"a":"dû","why":"A circumflex: not du (de + le).","hint":"<b>dû</b>."},{"q":"Futur: je ___ (voir)","en":"I will see","opts":["verrai","voirai","verai","voierai"],"a":"verrai","why":"An -rr- stem.","hint":"je <b>verrai</b>."},{"q":"Futur: je ___ (cueillir)","en":"I will pick","opts":["cueillerai","cueillirai","cueillrai","cueilliai"],"a":"cueillerai","why":"-er endings.","hint":"je <b>cueillerai</b>."},{"q":"la somme ___","en":"the sum owed","opts":["due","dûe","dû","du"],"a":"due","why":"Feminine: no circumflex.","hint":"la somme <b>due</b>."}],"build":[{"en":"I will send","tiles":["j'","enverrai"],"trap":"envoierai","why":"An -rr- stem.","hint":"j'<b>enverrai</b>."},{"en":"he will die","tiles":["il","mourra"],"trap":"mourira","why":"An -rr- stem.","hint":"il <b>mourra</b>."},{"en":"we will run","tiles":["nous","courrons"],"trap":"courirons","why":"An -rr- stem.","hint":"nous <b>courrons</b>."},{"en":"the sums owed","tiles":["les sommes","dues"],"trap":"dûes","why":"Feminine plural: no circumflex.","hint":"les sommes <b>dues</b>."},{"en":"I will know (savoir)","tiles":["je","saurai"],"trap":"serai","why":"savoir → saur-.","hint":"je <b>saurai</b>."}],"spot":[{"words":["j'","envoierai","la lettre"],"bad":1,"fix":"enverrai","hint":"envoyer → <b>enverr-</b>.","look":"Look at the stem."},{"words":["la somme","dûe"],"bad":1,"fix":"due","hint":"Only the masculine singular: <b>dû</b>.","look":"Look at the accent."},{"words":["je","cueillirai","des fleurs"],"bad":1,"fix":"cueillerai","hint":"cueillir takes -er endings: <b>cueillerai</b>.","look":"Look at the ending."},{"words":["il","mourira","un jour"],"bad":1,"fix":"mourra","hint":"mourir → <b>mourr-</b>.","look":"Look at the stem."},{"words":["Demain, je","serai","la réponse."],"bad":1,"fix":"saurai","hint":"to know: <b>saurai</b> (serai = être).","look":"know or be?"}]},"drill":[["Futur: j'(envoyer)","enverrai","envoyer → <b>enverr-</b>."],["Futur: il (mourir)","mourra","mourir → <b>mourr-</b>."],["Participe passé masculin de devoir","dû","With a circumflex: <b>dû</b>."],["Futur: je (voir)","verrai","voir → <b>verr-</b>."],["Futur: je (cueillir)","cueillerai","-er endings: <b>cueillerai</b>."],["Futur: nous (courir)","courrons","courir → <b>courr-</b>."]]},"v43":{"line":"Some verbs take <b>either mood</b>, and the meaning changes. Indicative = presented as <b>real</b>; subjonctif = a <b>doubt, a wish, a judgement</b>. Il <b>me</b> semble qu'il <b>a</b> raison / Il semble qu'il <b>ait</b> raison. Il dit qu'il <b>vient</b> (a fact) / qu'il <b>vienne</b> (an order). Je comprends qu'il <b>est</b> fâché (I realise) / qu'il <b>soit</b> fâché (I find it natural). Je cherche un hôtel qui <b>a</b> (a known one) / qui <b>ait</b> (any) une piscine. Always subjonctif: <b>où que, quoi que, quel que, s'attendre à ce que</b>. Always indicative: <b>espérer, il paraît que, après que</b>.","words":"","steps":[{"tool":"swap","title":"Same verb, two meanings","sub":"Pick a sentence and tap « Other mood »: read the English.","button":["Other mood","Back"],"legend":[["x","the verb that changes"]],"items":[{"label":"Il dit qu'il vient.","en":["He says he's coming. (a fact)","He says he should come. (an order)"],"a":[["s","Il dit qu'il",""],["v","vient.","x"]],"b":[["s","Il dit qu'il",""],["v","vienne.","x"]]},{"label":"Je comprends qu'il est fâché.","en":["I realise he's angry.","I can see why he's angry. (a judgement)"],"a":[["s","Je comprends qu'il",""],["v","est","x"],["o","fâché.",""]],"b":[["s","Je comprends qu'il",""],["v","soit","x"],["o","fâché.",""]]},{"label":"Je cherche un hôtel qui a une piscine.","en":["I am looking for a (specific) hotel that has a pool.","I want any hotel that has a pool."],"a":[["s","Je cherche un hôtel qui",""],["v","a","x"],["o","une piscine.",""]],"b":[["s","Je cherche un hôtel qui",""],["v","ait","x"],["o","une piscine.",""]]},{"label":"Le fait qu'il est parti prouve tout.","en":["The fact that he left proves everything. (a fact)","That he left surprises me. (a judgement)"],"a":[["s","Le fait qu'il",""],["v","est parti","x"],["o","prouve tout.",""]],"b":[["s","Le fait qu'il",""],["v","soit parti","x"],["o","m'étonne.",""]]},{"label":"Il me semble qu'il a raison.","en":["It seems to me he is right. (my opinion)","It seems he may be right. (doubt)"],"a":[["s","Il me semble qu'il",""],["v","a","x"],["o","raison.",""]],"b":[["s","Il semble qu'il",""],["v","ait","x"],["o","raison.",""]]}]},{"tool":"sort","title":"Which mood, always?","sub":"Tap the box.","boxes":[{"k":"s","label":"always subjonctif"},{"k":"i","label":"always indicative"}],"cards":[{"t":"où que","box":"s","why":"Où que vous <b>alliez</b>…"},{"t":"espérer que","box":"i","why":"J'espère qu'il <b>viendra</b>."},{"t":"s'attendre à ce que","box":"s","why":"Je m'attends à ce qu'il <b>refuse</b>."},{"t":"il paraît que","box":"i","why":"Il paraît qu'il <b>a</b> raison."},{"t":"quel que soit","box":"s"},{"t":"après que","box":"i","why":"Après qu'il <b>est</b> parti…"},{"t":"il se peut que","box":"s","why":"Il se peut qu'il <b>pleuve</b>."},{"t":"être sûr que","box":"i"}]}],"practice":{"choose":[{"q":"Il me semble qu'il ___ raison.","en":"It seems to me he is right.","opts":["a","ait","aurait","aura"],"a":"a","why":"il me semble que: an opinion.","hint":"<b>a</b>."},{"q":"Il semble qu'il ___ raison.","en":"It seems he may be right.","opts":["ait","a","aura","avait"],"a":"ait","why":"il semble que: doubt.","hint":"<b>ait</b>."},{"q":"J'espère qu'il ___.","en":"I hope he'll come.","opts":["viendra","vienne","viendrait","vînt"],"a":"viendra","why":"espérer: indicative.","hint":"<b>viendra</b>."},{"q":"Où que tu ___, je te suivrai.","en":"Wherever you go, I will follow you.","opts":["ailles","vas","iras","allais"],"a":"ailles","why":"où que + subjonctif.","hint":"<b>ailles</b>."},{"q":"Je m'attends à ce qu'il ___.","en":"I expect him to refuse.","opts":["refuse","refusera","refuserait","refusait"],"a":"refuse","why":"s'attendre à ce que + subjonctif.","hint":"<b>refuse</b>."},{"q":"Il paraît qu'il ___ démissionné.","en":"Apparently he has resigned.","opts":["a","ait","aurait","eût"],"a":"a","why":"il paraît que: indicative.","hint":"<b>a</b> démissionné."}],"build":[{"en":"It seems to me he is right.","tiles":["Il me semble","qu'il","a","raison."],"trap":"ait","why":"An opinion: indicative.","hint":"qu'il <b>a</b> raison."},{"en":"It seems he may be right.","tiles":["Il semble","qu'il","ait","raison."],"trap":"a","why":"Doubt: subjonctif.","hint":"qu'il <b>ait</b> raison."},{"en":"Wherever you go, I will follow you.","tiles":["Où que","tu","ailles,","je te suivrai."],"trap":"vas,","why":"où que + subjonctif.","hint":"<b>ailles</b>."},{"en":"I can see why he's angry.","tiles":["Je comprends","qu'il","soit","fâché."],"trap":"est","why":"A judgement: subjonctif.","hint":"<b>soit</b>."},{"en":"Apparently he is right.","tiles":["Il paraît","qu'il","a","raison."],"trap":"ait","why":"il paraît que: indicative.","hint":"<b>a</b>."}],"spot":[{"words":["J'espère qu'il","vienne."],"bad":1,"fix":"viendra.","hint":"espérer takes the <b>indicative</b>.","look":"Which mood after espérer?"},{"words":["Où que tu","vas,","je te suivrai."],"bad":1,"fix":"ailles,","hint":"où que + <b>subjonctif</b>.","look":"Which mood after où que?"},{"words":["Il paraît qu'il","ait","raison."],"bad":1,"fix":"a","hint":"il paraît que: <b>indicative</b>.","look":"Which mood after il paraît que?"},{"words":["Après qu'il","soit parti,","nous avons mangé."],"bad":1,"fix":"est parti,","hint":"après que: <b>indicative</b>.","look":"Which mood after après que?"},{"words":["Je m'attends à ce qu'il","refusera."],"bad":1,"fix":"refuse.","hint":"s'attendre à ce que + <b>subjonctif</b>.","look":"Which mood?"}]},"drill":[["Il me semble qu'il (avoir) raison. (opinion)","a","An opinion: <b>a</b>."],["Il semble qu'il (avoir) raison. (doubt)","ait","Doubt: <b>ait</b>."],["J'espère qu'il (venir, futur)","viendra","espérer: <b>indicative</b>."],["Où que tu (aller), je te suivrai.","ailles","où que + <b>subjonctif</b>."],["Je m'attends à ce qu'il (refuser).","refuse","s'attendre à ce que + <b>subjonctif</b>."],["Il dit qu'il (venir) — an order","vienne","An order: <b>vienne</b>."]]},"71":{"line":"Formal French keeps old fixed forms. A subjonctif with inversion = « even if »: <b>Fût-il roi</b>, il doit obéir (even if he were king). <b>Dût-il</b> attendre… (even if he had to). A wish: <b>Puisse-t-il</b> réussir ! Set phrases: <b>advienne que pourra</b> (come what may), <b>coûte que coûte</b> (at all costs), <b>si tant est que</b> + subjonctif (assuming that), <b>pour autant que je sache</b> (as far as I know), <b>qu'à cela ne tienne</b> (never mind).","words":"Idioms: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:53\">Vocab 53 · Idioms & Expressions</a>.","steps":[{"tool":"pairs","title":"Fixed forms in use","sub":"Tap the French to hear it.","cap":["French","meaning"],"right":"en","rows":[{"l":"Fût-il roi, il doit obéir à la loi.","r":"Even if he were king, he must obey the law.","en":"fût-il = even if he were"},{"l":"Dût-il attendre des heures, il restera.","r":"Even if he has to wait for hours, he will stay.","en":"dût-il = even if he had to"},{"l":"Puisse-t-il réussir !","r":"May he succeed!","en":"a wish"},{"l":"Je le ferai, advienne que pourra.","r":"I'll do it, come what may.","en":""},{"l":"Il veut gagner coûte que coûte.","r":"He wants to win at all costs.","en":""},{"l":"Si tant est qu'il soit honnête…","r":"Assuming that he is honest…","en":"+ subjonctif"},{"l":"Pour autant que je sache, il est parti.","r":"As far as I know, he has left.","en":"+ subjonctif"},{"l":"Pas de voiture ? Qu'à cela ne tienne !","r":"No car? Never mind!","en":""}]},{"tool":"flip","title":"Plain French → fixed form","sub":"Tap a card.","cards":[{"a":"même s'il était roi","b":"fût-il roi","tag":"literary"},{"a":"à tout prix","b":"coûte que coûte","tag":"at all costs"},{"a":"je souhaite qu'il réussisse","b":"puisse-t-il réussir","tag":"a wish"},{"a":"à condition qu'il soit honnête","b":"si tant est qu'il soit honnête","tag":"if indeed"},{"a":"à ma connaissance","b":"pour autant que je sache","tag":"as far as I know"},{"a":"ce n'est pas grave","b":"qu'à cela ne tienne","tag":"never mind"}]}],"practice":{"choose":[{"q":"___ roi, il doit obéir à la loi.","en":"Even if he were king, he must obey the law.","opts":["Fût-il","Fut-il","Soit-il","Était-il"],"a":"Fût-il","why":"even if he were (literary).","hint":"<b>Fût-il</b>."},{"q":"Si tant est qu'il ___ honnête…","en":"Assuming that he is honest…","opts":["soit","est","serait","sera"],"a":"soit","why":"si tant est que + subjonctif.","hint":"qu'il <b>soit</b>."},{"q":"Je le ferai, advienne que ___.","en":"I'll do it, come what may.","opts":["pourra","pourrait","peut","puisse"],"a":"pourra","why":"A fixed phrase.","hint":"advienne que <b>pourra</b>."},{"q":"Pour autant que je ___, il est parti.","en":"As far as I know, he has left.","opts":["sache","sais","saurai","savais"],"a":"sache","why":"pour autant que + subjonctif.","hint":"je <b>sache</b>."},{"q":"Il veut gagner coûte que ___.","en":"He wants to win at all costs.","opts":["coûte","coûtera","coûtait","coûté"],"a":"coûte","why":"A fixed phrase.","hint":"coûte que <b>coûte</b>."},{"q":"___-t-il réussir !","en":"May he succeed!","opts":["Puisse","Peut","Pourra","Puisses"],"a":"Puisse","why":"A wish.","hint":"<b>Puisse-t-il</b> réussir !"}],"build":[{"en":"even if he were king","tiles":["fût-il","roi"],"trap":"fut-il","why":"With a circumflex.","hint":"<b>fût-il</b> roi."},{"en":"assuming that he is honest","tiles":["si tant est","qu'il","soit","honnête"],"trap":"est","why":"si tant est que + subjonctif.","hint":"<b>soit</b>."},{"en":"come what may","tiles":["advienne","que","pourra"],"trap":"peut","why":"A fixed phrase.","hint":"advienne que <b>pourra</b>."},{"en":"as far as I know","tiles":["pour autant","que","je","sache"],"trap":"sais","why":"pour autant que + subjonctif.","hint":"je <b>sache</b>."},{"en":"May he succeed!","tiles":["Puisse-t-il","réussir !"],"trap":"Peut-il","why":"A wish.","hint":"<b>Puisse-t-il</b> réussir !"}],"spot":[{"words":["Si tant est qu'il","est","honnête…"],"bad":1,"fix":"soit","hint":"si tant est que + <b>subjonctif</b>.","look":"Which mood?"},{"words":["Pour autant que je","sais,","il est parti."],"bad":1,"fix":"sache,","hint":"pour autant que + <b>subjonctif</b>.","look":"Which mood?"},{"words":["Fut-il","roi,","il doit obéir."],"bad":0,"fix":"Fût-il","hint":"With a circumflex: <b>fût-il</b>.","look":"Look at the accent."},{"words":["Advienne que","pourrait,","je le ferai."],"bad":1,"fix":"pourra,","hint":"Fixed: advienne que <b>pourra</b>.","look":"Look at the fixed phrase."},{"words":["Il veut gagner","coûte que coûtera."],"bad":1,"fix":"coûte que coûte.","hint":"Fixed: <b>coûte que coûte</b>.","look":"Look at the fixed phrase."}]},"drill":[["'even if he were' (literary)","fût-il","<b>fût-il</b>."],["'assuming that he is honest'","si tant est qu'il soit honnête","si tant est que + <b>subjonctif</b>."],["'come what may'","advienne que pourra","<b>advienne que pourra</b>."],["'as far as I know'","pour autant que je sache","pour autant que + <b>sache</b>."],["'at all costs'","coûte que coûte","<b>coûte que coûte</b>."],["'May he succeed!'","Puisse-t-il réussir !","A wish: <b>Puisse-t-il</b>."]]},"72":{"line":"Two kinds of <b>ne</b> with no pas. The <b>ne explétif</b> means nothing: Je crains qu'il <b>ne</b> vienne = I'm afraid he <b>will</b> come. It follows <b>craindre, avoir peur, de peur que, éviter que, à moins que, avant que</b> and comparisons (plus grand que je <b>ne</b> le pensais). Never add pas. <b>ne alone</b> is a real negation in literary style: Je <b>ne saurais</b> vous dire; Il <b>ne cesse</b> de parler; Elle <b>n'ose</b> répondre; Il <b>ne peut</b> mentir.","words":"","steps":[{"tool":"sort","title":"Negative or not?","sub":"Read the English meaning. Tap the box.","boxes":[{"k":"pos","label":"not negative","sub":"ne explétif"},{"k":"neg","label":"negative","sub":"literary ne alone"}],"cards":[{"t":"Je crains qu'il ne vienne.","box":"pos","why":"I'm afraid he <b>will</b> come."},{"t":"Je ne saurais vous dire.","box":"neg","why":"I <b>couldn't</b> tell you."},{"t":"Rentre avant qu'il ne fasse nuit.","box":"pos","why":"Go home before night falls."},{"t":"Il ne cesse de parler.","box":"neg","why":"He <b>never</b> stops talking."},{"t":"Il est plus grand que je ne le pensais.","box":"pos","why":"He is taller than I thought."},{"t":"Elle n'ose répondre.","box":"neg","why":"She <b>doesn't</b> dare answer."},{"t":"Nous irons, à moins qu'il ne pleuve.","box":"pos","why":"unless it rains"},{"t":"Il ne peut mentir.","box":"neg","why":"He <b>can't</b> lie."}]},{"tool":"swap","title":"Add the formal ne","sub":"Pick a sentence and tap « Formal ». The meaning does not change.","button":["Formal","Everyday"],"legend":[["x","the ne explétif"]],"items":[{"label":"J'ai peur qu'il vienne.","en":["I'm afraid he'll come.","I'm afraid he'll come. (formal)"],"a":[["s","J'ai peur qu'il",""],["v","vienne.",""]],"b":[["s","J'ai peur qu'il",""],["n","ne","x"],["v","vienne.",""]]},{"label":"Il est plus grand que je pensais.","en":["He is taller than I thought.","(formal)"],"a":[["s","Il est plus grand que je",""],["v","pensais.",""]],"b":[["s","Il est plus grand que je",""],["n","ne le","x"],["v","pensais.",""]]},{"label":"Évitons qu'il soit trop tard.","en":["Let's avoid it being too late.","(formal)"],"a":[["s","Évitons qu'il",""],["v","soit trop tard.",""]],"b":[["s","Évitons qu'il",""],["n","ne","x"],["v","soit trop tard.",""]]}]}],"practice":{"choose":[{"q":"« Je crains qu'il ne vienne » means: ___","en":"What does the sentence mean?","opts":["he may come","he won't come","he came","he never comes"],"a":"he may come","why":"The ne is not negative.","hint":"I fear he <b>will</b> come.","say":"Je crains qu'il ne vienne."},{"q":"Je ne ___ vous dire.","en":"I couldn't tell you.","opts":["saurais","sais","saurai","savais"],"a":"saurais","why":"Literary: savoir in the conditional.","hint":"je ne <b>saurais</b>."},{"q":"Il est plus grand qu'on ___ pense.","en":"He is taller than people think.","opts":["ne le","le","ne pas le","pas"],"a":"ne le","why":"A comparison: formal ne.","hint":"qu'on <b>ne le</b> pense."},{"q":"Il ne ___ de parler.","en":"He never stops talking.","opts":["cesse","cesse pas","cessait pas","cessera pas"],"a":"cesse","why":"ne alone with cesser.","hint":"il ne <b>cesse</b> de parler."},{"q":"Elle n'___ répondre.","en":"She doesn't dare answer.","opts":["ose","ose pas","osait pas","oser"],"a":"ose","why":"ne alone with oser.","hint":"elle n'<b>ose</b> répondre."},{"q":"Je crains qu'il ne pleuve ___.","en":"I'm afraid it won't rain.","opts":["pas","—","ne","jamais plus"],"a":"pas","why":"Now it is a real negative.","hint":"qu'il ne pleuve <b>pas</b>."}],"build":[{"en":"I couldn't tell you.","tiles":["Je","ne","saurais","vous dire."],"trap":"pas","why":"ne alone: no pas.","hint":"je <b>ne saurais</b>."},{"en":"He never stops talking.","tiles":["Il","ne","cesse","de parler."],"trap":"pas","why":"ne alone: no pas.","hint":"il <b>ne cesse</b>."},{"en":"I'm afraid he will come.","tiles":["Je crains","qu'il","ne","vienne."],"trap":"pas","why":"The ne explétif: no pas.","hint":"qu'il <b>ne</b> vienne."},{"en":"taller than I thought","tiles":["plus grand","que","je","ne le","pensais"],"trap":"pas","why":"A comparison: formal ne.","hint":"que je <b>ne le</b> pensais."},{"en":"She doesn't dare answer.","tiles":["Elle","n'ose","répondre."],"trap":"pas","why":"ne alone with oser.","hint":"elle <b>n'ose</b> répondre."}],"spot":[{"words":["Je crains qu'il ne","vienne pas","(I fear he will come)."],"bad":1,"fix":"vienne","hint":"No pas: <b>qu'il ne vienne</b> = he will come.","look":"Does pas fit the meaning?","say":"Je crains qu'il ne vienne."},{"words":["Je ne","sais","vous dire. (literary)"],"bad":1,"fix":"saurais","hint":"Literary: <b>je ne saurais</b>.","look":"Look at savoir.","say":"Je ne saurais vous dire."},{"words":["Il ne cesse","pas","de parler. (he never stops)"],"bad":1,"fix":"—","hint":"ne alone: <b>Il ne cesse de parler.</b>","look":"Does pas fit?","say":"Il ne cesse de parler."},{"words":["Rentre avant qu'il","ne fasse pas","nuit."],"bad":1,"fix":"ne fasse","hint":"No pas: before night <b>falls</b>.","look":"Does pas fit the meaning?","say":"Rentre avant qu'il ne fasse nuit."},{"words":["Il est parti sans qu'on","ne le voie."],"bad":1,"fix":"le voie.","hint":"No ne after <b>sans que</b>.","look":"Does sans que take a ne?","say":"Il est parti sans qu'on le voie."}]},"drill":[["Does « Je crains qu'il ne vienne » mean he comes or not?","he may come / he will come / he comes","The ne explétif is <b>not</b> negative."],["Literary: Je ne ___ dire. (savoir, conditionnel)","saurais","je ne <b>saurais</b>."],["Il est plus grand qu'on ___ pense.","ne le","qu'on <b>ne le</b> pense."],["Il ne ___ de parler. (cesser)","cesse","il ne <b>cesse</b> de parler."],["She doesn't dare answer. (literary)","Elle n'ose répondre.","<b>n'ose</b>: ne alone."],["I'm afraid it's too late. (formal)","Je crains qu'il ne soit trop tard.","The ne explétif: <b>ne soit</b>."]]},"73":{"line":"Novels and editorials bend the usual order. <b>No verb</b>: Silence. Un bruit au loin. <b>Adjective first</b> for colour: un <b>étrange</b> silence. <b>A detached word</b> in front: <b>Fatigué</b>, le vieil homme s'assit. <b>Subject after the verb</b>: Sur la table <b>se trouvait une lettre</b>. <b>Il est des</b> jours où… (there are). Formal set phrases: <b>toujours est-il que</b> (the fact remains), <b>force est de constater que</b> (one has to admit), <b>il va sans dire que</b>, <b>à l'insu de</b> (without the knowledge of), <b>en l'occurrence</b> (in this case).","words":"","steps":[{"tool":"swap","title":"Plain order → literary order","sub":"Pick a sentence and tap « Literary ».","button":["Literary","Plain"],"legend":[["x","what moved"]],"items":[{"label":"Une lettre se trouvait sur la table.","en":["A letter was on the table.","On the table lay a letter."],"a":[["s","Une lettre","x"],["v","se trouvait",""],["o","sur la table.",""]],"b":[["o","Sur la table",""],["v","se trouvait",""],["s","une lettre.","x"]],"note":"The subject comes <b>after</b> the verb."},{"label":"Le vieil homme était fatigué et il s'assit.","en":["The old man was tired and sat down.","Tired, the old man sat down."],"a":[["s","Le vieil homme",""],["a","était fatigué","x"],["v","et il s'assit.",""]],"b":[["a","Fatigué,","x"],["s","le vieil homme",""],["v","s'assit.",""]]},{"label":"Il y a des jours où tout va mal.","en":["There are days when everything goes wrong.","(literary)"],"a":[["x","Il y a","x"],["o","des jours où tout va mal.",""]],"b":[["x","Il est","x"],["o","des jours où tout va mal.",""]]},{"label":"Un silence étrange régnait.","en":["A strange silence reigned. (classifies)","A strange silence reigned. (an impression)"],"a":[["s","Un silence",""],["a","étrange","x"],["v","régnait.",""]],"b":[["s0","Un",""],["a","étrange","x"],["s1","silence",""],["v","régnait.",""]],"note":"Before the noun, the adjective adds <b>colour</b>."}]},{"tool":"pairs","title":"Formal set phrases","sub":"Tap the French to hear it.","cap":["French","meaning"],"right":"en","rows":[{"l":"toujours est-il que","r":"the fact remains that"},{"l":"force est de constater que","r":"one has to admit that"},{"l":"il va sans dire que","r":"it goes without saying that"},{"l":"n'en déplaise à","r":"with all due respect to"},{"l":"tant et si bien que","r":"so much so that"},{"l":"à l'insu de","r":"without the knowledge of"},{"l":"en l'occurrence","r":"in this case"},{"l":"au demeurant","r":"moreover, anyway"}]}],"practice":{"choose":[{"q":"___ est-il que le problème demeure.","en":"The fact remains that the problem persists.","opts":["Toujours","Encore","Ainsi","Aussi"],"a":"Toujours","why":"the fact remains…","hint":"<b>Toujours est-il que</b>."},{"q":"___ est de constater que les prix augmentent.","en":"One has to admit that prices are rising.","opts":["Force","Faute","Fort","Forcé"],"a":"Force","why":"one has to admit…","hint":"<b>Force est de constater</b>."},{"q":"Il est parti à l'___ de ses parents.","en":"He left without his parents knowing.","opts":["insu","issue","insue","insu-"],"a":"insu","why":"without the knowledge of…","hint":"<b>à l'insu de</b>."},{"q":"Le responsable, en l'___, est le directeur.","en":"The person in charge, in this case, is the director.","opts":["occurrence","occasion","ocurrence","occurence"],"a":"occurrence","why":"in this case…","hint":"<b>en l'occurrence</b> (two c, two r)."},{"q":"Sur la table ___ une lettre.","en":"On the table lay a letter.","opts":["se trouvait","elle se trouvait","se trouvait-elle","trouvait"],"a":"se trouvait","why":"Verb before the subject.","hint":"sur la table <b>se trouvait</b> une lettre."},{"q":"Il ___ des jours où tout va mal.","en":"There are days when everything goes wrong.","opts":["est","a","y est","sont"],"a":"est","why":"Literary: il est des…","hint":"<b>Il est des</b> jours…"}],"build":[{"en":"the fact remains that","tiles":["toujours","est-il","que"],"trap":"encore","why":"A set phrase.","hint":"<b>toujours est-il que</b>."},{"en":"one has to admit that","tiles":["force","est","de constater","que"],"trap":"faute","why":"A set phrase.","hint":"<b>force est de constater que</b>."},{"en":"without the knowledge of his parents","tiles":["à l'insu","de","ses parents"],"trap":"insue","why":"A set phrase.","hint":"<b>à l'insu de</b>…"},{"en":"On the table lay a letter.","tiles":["Sur la table","se trouvait","une lettre."],"trap":"elle","why":"Verb before the subject.","hint":"sur la table <b>se trouvait une lettre</b>."},{"en":"Tired, the old man sat down.","tiles":["Fatigué,","le vieil homme","s'assit."],"trap":"Il était","why":"A detached adjective in front.","hint":"<b>Fatigué</b>, …"}],"spot":[{"words":["Toujours","il est","que le problème demeure."],"bad":1,"fix":"est-il","hint":"A set phrase: <b>toujours est-il que</b>.","look":"Look at the word order."},{"words":["en l'","occurence"],"bad":1,"fix":"occurrence","hint":"Spelling: <b>occurrence</b>.","look":"Count the c and r."},{"words":["à l'","insue","de ses parents"],"bad":1,"fix":"insu","hint":"Spelling: <b>à l'insu de</b>.","look":"Look at the spelling."},{"words":["Il","sont","des jours où tout va mal."],"bad":1,"fix":"est","hint":"Literary and singular: <b>Il est des</b>.","look":"Singular or plural verb?"},{"words":["Faute","est de constater","que les prix montent."],"bad":0,"fix":"Force","hint":"A set phrase: <b>Force est de constater</b>.","look":"Look at the first word."}]},"drill":[["'the fact remains that'","toujours est-il que","<b>toujours est-il que</b>."],["'one has to admit that'","force est de constater que","<b>force est de constater que</b>."],["'without the knowledge of'","à l'insu de","<b>à l'insu de</b>."],["'in this case'","en l'occurrence","<b>en l'occurrence</b>."],["'it goes without saying that'","il va sans dire que","<b>il va sans dire que</b>."],["There are days when everything goes wrong. (literary)","Il est des jours où tout va mal.","<b>Il est des</b> …"]]},"74":{"line":"To read what an author <b>means</b>, spot the figures. <b>Métaphore</b>: a hidden comparison (cet homme est un roc). <b>Comparaison</b>: with comme (rapide comme l'éclair). <b>Personnification</b>: la ville s'éveille. <b>Métonymie</b>: a part or container for the whole (boire un verre, lire du Zola). <b>Hyperbole</b>: je meurs de faim. <b>Litote</b>: say less to mean more (ce n'est pas mauvais = it's good). <b>Euphémisme</b>: soften (il nous a quittés = he died). <b>Antithèse</b>: opposites side by side. <b>Anaphore</b>: the same word repeated at the start. Irony: the words clash with the situation.","words":"Literary words: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:51\">Vocab 51 · Literature & Style</a>.","steps":[{"tool":"sort","title":"Which figure?","sub":"Tap the box.","boxes":[{"k":"lit","label":"litote","sub":"less for more"},{"k":"eup","label":"euphémisme","sub":"softens"},{"k":"hyp","label":"hyperbole","sub":"exaggerates"},{"k":"met","label":"métaphore / comparaison","sub":"compares"}],"cards":[{"t":"Ce n'est pas mauvais.","box":"lit","why":"= it is good."},{"t":"Il nous a quittés.","box":"eup","why":"= he died."},{"t":"Je meurs de faim.","box":"hyp","why":"= I'm very hungry."},{"t":"Cet homme est un roc.","box":"met","why":"A hidden comparison."},{"t":"Ce n'est pas rien.","box":"lit","why":"= it is quite something."},{"t":"un demandeur d'emploi","box":"eup","why":"= an unemployed person."},{"t":"Je te l'ai dit mille fois.","box":"hyp"},{"t":"rapide comme l'éclair","box":"met","why":"With comme: a comparison."}]},{"tool":"flip","en":"b","title":"What does it really say?","sub":"Tap a card.","cards":[{"a":"Boire un verre.","b":"Drink what is in the glass.","tag":"métonymie"},{"a":"Lire du Zola.","b":"Read the works of Zola.","tag":"métonymie"},{"a":"La ville s'éveille.","b":"The town wakes up (as if alive).","tag":"personnification"},{"a":"Le jour et la nuit.","b":"Two opposites side by side.","tag":"antithèse"},{"a":"un plan social","b":"job cuts","tag":"euphémisme"},{"a":"Va, cours, vole !","b":"Go, run, fly! (building up)","tag":"gradation"}]}],"practice":{"choose":[{"q":"« Ce n'est pas mauvais » (= good) is a ___.","en":"It's not bad.","opts":["litote","hyperbole","métaphore","euphémisme"],"a":"litote","why":"Saying less to mean more.","hint":"a <b>litote</b>.","say":"Ce n'est pas mauvais."},{"q":"« Il nous a quittés » (= he died) is an ___.","en":"He has left us.","opts":["euphémisme","hyperbole","antithèse","anaphore"],"a":"euphémisme","why":"It softens.","hint":"an <b>euphémisme</b>.","say":"Il nous a quittés."},{"q":"« Boire un verre » is a ___.","en":"Have a drink.","opts":["métonymie","métaphore","litote","comparaison"],"a":"métonymie","why":"The container for what is inside.","hint":"a <b>métonymie</b>.","say":"Boire un verre."},{"q":"« Cet homme est un roc » is a ___.","en":"This man is a rock.","opts":["métaphore","comparaison","litote","hyperbole"],"a":"métaphore","why":"A comparison without comme.","hint":"a <b>métaphore</b>.","say":"Cet homme est un roc."},{"q":"« Je meurs de faim » is an ___.","en":"I'm starving.","opts":["hyperbole","euphémisme","litote","antithèse"],"a":"hyperbole","why":"An exaggeration.","hint":"an <b>hyperbole</b>.","say":"Je meurs de faim."},{"q":"« rapide comme l'éclair » is a ___.","en":"as quick as lightning","opts":["comparaison","métaphore","métonymie","litote"],"a":"comparaison","why":"With comme.","hint":"a <b>comparaison</b>.","say":"rapide comme l'éclair"}],"build":[{"en":"It's not bad. (= it's good)","tiles":["Ce n'est","pas","mauvais."],"trap":"bon","why":"A litote.","hint":"<b>Ce n'est pas mauvais.</b>"},{"en":"He has left us. (= he died)","tiles":["Il","nous a","quittés."],"trap":"mort","why":"A euphemism.","hint":"il nous a <b>quittés</b>."},{"en":"This man is a rock.","tiles":["Cet homme","est","un roc."],"trap":"comme","why":"A metaphor: no comme.","hint":"est <b>un roc</b>."},{"en":"as quick as lightning","tiles":["rapide","comme","l'éclair"],"trap":"est","why":"A comparison: with comme.","hint":"rapide <b>comme</b> l'éclair."},{"en":"The town wakes up.","tiles":["La ville","s'éveille."],"trap":"se lève","why":"A personification.","hint":"la ville <b>s'éveille</b>."}],"spot":[{"words":["« Ce n'est pas rien »","est","une hyperbole."],"bad":2,"fix":"une litote.","hint":"Saying less to mean more: a <b>litote</b>.","look":"Does it exaggerate?","say":"« Ce n'est pas rien » est une litote."},{"words":["« Il nous a quittés »","est","une métaphore."],"bad":2,"fix":"un euphémisme.","hint":"It softens death: a <b>euphémisme</b>.","look":"Is it a comparison?","say":"« Il nous a quittés » est un euphémisme."},{"words":["« rapide comme l'éclair »","est","une métaphore."],"bad":2,"fix":"une comparaison.","hint":"With comme: a <b>comparaison</b>.","look":"Is there a comme?","say":"« rapide comme l'éclair » est une comparaison."},{"words":["« Lire du Zola »","est","une litote."],"bad":2,"fix":"une métonymie.","hint":"The author for the works: a <b>métonymie</b>.","look":"What does Zola stand for?","say":"« Lire du Zola » est une métonymie."},{"words":["« Je meurs de faim »","est","une litote."],"bad":2,"fix":"une hyperbole.","hint":"An exaggeration: an <b>hyperbole</b>.","look":"Does it say less or more?","say":"« Je meurs de faim » est une hyperbole."}]},"drill":[["Ce n'est pas mauvais = good: which figure?","litote","Saying less to mean more: <b>litote</b>."],["Il nous a quittés = he died: which figure?","euphémisme","It softens: <b>euphémisme</b>."],["Boire un verre: which figure?","métonymie","The container for the content: <b>métonymie</b>."],["Cet homme est un roc: which figure?","métaphore","A hidden comparison: <b>métaphore</b>."],["Je meurs de faim: which figure?","hyperbole","An exaggeration: <b>hyperbole</b>."],["rapide comme l'éclair: which figure?","comparaison","With comme: <b>comparaison</b>."]]},"75":{"line":"An idiom means more than its words: learn it as a block, never word for word. <b>poser un lapin</b> (to stand someone up), <b>avoir le cafard</b> (to feel down), <b>coûter les yeux de la tête</b> (to cost a fortune), <b>tomber dans les pommes</b> (to faint), <b>être dans le pétrin</b> (to be in a fix), <b>revenons à nos moutons</b> (back to the point). The verb still changes: il m'<b>a posé</b> un lapin. In an oral test, one natural idiom beats five forced ones.","words":"Idioms: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:53\">Vocab 53 · Idioms & Expressions</a> · <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:56\">Vocab 56 · Everyday Slang & Spoken French</a>.","steps":[{"tool":"flip","en":"b","title":"Word for word → what it means","sub":"Tap a card.","cards":[{"a":"poser un lapin","b":"to stand someone up","tag":"to put down a rabbit"},{"a":"avoir le cafard","b":"to feel down","tag":"to have the cockroach"},{"a":"coûter les yeux de la tête","b":"to cost a fortune","tag":"the eyes of the head"},{"a":"tomber dans les pommes","b":"to faint","tag":"to fall into the apples"},{"a":"casser les pieds à qqn","b":"to annoy someone","tag":"to break someone's feet"},{"a":"mettre son grain de sel","b":"to butt in","tag":"to put in a grain of salt"},{"a":"ce n'est pas la mer à boire","b":"it's not that hard","tag":"not the sea to drink"},{"a":"être dans le pétrin","b":"to be in a fix","tag":"in the kneading trough"},{"a":"faire la grasse matinée","b":"to sleep in","tag":"to do the fat morning"},{"a":"revenons à nos moutons","b":"let's get back to the point","tag":"back to our sheep"}]},{"tool":"pairs","title":"Proverbs","sub":"Tap the French to hear it.","cap":["proverb","meaning"],"right":"en","rows":[{"l":"L'habit ne fait pas le moine.","r":"Don't judge by appearances."},{"l":"Petit à petit, l'oiseau fait son nid.","r":"Little by little, you get there."},{"l":"Chat échaudé craint l'eau froide.","r":"Once bitten, twice shy."},{"l":"Il n'y a pas de fumée sans feu.","r":"There's no smoke without fire."},{"l":"Mieux vaut tard que jamais.","r":"Better late than never."},{"l":"Tel père, tel fils.","r":"Like father, like son."}]}],"practice":{"choose":[{"q":"Il m'a ___ un lapin.","en":"He stood me up.","opts":["posé","mis","donné","fait"],"a":"posé","why":"poser un lapin.","hint":"il m'a <b>posé</b> un lapin."},{"q":"J'ai le ___ aujourd'hui.","en":"I'm feeling down today.","opts":["cafard","lapin","pétrin","moine"],"a":"cafard","why":"avoir le cafard.","hint":"j'ai le <b>cafard</b>."},{"q":"Ce sac coûte les yeux de la ___.","en":"This bag costs a fortune.","opts":["tête","main","figure","bouche"],"a":"tête","why":"coûter les yeux de la tête.","hint":"de la <b>tête</b>."},{"q":"Mieux vaut tard que ___.","en":"Better late than never.","opts":["jamais","rien","toujours","demain"],"a":"jamais","why":"A proverb.","hint":"que <b>jamais</b>."},{"q":"Elle est tombée dans les ___.","en":"She fainted.","opts":["pommes","poires","pâtes","prunes"],"a":"pommes","why":"tomber dans les pommes.","hint":"dans les <b>pommes</b>."},{"q":"Revenons à nos ___.","en":"Let's get back to the point.","opts":["moutons","lapins","chats","oiseaux"],"a":"moutons","why":"A set phrase.","hint":"à nos <b>moutons</b>."}],"build":[{"en":"He stood me up.","tiles":["Il","m'a","posé","un lapin."],"trap":"donné","why":"poser un lapin.","hint":"il m'a <b>posé un lapin</b>."},{"en":"I'm feeling down.","tiles":["J'ai","le cafard."],"trap":"Je suis","why":"avoir le cafard.","hint":"<b>j'ai le cafard</b>."},{"en":"It's not that hard.","tiles":["Ce n'est pas","la mer","à boire."],"trap":"manger","why":"A set phrase.","hint":"la mer <b>à boire</b>."},{"en":"We're in a fix.","tiles":["Nous sommes","dans le","pétrin."],"trap":"pain","why":"être dans le pétrin.","hint":"dans le <b>pétrin</b>."},{"en":"Don't judge by appearances.","tiles":["L'habit","ne fait pas","le moine."],"trap":"la robe","why":"A proverb.","hint":"<b>L'habit ne fait pas le moine.</b>"}],"spot":[{"words":["Il","m'a donné","un lapin."],"bad":1,"fix":"m'a posé","hint":"poser un lapin.","look":"Which verb goes with lapin?"},{"words":["Ce sac coûte","les yeux de la main."],"bad":1,"fix":"les yeux de la tête.","hint":"coûter les yeux de la <b>tête</b>.","look":"Look at the body part."},{"words":["Mieux vaut tard","que rien."],"bad":1,"fix":"que jamais.","hint":"Better late than <b>never</b>.","look":"Look at the end."},{"words":["Elle est tombée","dans les poires."],"bad":1,"fix":"dans les pommes.","hint":"tomber dans les <b>pommes</b>.","look":"Which fruit?"},{"words":["Revenons","à nos lapins."],"bad":1,"fix":"à nos moutons.","hint":"Revenons à nos <b>moutons</b>.","look":"Which animal?"}]},"drill":[["poser un lapin = ?","to stand someone up","An idiom: <b>to stand someone up</b>."],["avoir le cafard = ?","to feel down / to feel blue / to be depressed","An idiom: <b>to feel down</b>."],["Mieux vaut tard que ___","jamais","<b>Mieux vaut tard que jamais.</b>"],["tomber dans les pommes = ?","to faint / to pass out","An idiom: <b>to faint</b>."],["He stood me up.","Il m'a posé un lapin.","<b>Il m'a posé un lapin.</b>"],["Let's get back to the point.","Revenons à nos moutons.","<b>Revenons à nos moutons.</b>"]]},"76":{"line":"<b>Faux amis</b> look English but mean something else: <b>actuellement</b> = currently (actually = <b>en fait</b>), <b>éventuellement</b> = possibly, <b>assister à</b> = to attend, <b>sensible</b> = sensitive, <b>la librairie</b> = bookshop, <b>rester</b> = to stay, <b>supporter</b> = to put up with, <b>passer un examen</b> = to take it (pass = <b>réussir</b>). Confusing pairs: <b>savoir</b> (facts) / <b>connaître</b> (people, places), <b>amener</b> (bring someone) / <b>emmener</b> (take someone away), <b>apporter / emporter</b> (things), <b>un jour / une journée</b>.","words":"False friends: <a class=\"text-indigo-700 font-semibold underline\" href=\"vocab.html?topic=theme:30\">Vocab 30 · Common False Friends</a>.","steps":[{"tool":"pairs","title":"Faux amis","sub":"Tap the French to hear it.","cap":["French","really means"],"right":"en","rows":[{"l":"actuellement","r":"currently (actually = en fait)"},{"l":"éventuellement","r":"possibly (eventually = finalement)"},{"l":"assister à une réunion","r":"to attend a meeting (to assist = aider)"},{"l":"sensible","r":"sensitive (sensible = raisonnable)"},{"l":"la librairie","r":"the bookshop (library = la bibliothèque)"},{"l":"rester","r":"to stay (to rest = se reposer)"},{"l":"supporter","r":"to put up with (to support = soutenir)"},{"l":"passer un examen","r":"to take an exam (to pass = réussir)"},{"l":"prétendre","r":"to claim (to pretend = faire semblant)"}]},{"tool":"sort","title":"Which one?","sub":"Tap the box.","boxes":[{"k":"am","label":"amener / apporter","sub":"bring here"},{"k":"em","label":"emmener / emporter","sub":"take away"}],"cards":[{"t":"Bring your sister to the party.","box":"am","why":"<b>Amène</b> ta sœur à la fête.","say":"Amène ta sœur à la fête."},{"t":"I take my son to school every morning.","box":"em","why":"J'<b>emmène</b> mon fils à l'école.","say":"J'emmène mon fils à l'école."},{"t":"Bring a cake.","box":"am","why":"<b>Apporte</b> un gâteau.","say":"Apporte un gâteau."},{"t":"Take an umbrella with you.","box":"em","why":"<b>Emporte</b> un parapluie.","say":"Emporte un parapluie."},{"t":"Can you bring me some water?","box":"am","why":"Tu peux m'<b>apporter</b> de l'eau ?","say":"Tu peux m'apporter de l'eau ?"},{"t":"A pizza to take away.","box":"em","why":"Une pizza à <b>emporter</b>.","say":"Une pizza à emporter."}]}],"practice":{"choose":[{"q":"'actually' in French: ___","en":"actually","opts":["en fait","actuellement","actuel","en effet"],"a":"en fait","why":"actuellement = currently.","hint":"<b>en fait</b>."},{"q":"J'ai ___ à une réunion.","en":"I attended a meeting.","opts":["assisté","attendu","aidé","participé"],"a":"assisté","why":"to attend = assister à.","hint":"j'ai <b>assisté</b> à."},{"q":"J'ai ___ mon examen !","en":"I passed my exam!","opts":["réussi","passé","gagné","pris"],"a":"réussi","why":"to pass = réussir.","hint":"j'ai <b>réussi</b>."},{"q":"Je vais à la ___ pour emprunter un livre.","en":"I'm going to the library to borrow a book.","opts":["bibliothèque","librairie","livrerie","libraire"],"a":"bibliothèque","why":"Borrowing: the library.","hint":"la <b>bibliothèque</b>."},{"q":"Je ___ cette ville.","en":"I know this town.","opts":["connais","sais","savais","connaît"],"a":"connais","why":"A place: connaître.","hint":"je <b>connais</b>."},{"q":"___ ton parapluie !","en":"Take your umbrella (with you)!","opts":["Emporte","Apporte","Amène","Emmène"],"a":"Emporte","why":"A thing, taken away.","hint":"<b>Emporte</b>."}],"build":[{"en":"to attend a meeting","tiles":["assister","à","une réunion"],"trap":"attendre","why":"to attend = assister à.","hint":"<b>assister à</b>."},{"en":"to pass an exam","tiles":["réussir","un examen"],"trap":"passer","why":"to pass = réussir.","hint":"<b>réussir</b> un examen."},{"en":"I take my son to school.","tiles":["J'","emmène","mon fils","à l'école."],"trap":"amène","why":"A person, taken away.","hint":"j'<b>emmène</b>."},{"en":"Actually, I prefer tea.","tiles":["En fait,","je","préfère","le thé."],"trap":"Actuellement,","why":"actually = en fait.","hint":"<b>En fait</b>…"},{"en":"I need to rest.","tiles":["J'ai besoin","de","me reposer."],"trap":"rester","why":"to rest = se reposer.","hint":"<b>me reposer</b>."}],"spot":[{"words":["Hier,","actuellement,","j'étais à Paris."],"bad":1,"fix":"en fait,","hint":"actually = <b>en fait</b>.","look":"actuellement means…"},{"words":["J'ai","passé","mon examen : 18/20 !"],"bad":1,"fix":"réussi","hint":"to pass = <b>réussir</b>.","look":"Took it, or passed it?"},{"words":["Je suis","resté","sur le canapé pour récupérer."],"bad":1,"fix":"je me suis reposé","hint":"to rest = <b>se reposer</b>.","look":"rester means…","say":"Je me suis reposé sur le canapé pour récupérer."},{"words":["J'ai","assisté","mon ami à déménager."],"bad":1,"fix":"aidé","hint":"to help = <b>aider</b>.","look":"assister means…"},{"words":["Je","sais","bien Marie."],"bad":1,"fix":"connais","hint":"A person: <b>connaître</b>.","look":"A fact, or a person?"}]},"drill":[["'actually' in French","en fait / en réalité","actually = <b>en fait</b>."],["'to attend a meeting'","assister à une réunion","to attend = <b>assister à</b>."],["'to pass an exam'","réussir un examen / réussir à un examen","to pass = <b>réussir</b>."],["'to take a child with you (away)'","emmener","A person, away: <b>emmener</b>."],["'currently'","actuellement","<b>actuellement</b> = currently."],["'the library'","la bibliothèque","la librairie = the bookshop."]]},"v44":{"line":"Every verb lesson in one place. A good text uses the tense each idea needs: <b>imparfait</b> for background (Quand j'étais enfant…), <b>passé composé</b> for events, <b>plus-que-parfait</b> for earlier, <b>présent</b>, <b>futur antérieur + futur</b> (Dès que j'aurai obtenu…), <b>si + imparfait → conditionnel</b>, <b>si + plus-que-parfait → conditionnel passé</b>, the <b>subjonctif</b> after il faut que, the <b>infinitif passé</b> (content d'avoir progressé). Then check: time line, si, mood, agreement, same subject, register.","words":"Every verb in full: <a class=\"text-indigo-700 font-semibold underline\" href=\"conjugations.html\">Conjugations</a>.","steps":[{"tool":"sort","title":"Name the tense","sub":"Tap the box for the verb in bold.","boxes":[{"k":"imp","label":"imparfait"},{"k":"pc","label":"passé composé"},{"k":"pqp","label":"plus-que-parfait"},{"k":"fa","label":"futur antérieur"},{"k":"cp","label":"conditionnel passé"},{"k":"subj","label":"subjonctif"}],"cards":[{"t":"Quand j'étais enfant, je rêvais du Canada.","box":"imp","why":"Background, a habit."},{"t":"En 2020, j'ai décidé de préparer le TCF.","box":"pc","why":"An event."},{"t":"Je m'étais déjà inscrit à un cours.","box":"pqp","why":"Earlier still."},{"t":"Dès que j'aurai obtenu mon résultat…","box":"fa","why":"Done before a future step."},{"t":"Si j'avais commencé plus tôt, j'aurais réussi.","box":"cp","why":"The result of an unreal past."},{"t":"Il faut que je réussisse.","box":"subj","why":"After il faut que."}]},{"tool":"flip","en":"b","title":"The checklist","sub":"Tap a card: the question, then what to check.","cards":[{"a":"1 · Time line","b":"Is every verb in the right time frame?"},{"a":"2 · Past tenses","b":"Event = passé composé; background = imparfait."},{"a":"3 · si","b":"No conditional right after si."},{"a":"4 · Mood","b":"Subjonctif after a wish, a doubt, a feeling, and the right conjunctions."},{"a":"5 · Agreement","b":"Subject and verb; participle with être; participle with an object before."},{"a":"6 · Same subject","b":"Same subject? The infinitive, not que + subjonctif."},{"a":"7 · Register","b":"No familiar words, no dropped ne."}]}],"practice":{"choose":[{"q":"Si j'avais su, je ___ venu.","en":"If I had known, I would have come.","opts":["serais","suis","serai","aurais"],"a":"serais","why":"Unreal past: conditionnel passé.","hint":"je <b>serais</b> venu."},{"q":"Dès que j'___ fini, je partirai.","en":"As soon as I've finished, I'll leave.","opts":["aurai","ai","aurais","avais"],"a":"aurai","why":"futur antérieur.","hint":"j'<b>aurai</b> fini."},{"q":"Il faut que je ___.","en":"I must succeed.","opts":["réussisse","réussis","réussirai","réussirais"],"a":"réussisse","why":"il faut que + subjonctif.","hint":"je <b>réussisse</b>."},{"q":"Il pensait que tu ___ parti.","en":"He thought you had left.","opts":["étais","es","serais","sois"],"a":"étais","why":"Earlier, after a past verb.","hint":"tu <b>étais</b> parti."},{"q":"Quand j'___ enfant, je rêvais du Canada.","en":"When I was a child, I dreamed of Canada.","opts":["étais","ai été","suis","serai"],"a":"étais","why":"Background: imparfait.","hint":"j'<b>étais</b>."},{"q":"Je suis content ___ progressé.","en":"I'm glad I've made progress.","opts":["d'avoir","que j'aie","avoir","d'être"],"a":"d'avoir","why":"Same subject: infinitif passé.","hint":"content <b>d'avoir</b> progressé."}],"build":[{"en":"If I had known, I would have come.","tiles":["Si j'","avais su,","je","serais","venu."],"trap":"aurais","why":"si + plus-que-parfait, then conditionnel passé.","hint":"je <b>serais venu</b>."},{"en":"As soon as I've finished, I'll leave.","tiles":["Dès que j'","aurai","fini,","je partirai."],"trap":"ai","why":"futur antérieur.","hint":"j'<b>aurai</b> fini."},{"en":"I must succeed.","tiles":["Il faut","que je","réussisse."],"trap":"réussis.","why":"il faut que + subjonctif.","hint":"que je <b>réussisse</b>."},{"en":"He thought you had left.","tiles":["Il pensait","que tu","étais","parti."],"trap":"es","why":"Earlier, after a past verb.","hint":"tu <b>étais</b> parti."},{"en":"I'm glad I've made progress.","tiles":["Je suis content","d'avoir","progressé."],"trap":"que j'aie","why":"Same subject: infinitif passé.","hint":"<b>d'avoir</b> progressé."}],"spot":[{"words":["Si j'","aurais su,","je serais venu."],"bad":1,"fix":"avais su,","hint":"No conditional after si: <b>avais su</b>.","look":"Look after si."},{"words":["Dès que j'","ai fini,","je partirai."],"bad":1,"fix":"aurai fini,","hint":"About the future: <b>aurai fini</b>.","look":"Is it the future?"},{"words":["Il faut que je","réussis."],"bad":1,"fix":"réussisse.","hint":"il faut que + <b>subjonctif</b>.","look":"Which mood?"},{"words":["Je suis content","que j'aie","progressé."],"bad":1,"fix":"d'avoir","hint":"Same subject: <b>d'avoir</b> progressé.","look":"Who made progress?"},{"words":["Quand j'","ai été","enfant, je rêvais du Canada."],"bad":1,"fix":"étais","hint":"Background: <b>imparfait</b>.","look":"Event or background?"}]},"drill":[["Si j'avais su, je (venir, cond. passé)...","je serais venu(e)","si + plus-que-parfait → <b>serais venu</b>."],["Dès que j'(finir, futur antérieur)...","aurai fini","<b>aurai fini</b>."],["Il faut que je (réussir, subj.)...","réussisse","<b>réussisse</b>."],["Il pensait que tu (partir, plus-que-parfait)...","étais parti(e)","Earlier: <b>étais parti</b>."],["Quand j'(être, imparfait) enfant...","étais","Background: <b>étais</b>."],["I'm glad I've made progress.","Je suis content d'avoir progressé. / Je suis contente d'avoir progressé.","Same subject: <b>d'avoir</b> progressé."]]},"78":{"line":"The last check before you hand in. The usual C1 slips: <b>après que</b> + indicative (après qu'il <b>est</b> parti); no conditional after <b>si</b> (s'il <b>avait</b> su); <b>chez</b> with people (<b>chez</b> le dentiste); <b>pallier</b> un problème (no à); <b>se rappeler</b> quelque chose (no de) but se souvenir <b>de</b>; <b>tout le monde est</b>; <b>la plupart des gens pensent</b>; quelque chose <b>d'</b>intéressant; elle s'est <b>lavé</b> les mains. Avoid <b>malgré que</b>: use bien que.","words":"","steps":[{"tool":"pairs","title":"Wrong → right","sub":"Tap the French to hear it.","cap":["right","not this"],"right":"en","rows":[{"l":"Après qu'il est parti","r":"✗ Après qu'il soit parti","en":"après que + indicative"},{"l":"S'il avait su","r":"✗ S'il aurait su","en":"no conditional after si"},{"l":"Je vais chez le dentiste.","r":"✗ Je vais au dentiste.","en":"chez + a person"},{"l":"pallier un problème","r":"✗ pallier à un problème","en":"no à"},{"l":"se rappeler quelque chose","r":"✗ se rappeler de quelque chose","en":"no de (se souvenir de)"},{"l":"Tout le monde est là.","r":"✗ Tout le monde sont là.","en":"singular"},{"l":"La plupart des gens pensent…","r":"✗ La plupart des gens pense…","en":"plural"},{"l":"quelque chose d'intéressant","r":"✗ quelque chose intéressant","en":"de + adjective"},{"l":"Elle s'est lavé les mains.","r":"✗ Elle s'est lavée les mains.","en":"the object comes after"},{"l":"Bien que ce soit cher…","r":"✗ Malgré que ce soit cher…","en":"avoid malgré que"}]},{"tool":"sort","title":"Right or wrong?","sub":"Tap the box.","boxes":[{"k":"ok","label":"right"},{"k":"no","label":"wrong"}],"cards":[{"t":"Après qu'il soit parti, nous avons dîné.","box":"no","why":"après que + <b>est</b> parti."},{"t":"Je me rappelle cette journée.","box":"ok"},{"t":"Je vais au coiffeur.","box":"no","why":"<b>chez</b> le coiffeur."},{"t":"Il faut pallier ce manque.","box":"ok"},{"t":"La plupart des étudiants ont réussi.","box":"ok"},{"t":"Tout le monde sont contents.","box":"no","why":"tout le monde <b>est</b> content."},{"t":"Elles se sont parlé.","box":"ok","why":"parler à: no agreement."},{"t":"S'il pleuvrait, je resterais.","box":"no","why":"<b>S'il pleuvait</b>…"}]}],"practice":{"choose":[{"q":"Après qu'il ___ parti, nous avons mangé.","en":"After he left, we ate.","opts":["est","soit","fût","serait"],"a":"est","why":"après que + indicative.","hint":"<b>est</b> parti."},{"q":"S'il ___, il viendrait.","en":"If he knew, he would come.","opts":["savait","saurait","sache","sait"],"a":"savait","why":"si + imparfait.","hint":"s'il <b>savait</b>."},{"q":"Je vais ___ dentiste.","en":"I'm going to the dentist's.","opts":["chez le","au","à le","vers le"],"a":"chez le","why":"chez + a person.","hint":"<b>chez le</b> dentiste."},{"q":"Elle s'est ___ les mains.","en":"She washed her hands.","opts":["lavé","lavée","lavées","lavés"],"a":"lavé","why":"The object comes after.","hint":"s'est <b>lavé</b>."},{"q":"Il faut ___ ce problème.","en":"We must deal with this problem.","opts":["pallier","pallier à","pallier de","pallier sur"],"a":"pallier","why":"pallier takes no à.","hint":"<b>pallier</b> ce problème."},{"q":"La plupart des gens ___ que c'est vrai.","en":"Most people think it is true.","opts":["pensent","pense","pensons","pensez"],"a":"pensent","why":"Plural after la plupart des.","hint":"<b>pensent</b>."}],"build":[{"en":"After he left, we ate.","tiles":["Après qu'il","est","parti,","nous avons mangé."],"trap":"soit","why":"après que + indicative.","hint":"après qu'il <b>est</b> parti."},{"en":"I'm going to the dentist's.","tiles":["Je vais","chez","le dentiste."],"trap":"au","why":"chez + a person.","hint":"<b>chez</b> le dentiste."},{"en":"I remember that day.","tiles":["Je","me rappelle","ce jour."],"trap":"de","why":"se rappeler: no de.","hint":"je me rappelle <b>ce jour</b>."},{"en":"Everyone is here.","tiles":["Tout le monde","est","là."],"trap":"sont","why":"Singular.","hint":"tout le monde <b>est</b>."},{"en":"something interesting","tiles":["quelque chose","d'","intéressant"],"trap":"intéressante","why":"de + masculine adjective.","hint":"quelque chose <b>d'</b>intéressant."}],"spot":[{"words":["Après qu'il","soit","parti, nous avons dîné."],"bad":1,"fix":"est","hint":"après que + <b>indicative</b>.","look":"Which mood?"},{"words":["Je vais","au","dentiste."],"bad":1,"fix":"chez le","hint":"<b>chez</b> + a person.","look":"A place or a person?"},{"words":["Il faut","pallier à","ce problème."],"bad":1,"fix":"pallier","hint":"pallier takes <b>no à</b>.","look":"Does pallier take à?"},{"words":["Je me rappelle","de","ce jour."],"bad":1,"fix":"—","hint":"se rappeler: <b>no de</b>.","look":"Does se rappeler take de?","say":"Je me rappelle ce jour."},{"words":["Malgré que","ce soit cher,","je l'achète."],"bad":0,"fix":"Bien que","hint":"Avoid malgré que: <b>bien que</b>.","look":"Is malgré que safe in an exam?"}]},"drill":[["Après qu'il (partir)...","est parti","après que + <b>indicative</b>."],["S'il (savoir), il viendrait. (imparfait)","savait","si + <b>imparfait</b>."],["Je vais ___ dentiste. (chez le / au)","chez le","<b>chez</b> + a person."],["Elle s'est ___ les mains. (lavé / lavées)","lavé","The object comes after: <b>lavé</b>."],["Most people think...","La plupart des gens pensent...","Plural: <b>pensent</b>."],["I remember that day. (se rappeler)","Je me rappelle ce jour.","se rappeler + <b>no de</b>."]]}};
